DG.put("ath-pakhyaan-charitr-likhyate/404",{"n":404,"title":null,"title_roman":null,"page":2467,"blocks":[{"type":"heading","kind":"speaker","name":"ਸਬੁਧਿ ਬਾਚ","gurmukhi":"ਸਬੁਧਿ ਬਾਚ","roman":"Sabudhi baach","meaning_en":"Subudhi said:","page":2467,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2467,"meaning_status":"draft"},{"type":"verse","number":[1],"number_text":"੧।","page":2467,"lines":[{"gurmukhi":"ਸਤਿ ਸੰਧਿ ਇਕ ਭੂਪ ਭਨਿਜੈ। ਪ੍ਰਥਮੇ ਸਤਿਜੁਗ ਬੀਚ ਕਹਿਜੈ।","roman":"Sati sandhi ik bhoop bhanijai | prathme satijug beech kahijai |","meaning_en":"A king named Satisandhi is mentioned, spoken of in the first age, the Satyug,","page":2467,"meaning_status":"draft"},{"gurmukhi":"ਜਿਹ ਜਸ ਪੁਰੀ ਚੌਦਹੂੰ ਛਾਯੋ। ਨਾਰਦ ਰਿਖਿ ਤਬ ਰਾਇ ਮੰਗਾਯੋ। ੧।","roman":"Jih jas puree chaudhoon chhaayo | naarad rikhi tab raai mangaayo | 1 |","meaning_en":"whose fame spread through the fourteen worlds; then the sage Narad summoned the king. 1.","page":2467,"meaning_status":"draft"}]},{"type":"verse","number":[2],"number_text":"੨।","page":2467,"lines":[{"gurmukhi":"ਸਭ ਦੇਵਨ ਕੋ ਰਾਜਾ ਭਯੋ। ਬ੍ਰਹਮਾ ਤਿਲਕ ਆਪੁ ਤਿਹ ਦਯੋ।","roman":"Sabh devan ko raajaa bhayo | brahmaa tilak aapu tih dayo |","meaning_en":"He became king of all the gods; Brahma himself applied the tilak to him.","page":2467,"meaning_status":"draft"},{"gurmukhi":"ਨਿਹਕੰਟਕ ਸੁਰ ਕਟਕ ਕਿਯਾ ਸਬ। ਦਾਨਵ ਮਾਰ ਨਿਕਾਰ ਦਏ ਜਬ। ੨।","roman":"Nihkantak sur katak kiyaa sab | daanav maar nikaar dae jab | 2 |","meaning_en":"He made the host of the gods free of thorns, when he had killed the demons and driven them out. 2.","page":2467,"meaning_status":"draft"}]},{"type":"verse","number":[3],"number_text":"੩।","page":2467,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਰਾਜ ਬਰਖ ਬਹੁ ਕਿਯਾ। ਦੀਰਘ ਦਾੜ ਦੈਤ ਭਵ ਲਿਯਾ।","roman":"Ih bidhi raaj barakh bahu kiyaa | deeragh daar dait bhav liyaa |","meaning_en":"In this way he ruled for many years; then the demon Dirghdadh took his turn.","page":2467,"meaning_status":"draft","note":"ਭਵ ਲਿਯਾ: 'took his turn / came to be'; rendered tentatively; uncertain."},{"gurmukhi":"ਦਸ ਸਹਸ ਛੂਹਨਿ ਦਲ ਲੈ ਕੈ। ਚੜਿ ਆਯੋ ਤਿਹ ਊਪਰ ਤੈ ਕੈ। ੩।","roman":"Das sahas chhoohni dal lai kai | chari aayo tih oopar tai kai | 3 |","meaning_en":"With an army of ten thousand chhauhinis he marched against him, resolved. 3.","page":2467,"meaning_status":"draft"}]},{"type":"verse","number":[4],"number_text":"੪।","page":2467,"lines":[{"gurmukhi":"ਸਭ ਦੇਵਨ ਐਸੇ ਸੁਨਿ ਪਾਯੋ। ਦੀਰਘ ਦਾੜ ਦੈਤ ਚੜਿ ਆਯੋ।","roman":"Sabh devan aise suni paayo | deeragh daar dait chari aayo |","meaning_en":"All the gods heard of this: the demon Dirghdadh had marched.","page":2467,"meaning_status":"draft"},{"gurmukhi":"ਬੀਸ ਸਹਸ ਛੋਹਨਿ ਦਲ ਲਿਯੋ। ਵਾ ਸੌ ਜਾਇ ਸਮਾਗਮ ਕਿਯੋ। ੪।","roman":"Bees sahas chhohni dal liyo | vaa sau jaai samaagam kiyo | 4 |","meaning_en":"Satisandhi took twenty thousand chhauhinis and went and joined battle with him. 4.","page":2467,"meaning_status":"draft","note":"ਛੋਹਨਿ: chhauhini, a division of army; 'ten thousand' and 'twenty thousand' and 'thirty thousand' appear as printed."}]},{"type":"verse","number":[5],"number_text":"੫।","page":2467,"lines":[{"gurmukhi":"ਸੂਰਜ ਕਹ ਸੈਨਾਪਤਿ ਕੀਨਾ। ਦਹਿਨੇ ਓਰ ਚੰਦ੍ਰ ਕਹ ਦੀਨਾ।","roman":"Sooraj kah sainaapti keenaa | dahine or chandr kah deenaa |","meaning_en":"He made the sun commander, and put the moon on the right.","page":2467,"meaning_status":"draft"},{"gurmukhi":"ਬਾਈ ਓਰ ਕਾਰਤਿਕੇ ਧਰਾ। ਜਿਹ ਪੌਰਖ ਕਿਨਹੂੰ ਨਹਿ ਹਰਾ। ੫।","roman":"Baaee or kaartike dharaa | jih paurakh kinhoon nahi haraa | 5 |","meaning_en":"On the left he set Kartikeya, whose prowess none has defeated. 5.","page":2467,"meaning_status":"draft"}]},{"type":"verse","number":[6],"number_text":"੬।","page":2467,"lines":[{"gurmukhi":"ਇਹ ਦਿਸ ਸਕਲ ਦੇਵ ਚੜਿ ਧਾਏ। ਉਹਿ ਦਿਸਿ ਤੇ ਦਾਨਵ ਮਿਲਿ ਆਏ।","roman":"Ih dis sakal dev chari dhaae | uhi disi te daanav mili aae |","meaning_en":"On this side all the gods marched; from that side the demons came together.","page":2467,"meaning_status":"draft"},{"gurmukhi":"ਬਾਜਨ ਭਾਤਿ ਭਾਤਿ ਤਨ ਬਾਜੇ। ਦੋਊ ਦਿਸਿਨ ਸੂਰਮਾ ਗਾਜੇ। ੬।","roman":"Baajan bhaati bhaati tan baaje | do'oo disin soormaa gaaje | 6 |","meaning_en":"Instruments of many kinds sounded; heroes roared on both sides. 6.","page":2467,"meaning_status":"draft"}]},{"type":"verse","number":[7],"number_text":"੭।","page":2467,"lines":[{"gurmukhi":"ਦੈ ਦੈ ਢੋਲ ਬਜਾਇ ਨਗਾਰੇ। ਪੀ ਪੀ ਭਏ ਕੈਫ ਮਤਵਾਰੇ।","roman":"Dai dai dhol bajaai nagaare | pee pee bhae kaiph matvaare |","meaning_en":"They beat drums and kettledrums, and drinking intoxicants they became crazed.","page":2467,"meaning_status":"draft"},{"gurmukhi":"ਤੀਸ ਸਹਸ ਛੋਹਨਿ ਦਲ ਸਾਥਾ। ਰਨ ਦਾਰੁਨੁ ਰਾਚਾ ਜਗਨਾਥਾ। ੭।","roman":"Tees sahas chhohni dal saathaa | ran daarunu raachaa jagnaathaa | 7 |","meaning_en":"With a host of thirty thousand chhauhinis, the fearful battle, O lord of the world, was joined. 7.","page":2467,"meaning_status":"draft","note":"ਜਗਨਾਥਾ: 'lord of the world'; whether an address or a name; uncertain."}]},{"type":"verse","number":[8],"number_text":"੮।","page":2467,"lines":[{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਮਾਰੂ ਜਬ ਬਾਜੋ। ਦੀਰਘ ਦਾੜ ਦੈਤ ਰਨ ਗਾਜੋ।","roman":"Bhaati bhaati maaroo jab baajo | deeragh daar dait ran gaajo |","meaning_en":"When the war-music sounded in many ways, the demon Dirghdadh roared in battle.","page":2467,"meaning_status":"draft"},{"gurmukhi":"ਤੀਛਨ ਬਾਨ ਦੋਊ ਦਿਸਿ ਬਹਹੀ। ਜਾਹਿ ਲਗਤ ਤਿਹ ਮਾਝ ਨ ਰਹਹੀ। ੮।","roman":"Teechhan baan do'oo disi bahhee | jaahi lagat tih maajh na rahhee | 8 |","meaning_en":"Sharp arrows flew from both sides; whom they struck did not remain in his place. 8.","page":2467,"meaning_status":"draft"}]},{"type":"verse","number":[9],"number_text":"੯।","page":2467,"lines":[{"gurmukhi":"ਧਾਵਤ ਭਏ ਦੇਵਤਾ ਜਬ ਹੀ। ਦਾਨਵ ਭਰੇ ਰੋਸ ਤਨ ਤਬ ਹੀ।","roman":"Dhaavat bhae devtaa jab hee | daanav bhare ros tan tab hee |","meaning_en":"When the gods charged, the demons were filled with rage.","page":2467,"meaning_status":"draft"},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਬਾਦਿਤ੍ਰ ਬਜਾਇ। ਖਤ੍ਰੀ ਉਠੇ ਖਿੰਗ ਖੁਨਸਾਇ। ੯।","roman":"Bhaati bhaati baaditr bajaai | khatree uthe khing khunsaai | 9 |","meaning_en":"Playing instruments in many ways, the warriors rose with their grey-feathered arrows; they hissed with rage. 9.","page":2467,"meaning_status":"draft","note":"ਖਿੰਗ ਖੁਨਸਾਇ: 'khing' (a type of arrow or horse), 'resentment'; uncertain."}]},{"type":"verse","number":[10],"number_text":"੧੦।","page":2467,"lines":[{"gurmukhi":"ਚਲੇ ਬਾਨ ਦੁਹੂੰ ਓਰ ਅਪਾਰਾ। ਬਿਛੂਆ ਬਰਛੀ ਬਜ੍ਰ ਹਜਾਰਾ।","roman":"Chale baan duhoon or apaaraa | bichhooaa barchhee bajr hajaaraa |","meaning_en":"Countless arrows flew from both sides, with scorpion-darts, lances and thousands of thunderbolts.","page":2467,"meaning_status":"draft"},{"gurmukhi":"ਗਦਾ ਗਰਿਸਟ ਜਵਨ ਪਰ ਝਰ ਹੀ। ਸ੍ਯੰਦਨ ਸਹਿਤ ਚੂਰਨ ਤਿਹ ਕਰ ਹੀ। ੧੦।","roman":"Gadaa garisat javan par jhar hee | syandan sahit chooran tih kar hee | 10 |","meaning_en":"Maces and great clubs fell upon whomever, crushing him together with his chariot. 10.","page":2467,"meaning_status":"draft"}]},{"type":"verse","number":[11],"number_text":"੧੧।","page":2469,"lines":[{"gurmukhi":"ਜਾ ਕੇ ਲਗੇ ਅੰਗ ਮੈ ਬਾਨਾ। ਕਰਾ ਬੀਰ ਤਿਹ ਸ੍ਵਰਗ ਪਯਾਨਾ।","roman":"Jaa ke lage ang mai baanaa | karaa beer tih svarag payaanaa |","meaning_en":"Whoever was struck by an arrow in the body, the warrior went to heaven.","page":2469,"meaning_status":"draft"},{"gurmukhi":"ਮਚ੍ਯੋ ਬੀਰ ਖੇਤ ਬਿਕਰਾਲਾ। ਨਾਚਤ ਭੂਤ ਪ੍ਰੇਤ ਬੇਤਾਲਾ। ੧੧।","roman":"Machyo beer khet bikraalaa | naachat bhoot pret betaalaa | 11 |","meaning_en":"A terrible battlefield rose up; ghosts, spirits and Betals danced. 11.","page":2469,"meaning_status":"draft"}]},{"type":"verse","number":[12],"number_text":"੧੨।","page":2469,"lines":[{"gurmukhi":"ਝੂਮਿ ਝੁਮਿ ਕਹੀ ਗਿਰੇ ਧਰਿਨ ਭਟ। ਜੁਦੇ ਜੁਦੇ ਕਹੀ ਅੰਗ ਪਰੇ ਕਟਿ।","roman":"Jhoomi jhumi kahee gire dharin bhat | jude jude kahee ang pare kati |","meaning_en":"Here and there, swaying, warriors fell on the ground; here and there limbs lay cut apart.","page":2469,"meaning_status":"draft"},{"gurmukhi":"ਚਲੀ ਸ੍ਰੋਨ ਕੀ ਨਦੀ ਬਿਰਾਜੈ। ਬੈਤਰੁਨੀ ਜਿਨ ਕੋ ਲਖਿ ਲਾਜੈ। ੧੨।","roman":"Chalee sron kee nadee biraajai | baitrunee jin ko lakhi laajai | 12 |","meaning_en":"A river of blood flowed, at which even the Baitarni would be ashamed. 12.","page":2469,"meaning_status":"draft"}]},{"type":"verse","number":[13],"number_text":"੧੩।","page":2469,"lines":[{"gurmukhi":"ਇਹ ਦਿਸਿ ਅਧਿਕ ਦੇਵਤਾ ਕੋਪੇ। ਉਹਿ ਦਿਸਿ ਪਾਵ ਦਾਨਵਨ ਰੋਪੇ।","roman":"Ih disi adhik devtaa kope | uhi disi paav daanvan rope |","meaning_en":"On this side the gods grew very angry; on that side the demons planted their feet.","page":2469,"meaning_status":"draft"},{"gurmukhi":"ਕੁਪਿ ਕੁਪਿ ਅਧਿਕ ਹ੍ਰਿਦਨ ਮੋ ਭਿਰੇ। ਜੂਝਿ ਜੂਝਿ ਗੇ ਬਹੁਰਿ ਨ ਫਿਰੇ। ੧੩।","roman":"Kupi kupi adhik hridan mo bhire | joojhi joojhi ge bahuri na phire | 13 |","meaning_en":"Raging, they grappled heart to heart; fighting, they fell and never turned back. 13.","page":2469,"meaning_status":"draft"}]},{"type":"verse","number":[14],"number_text":"੧੪।","page":2469,"lines":[{"gurmukhi":"ਕੋਟਿਕ ਕਟਕ ਤਹਾ ਕਟਿ ਮਰੇ। ਜੂਝੇ ਗਿਰੇ ਬਰੰਗਨਿਨ ਬਰੇ।","roman":"Kotik katak tahaa kati mare | joojhe gire barangnin bare |","meaning_en":"Crores of the host were cut down and killed; the fallen were wed by celestial women.","page":2469,"meaning_status":"draft","note":"ਬਰੰਗਨਿਨ ਬਰੇ: 'wed by the apsaras'; uncertain."},{"gurmukhi":"ਦੋਊ ਦਿਸਿ ਮਰੇ ਕਾਲ ਕੇ ਪ੍ਰੇਰੇ। ਗਿਰੇ ਭੂਮਿ ਰਨ ਫਿਰੇ ਨ ਫੇਰੇ। ੧੪।","roman":"Do'oo disi mare kaal ke prere | gire bhoomi ran phire na phere | 14 |","meaning_en":"On both sides they died, driven by Kal; they fell to the ground in battle and did not turn back though turned. 14.","page":2469,"meaning_status":"draft"}]},{"type":"verse","number":[15],"number_text":"੧੫।","page":2469,"lines":[{"gurmukhi":"ਸਤਿ ਸੰਧਿ ਦੇਵਿਸ ਇਤ ਧਾਯੋ। ਦੀਰਘ ਦਾੜ ਉਹ ਓਰ ਰਿਸਾਯੋ।","roman":"Sati sandhi devis it dhaayo | deeragh daar uh or risaayo |","meaning_en":"Satisandhi, lord of the gods, charged on this side; Dirghdadh raged on that.","page":2469,"meaning_status":"draft"},{"gurmukhi":"ਬਜ੍ਰ ਬਾਣ ਬਿਛੂਆ ਕੈ ਕੈ ਬ੍ਰਣ। ਜੂਝਿ ਜੂਝਿ ਭਟ ਗਿਰਤ ਭਏ ਰਣ। ੧੫।","roman":"Bajr baan bichhooaa kai kai bran | joojhi joojhi bhat girat bhae ran | 15 |","meaning_en":"With thunderbolts, arrows and scorpion-darts making wounds, warriors fought and fell in the battle. 15.","page":2469,"meaning_status":"draft"}]},{"type":"verse","number":[16],"number_text":"੧੬।","page":2469,"lines":[{"gurmukhi":"ਜੋਗਿਨਿ ਜਛ ਕਹੂੰ ਹਰਖਏ। ਭੂਤ ਪ੍ਰੇਤ ਨਾਚਤ ਕਹੂੰ ਭਏ।","roman":"Jogini jachh kahoon harkhae | bhoot pret naachat kahoon bhae |","meaning_en":"Yoginis and yakshas rejoiced here and there; ghosts and spirits danced here and there.","page":2469,"meaning_status":"draft"},{"gurmukhi":"ਕਹ ਕਹ ਕਹ ਕਲਿ ਸਾਹ ਸੁਨਾਵਤ। ਭੀਖਨ ਸੁਨੈ ਸਬਦ ਭੈ ਆਵਤ। ੧੬।","roman":"Kah kah kah kali saah sunaavat | bheekhan sunai sabad bhai aavat | 16 |","meaning_en":"The \"kah kah kah\" was made by Kali; hearing the fearful sound, fear came. 16.","page":2469,"meaning_status":"draft","note":"Sound-words ਕਹ ਕਹ ਕਹ left untranslated in sense."}]},{"type":"verse","number":[17],"number_text":"੧੭।","page":2469,"lines":[{"gurmukhi":"ਫਿਰੈ ਦੈਤ ਕਹੂੰ ਦਾਤ ਨਿਕਾਰੇ। ਬਮਤ ਸ੍ਰੋਨ ਕੇਤੇ ਰਨ ਮਾਰੇ।","roman":"Phirai dait kahoon daat nikaare | bamat sron kete ran maare |","meaning_en":"Demons went about with teeth bared; some vomited blood, killed in the battle.","page":2469,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਸਿਵਾ ਸਾਮੁਹਿ ਫਿਕਰਾਹੀ। ਭੂਤ ਪਿਸਾਚ ਮਾਸ ਕਹੂੰ ਖਾਹੀ। ੧੭।","roman":"Kahoon sivaa saamuhi phikraahee | bhoot pisaach maas kahoon khaahee | 17 |","meaning_en":"In places jackals howled face to face; ghosts and goblins ate flesh in places. 17.","page":2469,"meaning_status":"draft"}]},{"type":"verse","number":[18],"number_text":"੧੮।","page":2469,"lines":[{"gurmukhi":"ਸਕਟਾਬ੍ਯੂਹ ਰਚਾ ਸੁਰ ਪਤਿ ਤਬ। ਕ੍ਰੌਚਾਬ੍ਯੂਹ ਕਿਯੋ ਅਸੁਰਿਸ ਜਬ।","roman":"Saktaabyooh rachaa sur pati tab | krauchaabyooh kiyo asuris jab |","meaning_en":"Then Surpati, Indra, made the cart formation;","page":2469,"meaning_status":"draft"},{"gurmukhi":"ਮਚਿਯੋ ਤੁਮਲ ਜੁਧ ਤਹ ਭਾਰੀ। ਗਰਜਤ ਭਏ ਬੀਰ ਬਲ ਧਾਰੀ। ੧੮।","roman":"Machiyo tumal judh tah bhaaree | garjat bhae beer bal dhaaree | 18 |","meaning_en":"when the lord of demons made the heron formation. A great tumult of battle arose there; the mighty heroes roared. 18.","page":2469,"meaning_status":"draft","note":"Two vyuhas (battle formations): sakatavyuha (wagon) and kraunchavyuha (crane); the line ends with 'when the lord of the demons made ...' joined to the preceding line."}]},{"type":"verse","number":[19],"number_text":"੧੯।","page":2469,"lines":[{"gurmukhi":"ਜੂਝਿ ਗਏ ਜੋਧਾ ਕਹੀ ਭਾਰੇ। ਦੇਵ ਗਿਰੇ ਦਾਨਵ ਕਹੀ ਮਾਰੇ।","roman":"Joojhi gae jodhaa kahee bhaare | dev gire daanav kahee maare |","meaning_en":"Many warriors were killed; gods fell, demons were killed.","page":2469,"meaning_status":"draft"},{"gurmukhi":"ਬੀਰ ਖੇਤ ਐਸਾ ਤਹ ਪਰਾ। ਦੋਊ ਦਿਸਿ ਇਕ ਸੁਭਟ ਨ ਉਬਰਾ। ੧੯।","roman":"Beer khet aisaa tah paraa | do'oo disi ik subhat na ubraa | 19 |","meaning_en":"Such was the battlefield there that on neither side did one fine warrior survive. 19.","page":2469,"meaning_status":"draft"}]},{"type":"verse","number":[20],"number_text":"੨੦।","page":2469,"lines":[{"gurmukhi":"ਜੌ ਕ੍ਰਮ ਕ੍ਰਮ ਕਰਿ ਕਥਾ ਸੁਨਾਊ। ਗ੍ਰੰਥ ਬਢਨ ਤੇ ਅਧਿਕ ਡਰਾਊ।","roman":"Jau kram kram kari kathaa sunaaoo | granth badhan te adhik daraaoo |","meaning_en":"\"If I tell the tale in order, I fear the book will grow too large.","page":2469,"meaning_status":"draft"},{"gurmukhi":"ਤੀਸ ਸਹਸ ਛੂਹਨਿ ਜਹ ਜੋਧਾ। ਮੰਡ੍ਯੋ ਬੀਰ ਖੇਤ ਕਰਿ ਕ੍ਰੋਧਾ। ੨੦।","roman":"Tees sahas chhoohni jah jodhaa | mandyo beer khet kari krodhaa | 20 |","meaning_en":"Where thirty thousand chhauhinis of warriors, in rage, set up the battlefield. 20.","page":2469,"meaning_status":"draft","note":"ਮੰਡ੍ਯੋ: 'was set up'; the verb attaches to the field."}]},{"type":"verse","number":[21],"number_text":"੨੧।","page":2469,"lines":[{"gurmukhi":"ਪਤਿਅਨ ਸੋ ਪਤੀਅਨ ਭਿਰਿ ਮਰੇ। ਸ੍ਵਾਰਨ ਕੇ ਸ੍ਵਾਰਨ ਛੈ ਕਰੇ।","roman":"Patian so pateean bhiri mare | svaaran ke svaaran chhai kare |","meaning_en":"Foot soldiers fell fighting foot soldiers; horsemen cut down horsemen.","page":2469,"meaning_status":"draft"},{"gurmukhi":"ਰਥਿਯਨ ਤਹ ਰਥਿਯਨ ਕੌ ਘਾਯੋ। ਹਾਥਿਨ ਦੰਤੀ ਸ੍ਵਰਗ ਪਠਾਯੋ। ੨੧।","roman":"Rathiyan tah rathiyan kau ghaayo | haathin dantee svarag pathaayo | 21 |","meaning_en":"Charioteers killed charioteers; elephants were sent to heaven by elephants. 21.","page":2469,"meaning_status":"draft"}]},{"type":"verse","number":[22],"number_text":"੨੨।","page":2471,"lines":[{"gurmukhi":"ਦਲਪਤਿ ਸੌ ਦਲਪਤਿ ਲਰਿ ਮੂਆ। ਇਹ ਬਿਧਿ ਨਾਸ ਕਟਕ ਕਾ ਹੂਆ।","roman":"Dalapti sau dalapti lari mooaa | ih bidhi naas katak kaa hooaa |","meaning_en":"Commander died fighting commander; thus was the army destroyed.","page":2471,"meaning_status":"draft"},{"gurmukhi":"ਬਚੇ ਭੂਪ ਤੇ ਕੋਪ ਬਡਾਈ। ਮਾਡਤ ਭੇ ਹਠ ਠਾਨਿ ਲਰਾਈ। ੨੨।","roman":"Bache bhoop te kop badaaee | maadat bhe hath thaani laraaee | 22 |","meaning_en":"The kings who survived, in great rage, took up the fight with obstinacy. 22.","page":2471,"meaning_status":"draft"}]},{"type":"verse","number":[23],"number_text":"੨੩।","page":2471,"lines":[{"gurmukhi":"ਰਨ ਮਾਡਤ ਭੇ ਬਿਬਿਧ ਪ੍ਰਕਾਰਾ। ਦੈਤ ਰਾਟ ਅਰੁ ਦੇਵ ਨ੍ਰਿਪਾਰਾ।","roman":"Ran maadat bhe bibidh prakaaraa | dait raat aru dev nripaaraa |","meaning_en":"They engaged in the battle in many ways, the lord of the demons and the king of the gods.","page":2471,"meaning_status":"draft"},{"gurmukhi":"ਰਸਨਾ ਇਤੀ ਨ ਭਾਖ ਸੁਨਾਊ। ਗ੍ਰੰਥ ਬਢਨ ਤੇ ਅਤਿ ਡਰਪਾਊ। ੨੩।","roman":"Rasnaa itee na bhaakh sunaaoo | granth badhan te ati darpaaoo | 23 |","meaning_en":"My tongue cannot say or tell so much; I fear the book will grow too large.\" 23.","page":2471,"meaning_status":"draft","note":"The two lines continue the narrator's remark; rendered with the opening quotation as printed."}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","roman":"Bhujang prayaat chhand","meaning_en":"Bhujang Prayat metre.","page":2471,"meaning_status":"draft"},{"type":"verse","number":[24],"number_text":"੨੪।","page":2471,"lines":[{"gurmukhi":"ਕਹਾ ਲੌ ਬਖਾਨੌ ਮਹਾ ਲੋਹ ਮਚਿਯੋ। ਦੁਹੂੰ ਓਰ ਤੇ ਬੀਰ ਏਕੈ ਨ ਬਚਿਯੋ।","roman":"Kahaa lau bakhaanau mahaa loh machiyo | duhoon or te beer ekai na bachiyo |","meaning_en":"How far shall I describe it? A great clash arose; on both sides not one warrior survived.","page":2471,"meaning_status":"draft"},{"gurmukhi":"ਤਬੈ ਆਨਿ ਜੂਟੇ ਦੋਊ ਛਤ੍ਰਧਾਰੀ। ਪਰਾ ਲੋਹ ਗਾੜੋ ਕੰਪੀ ਭੂਮਿ ਸਾਰੀ। ੨੪।","roman":"Tabai aani joote do'oo chhatradhaaree | paraa loh gaaro kanpee bhoomi saaree | 24 |","meaning_en":"Then both the umbrella-bearing kings came and joined; thick iron fell and the whole earth trembled. 24.","page":2471,"meaning_status":"draft"}]},{"type":"verse","number":[25],"number_text":"੨੫।","page":2471,"lines":[{"gurmukhi":"ਜੁਟੇ ਰਾਵ ਦੋਊ ਉਠੀ ਧੂਰਿ ਐਸੀ। ਪ੍ਰਲੈ ਕਾਲ ਕੀ ਅਗਨਿ ਕੀ ਧੂਮ੍ਰ ਜੈਸੀ।","roman":"Jute raav do'oo uthee dhoori aisee | pralai kaal kee agni kee dhoomr jaisee |","meaning_en":"The two kings joined, and such dust arose as the smoke of the fire of the end of time.","page":2471,"meaning_status":"draft"},{"gurmukhi":"ਨ ਹਾਥੈ ਪਸਾਰਾ ਤਹਾ ਦ੍ਰਿਸਟਿ ਆਵੈ। ਕਛੂ ਭੂਮਿ ਆਕਾਸ ਹੇਰੋ ਨ ਜਾਵੈ। ੨੫।","roman":"Na haathai pasaaraa tahaa dristi aavai | kachhoo bhoomi aakaas hero na jaavai | 25 |","meaning_en":"A hand stretched out could not be seen there; neither earth nor sky could be made out. 25.","page":2471,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2471,"meaning_status":"draft"},{"type":"verse","number":[26],"number_text":"੨੬।","page":2471,"lines":[{"gurmukhi":"ਤੀਸ ਸਹਸ ਛੂਹਨਿ ਦਲ ਜਬ ਜੂਝਤ ਭਯੋ।","roman":"Tees sahas chhoohni dal jab joojhat bhayo |","meaning_en":"When the army of thirty thousand chhauhinis had been destroyed,","page":2471,"meaning_status":"draft"},{"gurmukhi":"ਦੁਹੂੰ ਨ੍ਰਿਪਨ ਕੇ ਕੋਪ ਅਧਿਕ ਤਬ ਹੀ ਭਯੋ।","roman":"Duhoon nripan ke kop adhik tab hee bhayo |","meaning_en":"the anger of both kings then grew greater still.","page":2471,"meaning_status":"draft"},{"gurmukhi":"ਪੀਸਿ ਪੀਸਿ ਰਦਨਛਦ ਬਿਸਿਖ ਪ੍ਰਹਾਰਹੀ।","roman":"Peesi peesi radanchhad bisikh prahaarhee |","meaning_en":"Grinding their lips they shot arrows,","page":2471,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜੋ ਜੀਯ ਭੀਤਰ ਕੋਪ ਸੁ ਪ੍ਰਗਟ ਦਿਖਾਰਹੀ। ੨੬।","roman":"Ho jo jeey bheetar kop su pragat dikhaarhee | 26 |","meaning_en":"and showed openly whatever rage was within their hearts. 26.","page":2471,"meaning_status":"draft","note":"ਰਦਨਛਦ: 'lip', literally 'tooth-cover'."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2471,"meaning_status":"draft"},{"type":"verse","number":[27],"number_text":"੨੭।","page":2471,"lines":[{"gurmukhi":"ਬੀਸ ਬਰਸ ਨਿਸੁ ਦਿਨ ਰਨ ਕਰਾ। ਦੁਹੂੰ ਨ੍ਰਿਪਨ ਤੇ ਏਕ ਨ ਟਰਾ।","roman":"Bees baras nisu din ran karaa | duhoon nripan te ek na taraa |","meaning_en":"For twenty years, night and day, they fought; neither of the two kings stirred.","page":2471,"meaning_status":"draft"},{"gurmukhi":"ਅੰਤ ਕਾਲ ਤਿਨ ਦੁਹੂੰ ਖਪਾਯੋ। ਉਹਿ ਕੌ ਇਹ ਇਹ ਕੌ ਉਹਿ ਘਾਯੋ। ੨੭।","roman":"Ant kaal tin duhoon khapaayo | uhi kau ih ih kau uhi ghaayo | 27 |","meaning_en":"In the end Death destroyed both of them: he killed the one and the other killed this. 27.","page":2471,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਛੰਦ","roman":"Bhujang chhand","meaning_en":"Bhujang metre.","page":2471,"meaning_status":"draft"},{"type":"verse","number":[28],"number_text":"੨੮।","page":2471,"lines":[{"gurmukhi":"ਜਬੈ ਛੂਹਨੀ ਤੀਸ ਸਾਹਸ੍ਰ ਮਾਰੇ। ਦੋਊ ਰਾਵਈ ਰਾਵ ਜੂਝੇ ਕਰਾਰੇ।","roman":"Jabai chhoohnee tees saahasr maare | do'oo raavaee raav joojhe karaare |","meaning_en":"When thirty thousand chhauhinis had been killed, the two kings, king against king, fought fiercely.","page":2471,"meaning_status":"draft"},{"gurmukhi":"ਮਚਿਯੋ ਲੋਹ ਗਾਢੌ ਉਠੀ ਅਗਨਿ ਜ੍ਵਾਲਾ। ਭਈ ਤੇਜ ਤੌਨੇ ਹੁਤੇ ਏਕ ਬਾਲਾ। ੨੮।","roman":"Machiyo loh gaadhau uthee agni jvaalaa | bhaee tej taune hute ek baalaa | 28 |","meaning_en":"Dense iron clashed and flames of fire rose; from that splendour a girl was born. 28.","page":2471,"meaning_status":"draft"}]},{"type":"verse","number":[29],"number_text":"੨੯।","page":2471,"lines":[{"gurmukhi":"ਤਿਸੀ ਕੋਪ ਕੀ ਅਗਨਿ ਤੇ ਬਾਲ ਹ੍ਵੈ ਕੈ। ਹਸੀ ਹਾਥ ਮੈ ਸਸਤ੍ਰ ਔ ਅਸਤ੍ਰ ਲੈ ਕੈ।","roman":"Tisee kop kee agni te baal hvai kai | hasee haath mai sasatr au asatr lai kai |","meaning_en":"From the fire of that rage, becoming a girl, she laughed, taking weapons and missiles in her hands.","page":2471,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਰੂਪ ਆਨੂਪ ਤਾ ਕੋ ਬਿਰਾਜੈ। ਲਖੇ ਤੇਜ ਤਾ ਕੋ ਸਸੀ ਸੂਰ ਲਾਜੈ। ੨੯।","roman":"Mahaa roop aanoop taa ko biraajai | lakhe tej taa ko sasee soor laajai | 29 |","meaning_en":"Her form was great and unequalled; seeing her radiance the moon and sun were ashamed. 29.","page":2471,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2471,"meaning_status":"draft"},{"type":"verse","number":[30],"number_text":"੩੦।","page":2471,"lines":[{"gurmukhi":"ਚਾਰਹੁ ਦਿਸਾ ਫਿਰੀ ਜਬ ਬਾਲਾ। ਜਾਨੋ ਨਾਗ ਰੂਪ ਕੀ ਮਾਲਾ।","roman":"Chaarhu disaa phiree jab baalaa | jaano naag roop kee maalaa |","meaning_en":"When the girl went round in all four directions, she was like a garland of serpent-forms.","page":2471,"meaning_status":"draft","note":"ਨਾਗ ਰੂਪ ਕੀ ਮਾਲਾ: 'a garland of snake-beauty'; uncertain."},{"gurmukhi":"ਐਸ ਨ ਕਤਹੂੰ ਪੁਰਖ ਨਿਹਾਰਾ। ਨਾਥ ਕਰੈ ਜਿਹ ਆਪੁ ਸੁਧਾਰਾ। ੩੦।","roman":"Ais na kathoon purakh nihaaraa | naath karai jih aapu sudhaaraa | 30 |","meaning_en":"No such man was seen anywhere whom she might make her lord by choosing him herself. 30.","page":2471,"meaning_status":"draft"}]},{"type":"verse","number":[31],"number_text":"੩੧।","page":2471,"lines":[{"gurmukhi":"ਫਿਰ ਜਿਯ ਮੈ ਇਹ ਭਾਤਿ ਬਿਚਾਰੀ। ਬਰੌ ਜਗਤ ਕੇ ਪਤਿਹਿ ਸੁਧਾਰੀ।","roman":"Phir jiy mai ih bhaati bichaaree | barau jagat ke patihi sudhaaree |","meaning_en":"Then she thought in her mind thus: \"I will wed the lord of the world, by choosing him.","page":2471,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਤੇ ਕਰੌ ਦੀਨ ਹ੍ਵੈ ਸੇਵਾ। ਹੋਇ ਪ੍ਰਸੰਨ ਕਾਲਿਕਾ ਦੇਵਾ। ੩੧।","roman":"Taa te karau deen hvai sevaa | hoi prasann kaalikaa devaa | 31 |","meaning_en":"Therefore I will serve humbly; may the goddess Kalika be pleased.\" 31.","page":2471,"meaning_status":"draft"}]},{"type":"verse","number":[32],"number_text":"੩੨।","page":2473,"lines":[{"gurmukhi":"ਅਧਿਕ ਸੁਚਿਤ ਹ੍ਵੈ ਕੀਏ ਸੁਮੰਤ੍ਰਾ। ਭਾਤਿ ਭਾਤਿ ਤਨ ਲਿਖਿ ਲਿਖਿ ਜੰਤ੍ਰਾ।","roman":"Adhik suchit hvai kee'e sumantraa | bhaati bhaati tan likhi likhi jantraa |","meaning_en":"With great concentration she did the charms, and wrote yantras in many ways.","page":2473,"meaning_status":"draft"},{"gurmukhi":"ਕ੍ਰਿਪਾ ਕਰੀ ਜਗਮਾਤ ਭਵਾਨੀ। ਇਹ ਬਿਧ ਬਤਿਯਾ ਤਾਹਿ ਬਖਾਨੀ। ੩੨।","roman":"Kripaa karee jagmaat bhavaanee | ih bidh batiyaa taahi bakhaanee | 32 |","meaning_en":"The mother of the world, Bhavani, showed mercy and spoke to her thus: 32.","page":2473,"meaning_status":"draft"}]},{"type":"verse","number":[33],"number_text":"੩੩।","page":2473,"lines":[{"gurmukhi":"ਕਰਿ ਜਿਨਿ ਸੋਕ ਹ੍ਰਿਦੈ ਤੈ ਪੁਤ੍ਰੀ। ਨਿਰੰਕਾਰ ਬਰਿ ਹੈ ਤੁਹਿ ਅਤ੍ਰੀ।","roman":"Kari jini sok hridai tai putree | nirankaar bari hai tuhi atree |","meaning_en":"\"Do not grieve in your heart, daughter; the Formless One will wed you, Atri's daughter.","page":2473,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਕਾ ਧ੍ਯਾਨ ਆਜੁ ਨਿਸਿ ਧਰਿਯਹੁ। ਕਹਿਹੈ ਜੁ ਕਛੂ ਸੋਈ ਤੁਮ ਕਰਿਯਹੁ। ੩੩।","roman":"Taa kaa dhyaan aaju nisi dhariyhu | kahihai ju kachhoo soee tum kariyhu | 33 |","meaning_en":"Fix your meditation on Him tonight; whatever He tells you, do.\" 33.","page":2473,"meaning_status":"draft","note":"ਅਤ੍ਰੀ: printed so; read as a name or address (descendant of Atri?) or 'weapon-bearer'; uncertain."}]},{"type":"verse","number":[34],"number_text":"੩੪।","page":2473,"lines":[{"gurmukhi":"ਜਬ ਅਸ ਬਰ ਤਿਹ ਦਿਯੋ ਭਵਾਨੀ। ਪ੍ਰਫੁਲਿਤ ਭਈ ਜਗਤ ਕੀ ਰਾਨੀ।","roman":"Jab as bar tih diyo bhavaanee | praphulit bhaee jagat kee raanee |","meaning_en":"When Bhavani gave her this boon, the queen of the world was delighted.","page":2473,"meaning_status":"draft"},{"gurmukhi":"ਅਤਿ ਪਵਿਤ੍ਰ ਨਿਸਿ ਹ੍ਵੈ ਛਿਤ ਸੋਈ। ਜਿਹ ਠਾ ਔਰ ਨ ਦੂਸਰ ਕੋਈ। ੩੪।","roman":"Ati pavitr nisi hvai chhit soee | jih thaa aur na doosar koee | 34 |","meaning_en":"That night became very pure on the earth, a place where there was no other. 34.","page":2473,"meaning_status":"draft","note":"ਛਿਤ ਸੋਈ: 'she slept on the ground'; uncertain."}]},{"type":"verse","number":[35],"number_text":"੩੫।","page":2473,"lines":[{"gurmukhi":"ਅਰਧ ਰਾਤ੍ਰਿ ਬੀਤਤ ਭੀ ਜਬ ਹੀ। ਆਗ੍ਯਾ ਭਈ ਨਾਥ ਕੀ ਤਬ ਹੀ।","roman":"Aradh raatri beetat bhee jab hee | aagyaa bhaee naath kee tab hee |","meaning_en":"When midnight had passed, the command of the Lord came then:","page":2473,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਵਾਸ ਬੀਰਜ ਦਾਨਵ ਜਬ ਮਰਿ ਹੈ। ਤਿਹ ਪਾਛੇ ਸੁੰਦਰਿ ਮੁਹਿ ਬੁਰਿ ਹੈ। ੩੫।","roman":"Svaas beeraj daanav jab mari hai | tih paachhe sundri muhi buri hai | 35 |","meaning_en":"\"When the demon Svas Birj dies, after that the beautiful one will wed me.\" 35.","page":2473,"meaning_status":"draft","note":"ਬੁਰਿ: printed ਬੁਰਿ (literally 'private part'); read as ਬਰਿ 'will wed' from the sense; uncertain. Svas Birj: the demon's name; uncertain."}]},{"type":"verse","number":[36],"number_text":"੩੬।","page":2473,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਤਿਹ ਆਗ੍ਯਾ ਜਬ ਭਈ। ਦਿਨਮਨਿ ਚੜਿਯੋ ਰੈਨਿ ਮਿਟਿ ਗਈ।","roman":"Ih bidhi tih aagyaa jab bhaee | dinamni chariyo raini miti gaee |","meaning_en":"When the command came to her in this way, the sun rose and the night was gone.","page":2473,"meaning_status":"draft"},{"gurmukhi":"ਸਾਜੇ ਸਸਤ੍ਰ ਚੰਚਲਾ ਤਬ ਹੀ। ਰਨ ਕੌ ਚਲੀ ਸਾਥ ਲੈ ਸਬ ਹੀ। ੩੬।","roman":"Saaje sasatr chanchlaa tab hee | ran kau chalee saath lai sab hee | 36 |","meaning_en":"The fickle girl then arranged her weapons, and went to the battle with all of them. 36.","page":2473,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2473,"meaning_status":"draft"},{"type":"verse","number":[37],"number_text":"੩੭।","page":2473,"lines":[{"gurmukhi":"ਜਹਾ ਸਤ੍ਰੁ ਕੋ ਪੁਰ ਹੁਤੋ ਤਿਤ ਕਹ ਕਿਯਾ ਪਯਾਨ।","roman":"Jahaa satru ko pur huto tit kah kiyaa payaan |","meaning_en":"She marched to where the enemy's city was,","page":2473,"meaning_status":"draft"},{"gurmukhi":"ਬਿਕਟ ਅਸੁਰ ਕੋ ਬੇੜਿ ਗੜ ਦਹਦਿਸ ਦਿਯੋ ਨਿਸਾਨ। ੩੭।","roman":"Bikat asur ko beri gar dahdis diyo nisaan | 37 |","meaning_en":"and, surrounding the fearful demon's fort, put banners on all ten sides. 37.","page":2473,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2473,"meaning_status":"draft"},{"type":"verse","number":[38],"number_text":"੩੮।","page":2473,"lines":[{"gurmukhi":"ਦੁੰਦਭਿ ਸੁਨਾ ਸ੍ਰਵਨ ਮਹਿ ਜਬ ਹੀ। ਜਾਗਾ ਅਸੁਰ ਕੋਪ ਕਰਿ ਤਬ ਹੀ।","roman":"Dundbhi sunaa sravan mahi jab hee | jaagaa asur kop kari tab hee |","meaning_en":"When the drum was heard in his ears, the demon awoke with rage.","page":2473,"meaning_status":"draft"},{"gurmukhi":"ਐਸਾ ਕਵਨ ਜੁ ਹਮ ਪਰ ਆਯੋ। ਰਕਤ ਬਿੰਦ ਮੈ ਰਨਹਿ ਹਰਾਯੋ। ੩੮।","roman":"Aisaa kavan ju ham par aayo | rakat bind mai ranhi haraayo | 38 |","meaning_en":"\"Who is this who has come against us? In a drop of blood I defeated all in battle. 38.","page":2473,"meaning_status":"draft"}]},{"type":"verse","number":[39],"number_text":"੩੯।","page":2473,"lines":[{"gurmukhi":"ਇੰਦ੍ਰ ਚੰਦ੍ਰ ਸੂਰਜ ਹਮ ਜੀਤਾ। ਰਾਵਨ ਜਿਤਾ ਹਰੀ ਜਿਨ ਸੀਤਾ।","roman":"Indr chandr sooraj ham jeetaa | raavan jitaa haree jin seetaa |","meaning_en":"I conquered Indra, the moon and the sun; I conquered Ravan who took away Sita.","page":2473,"meaning_status":"draft"},{"gurmukhi":"ਏਕ ਦਿਵਸ ਮੋ ਸੌ ਸਿਵ ਲਰਾ। ਤਾਹਿ ਭਜਾਯੋ ਮੈ ਨਹਿ ਟਰਾ। ੩੯।","roman":"Ek divas mo sau siv laraa | taahi bhajaayo mai nahi taraa | 39 |","meaning_en":"One day Shiva fought me; I made him flee; I did not stir. 39.","page":2473,"meaning_status":"draft"}]},{"type":"verse","number":[40],"number_text":"੪੦।","page":2473,"lines":[{"gurmukhi":"ਸਸਤ੍ਰ ਸਾਜ ਦਾਨਵ ਰਨ ਆਵਾ। ਅਮਿਤ ਕੋਪ ਕਰਿ ਸੰਖ ਬਜਾਵਾ।","roman":"Sasatr saaj daanav ran aavaa | amit kop kari sankh bajaavaa |","meaning_en":"The demon arrived at the battle with his weapons ready; in great rage he blew the conch.","page":2473,"meaning_status":"draft"},{"gurmukhi":"ਕਾਪੀ ਭੂਮ ਗਗਨ ਘਹਰਾਨਾ। ਅਤੁਲ ਬੀਰਜ ਕਿਹ ਓਰ ਰਿਸਾਨਾ। ੪੦।","roman":"Kaapee bhoom gagan ghahraanaa | atul beeraj kih or risaanaa | 40 |","meaning_en":"The earth shook, the sky trembled; the one of incomparable strength raged against whom? 40.","page":2473,"meaning_status":"draft"}]},{"type":"verse","number":[41],"number_text":"੪੧।","page":2473,"lines":[{"gurmukhi":"ਇਤਿ ਦਿਸਿ ਦੂਲਹ ਦੇਈ ਕੁਮਾਰੀ। ਸਸਤ੍ਰ ਸਾਜਿ ਰਥਿ ਕਰੀ ਸਵਾਰੀ।","roman":"Iti disi doolah de'ee kumaaree | sasatr saaji rathi karee savaaree |","meaning_en":"On this side Dulah De, the girl, arranged her weapons and rode her chariot.","page":2473,"meaning_status":"draft"},{"gurmukhi":"ਸਸਤ੍ਰਨ ਕਰਿ ਪ੍ਰਨਾਮ ਤਿਹ ਕਾਲਾ। ਛਾਡਤ ਭੀ ਰਨ ਬਿਸਿਖ ਕਰਾਲਾ। ੪੧।","roman":"Sastran kari pranaam tih kaalaa | chhaadat bhee ran bisikh karaalaa | 41 |","meaning_en":"Bowing to her weapons and to Kal, she loosed fearful arrows in the battle. 41.","page":2473,"meaning_status":"draft"}]},{"type":"verse","number":[42],"number_text":"੪੨।","page":2473,"lines":[{"gurmukhi":"ਲਗੇ ਬਿਸਿਖ ਜਬ ਅੰਗ ਕਰਾਰੇ। ਦਾਨਵ ਭਰੇ ਕੋਪ ਤਬ ਭਾਰੇ।","roman":"Lage bisikh jab ang karaare | daanav bhare kop tab bhaare |","meaning_en":"When the arrows struck his strong body, the demons became very angry.","page":2473,"meaning_status":"draft"},{"gurmukhi":"ਮੁਖ ਤੇ ਸ੍ਵਾਸ ਸ੍ਰਮਿਤ ਹ੍ਵੈ ਕਾਢੇ। ਤਿਨ ਤੇ ਅਮਿਤ ਅਸੁਰ ਰਨ ਬਾਢੇ। ੪੨।","roman":"Mukh te svaas sramit hvai kaadhe | tin te amit asur ran baadhe | 42 |","meaning_en":"They breathed out from their mouths, weary; from these breaths countless demons grew in the battle. 42.","page":2473,"meaning_status":"draft"}]},{"type":"verse","number":[43],"number_text":"੪੩।","page":2473,"lines":[{"gurmukhi":"ਤਿਨ ਕਾ ਬਾਲ ਬਹੁਰਿ ਬਧ ਕਰਾ। ਉਨ ਕਾ ਸ੍ਰੋਨ ਪ੍ਰਿਥੀ ਪਰ ਪਰਾ।","roman":"Tin kaa baal bahuri badh karaa | un kaa sron prithee par paraa |","meaning_en":"Then the girl killed them; their blood fell to the earth.","page":2473,"meaning_status":"draft"},{"gurmukhi":"ਅਗਨਿਤ ਬਢੇ ਤਬੈ ਤਹ ਦਾਨਵ। ਭਛਤ ਭਏ ਪਕਰਿ ਕਰਿ ਮਾਨਵ। ੪੩।","roman":"Agnit badhe tabai tah daanav | bhachhat bhae pakri kari maanav | 43 |","meaning_en":"Countless demons then rose there and began to seize and eat men. 43.","page":2473,"meaning_status":"draft"}]},{"type":"verse","number":[44],"number_text":"੪੪।","page":2475,"lines":[{"gurmukhi":"ਜਬ ਅਬਲਾ ਕੇ ਸੁਭਟ ਚਬਾਏ। ਦੂਲਹ ਦੇ ਤਿਹ ਬਿਸਿਖ ਲਗਾਏ।","roman":"Jab ablaa ke subhat chabaae | doolah de tih bisikh lagaae |","meaning_en":"When they chewed the warriors of the girl, Dulah De shot arrows at them.","page":2475,"meaning_status":"draft"},{"gurmukhi":"ਬੁੰਦਕਾ ਪਰਤ ਸ੍ਰੋਨ ਭੂਅ ਭਏ। ਉਪਜਿ ਅਸੁਰ ਸਾਮਹਿ ਉਠਿ ਧਏ। ੪੪।","roman":"Bundkaa parat sron bhooa bhae | upji asur saamhi uthi dhae | 44 |","meaning_en":"As drops of blood fell on the ground, demons were born and rose up and charged. 44.","page":2475,"meaning_status":"draft"}]},{"type":"verse","number":[45],"number_text":"੪੫।","page":2475,"lines":[{"gurmukhi":"ਪੁਨਿ ਅਬਲਾ ਤਿਨ ਬਿਸਿਖ ਪ੍ਰਹਾਰੇ। ਚਲੇ ਸ੍ਰੋਨ ਕੇ ਤਹਾ ਪਨਾਰੇ।","roman":"Puni ablaa tin bisikh prahaare | chale sron ke tahaa panaare |","meaning_en":"Again the girl shot arrows at them; streams of blood flowed.","page":2475,"meaning_status":"draft"},{"gurmukhi":"ਅਸੁਰ ਅਨੰਤ ਤਹਾ ਤੇ ਜਾਗੇ। ਜੂਝਤ ਭਏ ਪੈਗ ਨਹਿ ਭਾਗੇ। ੪੫।","roman":"Asur anant tahaa te jaage | joojhat bhae paig nahi bhaage | 45 |","meaning_en":"Endless demons awoke from there; they fought and did not flee a step. 45.","page":2475,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਛੰਦ","roman":"Bhujang chhand","meaning_en":"Bhujang metre.","page":2475,"meaning_status":"draft"},{"type":"verse","number":[46],"number_text":"੪੬।","page":2475,"lines":[{"gurmukhi":"ਜਬੈ ਓਰ ਚਾਰੌ ਉਠੇ ਦੈਤ ਬਾਨੀ। ਕਏ ਕੋਪ ਗਾੜੋ ਲਏ ਧੂਲਿਧਾਨੀ।","roman":"Jabai or chaarau uthe dait baanee | kae kop gaaro lae dhoolidhaanee |","meaning_en":"When the demons rose on all four sides, in rage they took up their dust-vessels.","page":2475,"meaning_status":"draft","note":"ਧੂਲਿਧਾਨੀ: obscure; read as 'dust-holders/dust'; uncertain."},{"gurmukhi":"ਕਿਤੇ ਮੂੰਡ ਮੁੰਡੇ ਕਿਤੇ ਅਰਧ ਮੁੰਡੇ। ਕਿਤੇ ਕੇਸ ਧਾਰੀ ਸਿਪਾਹੀ ਪ੍ਰਚੰਡੇ। ੪੬।","roman":"Kite moond munde kite aradh munde | kite kes dhaaree sipaahee prachande | 46 |","meaning_en":"Some with heads shaved, some half-shaved, some hair-wearing fierce soldiers. 46.","page":2475,"meaning_status":"draft"}]},{"type":"verse","number":[47],"number_text":"੪੭।","page":2475,"lines":[{"gurmukhi":"ਜਿਤੇ ਦੈਤ ਉਠੇ ਤਿਤੇ ਬਾਲ ਮਾਰੇ। ਵੁਠੇ ਆਨਿ ਬਾਨਾਨਿ ਬਾਂਕੇ ਡਰਾਰੇ।","roman":"Jite dait uthe tite baal maare | vuthe aani baanaani baanke daraare |","meaning_en":"As many demons as rose, so many the girl killed; the terrifying ones rose with sharp arrows.","page":2475,"meaning_status":"draft","note":"ਵੁਠੇ ਆਨਿ ਬਾਨਾਨਿ ਬਾਂਕੇ ਡਰਾਰੇ: obscure; sense given; uncertain."},{"gurmukhi":"ਜਿਤੇ ਸ੍ਵਾਸ ਛੋਰੈ ਉਠੈ ਦੈਤ ਭਾਰੇ। ਹਠੀ ਮਾਰ ਹੀ ਮਾਰਿ ਕੈ ਕੈ ਪਧਾਰੇ। ੪੭।","roman":"Jite svaas chhorai uthai dait bhaare | hathee maar hee maari kai kai padhaare | 47 |","meaning_en":"As many mighty demons rose breathing, the obstinate ones came on, crying \"kill, kill\". 47.","page":2475,"meaning_status":"draft"}]},{"type":"verse","number":[48],"number_text":"੪੮।","page":2475,"lines":[{"gurmukhi":"ਕਿਤੇ ਕੋਪ ਕੈ ਬੀਰ ਬਾਲਾ ਸੰਘਾਰੇ। ਜਿਤੇ ਦੈਤ ਢੂਕੇ ਮਹਾ ਬਾਹੁ ਭਾਰੇ।","roman":"Kite kop kai beer baalaa sanghaare | jite dait dhooke mahaa baahu bhaare |","meaning_en":"She slew many warriors in rage; as many demons as came near, with great strong arms,","page":2475,"meaning_status":"draft"},{"gurmukhi":"ਤਿਤ੍ਯੋ ਕਾ ਗਿਰਾ ਆਨਿ ਕੈ ਸ੍ਰੋਨ ਭੂ ਪੈ। ਉਠੇ ਨੇਕ ਜੋਧਾ ਮਹਾ ਭੀਮ ਰੂਪੇ। ੪੮।","roman":"Tityo kaa giraa aani kai sron bhoo pai | uthe nek jodhaa mahaa bheem roope | 48 |","meaning_en":"so many of their blood fell to the earth; many warriors rose, great and dreadful in form. 48.","page":2475,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2475,"meaning_status":"draft"},{"type":"verse","number":[49],"number_text":"੪੯।","page":2475,"lines":[{"gurmukhi":"ਤਿਨ ਕੀ ਭੂਮਿ ਜੁ ਮੇਜਾ ਪਰਹੀ। ਤਿਨ ਤੇ ਅਮਿਤ ਦੈਤ ਬਪੁ ਧਰਹੀ।","roman":"Tin kee bhoomi ju mejaa parhee | tin te amit dait bapu dharhee |","meaning_en":"The earth where their marrow fell, from it countless demons took form.","page":2475,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਰੋਨ ਗਿਰੈ ਤਿਨ ਕੋ ਧਰ ਮਾਹੀ। ਰਥੀ ਗਜੀ ਬਾਜੀ ਹ੍ਵੈ ਜਾਹੀ। ੪੯।","roman":"Sron girai tin ko dhar maahee | rathee gajee baajee hvai jaahee | 49 |","meaning_en":"Blood that fell from them on the earth became charioteers, elephant-riders and horsemen. 49.","page":2475,"meaning_status":"draft"}]},{"type":"verse","number":[50],"number_text":"੫੦।","page":2475,"lines":[{"gurmukhi":"ਪ੍ਰਾਨ ਤਜਤ ਸ੍ਵਾਸਾ ਅਰਿ ਤਜੈ। ਤਿਨ ਤੇ ਅਮਿਤ ਅਸੁਰ ਹ੍ਵੈ ਭਜੈ।","roman":"Praan tajat svaasaa ari tajai | tin te amit asur hvai bhajai |","meaning_en":"When the enemies gave up life, they breathed out; from these breaths countless demons arose and fled.","page":2475,"meaning_status":"draft","note":"Printed so; sense uncertain."},{"gurmukhi":"ਕਿਤਕ ਅਸੁਰ ਡਾਰਤ ਭੂਅ ਲਾਰੈ। ਤਿਨ ਤੇ ਅਨਿਕ ਦੈਤ ਤਨ ਧਾਰੈ। ੫੦।","roman":"Kitak asur daarat bhooa laarai | tin te anik dait tan dhaarai | 50 |","meaning_en":"Some demons, thrown on the ground, struck it; from them many demons took bodies. 50.","page":2475,"meaning_status":"draft"}]},{"type":"verse","number":[51],"number_text":"੫੧।","page":2475,"lines":[{"gurmukhi":"ਤਿਨ ਤੇ ਤਜਤ ਅਸੁਰ ਜੇ ਸ੍ਵਾਸਾ। ਤਿਨ ਤੇ ਦਾਨਵ ਹੋਹਿ ਪ੍ਰਕਾਸਾ।","roman":"Tin te tajat asur je svaasaa | tin te daanav hohi prakaasaa |","meaning_en":"From those who gave up breath, demons appeared.","page":2475,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤਕ ਮਰਤ ਕੈ ਤਰੁਨਿ ਸੰਘਾਰੇ। ਦਸੌ ਦਿਸਿਨ ਮਹਿ ਅਸੁਰ ਨਿਹਾਰੇ। ੫੧।","roman":"Kitak marat kai taruni sanghaare | dasau disin mahi asur nihaare | 51 |","meaning_en":"Some in dying killed the girl; she saw demons in all ten directions. 51.","page":2475,"meaning_status":"draft"}]},{"type":"verse","number":[52],"number_text":"੫੨।","page":2475,"lines":[{"gurmukhi":"ਚਿਤ ਮੋ ਕਿਯਾ ਕਾਲਕਾ ਧ੍ਯਾਨਾ। ਦਰਸਨ ਦਿਯਾ ਆਨਿ ਭਗਵਾਨਾ।","roman":"Chit mo kiyaa kaalkaa dhyaanaa | darsan diyaa aani bhagvaanaa |","meaning_en":"She meditated on Kalika in her mind, and the Lord came and gave her sight.","page":2475,"meaning_status":"draft"},{"gurmukhi":"ਕਰਿ ਪ੍ਰਨਾਮ ਚਰਨਨ ਉਠਿ ਪਰੀ। ਬਿਨਤੀ ਭਾਤਿ ਅਨਿਕ ਤਨ ਕਰੀ। ੫੨।","roman":"Kari pranaam charnan uthi paree | bintee bhaati anik tan karee | 52 |","meaning_en":"She bowed, rose and fell at his feet, and made petition in many ways. 52.","page":2475,"meaning_status":"draft"}]},{"type":"verse","number":[53],"number_text":"੫੩।","page":2475,"lines":[{"gurmukhi":"ਸਤਿ ਕਾਲ ਮੈ ਦਾਸ ਤਿਹਾਰੀ। ਅਪਨੀ ਜਾਨਿ ਕਰੋ ਪ੍ਰਤਿਪਾਰੀ।","roman":"Sati kaal mai daas tihaaree | apnee jaani karo pratipaaree |","meaning_en":"\"True Kal, I am your servant; count me your own and cherish me.","page":2475,"meaning_status":"draft"},{"gurmukhi":"ਗੁਨ ਅਵਗੁਨ ਮੁਰ ਕਛੁ ਨ ਨਿਹਾਰਹੁ। ਬਾਹਿ ਗਹੇ ਕੀ ਲਾਜ ਬਿਚਾਰਹੁ। ੫੩।","roman":"Gun avgun mur kachhu na nihaarhu | baahi gahe kee laaj bichaarhu | 53 |","meaning_en":"Do not look at my merits and faults; think of the shame of having held me by the arm. 53.","page":2475,"meaning_status":"draft"}]},{"type":"verse","number":[54],"number_text":"੫੪।","page":2475,"lines":[{"gurmukhi":"ਹਮ ਹੈ ਸਰਨਿ ਤੋਰ ਮਹਾਰਾਜਾ। ਤੁਮ ਕਹ ਬਾਹਿ ਗਹੇ ਕੀ ਲਾਜਾ।","roman":"Ham hai sarni tor mahaaraajaa | tum kah baahi gahe kee laajaa |","meaning_en":"I am in your shelter, great king; you have the shame of having held me by the arm.","page":2475,"meaning_status":"draft"},{"gurmukhi":"ਜੌ ਤਵ ਭਗਤ ਨੈਕ ਦੁਖ ਪੈ ਹੈ। ਦੀਨ ਦ੍ਯਾਲ ਪ੍ਰਭੁ ਬਿਰਦੁ ਲਜੈ ਹੈ। ੫੪।","roman":"Jau tav bhagat naik dukh pai hai | deen dyaal prabhu birdu lajai hai | 54 |","meaning_en":"If your devotee suffers even a little, the Lord, merciful to the poor, will be shamed in his nature. 54.","page":2475,"meaning_status":"draft"}]},{"type":"verse","number":[55],"number_text":"੫੫।","page":2475,"lines":[{"gurmukhi":"ਔ ਕਹ ਲਗ ਮੈ ਕਰੌ ਪੁਕਾਰਾ। ਤੈ ਘਟ ਘਟ ਕੀ ਜਾਨ ਨਿਹਾਰਾ।","roman":"Au kah lag mai karau pukaaraa | tai ghat ghat kee jaan nihaaraa |","meaning_en":"How far shall I cry out? You see into every heart.","page":2475,"meaning_status":"draft"},{"gurmukhi":"ਕਹੀ ਏਕ ਕਰਿ ਸਹਸ ਪਛਿਨਯਹੁ। ਆਪੁ ਆਪਨੇ ਬਿਰਦਹਿ ਜਨਿਯਹੁ। ੫੫।","roman":"Kahee ek kari sahas pachhinayhu | aapu aapne biradhi janiyhu | 55 |","meaning_en":"Take what I say as one for a thousand; know it as your own nature.\" 55.","page":2475,"meaning_status":"draft","note":"ਸਹਸ ਪਛਿਨਯਹੁ: 'recognise a thousand'; uncertain."}]},{"type":"verse","number":[56],"number_text":"੫੬।","page":2477,"lines":[{"gurmukhi":"ਹੜ ਹੜ ਸੁਨਤ ਕਾਲ ਬਚ ਹਸਾ। ਭਗਤ ਹੇਤ ਕਟਿ ਸੌ ਅਸਿ ਕਸਾ।","roman":"Har har sunat kaal bach hasaa | bhagat het kati sau asi kasaa |","meaning_en":"Hearing the cry \"har har\", Kal smiled; for his devotee he drew his sword from his waist.","page":2477,"meaning_status":"draft"},{"gurmukhi":"ਚਿੰਤ ਨ ਕਰਿ ਮੈ ਅਸੁਰ ਸੰਘਰਿ ਹੌ। ਸਕਲ ਸੋਕ ਭਗਤਨ ਕੋ ਹਰਿ ਹੌ। ੫੬।","roman":"Chint na kari mai asur sanghri hau | sakal sok bhagtan ko hari hau | 56 |","meaning_en":"\"Do not worry; I will kill the demons and take away all the sorrow of my devotees.\" 56.","page":2477,"meaning_status":"draft"}]},{"type":"verse","number":[57],"number_text":"੫੭।","page":2477,"lines":[{"gurmukhi":"ਅਮਿਤ ਅਸੁਰ ਉਪਜੇ ਥੇ ਜਹਾ। ਪ੍ਰਾਪਤਿ ਭਯੋ ਕਾਲ ਚਲਿ ਤਹਾ।","roman":"Amit asur upje the jahaa | praapti bhayo kaal chali tahaa |","meaning_en":"Where countless demons had arisen, Kal arrived.","page":2477,"meaning_status":"draft"},{"gurmukhi":"ਚਹੂੰ ਕਰਨ ਕਰਿ ਸਸਤ੍ਰ ਪ੍ਰਹਾਰੇ। ਦੈਤ ਅਨੇਕ ਮਾਰ ਹੀ ਡਾਰੇ। ੫੭।","roman":"Chahoon karan kari sasatr prahaare | dait anek maar hee daare | 57 |","meaning_en":"With four hands he shot weapons and killed many demons. 57.","page":2477,"meaning_status":"draft"}]},{"type":"verse","number":[58],"number_text":"੫੮।","page":2477,"lines":[{"gurmukhi":"ਤਿਨ ਤੇ ਪਰਾ ਸ੍ਰੋਨ ਜੇ ਭੂ ਪਰ। ਅਸੁਰ ਅਮਿਤ ਧਾਵਤ ਭੇ ਉਠਿ ਕਰਿ।","roman":"Tin te paraa sron je bhoo par | asur amit dhaavat bhe uthi kari |","meaning_en":"The blood from them that fell on the earth, countless demons rose up and charged.","page":2477,"meaning_status":"draft"},{"gurmukhi":"ਤਿਨ ਤੇ ਚਲਤ ਸ੍ਵਾਸ ਤੇ ਛੂਟੇ। ਅਮਿਤ ਦੈਤ ਰਨ ਕਹ ਉਠਿ ਜੂਟੇ। ੫੮।","roman":"Tin te chalat svaas te chhoote | amit dait ran kah uthi joote | 58 |","meaning_en":"From the breaths they released, countless demons rose and joined the battle. 58.","page":2477,"meaning_status":"draft"}]},{"type":"verse","number":[59],"number_text":"੫੯।","page":2477,"lines":[{"gurmukhi":"ਤੇ ਸਭ ਕਾਲ ਤਨਿਕ ਮੋ ਮਾਰੇ। ਚਲਤ ਭਏ ਭੂਅ ਰੁਧਿਰ ਪਨਾਰੇ।","roman":"Te sabh kaal tanik mo maare | chalat bhae bhooa rudhir panaare |","meaning_en":"Kal killed them all in an instant; streams of blood flowed on the earth.","page":2477,"meaning_status":"draft"},{"gurmukhi":"ਉਪਜਿ ਅਸੁਰ ਤਾ ਤੇ ਬਹੁ ਠਾਢੇ। ਧਾਵਤ ਭਏ ਰੋਸ ਕਰਿ ਗਾਢੇ। ੫੯।","roman":"Upji asur taa te bahu thaadhe | dhaavat bhae ros kari gaadhe | 59 |","meaning_en":"From it many demons stood up, rushing in dense rage. 59.","page":2477,"meaning_status":"draft"}]},{"type":"verse","number":[60],"number_text":"੬੦।","page":2477,"lines":[{"gurmukhi":"ਮਾਰਿ ਮਾਰਿ ਦਿਸਿ ਦਸੌ ਪੁਕਾਰੈ। ਤਿਨ ਤੇ ਅਮਿਤ ਅਸੁਰ ਤਨ ਧਾਰੈ।","roman":"Maari maari disi dasau pukaarai | tin te amit asur tan dhaarai |","meaning_en":"Crying \"kill, kill\" in all ten directions, from them countless demons took form.","page":2477,"meaning_status":"draft"},{"gurmukhi":"ਬਾਰ ਚਲਤ ਤਿਨ ਤੇ ਜੇ ਦੌਰੈ। ਤਿਨ ਤੇ ਹੋਤ ਅਸੁਰ ਪ੍ਰਗਟੌਰੈ। ੬੦।","roman":"Baar chalat tin te je daurai | tin te hot asur pragtaurai | 60 |","meaning_en":"Those who ran with the wind from them, from them demons appeared again and again. 60.","page":2477,"meaning_status":"draft"}]},{"type":"verse","number":[61],"number_text":"੬੧।","page":2477,"lines":[{"gurmukhi":"ਲਗੇ ਘਾਇ ਜੇ ਸ੍ਰੋਨ ਬਮਾਹੀ। ਤਿਹ ਤੇ ਗਜ ਬਾਜੀ ਹ੍ਵੈ ਜਾਹੀ।","roman":"Lage ghaai je sron bamaahee | tih te gaj baajee hvai jaahee |","meaning_en":"From wounds which vomited blood, elephants and horses came.","page":2477,"meaning_status":"draft"},{"gurmukhi":"ਤਿਹ ਤੇ ਚਲਿਤ ਅਮਿਤ ਜੋ ਸ੍ਵਾਸਾ। ਤਿਨ ਤੇ ਅਸੁਰ ਕਰਤ ਪਰਗਾਸਾ। ੬੧।","roman":"Tih te chalit amit jo svaasaa | tin te asur karat pargaasaa | 61 |","meaning_en":"From the breath that flowed from them, demons were made to appear. 61.","page":2477,"meaning_status":"draft"}]},{"type":"verse","number":[62],"number_text":"੬੨।","page":2477,"lines":[{"gurmukhi":"ਅਨਗਨ ਕਾਲ ਅਸੁਰ ਤਬ ਮਾਰੇ। ਪਰੇ ਭੂਮਿ ਪਰ ਮਨਹੁ ਮੁਨਾਰੇ।","roman":"Angan kaal asur tab maare | pare bhoomi par manhu munaare |","meaning_en":"Then Kal killed countless demons; they lay on the earth like minarets.","page":2477,"meaning_status":"draft"},{"gurmukhi":"ਮੇਧਾ ਤੇ ਗਜ ਬਾਜ ਉਠਾਹੀ। ਸ੍ਰੋਨਤ ਕੇ ਦਾਨਵ ਹ੍ਵੈ ਜਾਹੀ। ੬੨।","roman":"Medhaa te gaj baaj uthaahee | sronat ke daanav hvai jaahee | 62 |","meaning_en":"From fat, elephants and horses rose; the demons of blood arose. 62.","page":2477,"meaning_status":"draft"}]},{"type":"verse","number":[63],"number_text":"੬੩।","page":2477,"lines":[{"gurmukhi":"ਬਾਨਨ ਕੀ ਬਰਖਾ ਉਠਿ ਕਰਹੀ। ਮਾਰਿ ਮਾਰਿ ਕਰਿ ਕੋਪ ਉਚਰਹੀ।","roman":"Baanan kee barkhaa uthi karhee | maari maari kari kop ucharhee |","meaning_en":"They rose, made showers of arrows, and in rage cried \"kill, kill\".","page":2477,"meaning_status":"draft"},{"gurmukhi":"ਤਿਨ ਤੇ ਅਸੁਰਨ ਕਿਯਾ ਪਸਾਰਾ। ਦਸੇ ਦਿਸਨ ਹੂੰ ਕਹ ਭਰਿ ਡਾਰਾ। ੬੩।","roman":"Tin te asuran kiyaa pasaaraa | dase disan hoon kah bhari daaraa | 63 |","meaning_en":"From them the demons made their spread and filled all ten directions. 63.","page":2477,"meaning_status":"draft"}]},{"type":"verse","number":[64],"number_text":"੬੪।","page":2477,"lines":[{"gurmukhi":"ਵਹੈ ਕਾਲਕਾ ਅਸੁਰ ਖਪਾਏ। ਮਾਰਿ ਦੁਬਹਿਯਾ ਧੂਰਿ ਮਿਲਾਏ।","roman":"Vahai kaalkaa asur khapaae | maari dubhiyaa dhoori milaae |","meaning_en":"That same Kalika destroyed the demons; killing them she mingled the Dubahiya with dust.","page":2477,"meaning_status":"draft","note":"ਦੁਬਹਿਯਾ: obscure; uncertain."},{"gurmukhi":"ਪੁਨਿ ਪੁਨਿ ਉਠੈ ਪ੍ਰਹਾਰੈ ਬਾਨਾ। ਤਿਨ ਤੇ ਧਰਤ ਅਸੁਰ ਤਨ ਨਾਨਾ। ੬੪।","roman":"Puni puni uthai prahaarai baanaa | tin te dharat asur tan naanaa | 64 |","meaning_en":"Again and again they rose and shot arrows; from them demons took many bodies. 64.","page":2477,"meaning_status":"draft"}]},{"type":"verse","number":[65],"number_text":"੬੫।","page":2477,"lines":[{"gurmukhi":"ਟੂਕ ਟੂਕ ਦਾਨਵ ਜੇ ਭਏ। ਤਿਨ ਤੇ ਅਨਿਕ ਅਸੁਰ ਹ੍ਵੈ ਗਏ।","roman":"Took took daanav je bhae | tin te anik asur hvai gae |","meaning_en":"The demons who were cut into pieces, from them many demons came into being.","page":2477,"meaning_status":"draft"},{"gurmukhi":"ਤਾਹੀ ਤੇ ਦਾਨਵ ਬਹੁ ਹ੍ਵੈ ਕਰਿ। ਜੁਧ ਕਰੈ ਆਯੁਧ ਤੇ ਲੈ ਕਰਿ। ੬੫।","roman":"Taahee te daanav bahu hvai kari | judh karai aayudh te lai kari | 65 |","meaning_en":"From them, becoming many, the demons fought, taking up weapons. 65.","page":2477,"meaning_status":"draft"}]},{"type":"verse","number":[66],"number_text":"੬੬।","page":2477,"lines":[{"gurmukhi":"ਬਹੁਰਿ ਕਾਲ ਵੈ ਦੈਤ ਸੰਘਾਰੇ। ਤਿਲ ਤਿਲ ਪਾਇ ਟੂਕ ਕਰਿ ਡਾਰੇ।","roman":"Bahuri kaal vai dait sanghaare | til til paai took kari daare |","meaning_en":"Then Kal killed those demons; he cut them into pieces, bit by bit.","page":2477,"meaning_status":"draft"},{"gurmukhi":"ਜੇਤਿਕ ਗਿਰੈ ਭੂਮਿ ਟੁਕ ਹ੍ਵੈ ਕੈ। ਤਿਤ ਹੀ ਉਠੈ ਆਯੁਧਨ ਲੈ ਕੈ। ੬੬।","roman":"Jetik girai bhoomi tuk hvai kai | tit hee uthai aayudhan lai kai | 66 |","meaning_en":"As many as fell to the ground in pieces, so many rose again taking up weapons. 66.","page":2477,"meaning_status":"draft"}]},{"type":"verse","number":[67],"number_text":"੬੭।","page":2477,"lines":[{"gurmukhi":"ਤਿਲ ਤਿਲ ਕਰਿ ਭਟ ਜਿਤਕ ਉਡਾਏ। ਤੇਤਕ ਤਹਾ ਅਸੁਰ ਬਨ ਆਏ।","roman":"Til til kari bhat jitak udaae | tetak tahaa asur ban aae |","meaning_en":"However many warriors he cut up bit by bit, so many demons came into being there.","page":2477,"meaning_status":"draft"},{"gurmukhi":"ਤਿਨ ਕੇ ਟੂਕ ਟੂਕ ਜੇ ਕੀਏ। ਤਿਨ ਤੇ ਬਹੁ ਦਾਨਵ ਭਵ ਲੀਏ। ੬੭।","roman":"Tin ke took took je kee'e | tin te bahu daanav bhav lee'e | 67 |","meaning_en":"The ones whom he cut to pieces, from them many demons took being. 67.","page":2477,"meaning_status":"draft"}]},{"type":"verse","number":[68],"number_text":"੬੮।","page":2477,"lines":[{"gurmukhi":"ਕੇਤਿਕ ਤਹਾ ਸੁਭੈ ਦੰਤੀ ਰਨ। ਸੀਚਹਿ ਸੁੰਡ ਬਾਰਿ ਤੇ ਸਭ ਤਨ।","roman":"Ketik tahaa subhai dantee ran | seechhi sund baari te sabh tan |","meaning_en":"Some elephants shone there in the battle; they sprayed water from their trunks over all bodies.","page":2477,"meaning_status":"draft"},{"gurmukhi":"ਦਾਤ ਦਿਖਾਇ ਤਜੈ ਚਿੰਘਾਰਾ। ਗਿਰਿ ਗਿਰਿ ਪਰੈ ਨਿਰਖਿ ਅਸਵਾਰਾ। ੬੮।","roman":"Daat dikhaai tajai chinghaaraa | giri giri parai nirkhi asvaaraa | 68 |","meaning_en":"Showing their tusks they trumpeted, and fell down one after another, seeing the riders. 68.","page":2477,"meaning_status":"draft","note":"ਸੀਚਹਿ ਸੁੰਡ ਬਾਰਿ ਤੇ: 'sprayed water with their trunks' read; uncertain."}]},{"type":"verse","number":[69],"number_text":"੬੯।","page":2479,"lines":[{"gurmukhi":"ਕਹੂੰ ਭੇਰ ਭੀਖਨ ਭਭਕਾਰਹਿ। ਕਹੂੰ ਬੀਰ ਬਾਜੀ ਰਨ ਡਾਰਹਿ।","roman":"Kahoon bher bheekhan bhabhkaarhi | kahoon beer baajee ran daarhi |","meaning_en":"In places dreadful drums boomed; in places warriors threw horses down in the battle.","page":2479,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤਕ ਸੂਰ ਸੈਹਥੀ ਫਿਰਾਵਤ। ਮਹਾ ਕਾਲ ਕੇ ਸਨਮੁਖ ਧਾਵਤ। ੬੯।","roman":"Kitak soor saihthee phiraavat | mahaa kaal ke sanmukh dhaavat | 69 |","meaning_en":"Some heroes whirled their spears and ran against Mahakal. 69.","page":2479,"meaning_status":"draft"}]},{"type":"verse","number":[70],"number_text":"੭੦।","page":2479,"lines":[{"gurmukhi":"ਕੇਤਿਕ ਬਜ੍ਰ ਬਰਛਿਯਨ ਲੈ ਕੈ। ਧਾਵਤ ਅਸੁਰ ਕੋਪ ਤਨ ਤੈ ਕੈ।","roman":"Ketik bajr barchhiyan lai kai | dhaavat asur kop tan tai kai |","meaning_en":"Some, taking thunderbolts and lances, ran, the demons with rage in their bodies.","page":2479,"meaning_status":"draft"},{"gurmukhi":"ਕੋਪਿ ਕਾਲ ਪਰ ਕਰਤ ਪ੍ਰਹਾਰਾ। ਜਾਨੁਕ ਸਲਭ ਦੀਪ ਅਨੁਹਾਰਾ। ੭੦।","roman":"Kopi kaal par karat prahaaraa | jaanuk salabh deep anuhaaraa | 70 |","meaning_en":"In rage they struck at Kal, like moths rushing at a lamp. 70.","page":2479,"meaning_status":"draft"}]},{"type":"verse","number":[71],"number_text":"੭੧।","page":2479,"lines":[{"gurmukhi":"ਭਰੇ ਗੁਮਾਨ ਬਡੇ ਗਰਬੀਲੇ। ਧਾਵਤ ਚੌਪਿ ਚੜੇ ਚਟਕੀਲੇ।","roman":"Bhare gumaan bade garbeele | dhaavat chaupi chare chatkeele |","meaning_en":"Full of pride, very arrogant, the lively ones charged, eager and mounted.","page":2479,"meaning_status":"draft"},{"gurmukhi":"ਪੀਸਿ ਪੀਸਿ ਰਦਨਛਦ ਦੋਊ। ਧਾਵਤ ਮਹਾ ਕਾਲ ਪਰ ਸੋਊ। ੭੧।","roman":"Peesi peesi radanchhad do'oo | dhaavat mahaa kaal par so'oo | 71 |","meaning_en":"Grinding their lips, they both ran at Mahakal. 71.","page":2479,"meaning_status":"draft","note":"ਦੋਊ: 'both'; printed so; uncertain."}]},{"type":"verse","number":[72],"number_text":"੭੨।","page":2479,"lines":[{"gurmukhi":"ਬਾਜਹਿ ਢੋਲਿ ਮ੍ਰਿਦੰਗ ਨਗਾਰਾ। ਭੀਖਨ ਕਰਤ ਭੇਰ ਭਭਕਾਰਾ।","roman":"Baajhi dholi mridang nagaaraa | bheekhan karat bher bhabhkaaraa |","meaning_en":"Drums, mridangs and kettledrums sounded; the war-drums made dreadful booming.","page":2479,"meaning_status":"draft"},{"gurmukhi":"ਜੰਗ ਮੁਚੰਗ ਉਪੰਗ ਬਜੇ ਰਨ। ਝਾਲਰਿ ਤਾਲ ਨਫੀਰਨ ਕੇ ਗਨ। ੭੨।","roman":"Jang muchang upang baje ran | jhaalri taal napheeran ke gan | 72 |","meaning_en":"Jang, muchang and upang instruments sounded in the battle, with cymbals and hosts of trumpets. 72.","page":2479,"meaning_status":"draft","note":"Musical instruments: names left as printed."}]},{"type":"verse","number":[73],"number_text":"੭੩।","page":2479,"lines":[{"gurmukhi":"ਮੁਰਲੀ ਮੁਰਜ ਕਹੀ ਰਨ ਬਾਜਤ। ਦਾਨਵ ਭਰੇ ਗੁਮਾਨਹਿ ਗਾਜਤ।","roman":"Murlee muraj kahee ran baajat | daanav bhare gumaanhi gaajat |","meaning_en":"Flutes and murajs sounded in the battle; the proud demons roared.","page":2479,"meaning_status":"draft"},{"gurmukhi":"ਢੋਲਨ ਪਰ ਦੈ ਦੈ ਢਮਕਾਰੇ। ਗਹਿ ਗਹਿ ਧਵਤ ਕ੍ਰਿਪਾਨ ਕਟਾਰੇ। ੭੩।","roman":"Dholan par dai dai dhamkaare | gahi gahi dhavat kripaan kataare | 73 |","meaning_en":"Beating the drums, they ran seizing swords and daggers. 73.","page":2479,"meaning_status":"draft"}]},{"type":"verse","number":[74],"number_text":"੭੪।","page":2479,"lines":[{"gurmukhi":"ਦੀਰਘ ਦਾਤ ਕਾਢਿ ਕਈ ਕੋਸਾ। ਧਾਵਤ ਅਸੁਰ ਹੀਏ ਕਰਿ ਜੋਸਾ।","roman":"Deeragh daat kaadhi kaee kosaa | dhaavat asur hee'e kari josaa |","meaning_en":"Baring long teeth for miles, the demons ran with fury in their hearts.","page":2479,"meaning_status":"draft"},{"gurmukhi":"ਮਾਰਨ ਮਹਾ ਕਾਲ ਕਹ ਧਾਵੈ। ਮਨੋ ਮਾਰਤ ਵੇਈ ਮਰਿ ਜਾਵੈ। ੭੪।","roman":"Maaran mahaa kaal kah dhaavai | mano maarat ve'ee mari jaavai | 74 |","meaning_en":"They ran to kill Mahakal; it was as if in killing they themselves would die. 74.","page":2479,"meaning_status":"draft","note":"ਮਨੋ ਮਾਰਤ ਵੇਈ ਮਰਿ ਜਾਵੈ: 'as if they would die in killing'; uncertain."}]},{"type":"verse","number":[75],"number_text":"੭੫।","page":2479,"lines":[{"gurmukhi":"ਦਾਨਵ ਮਹਾ ਕੋਪ ਕਰਿ ਢੂਕੇ। ਮਾਰਹਿ ਮਾਰਿ ਦਸੋ ਦਿਸਿ ਕੂਕੇ।","roman":"Daanav mahaa kop kari dhooke | maarhi maari daso disi kooke |","meaning_en":"The demons came on in great rage; they cried \"kill, kill\" in all ten directions.","page":2479,"meaning_status":"draft"},{"gurmukhi":"ਦੈ ਦੈ ਢੋਲਿ ਮ੍ਰਿਦੰਗ ਨਗਾਰੇ। ਕਾਢਿ ਅਰਿ ਦਾਤਿ ਡਰਾਰੇ। ੭੫।","roman":"Dai dai dholi mridang nagaare | kaadhi ari daati daraare | 75 |","meaning_en":"Beating drums, mridangs and kettledrums, the enemies bared their teeth and terrified. 75.","page":2479,"meaning_status":"draft","note":"Obscure (ਅਰਿ ਦਾਤਿ); uncertain."}]},{"type":"verse","number":[76],"number_text":"੭੬।","page":2479,"lines":[{"gurmukhi":"ਚਾਹਤ ਮਹਾ ਕਾਲ ਕਹ ਮਾਰੋ। ਮਹਾ ਪੂਰਖ ਨਹਿ ਕਰਤ ਬਿਚਾਰੋ।","roman":"Chaahat mahaa kaal kah maaro | mahaa poorakh nahi karat bichaaro |","meaning_en":"They wished to kill Mahakal; fools, they did not consider the Great Being,","page":2479,"meaning_status":"draft"},{"gurmukhi":"ਜਿਨ ਸਭ ਜਗ ਕਾ ਕਰਾ ਪਸਾਰਾ। ਤਾਹਿ ਚਹਤ ਤੇ ਮੂੜ ਸੰਘਾਰਾ। ੭੬।","roman":"Jin sabh jag kaa karaa pasaaraa | taahi chahat te moor sanghaaraa | 76 |","meaning_en":"who made all the expanse of the world; him the fools wished to kill. 76.","page":2479,"meaning_status":"draft"}]},{"type":"verse","number":[77],"number_text":"੭੭।","page":2479,"lines":[{"gurmukhi":"ਠੋਕਿ ਠੋਕਿ ਭੁਜ ਦੰਡਨ ਜੋਧਾ। ਧਾਵਤ ਮਹਾ ਕਾਲ ਪਰ ਕ੍ਰੋਧਾ।","roman":"Thoki thoki bhuj dandan jodhaa | dhaavat mahaa kaal par krodhaa |","meaning_en":"Slapping their arms, warriors ran in rage at Mahakal.","page":2479,"meaning_status":"draft"},{"gurmukhi":"ਬੀਸ ਪਦੁਮ ਦਾਨਵ ਤਵ ਭਯੋ। ਨਾਸ ਕਰਨ ਕਾਲੀ ਕੋ ਧਯੋ। ੭੭।","roman":"Bees padum daanav tav bhayo | naas karan kaalee ko dhayo | 77 |","meaning_en":"Then there were twenty padmas of demons; they ran to destroy Kali. 77.","page":2479,"meaning_status":"draft","note":"ਬੀਸ ਪਦੁਮ: 'twenty padmas' (a very large number); as printed."}]},{"type":"verse","number":[78],"number_text":"੭੮।","page":2479,"lines":[{"gurmukhi":"ਛੂਹਨਿ ਸਹਸ ਅਸੁਰ ਕੀ ਸੈਨਾ। ਧਾਵਤ ਭਈ ਅਰੁਨ ਕਰਿ ਨੈਨਾ।","roman":"Chhoohni sahas asur kee sainaa | dhaavat bhaee arun kari nainaa |","meaning_en":"An army of a thousand chhauhinis of demons ran with eyes red.","page":2479,"meaning_status":"draft"},{"gurmukhi":"ਧਾਵਤ ਕੋਪ ਅਮਿਤ ਕਰਿ ਭਏ। ਪ੍ਰਿਥਵੀ ਕੇ ਖਟ ਪਟ ਉਡਿ ਗਏ। ੭੮।","roman":"Dhaavat kop amit kari bhae | prithvee ke khat pat udi gae | 78 |","meaning_en":"They ran in boundless rage; the earth's cot-and-bedding flew up. 78.","page":2479,"meaning_status":"draft","note":"ਖਟ ਪਟ: obscure; read as the earth's coverings/foundations; uncertain."}]},{"type":"verse","number":[79],"number_text":"੭੯।","page":2479,"lines":[{"gurmukhi":"ਏਕੈ ਪੁਰ ਪ੍ਰਿਥਵੀ ਰਹਿ ਗਈ। ਖਟ ਪਟ ਹਯਨ ਪਗ ਉਡਿ ਗਈ।","roman":"Ekai pur prithvee rahi gaee | khat pat hayan pag udi gaee |","meaning_en":"Only one city of the earth remained; the khat pat flew from the hooves of horses.","page":2479,"meaning_status":"draft"},{"gurmukhi":"ਜਨੁ ਬਿਧਿ ਏਕੈ ਰਚਾ ਪਯਾਰਾ। ਗਗਨ ਰਚੇ ਦਸ ਤੀਨਿ ਸੁਧਾਰਾ। ੭੯।","roman":"Janu bidhi ekai rachaa payaaraa | gagan rache das teeni sudhaaraa | 79 |","meaning_en":"It was as if the Creator had made one single being, and made thirteen skies as one. 79.","page":2479,"meaning_status":"draft","note":"Obscure; rendered loosely; uncertain."}]},{"type":"verse","number":[80],"number_text":"੮੦।","page":2479,"lines":[{"gurmukhi":"ਮਹਾਦੇਵ ਆਸਨ ਤੇ ਟਰਾ। ਬ੍ਰਹਮਾ ਤ੍ਰਸਤ ਬੂਟ ਮਹਿ ਦੁਰਾ।","roman":"Mahaadev aasan te taraa | brahmaa trasat boot mahi duraa |","meaning_en":"Mahadev was moved from his seat; Brahma, afraid, hid in a bush.","page":2479,"meaning_status":"draft"},{"gurmukhi":"ਨਿਰਖਿ ਬਿਸਨ ਰਨ ਅਧਿਕ ਡਰਾਨਾ। ਦੁਰਾ ਸਿੰਧ ਕੇ ਬੀਚ ਲਜਾਨਾ। ੮੦।","roman":"Nirkhi bisan ran adhik daraanaa | duraa sindh ke beech lajaanaa | 80 |","meaning_en":"Seeing the battle, Vishnu was greatly afraid; he hid ashamed in the middle of the ocean. 80.","page":2479,"meaning_status":"draft"}]},{"type":"verse","number":[81],"number_text":"੮੧।","page":2481,"lines":[{"gurmukhi":"ਕੜਾ ਕੜੀ ਮਾਚਾ ਘਮਸਾਨਾ। ਨਿਰਖਤ ਦੇਵ ਦੈਤ ਜਾ ਨਾਨਾ।","roman":"Karaa karee maachaa ghamsaanaa | nirkhat dev dait jaa naanaa |","meaning_en":"Hand-to-hand grappling and tumult broke out; gods and demons watched the many scenes.","page":2481,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਘੋਰ ਆਹਵ ਤਹ ਪਰਾ। ਕਾਪੀ ਭੂਮਿ ਗਗਨ ਥਰਹਰਾ। ੮੧।","roman":"Mahaa ghor aahav tah paraa | kaapee bhoomi gagan tharahraa | 81 |","meaning_en":"A great dreadful battle arose there; the earth shook and the sky trembled. 81.","page":2481,"meaning_status":"draft"}]},{"type":"verse","number":[82],"number_text":"੮੨।","page":2481,"lines":[{"gurmukhi":"ਨਿਰਖਿ ਜੁਧ ਕਾਪਾ ਕਮਲੇਸਾ। ਤਾ ਤੇ ਧਰਾ ਨਾਰਿ ਕਾ ਭੇਸਾ।","roman":"Nirkhi judh kaapaa kamlesaa | taa te dharaa naari kaa bhesaa |","meaning_en":"Seeing the war Kamlesh, Vishnu, trembled; for that he took the form of a woman.","page":2481,"meaning_status":"draft"},{"gurmukhi":"ਪਰਬਤੀਸ ਲਖਿ ਡਰਾ ਲਰਾਈ। ਬਾਸਾ ਬਨ ਬਿਖੈ ਅਤਿਥ ਕਹਾਈ। ੮੨।","roman":"Parabtees lakhi daraa laraaee | baasaa ban bikhai atith kahaaee | 82 |","meaning_en":"Seeing the battle the lord of Parbati was afraid; he took up his abode in the forest and was called a hermit. 82.","page":2481,"meaning_status":"draft","note":"ਪਰਬਤੀਸ: lord of Parbati (Shiva)."}]},{"type":"verse","number":[83],"number_text":"੮੩।","page":2481,"lines":[{"gurmukhi":"ਕਾਰਤਿਕੇਯ ਹ੍ਵੈ ਰਹਾ ਬਿਹੰਡਲ। ਬ੍ਰਹਮ ਛਾਡਿ ਗ੍ਰਿਹ ਗਯੋ ਕਮੰਡਲ।","roman":"Kaartikey hvai rahaa bihandal | braham chhaadi grih gayo kamandal |","meaning_en":"Kartikeya became distressed; Brahma left his house and his water-pot.","page":2481,"meaning_status":"draft"},{"gurmukhi":"ਪਬ ਪਿਸਾਨ ਪਗਨ ਭੇ ਤਬ ਹੀ। ਜਾਇ ਬਸੇ ਉਤਰ ਦਿਸਿ ਸਬ ਹੀ। ੮੩।","roman":"Pab pisaan pagan bhe tab hee | jaai base utar disi sab hee | 83 |","meaning_en":"Mountains and stones became feet and moved; all went and lived in the north. 83.","page":2481,"meaning_status":"draft","note":"Obscure; uncertain."}]},{"type":"verse","number":[84],"number_text":"੮੪।","page":2481,"lines":[{"gurmukhi":"ਡਗੀ ਧਰਨਿ ਅੰਬਰਿ ਘਹਰਾਨਾ। ਬਾਜ ਖੁਰਨ ਤੇ ਪਬ ਪਿਸਾਨਾ।","roman":"Dagee dharni anbri ghahraanaa | baaj khuran te pab pisaanaa |","meaning_en":"The earth shifted and the sky trembled; from the horses' hooves mountains and stones were scattered.","page":2481,"meaning_status":"draft"},{"gurmukhi":"ਅੰਧ ਗੁਬਾਰ ਭਯੋ ਬਾਨਨ ਤਨ। ਹਾਥ ਬਿਲੋਕ੍ਯੋ ਜਾਤ ਨ ਆਪਨ। ੮੪।","roman":"Andh gubaar bhayo baanan tan | haath bilokyo jaat na aapan | 84 |","meaning_en":"A blind darkness arose from the arrows; one could not see one's own hand. 84.","page":2481,"meaning_status":"draft"}]},{"type":"verse","number":[85],"number_text":"੮੫।","page":2481,"lines":[{"gurmukhi":"ਬਿਛੂਆ ਬਾਨ ਬਜ੍ਰ ਰਨ ਬਰਖਤ। ਰਿਸਿ ਰਿਸਿ ਸੁਭਟ ਧਨੁਖ ਕਹ ਕਰਖਤ।","roman":"Bichhooaa baan bajr ran barkhat | risi risi subhat dhanukh kah karkhat |","meaning_en":"Scorpion-darts, arrows and thunderbolts rained in the battle; in rage warriors drew their bows.","page":2481,"meaning_status":"draft"},{"gurmukhi":"ਤਕਿ ਤਕਿ ਬਾਨ ਪ੍ਰਕੋਪ ਚਲਾਵੈ। ਭੇਦਿ ਤ੍ਰਾਨ ਤਨ ਪਰੈ ਪਰਾਵੈ। ੮੫।","roman":"Taki taki baan prakop chalaavai | bhedi traan tan parai paraavai | 85 |","meaning_en":"Taking aim, they shot arrows in fury; piercing armour they struck the body and passed through. 85.","page":2481,"meaning_status":"draft"}]},{"type":"verse","number":[86],"number_text":"੮੬।","page":2481,"lines":[{"gurmukhi":"ਜਬ ਹੀ ਭਏ ਅਮਿਤ ਰਣ ਜੋਧਾ। ਬਾਢ੍ਯੋ ਮਹਾ ਕਾਲ ਕੈ ਕ੍ਰੋਧਾ।","roman":"Jab hee bhae amit ran jodhaa | baadhyo mahaa kaal kai krodhaa |","meaning_en":"When countless warriors had been killed in the battle, Mahakal's anger grew.","page":2481,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਕੋਪ ਕਰਿ ਬਿਸਿਖ ਪ੍ਰਹਾਰੇ। ਅਧਿਕ ਸਤ੍ਰੁ ਛਿਨ ਮਾਝ ਸੰਘਾਰੇ। ੮੬।","roman":"Mahaa kop kari bisikh prahaare | adhik satru chhin maajh sanghaare | 86 |","meaning_en":"In great rage he shot arrows and killed many enemies in an instant. 86.","page":2481,"meaning_status":"draft"}]},{"type":"verse","number":[87],"number_text":"੮੭।","page":2481,"lines":[{"gurmukhi":"ਰਕਤ ਸੰਬੂਹ ਧਰਨਿ ਤਬ ਪਰਾ। ਤਾ ਤੇ ਬਹੁ ਦਾਨ੍ਵਨ ਬਪੁ ਧਰਾ।","roman":"Rakat sanbooh dharni tab paraa | taa te bahu daanvan bapu dharaa |","meaning_en":"A mass of blood fell on the earth, and from it many demons took form.","page":2481,"meaning_status":"draft"},{"gurmukhi":"ਏਕ ਏਕ ਸਰ ਸਭਹਿ ਚਲਾਏ। ਤਿਨ ਤੇ ਅਸੁਰ ਅਨਿਕ ਹ੍ਵੈ ਧਾਏ। ੮੭।","roman":"Ek ek sar sabhhi chalaae | tin te asur anik hvai dhaae | 87 |","meaning_en":"Each one shot arrows, and from them many demons rose and ran. 87.","page":2481,"meaning_status":"draft"}]},{"type":"verse","number":[88],"number_text":"੮੮।","page":2481,"lines":[{"gurmukhi":"ਆਏ ਜਿਤਕ ਤਿਤਕ ਤਹ ਮਾਰੇ। ਬਹੇ ਧਰਨਿ ਪਰ ਰਕਤ ਪਨਾਰੇ।","roman":"Aae jitak titak tah maare | bahe dharni par rakat panaare |","meaning_en":"However many came he killed there; streams of blood flowed on the earth.","page":2481,"meaning_status":"draft"},{"gurmukhi":"ਤਿਨ ਤੇ ਅਮਿਤ ਅਸੁਰਨ ਬਪੁ ਧਰਾ। ਹਮ ਤੇ ਜਾਤ ਬਿਚਾਰ ਨ ਕਰਾ। ੮੮।","roman":"Tin te amit asuran bapu dharaa | ham te jaat bichaar na karaa | 88 |","meaning_en":"From them countless demons took bodies; he did not stop to reckon the going from us. 88.","page":2481,"meaning_status":"draft","note":"ਹਮ ਤੇ ਜਾਤ ਬਿਚਾਰ ਨ ਕਰਾ: obscure; uncertain."}]},{"type":"verse","number":[89],"number_text":"੮੯।","page":2481,"lines":[{"gurmukhi":"ਡਗਮਗ ਲੋਕ ਚਤੁਰ ਦਸ ਭਏ। ਅਸੁਰਨ ਸਾਥ ਸਕਲ ਭਰਿ ਗਏ।","roman":"Dagmag lok chatur das bhae | asuran saath sakal bhari gae |","meaning_en":"The fourteen worlds shook; they were all filled with demons.","page":2481,"meaning_status":"draft"},{"gurmukhi":"ਬ੍ਰਹਮਾ ਬਿਸਨ ਸਭੈ ਡਰ ਪਾਨੇ। ਮਹਾ ਕਾਲ ਕੀ ਸਰਨਿ ਸਿਧਾਨੇ। ੮੯।","roman":"Brahmaa bisan sabhai dar paane | mahaa kaal kee sarni sidhaane | 89 |","meaning_en":"Brahma, Vishnu and all were afraid, and went into the shelter of Mahakal. 89.","page":2481,"meaning_status":"draft"}]},{"type":"verse","number":[90],"number_text":"੯੦।","page":2481,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਸਭੈ ਪੁਕਾਰਤ ਭਏ। ਜਨੁ ਕਰ ਲੂਟਿ ਬਨਿਕ ਸੇ ਲਏ।","roman":"Ih bidhi sabhai pukaarat bhae | janu kar looti banik se lae |","meaning_en":"In this way all cried out, as if robbed by plunderers like merchants.","page":2481,"meaning_status":"draft"},{"gurmukhi":"ਤ੍ਰਾਹਿ ਤ੍ਰਾਹਿ ਹਮ ਸਰਨ ਤਿਹਾਰੀ। ਸਭ ਭੈ ਤੇ ਹਮ ਲੇਹੁ ਉਬਾਰੀ। ੯੦।","roman":"Traahi traahi ham saran tihaaree | sabh bhai te ham lehu ubaaree | 90 |","meaning_en":"\"Save us, save us; we are in your shelter; deliver us from all fear. 90.","page":2481,"meaning_status":"draft"}]},{"type":"verse","number":[91],"number_text":"੯੧।","page":2481,"lines":[{"gurmukhi":"ਤੁਮ ਹੋ ਸਕਲ ਲੋਕ ਸਿਰਤਾਜਾ। ਗਰਬਨ ਗੰਜ ਗਰੀਬ ਨਿਵਾਜਾ।","roman":"Tum ho sakal lok sirtaajaa | garban ganj gareeb nivaajaa |","meaning_en":"You are the crown of all worlds, destroyer of the proud, cherisher of the poor.","page":2481,"meaning_status":"draft"},{"gurmukhi":"ਆਦਿ ਅਕਾਲ ਅਜੋਨਿ ਬਿਨਾ ਭੈ। ਨਿਰਬਿਕਾਰ ਨਿਰਲੰਬ ਜਗਤ ਮੈ। ੯੧।","roman":"Aadi akaal ajoni binaa bhai | nirbikaar nirlanb jagat mai | 91 |","meaning_en":"Primal, timeless, unborn, without fear; untouched by change, without support in the world. 91.","page":2481,"meaning_status":"draft"}]},{"type":"verse","number":[92],"number_text":"੯੨।","page":2481,"lines":[{"gurmukhi":"ਨਿਰਬਿਕਾਰ ਨਿਰਜੁਰ ਅਬਿਨਾਸੀ। ਪਰਮ ਜੋਗ ਕੇ ਤਤੁ ਪ੍ਰਕਾਸੀ।","roman":"Nirbikaar nirjur abinaasee | param jog ke tatu prakaasee |","meaning_en":"Without change, never aging, imperishable; you made manifest the essence of the highest yoga.","page":2481,"meaning_status":"draft"},{"gurmukhi":"ਨਿਰੰਕਾਰ ਨਵ ਨਿਤ੍ਯ ਸੁਯੰਭਵ। ਤਾਤ ਮਾਤ ਜਹ ਜਾਤ ਨ ਬੰਧਵ। ੯੨।","roman":"Nirankaar nav nity suyanbhav | taat maat jah jaat na bandhav | 92 |","meaning_en":"Formless, ever new, eternal, self-existent; where there is no father, mother, caste or kin. 92.","page":2481,"meaning_status":"draft"}]},{"type":"verse","number":[93],"number_text":"੯੩।","page":2483,"lines":[{"gurmukhi":"ਸਤ੍ਰੁ ਬਿਹੰਡ ਸੁਰਿਦਿ ਸੁਖਦਾਇਕ। ਚੰਡ ਮੁੰਡ ਦਾਨਵ ਕੇ ਘਾਇਕ।","roman":"Satru bihand suridi sukhdaaik | chand mund daanav ke ghaaik |","meaning_en":"Destroyer of enemies, giver of joy to the heart, slayer of the demons Chand and Mund;","page":2483,"meaning_status":"draft"},{"gurmukhi":"ਸਤਿ ਸੰਧਿ ਸਤਿਤਾ ਨਿਵਾਸਾ। ਭੂਤ ਭਵਿਖ ਭਵਾਨ ਨਿਰਾਸਾ। ੯੩।","roman":"Sati sandhi satitaa nivaasaa | bhoot bhavikh bhavaan niraasaa | 93 |","meaning_en":"true to your word, abode of truth; past, future and present; without desire. 93.","page":2483,"meaning_status":"draft"}]},{"type":"verse","number":[94],"number_text":"੯੪।","page":2483,"lines":[{"gurmukhi":"ਆਦਿ ਅਨੰਤ ਅਰੂਪ ਅਭੇਸਾ। ਘਟ ਘਟ ਭੀਤਰ ਕੀਯਾ ਪ੍ਰਵੇਸਾ।","roman":"Aadi anant aroop abhesaa | ghat ghat bheetar keeyaa pravesaa |","meaning_en":"Primal, endless, formless, without garb, entered into every heart;","page":2483,"meaning_status":"draft"},{"gurmukhi":"ਅੰਤਰ ਬਸਤ ਨਿਰੰਤਰ ਰਹਈ। ਸਨਕ ਸਨੰਦ ਸਨਾਤਨ ਕਹਈ। ੯੪।","roman":"Antar basat nirantar rahaee | sanak sanand sanaatan kahaee | 94 |","meaning_en":"dwelling within, constantly present; Sanak, Sanand and Sanatan speak of you. 94.","page":2483,"meaning_status":"draft"}]},{"type":"verse","number":[95],"number_text":"੯੫।","page":2483,"lines":[{"gurmukhi":"ਆਦਿ ਜੁਗਾਦਿ ਸਦਾ ਪ੍ਰਭੁ ਏਕੈ। ਧਰਿ ਧਰਿ ਮੂਰਤਿ ਫਿਰਤਿ ਅਨੇਕੈ।","roman":"Aadi jugaadi sadaa prabhu ekai | dhari dhari moorti phirti anekai |","meaning_en":"From the beginning and in every age the Lord is ever One, yet assuming forms He goes about in many.","page":2483,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਜਗ ਕਹ ਇਹ ਬਿਧਿ ਭਰਮਾਯਾ। ਆਪੇ ਏਕ ਅਨੇਕ ਦਿਖਾਯਾ। ੯੫।","roman":"Sabh jag kah ih bidhi bharmaayaa | aape ek anek dikhaayaa | 95 |","meaning_en":"He has deluded the whole world thus; He Himself shows the One as many. 95.","page":2483,"meaning_status":"draft"}]},{"type":"verse","number":[96],"number_text":"੯੬।","page":2483,"lines":[{"gurmukhi":"ਘਟ ਘਟ ਮਹਿ ਸੋਇ ਪੁਰਖ ਬ੍ਯਾਪਕ। ਸਕਲ ਜੀਵ ਜੰਤਨ ਕੇ ਥਾਪਕ।","roman":"Ghat ghat mahi soi purakh byaapak | sakal jeev jantan ke thaapak |","meaning_en":"In every heart that Being pervades, and is the establisher of all living creatures.","page":2483,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਤੇ ਜੋਤਿ ਕਰਤ ਆਕਰਖਨ। ਤਾ ਕਹ ਕਹਤ ਮ੍ਰਿਤਕ ਜਗ ਕੇ ਜਨ। ੯੬।","roman":"Jaa te joti karat aakarkhan | taa kah kahat mritak jag ke jan | 96 |","meaning_en":"From whom the light draws its pull; the people of the world call him dead. 96.","page":2483,"meaning_status":"draft","note":"ਤਾ ਕਹ ਕਹਤ ਮ੍ਰਿਤਕ ਜਗ ਕੇ ਜਨ: printed so; the sense is obscure ('they call him dead'); uncertain."}]},{"type":"verse","number":[97],"number_text":"੯੭।","page":2483,"lines":[{"gurmukhi":"ਤੁਮ ਜਗ ਕੇ ਕਾਰਨ ਕਰਤਾਰਾ। ਘਟਿ ਘਟਿ ਕੀ ਮਤਿ ਜਾਨਨਹਾਰਾ।","roman":"Tum jag ke kaaran kartaaraa | ghati ghati kee mati jaananhaaraa |","meaning_en":"You are the cause of the world, Creator; you know the mind in every heart.","page":2483,"meaning_status":"draft"},{"gurmukhi":"ਨਿਰੰਕਾਰ ਨਿਰਵੈਰ ਨਿਰਾਲਮ। ਸਭ ਹੀ ਕੇ ਮਨ ਕੀ ਤੁਹਿ ਮਾਲਮ। ੯੭।","roman":"Nirankaar nirvair niraalam | sabh hee ke man kee tuhi maalam | 97 |","meaning_en":"Formless, without enmity, independent; you know the mind of everyone. 97.","page":2483,"meaning_status":"draft"}]},{"type":"verse","number":[98],"number_text":"੯੮।","page":2483,"lines":[{"gurmukhi":"ਤੁਮ ਹੀ ਬ੍ਰਹਮਾ ਬਿਸਨ ਬਨਾਯੋ। ਮਹਾ ਰੁਦ੍ਰ ਤੁਮ ਹੀ ਉਪਜਾਯੋ।","roman":"Tum hee brahmaa bisan banaayo | mahaa rudr tum hee upjaayo |","meaning_en":"You made Brahma and Vishnu; you brought forth the great Rudra.","page":2483,"meaning_status":"draft"},{"gurmukhi":"ਤੁਮ ਹੀ ਰਿਖਿ ਕਸਪਹਿ ਬਨਾਵਾ। ਦਿਤ ਅਦਿਤ ਜਨ ਬੈਰ ਬਢਾਵਾ। ੯੮।","roman":"Tum hee rikhi kasaphi banaavaa | dit adit jan bair badhaavaa | 98 |","meaning_en":"You made the sage Kashyap; you made the children of Diti and Aditi enemies. 98.","page":2483,"meaning_status":"draft"}]},{"type":"verse","number":[99],"number_text":"੯੯।","page":2483,"lines":[{"gurmukhi":"ਜਗ ਕਾਰਨ ਕਰੁਨਾਨਿਧਿ ਸ੍ਵਾਮੀ। ਕਮਲ ਨੈਨ ਅੰਤਰ ਕੇ ਜਾਮੀ।","roman":"Jag kaaran karunaanidhi svaamee | kamal nain antar ke jaamee |","meaning_en":"Cause of the world, treasury of compassion, Lord, lotus-eyed knower of the inner heart,","page":2483,"meaning_status":"draft"},{"gurmukhi":"ਦਯਾ ਸਿੰਧੁ ਦੀਨਨ ਕੇ ਦਯਾਲਾ। ਹੂਜੈ ਕ੍ਰਿਪਾਨਿਧਾਨ ਕ੍ਰਿਪਾਲਾ। ੯੯।","roman":"Dayaa sindhu deenan ke dayaalaa | hoojai kripaanidhaan kripaalaa | 99 |","meaning_en":"ocean of mercy, merciful to the poor, be gracious, treasury of grace. 99.","page":2483,"meaning_status":"draft"}]},{"type":"verse","number":[100],"number_text":"੧੦੦।","page":2483,"lines":[{"gurmukhi":"ਚਰਨ ਪਰੇ ਇਹ ਬਿਧਿ ਬਿਨਤੀ ਕਰਿ। ਤ੍ਰਾਹਿ ਤ੍ਰਾਹਿ ਰਾਖਹੁ ਹਮ ਧੁਰਧਰ।","roman":"Charan pare ih bidhi bintee kari | traahi traahi raakhhu ham dhurdhar |","meaning_en":"They fell at his feet and made supplication in this way: \"Save us, save us, bearer of burdens.\"","page":2483,"meaning_status":"draft"},{"gurmukhi":"ਕਹ ਕਹ ਹਸਾ ਬਚਨ ਸੁਨ ਕਾਲਾ। ਭਗਤ ਜਾਨ ਕਰ ਭਯੋ ਕ੍ਰਿਪਾਲਾ। ੧੦੦।","roman":"Kah kah hasaa bachan sun kaalaa | bhagat jaan kar bhayo kripaalaa | 100 |","meaning_en":"Hearing their words Kal laughed, and knowing them his devotees became merciful. 100.","page":2483,"meaning_status":"draft","note":"ਕਹ ਕਹ: laughter sound."}]},{"type":"verse","number":[101],"number_text":"੧੦੧।","page":2483,"lines":[{"gurmukhi":"ਰਛ ਰਛ ਕਰਿ ਸਬਦ ਉਚਾਰੋ। ਸਭ ਦੇਵਨ ਕਾ ਸੋਕ ਨਿਵਾਰੋ।","roman":"Rachh rachh kari sabad uchaaro | sabh devan kaa sok nivaaro |","meaning_en":"He said \"Protect, protect,\" and removed the grief of all the gods.","page":2483,"meaning_status":"draft"},{"gurmukhi":"ਨਿਜੁ ਭਗਤਨ ਕਹ ਲਿਯੋ ਉਬਾਰਾ। ਦੁਸਟਨ ਕੇ ਸੰਗ ਕਰਿਯੋ ਅਖਾਰਾ। ੧੦੧।","roman":"Niju bhagtan kah liyo ubaaraa | dustan ke sang kariyo akhaaraa | 101 |","meaning_en":"He rescued his own devotees and set up the arena with the wicked. 101.","page":2483,"meaning_status":"draft"}]},{"type":"verse","number":[102],"number_text":"੧੦੨।","page":2483,"lines":[{"gurmukhi":"ਕਰਿ ਕਰਿ ਕੋਪ ਕਾਲ ਸ੍ਰੀ ਤਬ ਹੀ। ਰਥ ਪਰ ਚੜਾ ਸਸਤ੍ਰ ਲੈ ਸਭ ਹੀ।","roman":"Kari kari kop kaal sree tab hee | rath par charaa sasatr lai sabh hee |","meaning_en":"Then Sri Kal, in rage, mounted his chariot taking all his weapons,","page":2483,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਸਤ੍ਰੁਅਨ ਕੇ ਛੈ ਕਾਰਨ। ਸਭ ਸੰਤਨ ਕੇ ਪ੍ਰਾਨ ਉਬਾਰਨ। ੧੦੨।","roman":"Sakal satruan ke chhai kaaran | sabh santan ke praan ubaaran | 102 |","meaning_en":"to destroy all enemies and to rescue the lives of all saints. 102.","page":2483,"meaning_status":"draft"}]},{"type":"verse","number":[103],"number_text":"੧੦੩।","page":2483,"lines":[{"gurmukhi":"ਪ੍ਰਾਨ ਔਰ ਪਾਨਿਪ ਧਨੁ ਰਾਜਾ। ਰਾਖਨ ਚੜਾ ਸੇਵਕਨ ਕਾਜਾ।","roman":"Praan aur paanip dhanu raajaa | raakhan charaa sevkan kaajaa |","meaning_en":"The Lord of life, the bearer of the bow, the king, mounted to protect his servants;","page":2483,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਕੀ ਧੁਜਾ ਬਿਖੈ ਰਾਜਿਤ ਅਸਿ। ਨਿਰਖਿ ਸਤ੍ਰੁ ਜਿਹ ਹੋਤ ਬਿਮਨ ਬਸਿ। ੧੦੩।","roman":"Jaa kee dhujaa bikhai raajit asi | nirkhi satru jih hot biman basi | 103 |","meaning_en":"on whose banner the sword shines, seeing which enemies fall in dejection. 103.","page":2483,"meaning_status":"draft","note":"ਪਾਨਿਪ: hand-holder; read as 'bearer'; uncertain."}]},{"type":"verse","number":[104],"number_text":"੧੦੪।","page":2485,"lines":[{"gurmukhi":"ਅਸਿਧੁਜ ਅਧਿਕ ਕੋਪ ਕਰਿ ਧਾਯੋ। ਬੈਰਿ ਬ੍ਰਿੰਦ ਦਲ ਪ੍ਰਗਟ ਖਪਾਯੋ।","roman":"Asidhuj adhik kop kari dhaayo | bairi brind dal pragat khapaayo |","meaning_en":"Asidhuj ran in great rage and openly destroyed the army of enemies.","page":2485,"meaning_status":"draft"},{"gurmukhi":"ਸਾਧੁਨ ਕੀ ਰਛਾ ਕਰਿ ਲੀਨੀ। ਸਤ੍ਰੁ ਸੈਨ ਤਿਲ ਤਿਲ ਖੈ ਕੀਨੀ। ੧੦੪।","roman":"Saadhun kee rachhaa kari leenee | satru sain til til khai keenee | 104 |","meaning_en":"He protected the saints and destroyed the enemy host bit by bit. 104.","page":2485,"meaning_status":"draft","note":"ਅਸਿਧੁਜ: 'Asidhuj' (sword-bannered), a name of the Lord."}]},{"type":"verse","number":[105],"number_text":"੧੦੫।","page":2485,"lines":[{"gurmukhi":"ਤਿਲ ਤਿਲ ਏਕ ਏਕ ਕਰਿ ਡਾਰਾ। ਗਜੀ ਰਥੀ ਬਾਜਿਯਨ ਬਿਦਾਰਾ।","roman":"Til til ek ek kari daaraa | gajee rathee baajiyan bidaaraa |","meaning_en":"He cut them up bit by bit, one by one; he tore apart elephants, chariots and horsemen.","page":2485,"meaning_status":"draft"},{"gurmukhi":"ਤਿਹ ਤੇ ਅਮਿਤ ਅਸੁਰ ਉਠਿ ਧਏ। ਘੇਰਤ ਮਹਾਕਾਲ ਕਹ ਞਏ। ੧੦੫।","roman":"Tih te amit asur uthi dhae | gherat mahaakaal kah nyae | 105 |","meaning_en":"From them countless demons rose and ran; they surrounded Mahakal. 105.","page":2485,"meaning_status":"draft","note":"ਞਏ: printed so; read as 'came'; uncertain."}]},{"type":"verse","number":[106],"number_text":"੧੦੬।","page":2485,"lines":[{"gurmukhi":"ਮਚਤ ਭਯੋ ਜਬ ਹੀ ਰਨ ਦਾਰੁਨ। ਕਟਿ ਕਟਿ ਗਏ ਬਾਜ ਅਰੁ ਬਾਰੁਨ।","roman":"Machat bhayo jab hee ran daarun | kati kati gae baaj aru baarun |","meaning_en":"When the fearful battle was joined, horses and elephants were cut to pieces.","page":2485,"meaning_status":"draft"},{"gurmukhi":"ਜੰਬਕ ਗੀਧ ਮਾਸੁ ਲੈ ਗਏ। ਰਨ ਤਜਿ ਸੁਭਟਨ ਭਾਜਤ ਭਏ। ੧੦੬।","roman":"Janbak geedh maasu lai gae | ran taji subhtan bhaajat bhae | 106 |","meaning_en":"Jackals and vultures carried off the flesh; the warriors left the battle and fled. 106.","page":2485,"meaning_status":"draft"}]},{"type":"verse","number":[107],"number_text":"੧੦੭।","page":2485,"lines":[{"gurmukhi":"ਸਸਤ੍ਰ ਸਾਜ ਕੋਪਾ ਤਬ ਕਾਲਾ। ਧਾਰਨ ਭਯੋ ਭੇਸ ਬਿਕਰਾਲਾ।","roman":"Sasatr saaj kopaa tab kaalaa | dhaaran bhayo bhes bikraalaa |","meaning_en":"Then Kal, in rage, arranged his weapons and took on a terrible form.","page":2485,"meaning_status":"draft"},{"gurmukhi":"ਬਾਨ ਅਨੇਕ ਕੋਪ ਕਰਿ ਛੋਰੇ। ਸਤ੍ਰੁ ਅਨੇਕਨ ਕੇ ਸਿਰ ਫੋਰੇ। ੧੦੭।","roman":"Baan anek kop kari chhore | satru anekan ke sir phore | 107 |","meaning_en":"In anger he loosed many arrows and split the heads of many enemies. 107.","page":2485,"meaning_status":"draft"}]},{"type":"verse","number":[108],"number_text":"੧੦੮।","page":2485,"lines":[{"gurmukhi":"ਹਕਾਹਕੀ ਮਾਚਾ ਸੰਗ੍ਰਾਮਾ। ਪਠੈ ਦਏ ਬਹੁ ਅਰਿ ਮ੍ਰਿਤੁ ਧਾਮਾ।","roman":"Hakaahkee maachaa sangraamaa | pathai dae bahu ari mritu dhaamaa |","meaning_en":"A clamour of war arose; he sent many enemies to the abode of death.","page":2485,"meaning_status":"draft"},{"gurmukhi":"ਬਾਜ ਖੁਰਨ ਭੂ ਆਕੁਲ ਭਈ। ਖਟ ਪਟ ਭੂਮਿ ਗਗਨ ਉਡਿ ਗਈ। ੧੦੮।","roman":"Baaj khuran bhoo aakul bhaee | khat pat bhoomi gagan udi gaee | 108 |","meaning_en":"The earth was troubled by the hooves of horses; the khat pat of earth and sky flew up. 108.","page":2485,"meaning_status":"draft"}]},{"type":"verse","number":[109],"number_text":"੧੦੯।","page":2485,"lines":[{"gurmukhi":"ਏਕੈ ਰਹਿ ਗਯੋ ਜਬੈ ਪਯਾਲਾ। ਐਸਾ ਮਚਾ ਜੁਧ ਬਿਕਰਾਲਾ।","roman":"Ekai rahi gayo jabai payaalaa | aisaa machaa judh bikraalaa |","meaning_en":"When only one underworld remained, so fearful a battle arose.","page":2485,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਕਾਲ ਕੈ ਭਯੋ ਪ੍ਰਸੇਤਾ। ਡਾਰਾ ਭੂਮਿ ਪੌਛਿ ਕਰਿ ਤੇਤਾ। ੧੦੯।","roman":"Mahaa kaal kai bhayo prasetaa | daaraa bhoomi pauchhi kari tetaa | 109 |","meaning_en":"Mahakal broke into sweat, and with it wiped and cast down to the earth as much. 109.","page":2485,"meaning_status":"draft","note":"Obscure; uncertain."}]},{"type":"verse","number":[110],"number_text":"੧੧੦।","page":2485,"lines":[{"gurmukhi":"ਭਟਾਚਾਰਜ ਰੂਪ ਤਬ ਧਰਾ। ਬਦਨ ਪ੍ਰਸੇਤ ਧਰਨਿ ਜੋ ਪਰਾ।","roman":"Bhataachaaraj roop tab dharaa | badan praset dharni jo paraa |","meaning_en":"Then he took the form of a bard; the sweat that fell on the earth from his body","page":2485,"meaning_status":"draft"},{"gurmukhi":"ਢਾਢਿ ਸੈਨ ਢਾਢੀ ਬਪੁ ਲਯੋ। ਕਰਖਾ ਬਾਰ ਉਚਾਰਤ ਭਯੋ। ੧੧੦।","roman":"Dhaadhi sain dhaadhee bapu layo | karkhaa baar uchaarat bhayo | 110 |","meaning_en":"took the form of a Dhadhi, a dhadhi's army; they began to sing ballads. 110.","page":2485,"meaning_status":"draft","note":"ਢਾਢਿ ਸੈਨ ਢਾਢੀ ਬਪੁ: 'army of bards'; ਕਰਖਾ: war-ballad; uncertain."}]},{"type":"verse","number":[111],"number_text":"੧੧੧।","page":2485,"lines":[{"gurmukhi":"ਜਿਹ ਅਰਿ ਕਾਲ ਕ੍ਰਿਪਾਨ ਪ੍ਰਹਾਰੈ। ਇਕ ਤੇ ਦੋਇ ਪੁਰਖ ਕੈ ਡਾਰੈ।","roman":"Jih ari kaal kripaan prahaarai | ik te doi purakh kai daarai |","meaning_en":"Whichever enemy Kal struck with his sword, he made one man into two.","page":2485,"meaning_status":"draft"},{"gurmukhi":"ਦ੍ਵੈ ਮਨੁਖਨ ਪਰ ਕਰਤ ਪ੍ਰਹਾਰਾ। ਦ੍ਵੈ ਤੇ ਹੋਤ ਛਿਨਿਕ ਮੋ ਚਾਰਾ। ੧੧੧।","roman":"Dvai manukhan par karat prahaaraa | dvai te hot chhinik mo chaaraa | 111 |","meaning_en":"He struck at two men, and from two came four in an instant. 111.","page":2485,"meaning_status":"draft"}]},{"type":"verse","number":[112],"number_text":"੧੧੨।","page":2485,"lines":[{"gurmukhi":"ਬਹੁਰਿ ਕਾਲ ਕੀਨਾ ਘਮਸਾਨਾ। ਮਾਰਤ ਭਯੋ ਦੈਤ ਬਿਧਿ ਨਾਨਾ।","roman":"Bahuri kaal keenaa ghamsaanaa | maarat bhayo dait bidhi naanaa |","meaning_en":"Again Kal made a tumult; he killed demons in many ways.","page":2485,"meaning_status":"draft"},{"gurmukhi":"ਅਧਿਕ ਪ੍ਰਸੇਤ ਧਰਨਿ ਪਰ ਪਰਿਯੋ। ਭੂਮ ਸੈਨ ਤਾ ਤੇ ਬਪੁ ਧਰਿਯੋ। ੧੧੨।","roman":"Adhik praset dharni par pariyo | bhoom sain taa te bapu dhariyo | 112 |","meaning_en":"Much sweat fell on the earth, and from the earth an army took bodies. 112.","page":2485,"meaning_status":"draft"}]},{"type":"verse","number":[113],"number_text":"੧੧੩।","page":2485,"lines":[{"gurmukhi":"ਕਾਢਿ ਕ੍ਰਿਪਾਨ ਧਸੌ ਹੁੰਕਾਰਾ। ਤਿਨ ਤੇ ਅਮਿਤ ਗਨਨ ਤਨ ਧਾਰਾ।","roman":"Kaadhi kripaan dhasau hunkaaraa | tin te amit ganan tan dhaaraa |","meaning_en":"Drawing swords they rushed with a shout; from them countless Ganas took form.","page":2485,"meaning_status":"draft"},{"gurmukhi":"ਢੋਲ ਪਟਹਿ ਇਕ ਤਾਲ ਬਜਾਵੈ। ਜੰਗ ਮੁਚੰਗ ਉਪੰਗ ਸੁਨਾਵੈ। ੧੧੩।","roman":"Dhol pathi ik taal bajaavai | jang muchang upang sunaavai | 113 |","meaning_en":"They played drums and tabors in one rhythm, and sounded jang, muchang and upang. 113.","page":2485,"meaning_status":"draft","note":"ਗਨਨ: Ganas (attendants of Shiva); read so; uncertain."}]},{"type":"verse","number":[114],"number_text":"੧੧੪।","page":2485,"lines":[{"gurmukhi":"ਗੋਮੁਖ ਝਾਂਝਰ ਤੂਰ ਅਪਾਰਾ। ਢੋਲ ਮ੍ਰਿਦੰਗ ਮੁਚੰਗ ਨਗਾਰਾ।","roman":"Gomukh jhaanjhar toor apaaraa | dhol mridang muchang nagaaraa |","meaning_en":"Gomukh horns, cymbals and countless trumpets, drums, mridangs, muchangs and kettledrums","page":2485,"meaning_status":"draft"},{"gurmukhi":"ਬਾਜਤ ਭੇਰ ਭਭਾਕਹਿ ਭੀਖਨ। ਕਸਿ ਧਨੁ ਤਜਤ ਸੁਭਟ ਸਰ ਤੀਛਨ। ੧੧੪।","roman":"Baajat bher bhabhaakhi bheekhan | kasi dhanu tajat subhat sar teechhan | 114 |","meaning_en":"sounded; war-drums boomed dreadfully; drawing bows, warriors loosed sharp arrows. 114.","page":2485,"meaning_status":"draft"}]},{"type":"verse","number":[115],"number_text":"੧੧੫।","page":2485,"lines":[{"gurmukhi":"ਭਰਿ ਗੇ ਕੁੰਡ ਤਹਾ ਸ੍ਰੋਨਤ ਤਨ। ਪ੍ਰਗਟੇ ਅਸੁਰ ਤਵਨ ਤੇ ਅਨਗਨ।","roman":"Bhari ge kund tahaa sronat tan | pragte asur tavan te angan |","meaning_en":"Pools there were filled with blood; countless demons appeared from it.","page":2485,"meaning_status":"draft"},{"gurmukhi":"ਮਾਰਿ ਮਾਰਿ ਮਿਲਿ ਕਰਤ ਪੁਕਾਰਾ। ਤਿਨ ਤੇ ਪ੍ਰਗਟਤ ਅਸੁਰ ਹਜਾਰਾ। ੧੧੫।","roman":"Maari maari mili karat pukaaraa | tin te pragtat asur hajaaraa | 115 |","meaning_en":"Crying \"kill, kill\" together, thousands of demons appeared from them. 115.","page":2485,"meaning_status":"draft"}]},{"type":"verse","number":[116],"number_text":"੧੧੬।","page":2487,"lines":[{"gurmukhi":"ਤਿਨਹਿ ਕਾਲ ਜਬ ਧਰਨਿ ਗਿਰਾਵੈ। ਸ੍ਰੋਨ ਪੁਲਿਤ ਹ੍ਵੈ ਭੂਮਿ ਸੁਹਾਵੈ।","roman":"Tinhi kaal jab dharni giraavai | sron pulit hvai bhoomi suhaavai |","meaning_en":"When Kal threw them to the ground, the earth, thrilled by blood, looked splendid.","page":2487,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਤੇ ਅਮਿਤ ਅਸੁਰ ਉਠਿ ਭਜਹੀ। ਬਾਨ ਕ੍ਰਿਪਾਨ ਸੈਹਥੀ ਸਜਹੀ। ੧੧੬।","roman":"Taa te amit asur uthi bhajhee | baan kripaan saihthee sajhee | 116 |","meaning_en":"From it countless demons rose and ran, arranging arrows, swords and spears. 116.","page":2487,"meaning_status":"draft"}]},{"type":"verse","number":[117],"number_text":"੧੧੭।","page":2487,"lines":[{"gurmukhi":"ਅਧਿਕ ਕੋਪ ਕਰਿ ਸਮੁਹਿ ਸਿਧਾਰੇ। ਸਭੈ ਕਾਲ ਛਿਨ ਇਕ ਮੋ ਮਾਰੇ।","roman":"Adhik kop kari samuhi sidhaare | sabhai kaal chhin ik mo maare |","meaning_en":"In great rage they advanced before him; Kal killed them all in an instant.","page":2487,"meaning_status":"draft"},{"gurmukhi":"ਤਿਨ ਤੇ ਸ੍ਰੋਨਤ ਪਰਾ ਸਬੂਹਾ। ਸਾਜਤ ਭਏ ਅਸੁਰ ਤਬ ਬਿਯੂਹਾ। ੧੧੭।","roman":"Tin te sronat paraa saboohaa | saajat bhae asur tab biyoohaa | 117 |","meaning_en":"From them a mass of blood fell, and then the demons arranged their battle-array. 117.","page":2487,"meaning_status":"draft"}]},{"type":"verse","number":[118],"number_text":"੧੧੮।","page":2487,"lines":[{"gurmukhi":"ਦਾਰੁਨ ਮਚਾ ਜੁਧ ਤਬ ਝਟ ਪਟ। ਉਡਿਗੇ ਬਾਜ ਖੂਰਨ ਭੂ ਖਟ ਪਟ।","roman":"Daarun machaa judh tab jhat pat | udige baaj khooran bhoo khat pat |","meaning_en":"A dreadful battle arose then in haste; the horses' hooves sent up the earth's khat pat.","page":2487,"meaning_status":"draft"},{"gurmukhi":"ਹ੍ਵੈ ਗੇ ਤੇਰਹ ਗਗਨ ਅਪਾਰਾ। ਏਕੈ ਰਹਿ ਗਯੋ ਤਹਾ ਪਤਾਰਾ। ੧੧੮।","roman":"Hvai ge terah gagan apaaraa | ekai rahi gayo tahaa pataaraa | 118 |","meaning_en":"There came to be thirteen limitless skies; only one underworld remained there. 118.","page":2487,"meaning_status":"draft","note":"Obscure; uncertain."}]},{"type":"verse","number":[119],"number_text":"੧੧੯।","page":2487,"lines":[{"gurmukhi":"ਭਟਾਚਾਰਜ ਇਤੈ ਜਸੁ ਗਾਵੈ। ਢਾਢਿ ਸੈਨ ਕਰਖਾਹੁ ਸੁਨਾਵੈ।","roman":"Bhataachaaraj itai jasu gaavai | dhaadhi sain karkhaahu sunaavai |","meaning_en":"On this side the bard sang his praise; the army of bards recited ballads.","page":2487,"meaning_status":"draft"},{"gurmukhi":"ਤਿਮਿ ਤਿਮਿ ਕਾਲਹਿ ਬਢੈ ਗੁਮਾਨਾ। ਚਹਿ ਚਹਿ ਹਨੇ ਦੁਬਹਿਯਾ ਨਾਨਾ। ੧੧੯।","roman":"Timi timi kaalhi badhai gumaanaa | chahi chahi hane dubhiyaa naanaa | 119 |","meaning_en":"The more they did so, the more Kal's pride grew; he killed the dubahiyas again and again in many forms. 119.","page":2487,"meaning_status":"draft","note":"ਦੁਬਹਿਯਾ: obscure; uncertain."}]},{"type":"verse","number":[120],"number_text":"੧੨੦।","page":2487,"lines":[{"gurmukhi":"ਤਿਨ ਤੇ ਮੇਦ ਮਾਸ ਜੋ ਪਰ ਹੀ। ਰਥੀ ਗਜੀ ਬਾਜੀ ਤਨ ਧਰ ਹੀ।","roman":"Tin te med maas jo par hee | rathee gajee baajee tan dhar hee |","meaning_en":"From them marrow and flesh fell; they took the bodies of charioteers, elephants and horses.","page":2487,"meaning_status":"draft"},{"gurmukhi":"ਕੇਤਿਕ ਭਏ ਅਸੁਰ ਬਿਕਰਾਰਾ। ਤਿਨ ਕੇ ਬਰਨਨ ਕਰੌ ਸਿਧਾਰਾ। ੧੨੦।","roman":"Ketik bhae asur bikraaraa | tin ke barnan karau sidhaaraa | 120 |","meaning_en":"Some demons became terrible; I will describe them. 120.","page":2487,"meaning_status":"draft"}]},{"type":"verse","number":[121],"number_text":"੧੨੧।","page":2487,"lines":[{"gurmukhi":"ਏਕੈ ਚਰਨ ਆਖਿ ਏਕੈ ਜਿਨਿ। ਭੁਜਾ ਅਮਿਤ ਸਹਸ ਦ੍ਵੈ ਕੈ ਤਿਨ।","roman":"Ekai charan aakhi ekai jini | bhujaa amit sahas dvai kai tin |","meaning_en":"One had a single foot and one eye; countless thousands of arms, two of them.","page":2487,"meaning_status":"draft","note":"Obscure; uncertain."},{"gurmukhi":"ਪਾਚ ਪਾਚ ਸੈ ਭੁਜ ਕੇ ਘਨੇ। ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਹਾਥਨ ਮੈ ਬਨੇ। ੧੨੧।","roman":"Paach paach sai bhuj ke ghane | sasatr asatr haathan mai bane | 121 |","meaning_en":"Some had five hundred arms each; weapons and missiles were in their hands. 121.","page":2487,"meaning_status":"draft"}]},{"type":"verse","number":[122],"number_text":"੧੨੨।","page":2487,"lines":[{"gurmukhi":"ਏਕ ਚਰਨ ਏਕੈ ਕੀ ਨਾਸਾ। ਏਕ ਏਕ ਭੁਜ ਭ੍ਰਮਤ ਅਕਾਸਾ।","roman":"Ek charan ekai kee naasaa | ek ek bhuj bhramat akaasaa |","meaning_en":"One foot, one nose; each one's arm wandered in the sky.","page":2487,"meaning_status":"draft"},{"gurmukhi":"ਅਰਧ ਮੂੰਡ ਮੁੰਡਿਤ ਕੇਤੇ ਸਿਰ। ਕੇਸਨ ਧਰੇ ਕਿਤਕ ਧਾਏ ਫਿਰਿ। ੧੨੨।","roman":"Aradh moond mundit kete sir | kesan dhare kitak dhaae phiri | 122 |","meaning_en":"Some had heads half shaved, some shaved; others wearing their hair ran about again. 122.","page":2487,"meaning_status":"draft"}]},{"type":"verse","number":[123],"number_text":"੧੨੩।","page":2487,"lines":[{"gurmukhi":"ਏਕ ਏਕ ਮਦ ਕੋ ਸਰ ਪੀਯੈ। ਮਾਨਵ ਖਾਇ ਜਗਤ ਕੇ ਜੀਯੈ।","roman":"Ek ek mad ko sar peeyai | maanav khaai jagat ke jeeyai |","meaning_en":"Each drank a pool of wine; they ate men and lived in the world.","page":2487,"meaning_status":"draft"},{"gurmukhi":"ਦਸ ਸਹੰਸ ਭਾਂਗ ਕੇ ਭਰਿ ਘਟ। ਪੀ ਪੀ ਭਿਰਤ ਅਸੁਰ ਰਨ ਚਟ ਪਟ। ੧੨੩।","roman":"Das sahans bhaang ke bhari ghat | pee pee bhirat asur ran chat pat | 123 |","meaning_en":"Filling ten thousand pots of bhang, they drank and fought, the demons, in the battle. 123.","page":2487,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2487,"meaning_status":"draft"},{"type":"verse","number":[124],"number_text":"੧੨੪।","page":2487,"lines":[{"gurmukhi":"ਬਜ੍ਰ ਬਾਨ ਬਿਛੂਆ ਬਿਸਿਖ ਬਰਖੈ ਸਸਤ੍ਰ ਅਪਾਰ।","roman":"Bajr baan bichhooaa bisikh barkhai sasatr apaar |","meaning_en":"Thunderbolts, arrows, scorpion-darts and shafts rained, and weapons without limit;","page":2487,"meaning_status":"draft"},{"gurmukhi":"ਊਚ ਨੀਚ ਕਾਤਰ ਸੁਭਟ ਸਭ ਕੀਨੇ ਇਕ ਸਾਰ। ੧੨੪।","roman":"Ooch neech kaatar subhat sabh keene ik saar | 124 |","meaning_en":"high and low, they made all the warriors equally cowardly. 124.","page":2487,"meaning_status":"draft","note":"ਸਭ ਕੀਨੇ ਇਕ ਸਾਰ: 'made all alike'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2487,"meaning_status":"draft"},{"type":"verse","number":[125],"number_text":"੧੨੫।","page":2487,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਭਯੋ ਘੋਰ ਸੰਗ੍ਰਾਮਾ। ਲੈ ਲੈ ਅਮਿਤ ਜੁਧ ਕਾ ਸਾਮਾ।","roman":"Ih bidhi bhayo ghor sangraamaa | lai lai amit judh kaa saamaa |","meaning_en":"Thus a terrible battle took place, with countless warlike gear.","page":2487,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਕਾਲ ਕੋਪਤ ਭਯੋ ਜਬ ਹੀ। ਅਸੁਰ ਅਨੇਕ ਬਿਦਾਰੇ ਤਬ ਹੀ। ੧੨੫।","roman":"Mahaa kaal kopat bhayo jab hee | asur anek bidaare tab hee | 125 |","meaning_en":"When Mahakal grew angry, he tore apart many demons then. 125.","page":2487,"meaning_status":"draft"}]},{"type":"verse","number":[126],"number_text":"੧੨੬।","page":2487,"lines":[{"gurmukhi":"ਮਹਾ ਕਾਲ ਜਬ ਹੀ ਰਿਸਿ ਭਰਾ। ਘੋਰ ਭਯਾਨਕ ਆਹਵ ਕਰਾ।","roman":"Mahaa kaal jab hee risi bharaa | ghor bhayaanak aahav karaa |","meaning_en":"When Mahakal was filled with rage, he made a fearful, dreadful war.","page":2487,"meaning_status":"draft"},{"gurmukhi":"ਮਾਰਤ ਭਯੋ ਅਸੁਰ ਬਿਕਰਾਲਾ। ਸਿੰਘ ਨਾਦ ਕੀਨਾ ਤਤਕਾਲਾ। ੧੨੬।","roman":"Maarat bhayo asur bikraalaa | singh naad keenaa tatkaalaa | 126 |","meaning_en":"He killed terrible demons and at once gave a lion's roar. 126.","page":2487,"meaning_status":"draft"}]},{"type":"verse","number":[127],"number_text":"੧੨੭।","page":2487,"lines":[{"gurmukhi":"ਕਹੂੰ ਮਸਾਨ ਕਿਲਕਟੀ ਮਾਰੈ। ਭੈਰਵ ਕਹੂੰ ਠਾਢ ਭੁੰਕਾਰੈ।","roman":"Kahoon masaan kilaktee maarai | bhairav kahoon thaadh bhunkaarai |","meaning_en":"Here the goblins shrieked; Bhairavs stood and bellowed.","page":2487,"meaning_status":"draft"},{"gurmukhi":"ਜੋਗਨਿ ਦੈਤ ਅਧਿਕ ਹਰਖਾਨੇ। ਭੂਤ ਸਿਵਾ ਬੋਲੈ ਅਭਿਮਾਨੇ। ੧੨੭।","roman":"Jogni dait adhik harkhaane | bhoot sivaa bolai abhimaane | 127 |","meaning_en":"Yoginis and demons greatly rejoiced; ghosts and jackals cried proudly. 127.","page":2487,"meaning_status":"draft"}]},{"type":"verse","number":[128],"number_text":"੧੨੮।","page":2489,"lines":[{"gurmukhi":"ਝਾਲਰਿ ਝਾਂਝਰ ਢੋਲ ਮ੍ਰਿਦੰਗਾ। ਪਟਹ ਨਗਾਰੇ ਮੁਰਜ ਮੁਚੰਗਾ।","roman":"Jhaalri jhaanjhar dhol mridangaa | patah nagaare muraj muchangaa |","meaning_en":"Cymbals, bells, drums and mridangs, war-drums, kettledrums, murajs and muchangs,","page":2489,"meaning_status":"draft"},{"gurmukhi":"ਡਵਰੂ ਗੁਡਗੁਡੀ ਕਹੂੰ ਉਪੰਗਾ। ਨਾਇ ਨਫੀਰੀ ਬਜਤ ਸੁਰੰਗਾ। ੧੨੮।","roman":"Davroo gudgudee kahoon upangaa | naai napheeree bajat surangaa | 128 |","meaning_en":"damrus, gudgudis and upangs, flutes and pipes sounded sweetly. 128.","page":2489,"meaning_status":"draft"}]},{"type":"verse","number":[129],"number_text":"੧੨੯।","page":2489,"lines":[{"gurmukhi":"ਮੁਰਲੀ ਕਹੂੰ ਬਾਸੁਰੀ ਬਾਜਤ। ਕਹੂੰ ਉਪੰਗ ਮ੍ਰਿਦੰਗ ਬਰਾਜਤ।","roman":"Murlee kahoon baasuree baajat | kahoon upang mridang baraajat |","meaning_en":"In places flutes and pipes sounded; in places upangs and mridangs were heard.","page":2489,"meaning_status":"draft"},{"gurmukhi":"ਦੁੰਦਭਿ ਢੋਲ ਕਹੂੰ ਸਹਨਾਈ। ਬਾਜਤ ਭੇ ਲਖਿ ਪਰੀ ਲਰਾਈ। ੧੨੯।","roman":"Dundbhi dhol kahoon sahnaaee | baajat bhe lakhi paree laraaee | 129 |","meaning_en":"Kettledrums, drums and shehnais sounded, when the battle was seen to begin. 129.","page":2489,"meaning_status":"draft"}]},{"type":"verse","number":[130],"number_text":"੧੩੦।","page":2489,"lines":[{"gurmukhi":"ਮੁਰਜ ਮੁਚੰਗ ਬਜੈ ਤੁਰਹੀ ਰਨ। ਭੇਰਨ ਕੇ ਭਭਕਾਰ ਕਰਤ ਗਨ।","roman":"Muraj muchang bajai turhee ran | bheran ke bhabhkaar karat gan |","meaning_en":"Murajs and muchangs and trumpets sounded in the battle; hosts made the booming of the war-drums.","page":2489,"meaning_status":"draft"},{"gurmukhi":"ਹਾਥੀ ਘੋਰਨ ਕੇ ਦੁੰਦਭਿ ਰਨ। ਉਸਟਨ ਕੇ ਬਾਜੇ ਰਨ ਮੂਰਧਨ। ੧੩੦।","roman":"Haathee ghoran ke dundbhi ran | ustan ke baaje ran moordhan | 130 |","meaning_en":"The kettledrums of elephants and horses, and the drums of camels, sounded on the heads in the battle. 130.","page":2489,"meaning_status":"draft"}]},{"type":"verse","number":[131],"number_text":"੧੩੧।","page":2489,"lines":[{"gurmukhi":"ਕੇਤਿਕ ਸੁਭਟ ਸਰਨ ਕੇ ਮਾਰੇ। ਗਿਰਤ ਭਏ ਰਨ ਡੀਲ ਡਿਲਾਰੇ।","roman":"Ketik subhat saran ke maare | girat bhae ran deel dilaare |","meaning_en":"Some warriors, struck by arrows, fell in the battle, limp and loosened.","page":2489,"meaning_status":"draft"},{"gurmukhi":"ਜਦਪਿ ਪ੍ਰਾਨ ਸਮੁਹ ਹ੍ਵੈ ਦਏ। ਕਰ ਤੇ ਤਜਤ ਕ੍ਰਿਪਾਨਨ ਭਏ। ੧੩੧।","roman":"Jadpi praan samuh hvai dae | kar te tajat kripaanan bhae | 131 |","meaning_en":"Although they gave their lives facing the enemy, they let the swords fall from their hands. 131.","page":2489,"meaning_status":"draft"}]},{"type":"verse","number":[132],"number_text":"੧੩੨।","page":2489,"lines":[{"gurmukhi":"ਚਲਤ ਭਈ ਸਰਿਤਾ ਸ੍ਰੋਨਤ ਤਹ। ਜੁਧ ਭਯੋ ਕਾਲੀ ਅਸੁਰਨ ਜਹ।","roman":"Chalat bhaee saritaa sronat tah | judh bhayo kaalee asuran jah |","meaning_en":"A river of blood flowed where the battle of Kali with the demons took place.","page":2489,"meaning_status":"draft"},{"gurmukhi":"ਸੀਸ ਕੇਸ ਜਹ ਭਏ ਸਿਵਾਰਾ। ਸ੍ਰੋਨ ਪ੍ਰਵਾਹ ਬਹਤ ਹਹਰਾਰਾ। ੧੩੨।","roman":"Sees kes jah bhae sivaaraa | sron pravaah bahat hahraaraa | 132 |","meaning_en":"Where heads and hair became moss, the stream of blood flowed with a roar. 132.","page":2489,"meaning_status":"draft"}]},{"type":"verse","number":[133],"number_text":"੧੩੩।","page":2489,"lines":[{"gurmukhi":"ਬਾਜ ਬ੍ਰਿਛ ਜਹ ਬਹੇ ਅਨੇਕੈ। ਬਿਨ ਬ੍ਰਿਣ ਬੀਰ ਰਹਾ ਨਹਿ ਏਕੈ।","roman":"Baaj brichh jah bahe anekai | bin brin beer rahaa nahi ekai |","meaning_en":"Where horses and trees were carried along in numbers, not a single warrior was left without wounds.","page":2489,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਰੋਨ ਭਰੇ ਪਟ ਅਧਿਕ ਸੁਹਾਏ। ਚਾਚਰਿ ਖੇਲਿ ਮਨੌ ਘਰ ਆਏ। ੧੩੩।","roman":"Sron bhare pat adhik suhaae | chaachri kheli manau ghar aae | 133 |","meaning_en":"Garments soaked in blood looked splendid, as if they came home after playing the Holi songs. 133.","page":2489,"meaning_status":"draft","note":"ਚਾਚਰਿ: chachar, a spring song/game of Holi; uncertain."}]},{"type":"verse","number":[134],"number_text":"੧੩੪।","page":2489,"lines":[{"gurmukhi":"ਸੂਰਨ ਕੇ ਜਹ ਮੂੰਡ ਪਖਾਨਾ। ਸੋਭਿਤ ਰੰਗ ਭੂਮ ਮਹਿ ਨਾਨਾ।","roman":"Sooran ke jah moond pakhaanaa | sobhit rang bhoom mahi naanaa |","meaning_en":"Where the heads of warriors were stones, they shone in many colours on the battlefield.","page":2489,"meaning_status":"draft"},{"gurmukhi":"ਬਹੇ ਜਾਤ ਜਹ ਬ੍ਰਿਛ ਤੁਰੰਗਾ। ਬਡੇ ਸੈਲ ਸੇ ਲਸਤ ਮਤੰਗਾ। ੧੩੪।","roman":"Bahe jaat jah brichh turangaa | bade sail se lasat matangaa | 134 |","meaning_en":"Where trees and horses were carried along, great elephants shone like big mountains. 134.","page":2489,"meaning_status":"draft"}]},{"type":"verse","number":[135],"number_text":"੧੩੫।","page":2489,"lines":[{"gurmukhi":"ਮਛਰੀ ਤਨਕਿ ਅੰਗੁਰਿਯੈ ਸੋਹੈ। ਭੁਜਾ ਭੁਜੰਗਨ ਸੀ ਮਨ ਮੋਹੈ।","roman":"Machhree tanki anguriyai sohai | bhujaa bhujangan see man mohai |","meaning_en":"Fingers shone like fish; arms like snakes charmed the mind.","page":2489,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਗ੍ਰਾਹ ਸੇ ਖੜਗ ਝਮਕਹਿ। ਭਕ ਭਕ ਕਰ ਕਹੂੰ ਘਾਇ ਭਭਕਹਿ। ੧੩੫।","roman":"Kahoon graah se kharag jhamakhi | bhak bhak kar kahoon ghaai bhabhakhi | 135 |","meaning_en":"In places swords flashed like crocodiles; in places wounds gurgled \"bhak bhak\". 135.","page":2489,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਛੰਦ","roman":"Bhujang chhand","meaning_en":"Bhujang metre.","page":2489,"meaning_status":"draft"},{"type":"verse","number":[136],"number_text":"੧੩੬।","page":2489,"lines":[{"gurmukhi":"ਜਹਾ ਬੀਰ ਬੈਰੀ ਬਡੇ ਘੇਰਿ ਮਾਰੇ। ਤਹਾ ਭੂਤ ਔ ਪ੍ਰੇਤ ਨਾਚੇ ਮਤਵਾਰੇ।","roman":"Jahaa beer bairee bade gheri maare | tahaa bhoot au pret naache matvaare |","meaning_en":"Where great warrior enemies were surrounded and killed, ghosts and spirits danced there, intoxicated.","page":2489,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਡਾਕਨੀ ਝਾਕਨੀ ਹਾਕ ਮਾਰੈ। ਉਠੈ ਨਾਦ ਭਾਰੇ ਛੁਟੇ ਚੀਤਕਾਰੈ। ੧੩੬।","roman":"Kahoon daaknee jhaaknee haak maarai | uthai naad bhaare chhute cheetkaarai | 136 |","meaning_en":"In places dakinis and jhakinis shouted; great cries rose, and screams broke out. 136.","page":2489,"meaning_status":"draft"}]},{"type":"verse","number":[137],"number_text":"੧੩੭।","page":2489,"lines":[{"gurmukhi":"ਕਹੂੰ ਅੰਗੁਲੈ ਤ੍ਰਾਣ ਕਾਟਾ ਬਿਰਾਜੈ। ਕਹੂੰ ਅੰਗੁਲਾ ਕਾਟਿ ਕੇ ਰਤਨ ਰਾਜੈ।","roman":"Kahoon angulai traan kaataa biraajai | kahoon angulaa kaati ke ratan raajai |","meaning_en":"In places finger-guards and daggers shone; in places a cut finger shone like a jewel.","page":2489,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਟੀਕ ਟਾਂਕੇ ਕਟੈ ਟੋਪ ਸੋਹੈ। ਕਹੂੰ ਬੀਰ ਮਾਰੇ ਗਿਰੇ ਭੂਮਿ ਮੋਹੈ। ੧੩੭।","roman":"Kahoon teek taanke katai top sohai | kahoon beer maare gire bhoomi mohai | 137 |","meaning_en":"In places helmets shone, cut by the strokes; in places slain warriors lay on the earth, charming. 137.","page":2489,"meaning_status":"draft","note":"Obscure in places; uncertain."}]},{"type":"verse","number":[138],"number_text":"੧੩੮।","page":2489,"lines":[{"gurmukhi":"ਜਿਤੇ ਸ੍ਰੋਨ ਕੇ ਬੂੰਦ ਭੂ ਪੈ ਪਰੇ ਹੈ। ਤਿਤੇ ਦਾਨਵੋ ਰੂਪ ਬਾਕੇ ਧਰੇ ਹੈ।","roman":"Jite sron ke boond bhoo pai pare hai | tite daanvo roop baake dhare hai |","meaning_en":"As many drops of blood as fell on the earth, so many demons took on dreadful forms.","page":2489,"meaning_status":"draft"},{"gurmukhi":"ਹਠੀ ਓਰ ਚਾਰੌ ਬਿਖੈ ਆਨਿ ਢੂਕੇ। ਮਹਾ ਕੋਪ ਕੈ ਮਾਰ ਹੀ ਮਾਰਿ ਕੂਕੈ। ੧੩੮।","roman":"Hathee or chaarau bikhai aani dhooke | mahaa kop kai maar hee maari kookai | 138 |","meaning_en":"The obstinate ones came pressing on all four sides, and in great rage cried \"kill, kill\". 138.","page":2489,"meaning_status":"draft"}]},{"type":"verse","number":[139],"number_text":"੧੩੯।","page":2489,"lines":[{"gurmukhi":"ਜਿਤੇ ਦੈਤ ਆਏ ਤਿਤੇ ਕਾਲ ਮਾਰੇ। ਬਹੇ ਸ੍ਰੋਨ ਕੇ ਭੂਮ ਹੂੰ ਪੈ ਪਨਾਰੇ।","roman":"Jite dait aae tite kaal maare | bahe sron ke bhoom hoon pai panaare |","meaning_en":"As many demons as came, Kal killed; streams of blood flowed over the earth.","page":2489,"meaning_status":"draft"},{"gurmukhi":"ਉਠ ਦੈਤ ਬਾਕੇ ਬਲੀ ਸਸਤ੍ਰ ਲੈ ਕੈ। ਦੁਹੂੰ ਓਰ ਤੇ ਮਾਰ ਹੀ ਮਾਰਿ ਕੈ ਕੈ। ੧੩੯।","roman":"Uth dait baake balee sasatr lai kai | duhoon or te maar hee maari kai kai | 139 |","meaning_en":"Fine mighty demons rose, taking weapons, and from both sides cried \"kill, kill\". 139.","page":2489,"meaning_status":"draft"}]},{"type":"verse","number":[140],"number_text":"੧੪੦।","page":2491,"lines":[{"gurmukhi":"ਹਠੀ ਬਧਿ ਗੋਪਾ ਗੁਲਿਤ੍ਰਾਨ ਬਾਕੇ। ਹਠੀਲੇ ਕਟੀਲੇ ਰਜੀਲੇ ਨਿਸਾਕੇ।","roman":"Hathee badhi gopaa gulitraan baake | hatheele kateele rajeele nisaake |","meaning_en":"Obstinate, with armoured hands and fine slingers, stubborn, sharp, eager and fearless,","page":2491,"meaning_status":"draft","note":"ਹਠੀ ਬਧਿ ਗੋਪਾ ਗੁਲਿਤ੍ਰਾਨ: obscure words (gopha, gulitran: sling/armour guards); rendered loosely; uncertain."},{"gurmukhi":"ਗਦਾ ਹਾਥ ਲੈ ਕੇ ਕਿਤੇ ਬੀਰ ਗਾਜੇ। ਲਰੇ ਆਨਿ ਕੈ ਪੈਗ ਦ੍ਵੈ ਕੈ ਨ ਭਾਜੇ। ੧੪੦।","roman":"Gadaa haath lai ke kite beer gaaje | lare aani kai paig dvai kai na bhaaje | 140 |","meaning_en":"some warriors, taking maces in hand, roared; they came and fought and did not flee two steps. 140.","page":2491,"meaning_status":"draft"}]},{"type":"verse","number":[141],"number_text":"੧੪੧।","page":2491,"lines":[{"gurmukhi":"ਕਹੂੰ ਬੀਰ ਮਾਰੇ ਬਿਦਾਰੇ ਪਰੇ ਹੈ। ਕਹੂੰ ਖੇਤ ਮੈ ਖਿੰਗ ਖਤ੍ਰੀ ਜਰੇ ਹੈ।","roman":"Kahoon beer maare bidaare pare hai | kahoon khet mai khing khatree jare hai |","meaning_en":"In places slain and torn warriors lay; in places on the field Kshatriya archers burned.","page":2491,"meaning_status":"draft","note":"ਖਿੰਗ: a kind of arrow or horse; uncertain."},{"gurmukhi":"ਕਹੂੰ ਮਤ ਦੰਤੀ ਕਹੂੰ ਉਸਟ ਮਾਰੇ। ਬਿਰਾਜੈ ਕਹੂੰ ਨਗਨ ਖੰਡੇ ਕਟਾਰੇ। ੧੪੧।","roman":"Kahoon mat dantee kahoon usat maare | biraajai kahoon nagan khande kataare | 141 |","meaning_en":"In places drunken elephants and camels were killed; in places naked swords and daggers shone. 141.","page":2491,"meaning_status":"draft"}]},{"type":"verse","number":[142],"number_text":"੧੪੨।","page":2491,"lines":[{"gurmukhi":"ਕਹੂੰ ਖੋਲ ਖਾਂਡੇ ਗਿਰੇ ਭੂਮਿ ਸੋਹੈ। ਕਹੂੰ ਬੀਰ ਬਾਨੀ ਪਰੇ ਭੂਮਿ ਮੋਹੈ।","roman":"Kahoon khol khaande gire bhoomi sohai | kahoon beer baanee pare bhoomi mohai |","meaning_en":"In places helmets and swords lay fallen on the ground, shining; in places warriors lay slain in the earth, charming.","page":2491,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਸ੍ਵਾਰ ਮਾਰੇ ਫਿਰੈ ਬਾਜ ਛੂਟੈ। ਕਿਤੇ ਛੈਲ ਛੋਰੇ ਕਿਤੇ ਦੁਸਟ ਲੂਟੈ। ੧੪੨।","roman":"Kahoon svaar maare phirai baaj chhootai | kite chhail chhore kite dusat lootai | 142 |","meaning_en":"In places the riders were killed and horses wandered loose; some spared the fine ones, some looted the wicked. 142.","page":2491,"meaning_status":"draft","note":"Obscure; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2491,"meaning_status":"draft"},{"type":"verse","number":[143],"number_text":"੧੪੩।","page":2491,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਤਹਾ ਭਯੋ ਸੰਗ੍ਰਾਮਾ। ਨਿਰਖਤ ਦੇਵ ਦਾਨਵੀ ਬਾਮਾ।","roman":"Ih bidhi tahaa bhayo sangraamaa | nirkhat dev daanvee baamaa |","meaning_en":"Thus the battle took place there, while gods and demon-women watched.","page":2491,"meaning_status":"draft"},{"gurmukhi":"ਕੇਤਿਕ ਕਰੀ ਕਰਨ ਬਿਨੁ ਭਏ। ਪ੍ਰਾਪਤ ਦੁਸਟ ਨਿਧਨ ਕਹ ਗਏ। ੧੪੩।","roman":"Ketik karee karan binu bhae | praapat dusat nidhan kah gae | 143 |","meaning_en":"Some elephants lost their trunks; the wicked went to death. 143.","page":2491,"meaning_status":"draft"}]},{"type":"verse","number":[144],"number_text":"੧੪੪।","page":2491,"lines":[{"gurmukhi":"ਮਾਰਹਿ ਮਾਰਿ ਮਹਾ ਸੂਰ ਕੂਕਹਿ। ਕਾਢਿ ਕਾਢਿ ਦਾਤਨ ਕਹ ਢੂਕਹਿ।","roman":"Maarhi maari mahaa soor kookhi | kaadhi kaadhi daatan kah dhookhi |","meaning_en":"Great heroes cried \"kill, kill\"; baring their teeth they came on.","page":2491,"meaning_status":"draft"},{"gurmukhi":"ਬਾਜਹਿ ਢੋਲ ਮ੍ਰਿਦੰਗ ਨਗਾਰੇ। ਜੰਗ ਮਚੰਗ ਉਪੰਗ ਜੁਝਾਰੇ। ੧੪੪।","roman":"Baajhi dhol mridang nagaare | jang machang upang jujhaare | 144 |","meaning_en":"Drums, mridangs and kettledrums sounded; jang, muchang and upang, the fighters. 144.","page":2491,"meaning_status":"draft"}]},{"type":"verse","number":[145],"number_text":"੧੪੫।","page":2491,"lines":[{"gurmukhi":"ਜਿਹ ਤਨ ਕਾਲ ਬਿਸਿਖ ਕੀ ਮਾਰੈ। ਤਾ ਕਹ ਤਹੀ ਚੂਰ ਕਰਿ ਡਾਰੈ।","roman":"Jih tan kaal bisikh kee maarai | taa kah tahee choor kari daarai |","meaning_en":"In whose body Kal struck an arrow, he crushed him on the spot.","page":2491,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਕਰ ਕੋਪਿ ਕ੍ਰਿਪਾਨ ਪ੍ਰਹਾਰਤ। ਤਿਹ ਕਾ ਮੂੰਡ ਕਾਟਿ ਹੀ ਡਾਰਤ। ੧੪੫।","roman":"Jaa kar kopi kripaan prahaarat | tih kaa moond kaati hee daarat | 145 |","meaning_en":"Whom he struck in anger with his sword, he cut off his head. 145.","page":2491,"meaning_status":"draft"}]},{"type":"verse","number":[146],"number_text":"੧੪੬।","page":2491,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਭਯੋ ਭਯਾਨਕ ਜੁਧਾ। ਉਪਜਾ ਕਛੁਕ ਕਾਲ ਕੇ ਕ੍ਰਧਾ।","roman":"Ih bidhi bhayo bhayaanak judhaa | upjaa kachhuk kaal ke kradhaa |","meaning_en":"Thus a fearful battle took place; a little anger rose in Kal.","page":2491,"meaning_status":"draft"},{"gurmukhi":"ਕੇਸਨ ਤੇ ਗਹਿ ਅਸੁਰ ਪਛਾਰੇ। ਕਾਢਿ ਕ੍ਰਿਪਾਨ ਏਕ ਹਨਿ ਡਾਰੇ। ੧੪੬।","roman":"Kesan te gahi asur pachhaare | kaadhi kripaan ek hani daare | 146 |","meaning_en":"Seizing demons by their hair he threw them down; drawing his sword he killed one. 146.","page":2491,"meaning_status":"draft"}]},{"type":"verse","number":[147],"number_text":"੧੪੭।","page":2491,"lines":[{"gurmukhi":"ਮਾਰੇ ਅਧਿਕ ਤਾਹਿ ਦਾਨਵ ਰਨ। ਟੂਕ ਟੂਕ ਹ੍ਵੈਗੇ ਤਿਨ ਕੇ ਤਨ।","roman":"Maare adhik taahi daanav ran | took took hvaige tin ke tan |","meaning_en":"He killed many demons in the battle; their bodies became pieces.","page":2491,"meaning_status":"draft"},{"gurmukhi":"ਤਊ ਮਾਰ ਹੀ ਮਾਰਿ ਪੁਕਾਰਤ। ਪਾਛੇ ਪਾਵ ਏਕ ਨਹਿ ਡਾਰਤ। ੧੪੭।","roman":"Taoo maar hee maari pukaarat | paachhe paav ek nahi daarat | 147 |","meaning_en":"Yet they cried \"kill, kill\", and did not set back a single foot. 147.","page":2491,"meaning_status":"draft"}]},{"type":"verse","number":[148],"number_text":"੧੪੮।","page":2491,"lines":[{"gurmukhi":"ਕੇਤਿਕ ਘੂਮਿ ਗਿਰਤ ਹੈ ਘਾਇਲ। ਪਰਤ ਭਏ ਭੂ ਤਰ ਹ੍ਵੈ ਹਾਇਲ।","roman":"Ketik ghoomi girat hai ghaail | parat bhae bhoo tar hvai haail |","meaning_en":"Some, wounded, fell turning round; they fell to the earth in pain.","page":2491,"meaning_status":"draft"},{"gurmukhi":"ਤਊ ਜੁਧ ਕੋ ਤ੍ਯਾਗਿ ਨ ਭਜਹੀ। ਜਬ ਲਗਿ ਦੁਸਟ ਪ੍ਰਾਨ ਨਹਿ ਤਜਹੀ। ੧੪੮।","roman":"Taoo judh ko tyaagi na bhajhee | jab lagi dusat praan nahi tajhee | 148 |","meaning_en":"Even so they did not leave the battle and flee, so long as the wicked did not give up life. 148.","page":2491,"meaning_status":"draft"}]},{"type":"verse","number":[149],"number_text":"੧੪੯।","page":2491,"lines":[{"gurmukhi":"ਗੁਰਜ ਗੋਫਨੈ ਕਿਤਕ ਸੰਭਾਰੈ। ਕੇਤਿਕ ਕਸਿ ਕਸਿ ਬਾਨ ਪ੍ਰਹਾਰੈ।","roman":"Guraj gophnai kitak sanbhaarai | ketik kasi kasi baan prahaarai |","meaning_en":"Some took up clubs and slings; some drew and shot arrows with force.","page":2491,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤੇ ਤਮਕਿ ਰਨ ਤੁਰੀ ਨਚਾਵੈ। ਚਟਪਟ ਸੁਭਟ ਜੂਝਿ ਰਨ ਜਾਵੈ। ੧੪੯।","roman":"Kite tamki ran turee nachaavai | chatpat subhat joojhi ran jaavai | 149 |","meaning_en":"Some, bold, made horses prance in the battle; quickly the warriors went fighting to death. 149.","page":2491,"meaning_status":"draft","note":"ਤੁਰੀ: horse (turi, a horse) read so; uncertain."}]},{"type":"verse","number":[150],"number_text":"੧੫੦।","page":2491,"lines":[{"gurmukhi":"ਕਿਤਕ ਤਮਕਿ ਰਨ ਤੁਰੀ ਨਚਾਵਤ। ਮਾਰਿ ਮਾਰਿ ਧੁਨਿ ਕਿਤਕ ਉਘਾਵਤ।","roman":"Kitak tamki ran turee nachaavat | maari maari dhuni kitak ughaavat |","meaning_en":"Some made horses prance boldly; some raised the call \"kill, kill\".","page":2491,"meaning_status":"draft"},{"gurmukhi":"ਮੰਡਹਿ ਮਹਾ ਕਾਲ ਸੌ ਜੁਧਾ। ਹ੍ਵੈ ਹ੍ਵੈ ਅਧਿਕ ਚਿਤ ਮਹਿ ਕ੍ਰੂਧਾ। ੧੫੦।","roman":"Mandhi mahaa kaal sau judhaa | hvai hvai adhik chit mahi kroodhaa | 150 |","meaning_en":"They engaged in battle with Mahakal, becoming ever angrier in mind. 150.","page":2491,"meaning_status":"draft"}]},{"type":"verse","number":[151],"number_text":"੧੫੧।","page":2493,"lines":[{"gurmukhi":"ਜੇਤਿਕ ਸੁਭਟ ਕੋਪਿ ਕਰਿ ਆਏ। ਮਹਾ ਕਾਲ ਤੇਤੇ ਈ ਖਪਾਏ।","roman":"Jetik subhat kopi kari aae | mahaa kaal tete ee khapaae |","meaning_en":"However many warriors came in rage, Mahakal destroyed that many.","page":2493,"meaning_status":"draft"},{"gurmukhi":"ਤਿਨ ਕੋ ਮੇਦ ਮਾਸ ਭੂਅ ਪਰਾ। ਬਹੁ ਅਸੁਰਨ ਤਾ ਤੇ ਬਪੁ ਧਰਾ। ੧੫੧।","roman":"Tin ko med maas bhooa paraa | bahu asuran taa te bapu dharaa | 151 |","meaning_en":"Their marrow and flesh fell on the earth, and many demons took body from it. 151.","page":2493,"meaning_status":"draft"}]},{"type":"verse","number":[152],"number_text":"੧੫੨।","page":2493,"lines":[{"gurmukhi":"ਮਹਾ ਕਾਲ ਤੇ ਦਏ ਖਪਾਇ। ਸ੍ਰੋਨਤ ਸੋ ਪ੍ਰਿਥਵੀ ਰਹੀ ਛਾਇ।","roman":"Mahaa kaal te dae khapaai | sronat so prithvee rahee chhaai |","meaning_en":"Mahakal destroyed them,","page":2493,"meaning_status":"draft"},{"gurmukhi":"ਤਿਹ ਤੇ ਅਮਿਤ ਅਸੁਰ ਉਠਿ ਢੂਕੇ। ਮਾਰਹਿ ਮਾਰਿ ਦਸੌ ਦਿਸਿ ਕੂਕੇ। ੧੫੨।","roman":"Tih te amit asur uthi dhooke | maarhi maari dasau disi kooke | 152 |","meaning_en":"and the earth was covered with blood. From it countless demons rose and pressed in, crying \"kill, kill\" in all ten directions. 152.","page":2493,"meaning_status":"draft"}]},{"type":"verse","number":[153],"number_text":"੧੫੩।","page":2493,"lines":[{"gurmukhi":"ਕੇਤਿਕ ਕੀ ਬਾਹਨ ਕਟਿ ਡਾਰਾ। ਕਰੇ ਰੁੰਡ ਬਿਨੁ ਮੁੰਡ ਹਜਾਰਾ।","roman":"Ketik kee baahan kati daaraa | kare rund binu mund hajaaraa |","meaning_en":"Some he cut down with their mounts; he made thousands of trunks without heads.","page":2493,"meaning_status":"draft"},{"gurmukhi":"ਕੇਤਿਕ ਚੀਰ ਅਧੌ ਅਧ ਡਾਰੇ। ਨਾਚਤ ਭੂਤ ਪ੍ਰੇਤ ਮਤਵਾਰੇ। ੧੫੩।","roman":"Ketik cheer adhau adh daare | naachat bhoot pret matvaare | 153 |","meaning_en":"Some he split in half; ghosts and spirits danced, intoxicated. 153.","page":2493,"meaning_status":"draft"}]},{"type":"verse","number":[154],"number_text":"੧੫੪।","page":2493,"lines":[{"gurmukhi":"ਜ ਤਿਨ ਕੇ ਸਿਰਿ ਬਹੀ ਕ੍ਰਿਪਾਨੈ। ਅਰਧ ਅਰਧ ਹ੍ਵੈ ਜੂਝੇ ਜ੍ਵਾਨੈ।","roman":"Ja tin ke siri bahee kripaanai | aradh aradh hvai joojhe jvaanai |","meaning_en":"Those whose heads the sword struck, the youths fought on though cut in half.","page":2493,"meaning_status":"draft"},{"gurmukhi":"ਗਜ ਬਾਜੀ ਲੋਟਤ ਕਹੂੰ ਭੂ ਪਰ। ਸੁੰਭਨ ਸਬਦ ਸੁਨਾ ਅਵਨੀ ਤਰ। ੧੫੪।","roman":"Gaj baajee lotat kahoon bhoo par | sunbhan sabad sunaa avnee tar | 154 |","meaning_en":"Elephants and horses rolled on the earth in places; the sound of Sumbh was heard beneath the earth. 154.","page":2493,"meaning_status":"draft","note":"ਸੁੰਭਨ ਸਬਦ: obscure; uncertain."}]},{"type":"verse","number":[155],"number_text":"੧੫੫।","page":2493,"lines":[{"gurmukhi":"ਗਿਰਿ ਗਿਰਿ ਪਰੇ ਕਹੂੰ ਘਾਯਲ ਰਨ। ਭਾਜਿ ਚਲੇ ਕਈ ਹੋਇ ਬਿਮਨ ਮਨ।","roman":"Giri giri pare kahoon ghaayal ran | bhaaji chale kaee hoi biman man |","meaning_en":"In places wounded warriors fell in the battle; many fled with downcast minds.","page":2493,"meaning_status":"draft"},{"gurmukhi":"ਝਮਕਤ ਕਹੀ ਅਸਿਨ ਕੀ ਧਾਰਾ। ਭਭਕਤ ਰੁੰਡ ਮੁੰਡ ਬਿਕਰਾਰਾ। ੧੫੫।","roman":"Jhamkat kahee asin kee dhaaraa | bhabhkat rund mund bikraaraa | 155 |","meaning_en":"In places the edges of swords flashed; trunks and heads gurgled terribly. 155.","page":2493,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਛੰਦ","roman":"Bhujang chhand","meaning_en":"Bhujang metre.","page":2493,"meaning_status":"draft"},{"type":"verse","number":[156],"number_text":"੧੫੬।","page":2493,"lines":[{"gurmukhi":"ਤਹਾ ਜੁਧ ਮਾਚਾ ਮਹਾ ਬੀਰ ਖੇਤੰ। ਬਿਦਾਰੇ ਪਰੇ ਬੀਰ ਬ੍ਰਿੰਦੰ ਬਿਚੇਤੰ।","roman":"Tahaa judh maachaa mahaa beer khetan | bidaare pare beer brindan bichetan |","meaning_en":"There a great battle was joined on the field; broken heroes lay unconscious in heaps.","page":2493,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਡਾਮਰੂੰ ਡਹ ਡਹਾ ਸਬਦ ਬਾਜੈ। ਸੁਨੇ ਦੀਹ ਦਾਨਵਾਨ ਕੋ ਦ੍ਰਪ ਭਾਜੈ। ੧੫੬।","roman":"Kahoon daamroon dah dahaa sabad baajai | sune deeh daanvaan ko drap bhaajai | 156 |","meaning_en":"In places damrus sounded \"dah dahah\"; hearing the sound the pride of the demons fled. 156.","page":2493,"meaning_status":"draft"}]},{"type":"verse","number":[157],"number_text":"੧੫੭।","page":2493,"lines":[{"gurmukhi":"ਕਹੂੰ ਸੰਖ ਭੇਰੀ ਬਜੈ ਤਾਲ ਭਾਰੇ। ਕਹੂੰ ਬੇਨ ਬੀਨਾ ਪਨੋ ਔ ਨਗਾਰੇ।","roman":"Kahoon sankh bheree bajai taal bhaare | kahoon ben beenaa pano au nagaare |","meaning_en":"In places conches, drums and great cymbals sounded; in places flutes, veenas, panos and kettledrums.","page":2493,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਨਾਇ ਨਾਫੀਰਿਯੈ ਨਾਦ ਐਸੇ। ਬਜੈ ਘੋਰ ਬਾਜਾ ਪ੍ਰਲੈ ਕਾਲ ਜੈਸੇ। ੧੫੭।","roman":"Kahoon naai naapheeriyai naad aise | bajai ghor baajaa pralai kaal jaise | 157 |","meaning_en":"In places pipes sounded thus; a terrible music played like the end of time. 157.","page":2493,"meaning_status":"draft"}]},{"type":"verse","number":[158],"number_text":"੧੫੮।","page":2493,"lines":[{"gurmukhi":"ਕਹੂੰ ਛੈਨ ਤੂਰੈ ਨਗਾਰੈ ਮ੍ਰਿਦੰਗੈ। ਕਹੂੰ ਬਾਸੁਰੀ ਬੀਨ ਬਾਜੈ ਸੁਰੰਗੈ।","roman":"Kahoon chhain toorai nagaarai mridangai | kahoon baasuree been baajai surangai |","meaning_en":"In places drums, kettledrums and mridangs; in places flutes and veenas sounded sweetly.","page":2493,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਬਗਲ ਤਾਰੰਗ ਬਾਜੇ ਬਜਾਵੈ। ਕਹੂੰ ਬਾਰਤਾ ਰੰਗ ਨੀਕੇ ਸੁਹਾਵੈ। ੧੫੮।","roman":"Kahoon bagal taarang baaje bajaavai | kahoon baartaa rang neeke suhaavai | 158 |","meaning_en":"In places the bagal and tarang were played; in places news was told delightfully. 158.","page":2493,"meaning_status":"draft","note":"Instruments as printed; uncertain."}]},{"type":"verse","number":[159],"number_text":"੧੫੯।","page":2493,"lines":[{"gurmukhi":"ਕਹੂੰ ਝਾਂਝ ਬਾਜੈ ਕਹੂੰ ਤਾਲ ਐਸੇ। ਕਹੂੰ ਬੇਨੁ ਬੀਨਾ ਪ੍ਰਲੈ ਕਾਲ ਜੈਸੇ।","roman":"Kahoon jhaanjh baajai kahoon taal aise | kahoon benu beenaa pralai kaal jaise |","meaning_en":"In places cymbals sounded, in places beats thus; in places flute and veena like the end of time.","page":2493,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਬਾਸੁਰੀ ਨਾਇ ਨਾਦੈ ਮ੍ਰਿਦੰਗੈ। ਕਹੂੰ ਸਾਰੰਗੀ ਔ ਮੁਚੰਗੈ ਉਪੰਗੈ। ੧੫੯।","roman":"Kahoon baasuree naai naadai mridangai | kahoon saarangee au muchangai upangai | 159 |","meaning_en":"In places flutes, pipes and mridangs sounded; in places sarangi, muchang and upang. 159.","page":2493,"meaning_status":"draft"}]},{"type":"verse","number":[160],"number_text":"੧੬੦।","page":2493,"lines":[{"gurmukhi":"ਕਹੂੰ ਗਰਜਿ ਕੈ ਕੈ ਭੁਜਾ ਭੂਪ ਠੋਕੈ। ਕਹੂੰ ਬੀਰ ਬੀਰਾਨ ਕੀ ਰਾਹ ਰੋਕੈ।","roman":"Kahoon garji kai kai bhujaa bhoop thokai | kahoon beer beeraan kee raah rokai |","meaning_en":"In places kings roared and slapped their arms; in places warriors blocked the path of warriors.","page":2493,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤੇ ਅਸਤ੍ਰ ਔ ਸਸਤ੍ਰ ਲੈ ਲੈ ਚਲਾਵੈ। ਕਿਤੇ ਚਰਮ ਲੈ ਚੋਟ ਤਾ ਕੀ ਬਜਾਵੈ। ੧੬੦।","roman":"Kite asatr au sasatr lai lai chalaavai | kite charam lai chot taa kee bajaavai | 160 |","meaning_en":"Some took missiles and weapons and shot them; some took a shield and struck blows with it. 160.","page":2493,"meaning_status":"draft"}]},{"type":"verse","number":[161],"number_text":"੧੬੧।","page":2493,"lines":[{"gurmukhi":"ਕਹੂੰ ਰੁੰਡ ਸੋਹੈ ਕਹੂੰ ਮੁੰਡ ਬਾਕੇ। ਕਹੂੰ ਬੀਰ ਮਾਰੇ ਬਿਦਾਰੇ ਨਿਸਾਕੇ।","roman":"Kahoon rund sohai kahoon mund baake | kahoon beer maare bidaare nisaake |","meaning_en":"In places trunks shone, in places fine heads; in places warriors lay slain and torn, fearless.","page":2493,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਬਾਜ ਮਾਰੇ ਗਜਾਰਾਜ ਜੂਝੇ। ਕਹੂੰ ਉਸਟ ਕਾਟੇ ਨਹੀ ਜਾਤ ਬੂਝੇ। ੧੬੧।","roman":"Kahoon baaj maare gajaaraaj joojhe | kahoon usat kaate nahee jaat boojhe | 161 |","meaning_en":"In places horses were killed and elephants fought; in places camels lay cut, beyond reckoning. 161.","page":2493,"meaning_status":"draft"}]},{"type":"verse","number":[162],"number_text":"੧੬੨।","page":2495,"lines":[{"gurmukhi":"ਕਹੂੰ ਚਰਮ ਬਰਮੈ ਗਿਰੇ ਭੂਮਿ ਐਸੇ। ਬਗੇ ਬ੍ਯੋਤਿ ਡਾਰੇ ਸਮੈ ਸੀਤ ਜੈਸੇ।","roman":"Kahoon charam barmai gire bhoomi aise | bage byoti daare samai seet jaise |","meaning_en":"In places shields and armour fell on the ground, like white lightning dropped at the time of cold.","page":2495,"meaning_status":"draft","note":"ਬਗੇ ਬ੍ਯੋਤਿ ਡਾਰੇ: obscure; uncertain."},{"gurmukhi":"ਗਏ ਜੂਝਿ ਜੋਧਾ ਜਗੇ ਜੋਰ ਜੰਗੈ। ਮਨੋ ਪਾਨ ਕੈ ਭੰਗ ਸੋਏ ਮਲੰਗੈ। ੧੬੨।","roman":"Gae joojhi jodhaa jage jor jangai | mano paan kai bhang soe malangai | 162 |","meaning_en":"Warriors lay killed who had awakened to fierce battle, like malangs asleep after taking drink and bhang. 162.","page":2495,"meaning_status":"draft"}]},{"type":"verse","number":[163],"number_text":"੧੬੩।","page":2495,"lines":[{"gurmukhi":"ਕਿਤੇ ਡਹਡਹਾ ਸਬਦ ਡਵਰੂ ਬਜਾਵੈ। ਕਿਤੇ ਰਾਗ ਮਾਰੂ ਖਰੇ ਖੇਤ ਗਾਵੈ।","roman":"Kite dahadhaa sabad davroo bajaavai | kite raag maaroo khare khet gaavai |","meaning_en":"Some sounded damrus with the sound \"dahdaha\"; some sang the Maru raga standing on the field.","page":2495,"meaning_status":"draft"},{"gurmukhi":"ਹਸੈ ਗਰਜਿ ਠੋਕੈ ਭੁਜਾ ਪਾਟ ਫਾਟੈ। ਕਿਤੇ ਬੀਰ ਬੀਰਾਨ ਕੇ ਮੂੰਡ ਕਾਟੈ। ੧੬੩।","roman":"Hasai garji thokai bhujaa paat phaatai | kite beer beeraan ke moond kaatai | 163 |","meaning_en":"They laughed, roared, slapped arms, tearing silk; some warriors cut off the heads of warriors. 163.","page":2495,"meaning_status":"draft"}]},{"type":"verse","number":[164],"number_text":"੧੬੪।","page":2495,"lines":[{"gurmukhi":"ਕਹੂੰ ਚੰਚਲਾ ਚਾਰੁ ਚੀਰੈ ਬਨੈਕੈ। ਬਰੈ ਜ੍ਵਾਨਿ ਜੋਧਾ ਜੁਝਿਯੋ ਜ੍ਵਾਨ ਧੈਕੈ।","roman":"Kahoon chanchlaa chaaru cheerai banaikai | barai jvaani jodhaa jujhiyo jvaan dhaikai |","meaning_en":"In places a fickle woman, beautifully dressed, chooses a young warrior fighting in the fight.","page":2495,"meaning_status":"draft","note":"ਚੰਚਲਾ ਚਾਰੁ ਚੀਰੈ: obscure; uncertain."},{"gurmukhi":"ਕਹੂੰ ਬੀਰ ਬੀਰਾਨ ਕੇ ਪਾਵ ਪੇਲੈ। ਮਹਾ ਜੰਗ ਜੋਧਾ ਲਗੇ ਸੁਧ ਸੇਲੈ। ੧੬੪।","roman":"Kahoon beer beeraan ke paav pelai | mahaa jang jodhaa lage sudh selai | 164 |","meaning_en":"In places warriors pushed the feet of warriors; in the great battle warriors struck spears. 164.","page":2495,"meaning_status":"draft"}]},{"type":"verse","number":[165],"number_text":"੧੬੫।","page":2495,"lines":[{"gurmukhi":"ਕਹੂੰ ਜਛਨੀ ਕਿੰਨ੍ਰਨੀ ਆਨਿ ਕੈ ਕੈ। ਕਹੂੰ ਗੰਧ੍ਰਬੀ ਦੇਵਨੀ ਮੋਦ ਹ੍ਵੈ ਕੈ।","roman":"Kahoon jachhnee kinnranee aani kai kai | kahoon gandhrabee devnee mod hvai kai |","meaning_en":"In places yakshinis and kinnaris came; in places gandharvis and goddesses, glad.","page":2495,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਅਛਰਾ ਪਛਰਾ ਗੀਤ ਗਾਵੈ। ਕਹੂੰ ਚੰਚਲਾ ਅੰਚਲਾ ਕੋ ਬਨਾਵੈ। ੧੬੫।","roman":"Kahoon achhraa pachhraa geet gaavai | kahoon chanchlaa anchlaa ko banaavai | 165 |","meaning_en":"In places apsaras sang songs; in places the fickle ones arranged their veils. 165.","page":2495,"meaning_status":"draft"}]},{"type":"verse","number":[166],"number_text":"੧੬੬।","page":2495,"lines":[{"gurmukhi":"ਕਹੂੰ ਦੇਵ ਕੰਨ੍ਯਾ ਨਚੈ ਤਾਲ ਦੈ ਕੈ। ਕਹੂੰ ਦੈਤ ਪੁਤ੍ਰੀ ਹਸੈ ਮੋਦ ਹ੍ਵੈ ਕੈ।","roman":"Kahoon dev kannyaa nachai taal dai kai | kahoon dait putree hasai mod hvai kai |","meaning_en":"In places daughters of gods danced to the beat; in places the daughters of demons laughed, glad.","page":2495,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਚੰਚਲਾ ਅੰਚਲਾ ਕੋ ਬਨਾਵੈ। ਕਹੂੰ ਜਛਨੀ ਕਿੰਨ੍ਰਨੀ ਗੀਤ ਗਾਵੈ। ੧੬੬।","roman":"Kahoon chanchlaa anchlaa ko banaavai | kahoon jachhnee kinnranee geet gaavai | 166 |","meaning_en":"In places the fickle ones arranged their veils; in places yakshinis and kinnaris sang songs. 166.","page":2495,"meaning_status":"draft"}]},{"type":"verse","number":[167],"number_text":"੧੬੭।","page":2495,"lines":[{"gurmukhi":"ਲਰੈ ਆਨਿ ਜੋਧਾ ਮਹਾ ਤੇਜ ਤੈ ਕੈ। ਗਿਰੇ ਪਾਕ ਸਾਹੀਦ ਯਾਕੀਨ ਹ੍ਵੈ ਕੈ।","roman":"Larai aani jodhaa mahaa tej tai kai | gire paak saaheed yaakeen hvai kai |","meaning_en":"Warriors came and fought with great splendour; they fell pure, martyrs, resolute.","page":2495,"meaning_status":"draft","note":"ਪਾਕ ਸਾਹੀਦ ਯਾਕੀਨ: Persian: 'pure, martyr, certainty'; as printed."},{"gurmukhi":"ਕਹੂੰ ਬੀਰ ਬਾਕੇ ਨਚਾਵੈ ਤੁਰੰਗੈ। ਕਹੂੰ ਜੰਗ ਜੋਧਾ ਬਿਰਾਜੈ ਉਤੰਗੈ। ੧੬੭।","roman":"Kahoon beer baake nachaavai turangai | kahoon jang jodhaa biraajai utangai | 167 |","meaning_en":"In places fine warriors made horses prance; in places heroes of war shone, tall. 167.","page":2495,"meaning_status":"draft"}]},{"type":"verse","number":[168],"number_text":"੧੬੮।","page":2495,"lines":[{"gurmukhi":"ਕਹੂੰ ਬੀਰ ਬਾਨੈਤ ਬੀਰੇ ਉਠਾਵੈ। ਕਹੂੰ ਖੇਤ ਮੈ ਖਿੰਗ ਖਤ੍ਰੀ ਨਚਾਵੈ।","roman":"Kahoon beer baanait beere uthaavai | kahoon khet mai khing khatree nachaavai |","meaning_en":"In places warriors lifted warriors; in places on the field Kshatriya archers made their horses dance.","page":2495,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਕੋਪ ਕੈ ਕੈ ਹਠੀ ਦਾਤ ਚਾਬੈ। ਕਿਤੇ ਮੂੰਛ ਐਠੈ ਕਿਤੇ ਪਾਗ ਦਾਬੈ। ੧੬੮।","roman":"Kahoon kop kai kai hathee daat chaabai | kite moonchh aithai kite paag daabai | 168 |","meaning_en":"In places the obstinate ones in rage chewed their teeth; some twirled moustaches, some pressed turbans. 168.","page":2495,"meaning_status":"draft"}]},{"type":"verse","number":[169],"number_text":"੧੬੯।","page":2495,"lines":[{"gurmukhi":"ਦੁਹੂੰ ਓਰ ਗਾਜੇ ਜਬੈ ਛਤ੍ਰਧਾਰੀ। ਮਚੋ ਲੋਹ ਗਾੜੋ ਪਰੀ ਮਾਰਿ ਭਾਰੀ।","roman":"Duhoon or gaaje jabai chhatradhaaree | macho loh gaaro paree maari bhaaree |","meaning_en":"When the umbrella-bearing warriors roared on both sides, a thick iron clash arose and a great slaughter fell.","page":2495,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਕੋਪ ਕੈ ਬੀਰ ਬਾਜੀ ਉਚਕੈ। ਲਗੇ ਦੇਹ ਮੋ ਘਾਇ ਗਾੜੇ ਭਭਕੈ। ੧੬੯।","roman":"Mahaa kop kai beer baajee uchkai | lage deh mo ghaai gaare bhabhkai | 169 |","meaning_en":"In great rage warriors leapt on horses; deep wounds fell on their bodies and gurgled. 169.","page":2495,"meaning_status":"draft"}]},{"type":"verse","number":[170],"number_text":"੧੭੦।","page":2495,"lines":[{"gurmukhi":"ਕਹੂੰ ਕੁੰਡਲਾਕਾਰ ਮੁੰਡੈ ਬਿਰਾਜੈ। ਲਖੇ ਮੁੰਡ ਮਾਲਾਹੁ ਕੇ ਮੁੰਡ ਲਾਜੈ।","roman":"Kahoon kundlaakaar mundai biraajai | lakhe mund maalaahu ke mund laajai |","meaning_en":"In places heads shone in circles; seeing the heads, those of the garland shamed.","page":2495,"meaning_status":"draft","note":"Obscure; uncertain."},{"gurmukhi":"ਕਹੂੰ ਘੂੰਮ ਘੂਮੈ ਪਰੇ ਬੀਰ ਭਾਰੀ। ਮਨੋ ਸਿਧ੍ਯ ਬੈਠੇ ਲਗੇ ਜੋਗ ਤਾਰੀ। ੧੭੦।","roman":"Kahoon ghoonm ghoomai pare beer bhaaree | mano sidhy baithe lage jog taaree | 170 |","meaning_en":"In places great warriors fell, turning round, as if siddhas sat absorbed in yoga. 170.","page":2495,"meaning_status":"draft"}]},{"type":"verse","number":[171],"number_text":"੧੭੧।","page":2495,"lines":[{"gurmukhi":"ਤਹਾ ਸ੍ਰੋਨ ਕੀ ਕੂਲ ਘਾਰੀ ਬਿਰਾਜੈ। ਲਖੈ ਅਸਟ ਨਦ੍ਯਾਨ ਕੋ ਦ੍ਰਪ ਭਾਜੈ।","roman":"Tahaa sron kee kool ghaaree biraajai | lakhai asat nadyaan ko drap bhaajai |","meaning_en":"There a bank of blood shone; seeing it the pride of the eight rivers fled.","page":2495,"meaning_status":"draft","note":"ਕੂਲ ਘਾਰੀ: bank/channel; uncertain."},{"gurmukhi":"ਤਹਾ ਬ੍ਰਿੰਦ ਬਾਜੀ ਬਹੇ ਨਕ੍ਰ ਜੈਸੇ। ਲਸੈ ਮਤ ਦੰਤੀ ਮਹਾ ਸੈਲ ਕੈਸੇ। ੧੭੧।","roman":"Tahaa brind baajee bahe nakr jaise | lasai mat dantee mahaa sail kaise | 171 |","meaning_en":"There hosts of horses were carried along like crocodiles; mad elephants shone like great mountains. 171.","page":2495,"meaning_status":"draft"}]},{"type":"verse","number":[172],"number_text":"੧੭੨।","page":2495,"lines":[{"gurmukhi":"ਧੁਜਾ ਬ੍ਰਿਛ ਤਾ ਮੋ ਬਹੇ ਜਾਤ ਐਸੇ। ਲਸੈ ਡੰਡ ਪਤ੍ਰੀ ਬਿਨਾ ਪਤ੍ਰ ਜੈਸੇ।","roman":"Dhujaa brichh taa mo bahe jaat aise | lasai dand patree binaa patr jaise |","meaning_en":"Banners and trees were carried along in it, shining like staves without leaves.","page":2495,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਛਤ੍ਰ ਤਾ ਮੋ ਬਹੇ ਜਾਤ ਕਾਟੇ। ਮਨੋ ਫੇਨ ਸੇ ਬਾਰਿ ਮੈ ਬਸਤ੍ਰ ਫਾਟੇ। ੧੭੨।","roman":"Kahoon chhatr taa mo bahe jaat kaate | mano phen se baari mai basatr phaate | 172 |","meaning_en":"In places umbrellas were carried along cut, like foam on the water, torn garments. 172.","page":2495,"meaning_status":"draft"}]},{"type":"verse","number":[173],"number_text":"੧੭੩।","page":2495,"lines":[{"gurmukhi":"ਕਹੂੰ ਬਾਹ ਕਾਟੀ ਬਹੇ ਜਾਤ ਐਸੇ। ਮਨੋ ਪੰਚ ਬਕ੍ਰਤਾਨ ਕੇ ਨਾਗ ਜੈਸੇ।","roman":"Kahoon baah kaatee bahe jaat aise | mano panch bakrataan ke naag jaise |","meaning_en":"In places cut arms were carried along like five-headed snakes.","page":2495,"meaning_status":"draft","note":"ਪੰਚ ਬਕ੍ਰਤਾਨ ਕੇ ਨਾਗ: 'five-mouthed serpents'."},{"gurmukhi":"ਚੜੇ ਬੀਰ ਬਾਜੀ ਬਹੇ ਜਾਤ ਮਾਰੇ। ਸਨਾਹੀਨ ਕੇ ਸ੍ਵਾਰ ਪਾਰੈ ਪਧਾਰੇ। ੧੭੩।","roman":"Chare beer baajee bahe jaat maare | sanaaheen ke svaar paarai padhaare | 173 |","meaning_en":"Warriors on horses were carried along slain; the riders of armoured horses went to the other bank. 173.","page":2495,"meaning_status":"draft","note":"ਸਨਾਹੀਨ: armoured; uncertain."}]},{"type":"verse","number":[174],"number_text":"੧੭੪।","page":2497,"lines":[{"gurmukhi":"ਕਹੂੰ ਖੋਲ ਖੰਡੇ ਬਹੇ ਜਾਤ ਮਾਰੇ। ਮਨੋ ਏਕਠੇ ਕਛ ਮਛ ਹ੍ਵੈ ਪਧਾਰੇ।","roman":"Kahoon khol khande bahe jaat maare | mano ekthe kachh machh hvai padhaare |","meaning_en":"In places helmets and swords were carried along, as if tortoises and fish had gathered.","page":2497,"meaning_status":"draft"},{"gurmukhi":"ਤਹਾ ਪਾਗ ਛੂਟੇ ਬਹੇ ਜਾਤ ਐਸੇ। ਮਨੋ ਤੀਸ ਬ੍ਯਾਮਾਨ ਕੇ ਨਾਗ ਜੈਸੇ। ੧੭੪।","roman":"Tahaa paag chhoote bahe jaat aise | mano tees byaamaan ke naag jaise | 174 |","meaning_en":"There turbans loosened and were carried along, like snakes of thirty cubits. 174.","page":2497,"meaning_status":"draft","note":"ਬ੍ਯਾਮਾਨ: 'vyam', a measure of length; uncertain."}]},{"type":"verse","number":[175],"number_text":"੧੭੫।","page":2497,"lines":[{"gurmukhi":"ਝਖੀ ਝੁੰਡ ਜਾ ਮੈ ਕਟਾਰੀ ਬਿਰਾਜੈ। ਲਖੇ ਖਿੰਗ ਬਾਕੇ ਬਲੀ ਨਾਗ ਲਾਜੈ।","roman":"Jhakhee jhund jaa mai kataaree biraajai | lakhe khing baake balee naag laajai |","meaning_en":"Where a dagger shone like a school of fish, seeing the fine arrows the strong snakes were ashamed.","page":2497,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਚਰਮ ਕਾਟੇ ਗਿਰੇ ਸਸਤ੍ਰ ਅਸਤ੍ਰੈ। ਕਹੂੰ ਬੀਰ ਬਾਜੀ ਬਹੇ ਜਾਤ ਬਸਤ੍ਰੈ। ੧੭੫।","roman":"Kahoon charam kaate gire sasatr astrai | kahoon beer baajee bahe jaat bastrai | 175 |","meaning_en":"In places cut shields, missiles and weapons fell; in places warriors and horses were carried along in garments. 175.","page":2497,"meaning_status":"draft"}]},{"type":"verse","number":[176],"number_text":"੧੭੬।","page":2497,"lines":[{"gurmukhi":"ਹਲਾਚਾਲ ਕੈ ਕੈ ਹਠੀ ਦੈਤ ਢੂਕੇ। ਚਹੂੰ ਓਰ ਗਾਜੇ ਮਹਾ ਕਾਲ ਜੂ ਕੇ।","roman":"Halaachaal kai kai hathee dait dhooke | chahoon or gaaje mahaa kaal joo ke |","meaning_en":"The obstinate demons pressed on with tumult; they roared on all four sides at Mahakal.","page":2497,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤੇ ਕੋਪ ਕੈ ਸਸਤ੍ਰ ਅਸਤ੍ਰੈ ਚਲਾਵੈ। ਕਿਤੇ ਸੰਖ ਔ ਭੀਮ ਭੇਰੀ ਬਜਾਵੈ। ੧੭੬।","roman":"Kite kop kai sasatr astrai chalaavai | kite sankh au bheem bheree bajaavai | 176 |","meaning_en":"Some in rage shot missiles and weapons; some blew conches and dreadful drums. 176.","page":2497,"meaning_status":"draft"}]},{"type":"verse","number":[177],"number_text":"੧੭੭।","page":2497,"lines":[{"gurmukhi":"ਮਹਾ ਫੂਲਿ ਫੀਲੀ ਨਗਾਰੇ ਬਜੈ ਕੈ। ਚਲੇ ਦੁੰਦਭੀ ਤਾਜਿਯੌ ਕੇ ਸੁਨੈ ਕੈ।","roman":"Mahaa phooli pheelee nagaare bajai kai | chale dundbhee taajiyau ke sunai kai |","meaning_en":"Great kettledrums sounded, swollen; drums sounded as the Tajiks were heard.","page":2497,"meaning_status":"draft","note":"Obscure; uncertain."},{"gurmukhi":"ਮਚੇ ਕੋਪ ਕੈ ਸੁ ਉਸਟੀ ਦਮਾਮੇ। ਮਨੋ ਬਾਜ ਟੁਟੇ ਲਖੇ ਲਾਲ ਤਾਮੇ। ੧੭੭।","roman":"Mache kop kai su ustee damaame | mano baaj tute lakhe laal taame | 177 |","meaning_en":"In rage the camel-drums resounded; red copper seemed to have been broken like horses. 177.","page":2497,"meaning_status":"draft","note":"Obscure; uncertain."}]},{"type":"verse","number":[178],"number_text":"੧੭੮।","page":2497,"lines":[{"gurmukhi":"ਕਿਤੇ ਬੀਰ ਬਾਕੇ ਧਰੇ ਲਾਲ ਬਾਨੇ। ਕਿਤੇ ਸ੍ਯਾਮ ਔ ਸੇਤ ਕੀਨੇ ਨਿਸਾਨੇ।","roman":"Kite beer baake dhare laal baane | kite syaam au set keene nisaane |","meaning_en":"Some fine warriors wore red dresses; some made black and white banners.","page":2497,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤੇ ਹਰਤਿ ਯੌ ਪੀਤ ਬਾਨੇ ਸੁਹਾਏ। ਹਠੀ ਚੁੰਗ ਬਾਧੇ ਚਲੇ ਖੇਤ ਆਏ। ੧੭੮।","roman":"Kite harti yau peet baane suhaae | hathee chung baadhe chale khet aae | 178 |","meaning_en":"Some shone in green and yellow dresses; the obstinate ones, tying their hair-knots, came to the field. 178.","page":2497,"meaning_status":"draft"}]},{"type":"verse","number":[179],"number_text":"੧੭੯।","page":2497,"lines":[{"gurmukhi":"ਕਿਤੇ ਢਾਲ ਢਾਪੈ ਕਿਤੇ ਚੋਟ ਓਟੈ। ਸਭੈ ਆਨਿ ਜੂਝੈ ਭਜੈ ਕੋਟ ਕੋਟੈ।","roman":"Kite dhaal dhaapai kite chot otai | sabhai aani joojhai bhajai kot kotai |","meaning_en":"Some covered with shields, some took blows on the guard; all came and fought; crores fled.","page":2497,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤੇ ਸੂਲ ਔ ਸੈਹਥੀ ਖਿੰਗ ਖੇਲੈ। ਕਿਤੇ ਪਾਸ ਔ ਪਰਸ ਲੈ ਪਾਵ ਪੇਲੈ। ੧੭੯।","roman":"Kite sool au saihthee khing khelai | kite paas au paras lai paav pelai | 179 |","meaning_en":"Some played with spears, spears and shields; some with nooses and axes pushed forward their feet. 179.","page":2497,"meaning_status":"draft"}]},{"type":"verse","number":[180],"number_text":"੧੮੦।","page":2497,"lines":[{"gurmukhi":"ਕਿਤੇ ਪਾਖਰੈ ਡਾਰਿ ਕੈ ਤਾਜਿਯੌ ਪੈ। ਚੜੈ ਚਾਰੁ ਜਾਮੈ ਕਿਤੇ ਬਾਜਿਯੌ ਪੈ।","roman":"Kite paakhrai daari kai taajiyau pai | charai chaaru jaamai kite baajiyau pai |","meaning_en":"Some, throwing armour on Tajik horses, mounted beautifully dressed on the steeds.","page":2497,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤੇ ਮਦ ਦੰਤੀਨਿਯੌ ਪੈ ਬਿਰਾਜੈ। ਮਨੋ ਬਾਰਣੇਸੇ ਚੜੇ ਇੰਦ੍ਰ ਲਾਜੈ। ੧੮੦।","roman":"Kite mad danteeniyau pai biraajai | mano baarnese chare indr laajai | 180 |","meaning_en":"Some rode mad elephants, so that Indra on Airavat would be ashamed. 180.","page":2497,"meaning_status":"draft","note":"ਬਾਰਣੇਸ: obscure; read as Indra's elephant."}]},{"type":"verse","number":[181],"number_text":"੧੮੧।","page":2497,"lines":[{"gurmukhi":"ਕਿਤੇ ਖਚਰਾਰੋਹ ਬੈਰੀ ਬਿਰਾਜੈ। ਕਿਤੇ ਗਰਧਭੈ ਪੈ ਚੜੇ ਸੂਰ ਗਾਜੈ।","roman":"Kite khachraaroh bairee biraajai | kite garadhbhai pai chare soor gaajai |","meaning_en":"Some enemies shone riding mules; some heroes roared on donkeys.","page":2497,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤੇ ਦਾਨਵੌ ਪੈ ਚੜੇ ਦੈਤ ਭਾਰੇ। ਚਹੂੰ ਓਰ ਗਾਜੇ ਸੁ ਦੈ ਕੈ ਨਗਾਰੇ। ੧੮੧।","roman":"Kite daanvau pai chare dait bhaare | chahoon or gaaje su dai kai nagaare | 181 |","meaning_en":"Some great demons rode on demons; they roared on all four sides, beating drums. 181.","page":2497,"meaning_status":"draft"}]},{"type":"verse","number":[182],"number_text":"੧੮੨।","page":2497,"lines":[{"gurmukhi":"ਕਿਤੇ ਮਾਹਿਖੀ ਪੈ ਚੜੇ ਦੈਤ ਢੂਕੇ। ਕਿਤੇ ਸੂਕਰਾ ਸ੍ਵਾਰ ਹ੍ਵੈ ਆਨਿ ਝੂਕੇ।","roman":"Kite maahikhee pai chare dait dhooke | kite sookraa svaar hvai aani jhooke |","meaning_en":"Some demons rode she-buffaloes and pressed on; some riding boars came and bent.","page":2497,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤੇ ਦਾਨਵੋ ਪੈ ਚੜੇ ਦੈਤ ਭਾਰੇ। ਚਹੂੰ ਓਰ ਤੇ ਮਾਰ ਮਾਰੈ ਪੁਕਾਰੈ। ੧੮੨।","roman":"Kite daanvo pai chare dait bhaare | chahoon or te maar maarai pukaarai | 182 |","meaning_en":"Some great demons rode demons; from all four sides they cried \"kill, kill\". 182.","page":2497,"meaning_status":"draft"}]},{"type":"verse","number":[183],"number_text":"੧੮੩।","page":2497,"lines":[{"gurmukhi":"ਕਿਤੇ ਸਰਪ ਅਸਵਾਰ ਹੈ ਕੈ ਸਿਧਾਏ। ਕਿਤੇ ਸ੍ਵਾਰ ਬਘ੍ਯਾਰ ਹ੍ਵੈ ਦੁਸਟ ਆਏ।","roman":"Kite sarap asvaar hai kai sidhaae | kite svaar baghyaar hvai dusat aae |","meaning_en":"Some went riding on snakes; some wicked ones came riding leopards.","page":2497,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤੇ ਚੀਤਿਯੌ ਪੈ ਚੜੇ ਕੋਪ ਕੈ ਕੈ। ਕਿਤੇ ਚੀਤਰੋ ਪੈ ਚੜੇ ਤੇਜ ਤੈ ਕੈ। ੧੮੩।","roman":"Kite cheetiyau pai chare kop kai kai | kite cheetro pai chare tej tai kai | 183 |","meaning_en":"Some mounted cheetahs in rage; some mounted panthers with splendour. 183.","page":2497,"meaning_status":"draft"}]},{"type":"verse","number":[184],"number_text":"੧੮੪।","page":2497,"lines":[{"gurmukhi":"ਕਿਤੇ ਚਾਕਚੁੰਧ੍ਰ ਚੜੇ ਕਾਕ ਬਾਹੀ। ਅਠੂਹਾਨ ਕੌ ਸ੍ਵਾਰ ਕੇਤੇ ਸਿਪਾਹੀ।","roman":"Kite chaakchundhr chare kaak baahee | athoohaan kau svaar kete sipaahee |","meaning_en":"Some mounted crows and ravens; some soldiers rode the owls.","page":2497,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤੇ ਬੀਰ ਬਾਨੀ ਚੜੇ ਬ੍ਰਿਧ ਗਿਧੈ। ਮਨੋ ਧ੍ਯਾਨ ਲਾਗੇ ਲਸੈ ਸੁਧ ਸਿਧੈ। ੧੮੪।","roman":"Kite beer baanee chare bridh gidhai | mano dhyaan laage lasai sudh sidhai | 184 |","meaning_en":"Some warriors rode old vultures, as if absorbed in meditation, shining like pure siddhas. 184.","page":2497,"meaning_status":"draft","note":"Obscure; uncertain."}]},{"type":"verse","number":[185],"number_text":"੧੮੫।","page":2499,"lines":[{"gurmukhi":"ਹਠੀ ਬਧਿ ਗੋਪਾ ਗੁਲਿਤ੍ਰਾਨ ਬਾਕੇ। ਬਰਜੀਲੇ ਕਟੀਲੇ ਹਠੀਲੇ ਨਿਸਾਂਕੇ।","roman":"Hathee badhi gopaa gulitraan baake | barjeele kateele hatheele nisaanke |","meaning_en":"Obstinate, with armoured hands and fine slingers, strong, sharp, stubborn and fearless,","page":2499,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਜੁਧ ਮਾਲੀ ਭਰੇ ਕੋਪ ਭਾਰੇ। ਚਹੂੰ ਓਰ ਤੈ ਅਭ੍ਰ ਜ੍ਯੋ ਚੀਤਕਾਰੇ। ੧੮੫।","roman":"Mahaa judh maalee bhare kop bhaare | chahoon or tai abhr jyo cheetkaare | 185 |","meaning_en":"in a great battle they were garlanded, filled with great rage; from all four sides they screamed like clouds. 185.","page":2499,"meaning_status":"draft"}]},{"type":"verse","number":[186],"number_text":"੧੮੬।","page":2499,"lines":[{"gurmukhi":"ਬਡੇ ਦਾਤ ਕਾਢੇ ਚਲੇ ਕੋਪਿ ਭਾਰੇ। ਲਹੇ ਹਾਥ ਮੈ ਪਬ ਪਤ੍ਰੀ ਉਪਾਰੇ।","roman":"Bade daat kaadhe chale kopi bhaare | lahe haath mai pab patree upaare |","meaning_en":"They bared great teeth and went with great rage; they took up in hand stones and uprooted trees.","page":2499,"meaning_status":"draft","note":"ਪਬ ਪਤ੍ਰੀ: 'mountains and trees'; uncertain."},{"gurmukhi":"ਕਿਤੇ ਸੂਲ ਸੈਥੀ ਸੂਆ ਹਾਥ ਲੀਨੇ। ਮੰਡੇ ਆਨਿ ਮਾਰੂ ਮਹਾ ਰੋਸ ਕੀਨੇ। ੧੮੬।","roman":"Kite sool saithee sooaa haath leene | mande aani maaroo mahaa ros keene | 186 |","meaning_en":"Some took spears, javelins and skewers in their hands; they joined battle, enraged. 186.","page":2499,"meaning_status":"draft"}]},{"type":"verse","number":[187],"number_text":"੧੮੭।","page":2499,"lines":[{"gurmukhi":"ਹਠੀ ਹਾਕ ਹਾਕੈ ਉਠਾਵੈ ਤੁਰੰਗੈ। ਮਹਾ ਬੀਰ ਬਾਕੇ ਜਗੇ ਜੋਰ ਜੰਗੈ।","roman":"Hathee haak haakai uthaavai turangai | mahaa beer baake jage jor jangai |","meaning_en":"The obstinate ones shouted and urged on their horses; great fine warriors awoke to the fierce fight.","page":2499,"meaning_status":"draft"},{"gurmukhi":"ਸੂਆ ਸਾਂਗ ਲੀਨੇ ਅਤਿ ਅਤ੍ਰੀ ਧਰਤ੍ਰੀ। ਮਚੇ ਆਨਿ ਕੈ ਕੈ ਛਕੇ ਛੋਭ ਛਤ੍ਰੀ। ੧੮੭।","roman":"Sooaa saang leene ati atree dhartree | mache aani kai kai chhake chhobh chhatree | 187 |","meaning_en":"Taking skewers and spears, very strong, the Kshatriyas joined, drunk with excitement. 187.","page":2499,"meaning_status":"draft","note":"ਅਤ੍ਰੀ ਧਰਤ੍ਰੀ: printed so; uncertain."}]},{"type":"verse","number":[188],"number_text":"੧੮੮।","page":2499,"lines":[{"gurmukhi":"ਕਹੂੰ ਬੀਰ ਬੀਰੈ ਲਰੈ ਸਸਤ੍ਰਧਾਰੀ। ਮਨੋ ਕਾਛ ਕਾਛੇ ਨਚੈ ਨ੍ਰਿਤਕਾਰੀ।","roman":"Kahoon beer beerai larai sastradhaaree | mano kaachh kaachhe nachai nritkaaree |","meaning_en":"In places warrior fought warrior, weapon-bearers, like the dancers dressed in costume.","page":2499,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਸੂਰ ਸਾਂਗੈ ਪੁਐ ਭਾਤਿ ਐਸੇ। ਚੜੈ ਬਾਸ ਬਾਜੀਗਰੈ ਜ੍ਵਾਨ ਜੈਸੇ। ੧੮੮।","roman":"Kahoon soor saangai puai bhaati aise | charai baas baajeegrai jvaan jaise | 188 |","meaning_en":"In places warriors were pierced by spears, like youths climbing the bamboo of jugglers. 188.","page":2499,"meaning_status":"draft"}]},{"type":"verse","number":[189],"number_text":"੧੮੯।","page":2499,"lines":[{"gurmukhi":"ਕਹੂੰ ਅੰਗ ਭੰਗੈ ਗਿਰੇ ਸਸਤ੍ਰ ਅਸਤ੍ਰੈ। ਕਹੂੰ ਬੀਰ ਬਾਜੀਨ ਕੇ ਬਰਮ ਬਸਤ੍ਰੈ।","roman":"Kahoon ang bhangai gire sasatr astrai | kahoon beer baajeen ke baram bastrai |","meaning_en":"In places broken limbs and missiles and weapons fell; in places the armour and garments of the horse-warriors.","page":2499,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਟੋਪ ਟਾਂਕੇ ਗਿਰੇ ਟੋਪ ਟੂਟੇ। ਕਹੂੰ ਬੀਰ ਅਭ੍ਰਾਨ ਕੀ ਭਾਤਿ ਫੂਟੇ। ੧੮੯।","roman":"Kahoon top taanke gire top toote | kahoon beer abhraan kee bhaati phoote | 189 |","meaning_en":"In places helmets and stitched things fell, helmets broke; in places warriors burst like clouds. 189.","page":2499,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2499,"meaning_status":"draft"},{"type":"verse","number":[190],"number_text":"੧੯੦।","page":2499,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਬੀਰ ਖੇਤ ਬਿਕਰਾਲਾ। ਮਾਚਤ ਭਯੋ ਆਨਿ ਤਿਹ ਕਾਲਾ।","roman":"Ih bidhi beer khet bikraalaa | maachat bhayo aani tih kaalaa |","meaning_en":"In this way the terrible battlefield was entered by Kal, who joined battle.","page":2499,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਕਾਲ ਕਛੁਹੂ ਤਬ ਕੋਪੇ। ਪੁਹਮੀ ਪਾਵ ਗਾੜ ਕਰਿ ਰੋਪੇ। ੧੯੦।","roman":"Mahaa kaal kachhuhoo tab kope | puhmee paav gaar kari rope | 190 |","meaning_en":"Mahakal then grew a little angry and planted his foot firmly on the earth. 190.","page":2499,"meaning_status":"draft"}]},{"type":"verse","number":[191],"number_text":"੧੯੧।","page":2499,"lines":[{"gurmukhi":"ਮੋਹਨਾਸਤ੍ਰ ਕੇਤੇ ਮੋਹਿਤ ਕਰਿ। ਬਰੁਣਾਸਤ੍ਰ ਭੇ ਪ੍ਰਾਨ ਕਿਤਨ ਹਰਿ।","roman":"Mohnaasatr kete mohit kari | barunaasatr bhe praan kitan hari |","meaning_en":"He bewildered many with the Mohan weapon; with the Varun weapon he took the lives of some.","page":2499,"meaning_status":"draft"},{"gurmukhi":"ਪਾਵਕਾਸਤ੍ਰ ਭੇ ਅਧਿਕ ਜਰਾਏ। ਅਮਿਤ ਸੁਭਟ ਮ੍ਰਿਤ ਲੋਕ ਪਠਾਏ। ੧੯੧।","roman":"Paavkaasatr bhe adhik jaraae | amit subhat mrit lok pathaae | 191 |","meaning_en":"With the Pavak weapon he burned many; he sent countless warriors to the world of the dead. 191.","page":2499,"meaning_status":"draft"}]},{"type":"verse","number":[192],"number_text":"੧੯੨।","page":2499,"lines":[{"gurmukhi":"ਜਾ ਪਰ ਮਹਾ ਕਾਲ ਅਸਿ ਝਾਰਾ। ਏਕ ਸੁਭਟ ਤੇ ਦ੍ਵੈ ਕਰਿ ਡਾਰਾ।","roman":"Jaa par mahaa kaal asi jhaaraa | ek subhat te dvai kari daaraa |","meaning_en":"On whom Mahakal swung his sword, he made one warrior into two.","page":2499,"meaning_status":"draft"},{"gurmukhi":"ਜੌ ਦ੍ਵੈ ਨਰ ਪਰ ਟੁਕ ਅਸਿ ਧਰਾ। ਚਾਰਿ ਟੂਕ ਤਿਨ ਦ੍ਵੈ ਕੈ ਕਰਾ। ੧੯੨।","roman":"Jau dvai nar par tuk asi dharaa | chaari took tin dvai kai karaa | 192 |","meaning_en":"When he put his sword on two men, he made them four pieces. 192.","page":2499,"meaning_status":"draft"}]},{"type":"verse","number":[193],"number_text":"੧੯੩।","page":2499,"lines":[{"gurmukhi":"ਕੇਤਿਕ ਪਰੇ ਸੁਭਟ ਬਿਲਲਾਹੀ। ਜੰਬੁਕ ਗਿਧ ਮਾਸੁ ਲੈ ਜਾਹੀ।","roman":"Ketik pare subhat billaahee | janbuk gidh maasu lai jaahee |","meaning_en":"Some warriors lay wailing; jackals and vultures took away the flesh.","page":2499,"meaning_status":"draft"},{"gurmukhi":"ਭੈਰਵ ਆਨਿ ਦੁਹੂੰ ਭਭਕਾਰੈ। ਕਹੂੰ ਮਸਾਨ ਕਿਲਕਟੀ ਮਾਰੈ। ੧੯੩।","roman":"Bhairav aani duhoon bhabhkaarai | kahoon masaan kilaktee maarai | 193 |","meaning_en":"Bhairavs came and boomed on both sides; in places goblins shrieked. 193.","page":2499,"meaning_status":"draft"}]},{"type":"verse","number":[194],"number_text":"੧੯੪।","page":2499,"lines":[{"gurmukhi":"ਕੇਤਿਕ ਸੁਭਟ ਆਨਿ ਹੀ ਢੂਕੈ। ਮਾਰਹਿ ਮਾਰਿ ਦਸੋ ਦਿਸਿ ਕੂਕੈ।","roman":"Ketik subhat aani hee dhookai | maarhi maari daso disi kookai |","meaning_en":"Some warriors came on; they cried \"kill, kill\" in all ten directions.","page":2499,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਕਾਲ ਪਰ ਜੇ ਬ੍ਰਿਣ ਕਰਹੀ। ਕੁੰਠਤ ਹੋਇ ਧਰਨਿ ਗਿਰ ਪਰਹੀ। ੧੯੪।","roman":"Mahaa kaal par je brin karhee | kunthat hoi dharni gir parhee | 194 |","meaning_en":"Those who wounded Mahakal fell to the ground blunted. 194.","page":2499,"meaning_status":"draft"}]},{"type":"verse","number":[195],"number_text":"੧੯੫।","page":2499,"lines":[{"gurmukhi":"ਬਹੁਰਿ ਕੋਪ ਕਰਿ ਅਸੁਰ ਅਪਾਰਾ।ਅ ਮਹਾ ਕਾਲ ਕਹ ਕਰਤ ਪ੍ਰਹਾਰਾ।","roman":"Bahuri kop kari asur apaaraa | a mahaa kaal kah karat prahaaraa |","meaning_en":"Again countless demons in rage struck at Mahakal.","page":2499,"meaning_status":"draft"},{"gurmukhi":"ਤੇ ਵੈ ਏਕ ਰੂਪ ਹ੍ਵੈ ਜਾਹੀ। ਮਹਾ ਕਾਲ ਕੇ ਮਧ੍ਯ ਸਮਾਹੀ। ੧੯੫।","roman":"Te vai ek roop hvai jaahee | mahaa kaal ke madhy samaahee | 195 |","meaning_en":"They became one form, and merged into the midst of Mahakal. 195.","page":2499,"meaning_status":"draft"}]},{"type":"verse","number":[196],"number_text":"੧੯੬।","page":2501,"lines":[{"gurmukhi":"ਜਿਮਿ ਕੋਈ ਬਾਰਿ ਬਾਰਿ ਪਰ ਮਾਰੈ। ਹੋਤ ਲੀਨ ਤਿਹ ਮਾਝ ਸੁਧਾਰੈ।","roman":"Jimi koee baari baari par maarai | hot leen tih maajh sudhaarai |","meaning_en":"As if someone were to strike water upon water, it merges into it and is set right.","page":2501,"meaning_status":"draft"},{"gurmukhi":"ਪੁਨਿ ਕੋਈ ਤਾਹਿ ਨ ਸਕਤ ਪਛਾਨੀ। ਆਗਿਲ ਆਹਿ ਕਿ ਮੋਰਾ ਪਾਨੀ। ੧੯੬।","roman":"Puni koee taahi na sakat pachhaanee | aagil aahi ki moraa paanee | 196 |","meaning_en":"Again no one could recognise it: \"Is this the earlier one or is it my water?\" 196.","page":2501,"meaning_status":"draft"}]},{"type":"verse","number":[197],"number_text":"੧੯੭।","page":2501,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਭਏ ਸਸਤ੍ਰ ਜਬ ਲੀਨਾ। ਅਸੁਰਨ ਕੋਪ ਅਮਿਤ ਤਬ ਕੀਨਾ।","roman":"Ih bidhi bhae sasatr jab leenaa | asuran kop amit tab keenaa |","meaning_en":"When weapons were taken up in this way, the demons then were enraged greatly.","page":2501,"meaning_status":"draft"},{"gurmukhi":"ਕਾਪਤ ਅਧਿਕ ਚਿਤ ਮੋ ਗਏ। ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਲੈ ਆਵਤ ਭਏ। ੧੯੭।","roman":"Kaapat adhik chit mo gae | sasatr asatr lai aavat bhae | 197 |","meaning_en":"They went trembling in their minds, yet came taking missiles and weapons. 197.","page":2501,"meaning_status":"draft"}]},{"type":"verse","number":[198],"number_text":"੧੯੮।","page":2501,"lines":[{"gurmukhi":"ਜ੍ਵਾਲ ਤਜੀ ਕਰਿ ਕੋਪ ਨਿਸਾਚਰ। ਤਿਨ ਤੇ ਭਏ ਪਠਾਨ ਧਨੁਖ ਧਰ।","roman":"Jvaal tajee kari kop nisaachar | tin te bhae pathaan dhanukh dhar |","meaning_en":"The night-walking demons in rage gave off flames; from them came Pathans bearing bows.","page":2501,"meaning_status":"draft"},{"gurmukhi":"ਪੁਨਿ ਮੁਖ ਤੇ ਉਲਕਾ ਜੇ ਕਾਢੇ। ਤਾ ਤੇ ਮੁਗਲ ਉਪਜਿ ਭੇ ਠਾਢੇ। ੧੯੮।","roman":"Puni mukh te ulkaa je kaadhe | taa te mugal upji bhe thaadhe | 198 |","meaning_en":"Again from the meteors they drew from their mouths, Mughals arose and stood. 198.","page":2501,"meaning_status":"draft"}]},{"type":"verse","number":[199],"number_text":"੧੯੯।","page":2501,"lines":[{"gurmukhi":"ਪੁਨਿ ਰਿਸਿ ਤਨ ਤਿਨ ਸ੍ਵਾਸ ਨਿਕਾਰੇ। ਸੈਯਦ ਸੇਖ ਭਏ ਰਿਸ ਵਾਰੇ।","roman":"Puni risi tan tin svaas nikaare | saiyad sekh bhae ris vaare |","meaning_en":"Then, angered, they breathed out breaths; Sayyids and Shaikhs came, full of rage.","page":2501,"meaning_status":"draft"},{"gurmukhi":"ਧਾਏ ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਕਰ ਲੈ ਕੈ। ਤਮਕਿ ਤੇਜ ਰਨ ਤੁਰੀ ਨਚੈ ਕੈ। ੧੯੯।","roman":"Dhaae sasatr asatr kar lai kai | tamki tej ran turee nachai kai | 199 |","meaning_en":"They ran with missiles and weapons in hand; boldly, brightly, they made horses prance in the battle. 199.","page":2501,"meaning_status":"draft"}]},{"type":"verse","number":[200],"number_text":"੨੦੦।","page":2501,"lines":[{"gurmukhi":"ਖਾਨ ਪਠਾਨ ਢੁਕੇ ਰਿਸਿ ਕੈ ਕੈ। ਕੋਪਿ ਕ੍ਰਿਪਾਨ ਨਗਨ ਕਰ ਲੈ ਕੈ।","roman":"Khaan pathaan dhuke risi kai kai | kopi kripaan nagan kar lai kai |","meaning_en":"Khans and Pathans pressed on in anger; in fury with naked swords in hand","page":2501,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਕਾਲ ਕੌ ਕਰਤ ਪ੍ਰਹਾਰਾ। ਏਕ ਨ ਉਪਰਤ ਰੋਮ ਉਪਾਰਾ। ੨੦੦।","roman":"Mahaa kaal kau karat prahaaraa | ek na uprat rom upaaraa | 200 |","meaning_en":"they struck at Mahakal; not one hair was uprooted. 200.","page":2501,"meaning_status":"draft"}]},{"type":"verse","number":[201],"number_text":"੨੦੧।","page":2501,"lines":[{"gurmukhi":"ਅਮਿਤ ਖਾਨ ਕਰਿ ਕੋਪ ਸਿਧਾਰੇ। ਮਦ ਕਰਿ ਭਏ ਸਕਲ ਮਤਵਾਰੇ।","roman":"Amit khaan kari kop sidhaare | mad kari bhae sakal matvaare |","meaning_en":"Countless Khans advanced in rage; all became crazed with drink.","page":2501,"meaning_status":"draft"},{"gurmukhi":"ਉਮਡੇ ਅਮਿਤ ਮਲੇਛਨ ਕੇ ਗਨ। ਤਿਨ ਕੇ ਨਾਮ ਕਹਤ ਤੁਮ ਸੌ ਭਨਿ। ੨੦੧।","roman":"Umde amit malechhan ke gan | tin ke naam kahat tum sau bhani | 201 |","meaning_en":"Hosts of countless Mlechhas surged up; I tell you their names. 201.","page":2501,"meaning_status":"draft"}]},{"type":"verse","number":[202],"number_text":"੨੦੨।","page":2501,"lines":[{"gurmukhi":"ਨਾਹਰ ਖਾਨ ਝੜਾਝੜ ਖਾਨਾ। ਖਾਨ ਨਿਹੰਗ ਭੜੰਗ ਜੁਆਨਾ।","roman":"Naahar khaan jharaajhar khaanaa | khaan nihang bharang juaanaa |","meaning_en":"Nahar Khan, Jharajhar Khan, Khan Nihang, Bharang the youth,","page":2501,"meaning_status":"draft"},{"gurmukhi":"ਔਰ ਝੜੰਗ ਖਾਨ ਰਨ ਧਾਯੋ। ਅਮਿਤ ਸਸਤ੍ਰ ਕਰ ਲਏ ਸਿਧਾਯੋ। ੨੦੨।","roman":"Aur jharang khaan ran dhaayo | amit sasatr kar lae sidhaayo | 202 |","meaning_en":"and Jharang Khan ran into the battle; they went with countless weapons in hand. 202.","page":2501,"meaning_status":"draft","note":"Names transliterated: Nahar Khan, Jharajhar Khan, Nihang Khan, Bharang, Jharang Khan."}]},{"type":"verse","number":[203],"number_text":"੨੦੩।","page":2501,"lines":[{"gurmukhi":"ਬੈਰਮ ਖਾਨ ਬਹਾਦੁਰ ਖਾਨਾ। ਬਲਵੰਡ ਖਾਨ ਬਡੋ ਸੁਰ ਗ੍ਯਾਨਾ।","roman":"Bairam khaan bahaadur khaanaa | balvand khaan bado sur gyaanaa |","meaning_en":"Bairam Khan, Bahadur Khan, Balvand Khan, a great hero and wise,","page":2501,"meaning_status":"draft"},{"gurmukhi":"ਰੁਸਤਮ ਖਾਨ ਕੋਪ ਕਰਿ ਚਲੋ। ਲੀਨੇ ਅਮਿਤ ਸੈਨ ਸੰਗ ਭਲੋ। ੨੦੩।","roman":"Rustam khaan kop kari chalo | leene amit sain sang bhalo | 203 |","meaning_en":"and Rustam Khan went in anger, with a good, vast army. 203.","page":2501,"meaning_status":"draft"}]},{"type":"verse","number":[204],"number_text":"੨੦੪।","page":2501,"lines":[{"gurmukhi":"ਹਸਨ ਖਾਨ ਹੁਸੈਨ ਖਾਨ ਭਨ। ਖਾਨ ਮੁਹੰਮਦ ਲੈ ਮਲੇਛ ਗਨ।","roman":"Hasan khaan husain khaan bhan | khaan muhanmad lai malechh gan |","meaning_en":"Hasan Khan, Husain Khan, Khan Muhammad, with hosts of Mlechhas,","page":2501,"meaning_status":"draft"},{"gurmukhi":"ਸਮਸ ਖਾਨ ਸਮਸਰੋ ਖਾਨਾ। ਚਲੇ ਪੀਸ ਕਰਿ ਦਾਤ ਜੁਆਨਾ। ੨੦੪।","roman":"Samas khaan samasro khaanaa | chale pees kari daat juaanaa | 204 |","meaning_en":"Shams Khan, Shamsro Khan, went grinding their teeth, the youths. 204.","page":2501,"meaning_status":"draft"}]},{"type":"verse","number":[205],"number_text":"੨੦੫।","page":2501,"lines":[{"gurmukhi":"ਆਵਤ ਹੀ ਕੀਏ ਬਾਨ ਪ੍ਰਹਾਰਾ। ਮਹਾ ਕਾਲ ਕਰ ਚਹਤ ਸੰਘਾਰਾ।","roman":"Aavat hee kee'e baan prahaaraa | mahaa kaal kar chahat sanghaaraa |","meaning_en":"On arriving they shot arrows; they wished to kill Mahakal.","page":2501,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਕਾਲ ਸਰ ਚਲਤ ਨਿਹਾਰੇ। ਟੂਕ ਸਹੰਸ੍ਰ ਪ੍ਰਿਥੀ ਕਰਿ ਡਾਰੇ। ੨੦੫।","roman":"Mahaa kaal sar chalat nihaare | took sahansr prithee kari daare | 205 |","meaning_en":"Seeing Mahakal's arrows go, they threw the earth into a thousand pieces. 205.","page":2501,"meaning_status":"draft","note":"Obscure; sense uncertain."}]},{"type":"verse","number":[206],"number_text":"੨੦੬।","page":2501,"lines":[{"gurmukhi":"ਡਾਰੇ ਸਤ ਸਤ ਟੂਕ ਪ੍ਰਿਥੀ ਕਰਿ। ਮਹਾ ਕਾਲ ਕਰਿ ਕੋਪ ਅਮਿਤ ਸਰ।","roman":"Daare sat sat took prithee kari | mahaa kaal kari kop amit sar |","meaning_en":"He made the earth into seven and seven pieces; Mahakal in rage with countless arrows,","page":2501,"meaning_status":"draft"},{"gurmukhi":"ਇਕ ਇਕ ਸਰ ਤਨ ਬਹੁਰਿ ਪ੍ਰਹਾਰੇ। ਗਿਰੇ ਪਠਾਨ ਸੁ ਭੂਮਿ ਮੰਝਾਰੇ। ੨੦੬।","roman":"Ik ik sar tan bahuri prahaare | gire pathaan su bhoomi manjhaare | 206 |","meaning_en":"struck again each one's body with one arrow; the Pathans fell on the earth. 206.","page":2501,"meaning_status":"draft","note":"ਸਤ ਸਤ ਟੂਕ: 'seven (times) pieces'; uncertain."}]},{"type":"verse","number":[207],"number_text":"੨੦੭।","page":2501,"lines":[{"gurmukhi":"ਕਟਿ ਨਿਹੰਗਕ ਰਾਖਾ ਦ੍ਵੈ ਧਰ। ਮਾਰੇ ਅਮਿਤ ਝੜਾਝੜ ਖਾ ਸਰ।","roman":"Kati nihangak raakhaa dvai dhar | maare amit jharaajhar khaa sar |","meaning_en":"He cut Nihang Khan and left him in two halves; he killed countless with arrows, Jharajhar Khan.","page":2501,"meaning_status":"draft"},{"gurmukhi":"ਖਾਨ ਭੜੰਗ ਬਹੁਰਿ ਰਨ ਮਾਰੇ। ਦੇਖਤ ਚਾਰਣ ਸਿਧ ਹਜਾਰੇ। ੨੦੭।","roman":"Khaan bharang bahuri ran maare | dekhat chaaran sidh hajaare | 207 |","meaning_en":"Khan Bharang he then killed in the battle, while thousands of charans and siddhas watched. 207.","page":2501,"meaning_status":"draft"}]},{"type":"verse","number":[208],"number_text":"੨੦੮।","page":2501,"lines":[{"gurmukhi":"ਨਾਹਰ ਖਾ ਗੈਰਤ ਖਾ ਮਾਰਾ। ਬਲਵੰਡ ਖਾ ਕਾ ਸੀਸ ਉਤਾਰਾ।","roman":"Naahar khaa gairat khaa maaraa | balvand khaa kaa sees utaaraa |","meaning_en":"He killed Nahar Khan and Ghairat Khan; he took off Balvand Khan's head.","page":2501,"meaning_status":"draft"},{"gurmukhi":"ਸੇਰ ਖਾਨ ਕਟਿ ਤੇ ਕਟਿ ਡਾਰਿਯੋ। ਬੈਰਮ ਖਾ ਗਹਿ ਕੇਸ ਪਛਾਰਿਯੋ। ੨੦੮।","roman":"Ser khaan kati te kati daariyo | bairam khaa gahi kes pachhaariyo | 208 |","meaning_en":"Sher Khan he cut from the waist; Bairam Khan he seized by the hair and threw down. 208.","page":2501,"meaning_status":"draft"}]},{"type":"verse","number":[209],"number_text":"੨੦੯।","page":2503,"lines":[{"gurmukhi":"ਪੁਨਿ ਕਰਿ ਕੋਪ ਬਹਾਦੁਰ ਖਾਨਾ। ਛਾਡੇ ਤਬੈ ਬਿਸਿਖ ਰਿਸਿ ਨਾਨਾ।","roman":"Puni kari kop bahaadur khaanaa | chhaade tabai bisikh risi naanaa |","meaning_en":"Then in anger Bahadur Khan shot many arrows in rage.","page":2503,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਕਾਲ ਕੁਪ ਬਾਨ ਪ੍ਰਹਾਰੋ। ਗਿਰਿਯੋ ਕਹਾ ਲੌ ਲਰੈ ਬਿਚਾਰੋ। ੨੦੯।","roman":"Mahaa kaal kup baan prahaaro | giriyo kahaa lau larai bichaaro | 209 |","meaning_en":"Mahakal angrily shot an arrow; the wretch fell: how long could he fight? 209.","page":2503,"meaning_status":"draft"}]},{"type":"verse","number":[210],"number_text":"੨੧੦।","page":2503,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਹਨੀ ਪਠਾਨੀ ਸੈਨਾ। ਮੁਗਲਨ ਪਰਾ ਮਧਿ ਕਛੁ ਭੈ ਨਾ।","roman":"Ih bidhi hanee pathaanee sainaa | muglan paraa madhi kachhu bhai naa |","meaning_en":"In this way the Pathan army was destroyed; among the Mughals there was no fear at all.","page":2503,"meaning_status":"draft","note":"Obscure second part; uncertain."},{"gurmukhi":"ਛਿਨਕਿਕ ਮੋ ਬਹੁ ਸੁਭਟ ਗਿਰਾਏ। ਜਾਨੁ ਇੰਦ੍ਰ ਪਰਬਤ ਸੇ ਘਾਏ। ੨੧੦।","roman":"Chhinkik mo bahu subhat giraae | jaanu indr parbat se ghaae | 210 |","meaning_en":"In an instant many warriors were felled, as if Indra had struck mountains. 210.","page":2503,"meaning_status":"draft"}]},{"type":"verse","number":[211],"number_text":"੨੧੧।","page":2503,"lines":[{"gurmukhi":"ਬੈਰਮ ਬੇਗ ਮੁਗਲ ਕੌ ਮਾਰਾ। ਯੂਸਫ ਖਾ ਕਟਿ ਤੇ ਕਟਿ ਡਾਰਾ।","roman":"Bairam beg mugal kau maaraa | yoosaph khaa kati te kati daaraa |","meaning_en":"Bairam Beg he killed, a Mughal; Yusuf Khan he cut from waist to waist.","page":2503,"meaning_status":"draft"},{"gurmukhi":"ਤਾਹਿਰ ਬੇਗ ਟਿਕਾ ਸੰਗ੍ਰਾਮਾ। ਅੰਤ ਗਿਰਿਯੋ ਭਿਰਿ ਕੈ ਦ੍ਵੈ ਜਾਮਾ। ੨੧੧।","roman":"Taahir beg tikaa sangraamaa | ant giriyo bhiri kai dvai jaamaa | 211 |","meaning_en":"Tahir Beg stood firm in battle, but in the end he fell after fighting for two watches. 211.","page":2503,"meaning_status":"draft"}]},{"type":"verse","number":[212],"number_text":"੨੧੨।","page":2503,"lines":[{"gurmukhi":"ਨੂਰਮ ਬੇਗ ਬਹੁਰਿ ਰਿਸਿ ਮਾਰਿਯੋ। ਆਦਿਲ ਬੇਗਹਿ ਬਹੁਰਿ ਪ੍ਰਜਾਰਿਯੋ।","roman":"Nooram beg bahuri risi maariyo | aadil beghi bahuri prajaariyo |","meaning_en":"Then he killed Nurum Beg in rage, and burned Adil Beg.","page":2503,"meaning_status":"draft"},{"gurmukhi":"ਤ੍ਰਾਸਿਤ ਭਈ ਮਲੇਛੀ ਸੈਨਾ। ਆਯੁਧ ਸਕਾ ਹਾਥ ਕੋਈ ਲੈ ਨਾ। ੨੧੨।","roman":"Traasit bhaee malechhee sainaa | aayudh sakaa haath koee lai naa | 212 |","meaning_en":"The army of the Mlechhas was terrified; no one could take a weapon in hand. 212.","page":2503,"meaning_status":"draft"}]},{"type":"verse","number":[213],"number_text":"੨੧੩।","page":2503,"lines":[{"gurmukhi":"ਭਜੇ ਪਠਾਨ ਮੁਗਲ ਹੂੰ ਭਾਜੇ। ਸੈਯਦ ਆਨਿ ਦਸੌ ਦਿਸਿ ਗਾਜੇ।","roman":"Bhaje pathaan mugal hoon bhaaje | saiyad aani dasau disi gaaje |","meaning_en":"The Pathans fled and the Mughals fled; the Sayyids came and roared in all ten directions.","page":2503,"meaning_status":"draft"},{"gurmukhi":"ਫਿਰੇ ਪਠਾਨ ਬਿਮਨ ਜੇ ਭਏ। ਬਹੁਰਿ ਧਨੁਖ ਟੰਕੋਰਤ ਗਏ। ੨੧੩।","roman":"Phire pathaan biman je bhae | bahuri dhanukh tankorat gae | 213 |","meaning_en":"The Pathans who had grown downcast turned back, and again went twanging their bows. 213.","page":2503,"meaning_status":"draft"}]},{"type":"verse","number":[214],"number_text":"੨੧੪।","page":2503,"lines":[{"gurmukhi":"ਆਵਤ ਹੀ ਹੁਸੈਨ ਖਾ ਜੂਝਾ। ਹਸਨ ਖਾਨ ਸਨਮੁਖ ਹ੍ਵੈ ਲੂਝਾ।","roman":"Aavat hee husain khaa joojhaa | hasan khaan sanmukh hvai loojhaa |","meaning_en":"On arriving, Husain Khan fell; Hasan Khan fought facing him.","page":2503,"meaning_status":"draft"},{"gurmukhi":"ਬਹੁਰਿ ਮੁਹੰਮਦ ਖਾ ਲਰਿ ਮਰਿਯੋ। ਜਾਨਕ ਸਲਭ ਦੀਪ ਮਹਿ ਪਰਿਯੋ। ੨੧੪।","roman":"Bahuri muhanmad khaa lari mariyo | jaanak salabh deep mahi pariyo | 214 |","meaning_en":"Then Muhammad Khan fought and died, like a moth falling into a lamp. 214.","page":2503,"meaning_status":"draft"}]},{"type":"verse","number":[215],"number_text":"੨੧੫।","page":2503,"lines":[{"gurmukhi":"ਸੈਦ ਹੁਸੈਨ ਕੋਪ ਕਰਿ ਗਰਜੋ। ਜਾਫਰ ਸੈਦ ਰਹਾ ਨਹਿ ਬਰਜੋ।","roman":"Said husain kop kari garjo | jaaphar said rahaa nahi barjo |","meaning_en":"Sayyid Husain roared in anger; Jafar Sayyid could not be held back.","page":2503,"meaning_status":"draft"},{"gurmukhi":"ਲੋਹ ਪ੍ਰਜੰਤ ਬਾਨ ਤਨਿ ਮਾਰੇ। ਭਏ ਲੀਨ ਨਹਿ ਬਹੁਰਿ ਨਿਹਾਰੇ। ੨੧੫।","roman":"Loh prajant baan tani maare | bhae leen nahi bahuri nihaare | 215 |","meaning_en":"He struck arrows tipped with iron into his body; they merged and were not seen again. 215.","page":2503,"meaning_status":"draft"}]},{"type":"verse","number":[216],"number_text":"੨੧੬।","page":2503,"lines":[{"gurmukhi":"ਬਹੁਰੋ ਅਮਿਤ ਕੋਪ ਕਹ ਕਰਿ ਕੈ। ਛਾਡੇ ਬਿਸਿਖ ਧਨੁਖ ਕੌ ਧਰਿ ਕੈ।","roman":"Bahuro amit kop kah kari kai | chhaade bisikh dhanukh kau dhari kai |","meaning_en":"Then, in boundless anger, he shot arrows setting them to the bow.","page":2503,"meaning_status":"draft"},{"gurmukhi":"ਛੂਟਤ ਭਏ ਸਲਭ ਕੀ ਜਿਮਿ ਸਰ। ਲੀਨ ਭਏ ਨਹਿ ਲਖੇ ਦ੍ਰਿਗਨ ਕਰਿ। ੨੧੬।","roman":"Chhootat bhae salabh kee jimi sar | leen bhae nahi lakhe drigan kari | 216 |","meaning_en":"They were loosed like the flight of moths and merged, not seen by eyes. 216.","page":2503,"meaning_status":"draft","note":"Obscure: 'like the arrows of moths'; uncertain."}]},{"type":"verse","number":[217],"number_text":"੨੧੭।","page":2503,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਮਾਰਿ ਸੈਯਦੀ ਸੈਨਾ। ਸੇਖ ਫੌਜ ਭਾਜੀ ਬਿਨੁ ਚੈਨਾ।","roman":"Ih bidhi maari saiydee sainaa | sekh phauj bhaajee binu chainaa |","meaning_en":"In this way he killed the army of Sayyids; the army of Shaikhs fled without peace.","page":2503,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਕਾਲ ਜਬ ਭਜੇ ਨਿਹਾਰੇ। ਬਿਸਿਖ ਕੋਪ ਨਹਿ ਤਾਹਿ ਪ੍ਰਹਾਰੇ। ੨੧੭।","roman":"Mahaa kaal jab bhaje nihaare | bisikh kop nahi taahi prahaare | 217 |","meaning_en":"When Mahakal saw them fleeing, in anger he did not shoot an arrow at them. 217.","page":2503,"meaning_status":"draft"}]},{"type":"verse","number":[218],"number_text":"੨੧੮।","page":2503,"lines":[{"gurmukhi":"ਬਹੁਰੌ ਭਿਰੇ ਸੇਖ ਭਰਿ ਲਾਜਾ। ਲੈ ਲੈ ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਸਭ ਸਾਜਾ।","roman":"Bahurau bhire sekh bhari laajaa | lai lai sasatr asatr sabh saajaa |","meaning_en":"Again the Shaikhs fought, filled with shame, taking up all their missiles and weapons.","page":2503,"meaning_status":"draft"},{"gurmukhi":"ਜਿਮਿ ਮ੍ਰਿਗ ਬਧ ਮ੍ਰਿਗਪਤਿ ਕੌ ਤਕਹੀ। ਝਖਿ ਝਖਿ ਗਿਰਤ ਮਾਰਿ ਨਹਿ ਸਕਹੀ। ੨੧੮।","roman":"Jimi mrig badh mrigapti kau takhee | jhakhi jhakhi girat maari nahi sakhee | 218 |","meaning_en":"As deer look to kill the lion, they fell while fretting and could not kill. 218.","page":2503,"meaning_status":"draft","note":"Obscure comparison; read as printed; uncertain."}]},{"type":"verse","number":[219],"number_text":"੨੧੯।","page":2503,"lines":[{"gurmukhi":"ਸੇਖ ਫਰੀਦ ਹਨਾ ਤਤਕਾਲਾ। ਸੇਖ ਉਜੈਨ ਹਨਾ ਬਿਕਰਾਲਾ।","roman":"Sekh phareed hanaa tatkaalaa | sekh ujain hanaa bikraalaa |","meaning_en":"He killed Shaikh Farid at once; he killed Shaikh Ujain, the terrible.","page":2503,"meaning_status":"draft"},{"gurmukhi":"ਸੇਖ ਅਮਾਨੁਲਹ ਪੁਨਿ ਮਾਰਿਯੋ। ਸੇਖ ਵਲੀ ਕੋ ਸੈਨ ਸੰਘਾਰਿਯੋ। ੨੧੯।","roman":"Sekh amaanulah puni maariyo | sekh valee ko sain sanghaariyo | 219 |","meaning_en":"He then killed Shaikh Amanullah; he destroyed the host of Shaikh Wali. 219.","page":2503,"meaning_status":"draft"}]},{"type":"verse","number":[220],"number_text":"੨੨੦।","page":2503,"lines":[{"gurmukhi":"ਤਿਲ ਤਿਲ ਪਾਇ ਸੁਭਟ ਕਹੂੰ ਕਰੇ। ਚਰਮ ਬਰਮ ਰਨ ਮੋ ਕਹੂੰ ਝਰੇ।","roman":"Til til paai subhat kahoon kare | charam baram ran mo kahoon jhare |","meaning_en":"He cut warriors up bit by bit; in places shields and armour fell in the battle.","page":2503,"meaning_status":"draft"},{"gurmukhi":"ਭਖਿ ਭਖਿ ਉਠੈ ਸੁਭਟ ਕਹੂੰ ਕ੍ਰੁਧਾ। ਦਾਰੁਣ ਮਚਿਯੋ ਐਸ ਤਹ ਜੁਧਾ। ੨੨੦।","roman":"Bhakhi bhakhi uthai subhat kahoon krudhaa | daarun machiyo ais tah judhaa | 220 |","meaning_en":"Warriors rose in places, blazing with rage; such a dreadful battle was joined there. 220.","page":2503,"meaning_status":"draft"}]},{"type":"verse","number":[221],"number_text":"੨੨੧।","page":2505,"lines":[{"gurmukhi":"ਕਹੂੰ ਕਬੰਧ ਫਿਰਤ ਸਿਰ ਬਿਨਾ। ਕਹੂੰ ਸੁਭਟ ਗਹਿ ਦਾਤਨ ਤ੍ਰਿਨਾ।","roman":"Kahoon kabandh phirat sir binaa | kahoon subhat gahi daatan trinaa |","meaning_en":"In places headless trunks walked about; in places warriors held straw in their teeth.","page":2505,"meaning_status":"draft","note":"Holding straw in the teeth is a sign of surrender; noted."},{"gurmukhi":"ਰਛ ਰਛ ਕਹਿ ਤਾਹਿ ਪੁਕਾਰੈ। ਮਹਾ ਕਾਲ ਜਿਨਿ ਹਮੈ ਸੰਘਾਰੈ। ੨੨੧।","roman":"Rachh rachh kahi taahi pukaarai | mahaa kaal jini hamai sanghaarai | 221 |","meaning_en":"They cried \"Protect, protect\": \"Let not Mahakal kill us.\" 221.","page":2505,"meaning_status":"draft"}]},{"type":"verse","number":[222],"number_text":"੨੨੨।","page":2505,"lines":[{"gurmukhi":"ਕਹੂੰ ਆਨਿ ਡਾਕਿਨਿ ਡਹਕਾਰੈ। ਕਹੂੰ ਮਸਾਨ ਕਿਲਕਟੀ ਮਾਰੈ।","roman":"Kahoon aani daakini dahkaarai | kahoon masaan kilaktee maarai |","meaning_en":"In places dakinis came and screamed; in places goblins shrieked.","page":2505,"meaning_status":"draft"},{"gurmukhi":"ਭੂਤ ਪਿਸਾਚ ਨਚੇ ਬੈਤਾਲਾ। ਬਰਤ ਫਿਰਤ ਬੀਰਨ ਕਹ ਬਾਲਾ। ੨੨੨।","roman":"Bhoot pisaach nache baitaalaa | barat phirat beeran kah baalaa | 222 |","meaning_en":"Ghosts, goblins and Betals danced; the celestial women went about choosing the warriors. 222.","page":2505,"meaning_status":"draft"}]},{"type":"verse","number":[223],"number_text":"੨੨੩।","page":2505,"lines":[{"gurmukhi":"ਏਕੈ ਅਛ ਏਕ ਹੀ ਬਾਹਾ। ਏਕ ਚਰਨ ਅਰੁ ਅਰਧ ਸਨਾਹਾ।","roman":"Ekai achh ek hee baahaa | ek charan aru aradh sanaahaa |","meaning_en":"One eye, one arm, one foot and half an armour:","page":2505,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਬਿਧਿ ਸੁਭਟ ਬਿਕਟ ਹਨਿ ਡਾਰੇ। ਪਵਨ ਬਲੀ ਜਨੁ ਰੂਖ ਉਖਾਰੇ। ੨੨੩।","roman":"Ih bidhi subhat bikat hani daare | pavan balee janu rookh ukhaare | 223 |","meaning_en":"in this way he killed the fearful warriors, as a strong wind uproots trees. 223.","page":2505,"meaning_status":"draft"}]},{"type":"verse","number":[224],"number_text":"੨੨੪।","page":2505,"lines":[{"gurmukhi":"ਜਿਹ ਅਰਿ ਕਾਲ ਕ੍ਰਿਪਾਨ ਬਹੀ ਸਿਰ। ਤਿਨ ਕੇ ਰਹੀ ਨ ਜੀਵਕਰਾ ਫਿਰਿ।","roman":"Jih ari kaal kripaan bahee sir | tin ke rahee na jeevakraa phiri |","meaning_en":"On whose head Kal's sword struck, his life did not remain.","page":2505,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਕਹ ਕਾਲ ਖੜਗ ਛ੍ਵੈ ਗਯਾ। ਅਰਧੈ ਅਰਧ ਛਿਨਿਕ ਮਹਿ ਭਯਾ। ੨੨੪।","roman":"Jaa kah kaal kharag chhvai gayaa | ardhai aradh chhinik mahi bhayaa | 224 |","meaning_en":"Whom Kal's sword touched, in an instant he was cut in half. 224.","page":2505,"meaning_status":"draft"}]},{"type":"verse","number":[225],"number_text":"੨੨੫।","page":2505,"lines":[{"gurmukhi":"ਬਹੀ ਜਾਹਿ ਸਿਰ ਸਰਕਿ ਸਰੋਹੀ। ਤਾ ਕਾ ਰਹਾ ਸੀਸੁ ਹ੍ਵੈ ਦੋਹੀ।","roman":"Bahee jaahi sir sarki sarohee | taa kaa rahaa seesu hvai dohee |","meaning_en":"Whose head a Sirohi sword slid on, his head was split in two.","page":2505,"meaning_status":"draft","note":"ਸਰੋਹੀ: Sirohi, a sword from Sirohi."},{"gurmukhi":"ਜਾ ਕੌ ਬਾਨ ਕਾਲ ਕਾ ਲਾਗਾ। ਤਾ ਕੇ ਪ੍ਰਾਨ ਬਾਨ ਲੈ ਭਾਗਾ। ੨੨੫।","roman":"Jaa kau baan kaal kaa laagaa | taa ke praan baan lai bhaagaa | 225 |","meaning_en":"Whom Kal's arrow struck, the arrow took his life and went away. 225.","page":2505,"meaning_status":"draft"}]},{"type":"verse","number":[226],"number_text":"੨੨੬।","page":2505,"lines":[{"gurmukhi":"ਮਾਰੂ ਬਜਤ ਦੋਊ ਦਿਸਿ ਐਸੋ। ਜਾਨੁਕ ਪ੍ਰਲੈ ਕਾਲ ਕੇ ਐਸੇ।","roman":"Maaroo bajat do'oo disi aiso | jaanuk pralai kaal ke aise |","meaning_en":"The war-music sounded on both sides, as if at the time of the end of the world.","page":2505,"meaning_status":"draft"},{"gurmukhi":"ਗੋਮੁਖ ਝਾਂਝਰ ਤੂਰ ਅਪਾਰਾ। ਢੋਲ ਮ੍ਰਿਦੰਗ ਮੁਚੰਗ ਹਜਾਰਾ। ੨੨੬।","roman":"Gomukh jhaanjhar toor apaaraa | dhol mridang muchang hajaaraa | 226 |","meaning_en":"Gomukh horns, cymbals and countless trumpets, drums, mridangs and thousands of muchangs. 226.","page":2505,"meaning_status":"draft"}]},{"type":"verse","number":[227],"number_text":"੨੨੭।","page":2505,"lines":[{"gurmukhi":"ਘੋਰ ਆਯੁਧਨ ਇਹ ਬਿਧਿ ਭਯੋ। ਜਿਹ ਕੋ ਪਾਰ ਨ ਕਿਨਹੂੰ ਲਯੋ।","roman":"Ghor aayudhan ih bidhi bhayo | jih ko paar na kinhoon layo |","meaning_en":"Thus a dreadful battle with weapons took place, whose end no one reached.","page":2505,"meaning_status":"draft"},{"gurmukhi":"ਜੇਤਿਕ ਅਸੁਰ ਮਲੇਛੁਪਜਾਏ। ਮਹਾ ਕਾਲ ਛਿਨ ਬੀਚ ਖਪਾਏ। ੨੨੭।","roman":"Jetik asur malechhupjaae | mahaa kaal chhin beech khapaae | 227 |","meaning_en":"As many demons and Mlechhas as were produced, Mahakal destroyed in an instant. 227.","page":2505,"meaning_status":"draft"}]},{"type":"verse","number":[228],"number_text":"੨੨੮।","page":2505,"lines":[{"gurmukhi":"ਬਹੁਰਿ ਅਸੁਰ ਕ੍ਰੂਧਤ ਅਤਿ ਭਯੋ। ਅਮਿਤ ਅਸੁਰ ਉਪਰਾਜਿ ਸੁ ਲਯੋ।","roman":"Bahuri asur kroodhat ati bhayo | amit asur upraaji su layo |","meaning_en":"Then the demons became greatly enraged and brought forth countless more demons.","page":2505,"meaning_status":"draft"},{"gurmukhi":"ਧੂਲੀ ਕਰਨ ਬਿਦਿਤ ਕੇਸੀ ਭਨ। ਘੋਰ ਦਾੜ ਅਰੁ ਸ੍ਰੋਨਤ ਲੋਚਨ। ੨੨੮।","roman":"Dhoolee karan bidit kesee bhan | ghor daar aru sronat lochan | 228 |","meaning_en":"Dhuli Karan, Bidit Kesi, Ghor Dadh and Sronat Lochan, I tell. 228.","page":2505,"meaning_status":"draft","note":"Names transliterated; uncertain division: ਧੂਲੀ ਕਰਨ, ਬਿਦਿਤ ਕੇਸੀ, ਘੋਰ ਦਾੜ, ਸ੍ਰੋਨਤ ਲੋਚਨ."}]},{"type":"verse","number":[229],"number_text":"੨੨੯।","page":2505,"lines":[{"gurmukhi":"ਗਰਧਬ ਕੇਤੁ ਮਹਿਖ ਧੁਜ ਨਾਮਾ। ਅਰੁਨ ਨੇਤ੍ਰ ਉਪਜਾ ਸੰਗ੍ਰਾਮਾ।","roman":"Gardhab ketu mahikh dhuj naamaa | arun netr upjaa sangraamaa |","meaning_en":"Gardhab Ketu, Mahikh Dhuj by name, and Arun Netra: a battle arose.","page":2505,"meaning_status":"draft","note":"ਗਰਧਬ ਕੇਤੁ, ਮਹਿਖ ਧੁਜ, ਅਰੁਨ ਨੇਤ੍ਰ: names; 'Donkey-banner', 'Buffalo-banner', 'Red-eyed'."},{"gurmukhi":"ਅਸਿਧੁਜ ਨਿਰਖਿ ਅਸੁਰ ਉਪਜੇ ਰਨ। ਮਾਰਤ ਭਯੋ ਦਾਨਵਨ ਕੇ ਗਨ। ੨੨੯।","roman":"Asidhuj nirkhi asur upje ran | maarat bhayo daanvan ke gan | 229 |","meaning_en":"Seeing Asidhuj, the demons rose in the battle; he killed hosts of demons. 229.","page":2505,"meaning_status":"draft"}]},{"type":"verse","number":[230],"number_text":"੨੩੦।","page":2505,"lines":[{"gurmukhi":"ਅਸਿਧੁਜ ਕੋਪ ਅਧਿਕ ਕਹ ਕਰਾ। ਸੈਨ ਦਾਨਵਨ ਕੋ ਰਨ ਹਰਾ।","roman":"Asidhuj kop adhik kah karaa | sain daanvan ko ran haraa |","meaning_en":"Asidhuj grew very angry and defeated the army of the demons in battle.","page":2505,"meaning_status":"draft"},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਤਨ ਸਸਤ੍ਰ ਪ੍ਰਹਾਰੇ। ਤਿਲ ਤਿਲ ਪਾਇ ਸੁਭਟ ਕਟਿ ਡਾਰੇ। ੨੩੦।","roman":"Bhaati bhaati tan sasatr prahaare | til til paai subhat kati daare | 230 |","meaning_en":"He struck weapons into their bodies in many ways, and cut warriors up bit by bit. 230.","page":2505,"meaning_status":"draft"}]},{"type":"verse","number":[231],"number_text":"੨੩੧।","page":2505,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਹਨੀ ਸੈਨ ਅਸਿਧੁਜ ਜਬ। ਕਾਪਤ ਭਯੋ ਅਸੁਰ ਜਿਯ ਮੋ ਤਬ।","roman":"Ih bidhi hanee sain asidhuj jab | kaapat bhayo asur jiy mo tab |","meaning_en":"When Asidhuj had killed the army in this way, the demon trembled in his heart.","page":2505,"meaning_status":"draft"},{"gurmukhi":"ਅਮਿਤ ਅਸੁਰ ਰਨ ਔਰ ਪ੍ਰਕਾਸੇ। ਤਿਨ ਕੋ ਕਹਤ ਨਾਮ ਬਿਨੁ ਸਾਸੇ। ੨੩੧।","roman":"Amit asur ran aur prakaase | tin ko kahat naam binu saase | 231 |","meaning_en":"Countless more demons appeared in the battle; I say their names without doubt. 231.","page":2505,"meaning_status":"draft"}]},{"type":"verse","number":[232],"number_text":"੨੩੨।","page":2505,"lines":[{"gurmukhi":"ਗੀਧ ਧੁਜਾ ਕਾਕ ਧੁਜ ਰਾਛਸ। ਉਲੂ ਕੇਤੁ ਬੀਯੋ ਬਡ ਰਾਛਸ।","roman":"Geedh dhujaa kaak dhuj raachhas | uloo ketu beeyo bad raachhas |","meaning_en":"Gidh Dhuja, Kak Dhuj the demon, Ulu Ketu, another great demon,","page":2505,"meaning_status":"draft"},{"gurmukhi":"ਅਸਿਧੁਜ ਕੇ ਰਨ ਸਮੁਹਿ ਸਿਧਾਏ। ਮਾਰਿ ਮਾਰਿ ਚਹੂੰ ਓਰ ਉਘਾਏ। ੨੩੨।","roman":"Asidhuj ke ran samuhi sidhaae | maari maari chahoon or ughaae | 232 |","meaning_en":"went against Asidhuj in the battle, crying \"kill, kill\" on all four sides. 232.","page":2505,"meaning_status":"draft"}]},{"type":"verse","number":[233],"number_text":"੨੩੩।","page":2505,"lines":[{"gurmukhi":"ਬਿਸਿਖਨ ਬ੍ਰਿਸਟਿ ਕਰੀ ਕੋਪਹਿ ਕਰਿ। ਜਲਧਰ ਐਸ ਬਡੇ ਭੂਧਰ ਪਰ।","roman":"Bisikhan bristi karee kophi kari | jaldhar ais bade bhoodhar par |","meaning_en":"They rained arrows in anger, like a cloud on a great mountain.","page":2505,"meaning_status":"draft"},{"gurmukhi":"ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਕਰਿ ਕੋਪ ਪ੍ਰਹਾਰੇ। ਚਟਪਟ ਸੁਭਟ ਬਿਕਟਿ ਕਟਿ ਡਾਰੈ। ੨੩੩।","roman":"Sasatr asatr kari kop prahaare | chatpat subhat bikti kati daarai | 233 |","meaning_en":"In rage they struck with missiles and weapons; quickly they cut down warriors terribly. 233.","page":2505,"meaning_status":"draft"}]},{"type":"verse","number":[234],"number_text":"੨੩੪।","page":2507,"lines":[{"gurmukhi":"ਹੁਅੰ ਸਬਦ ਅਸਿਧੁਜਹਿ ਉਚਾਰਾ। ਤਿਹ ਤੇ ਆਧਿ ਬ੍ਯਾਧਿ ਬਪੁ ਧਾਰਾ।","roman":"Huan sabad asidhujhi uchaaraa | tih te aadhi byaadhi bapu dhaaraa |","meaning_en":"Asidhuj uttered the sound \"Hum\"; from it mental and bodily afflictions took form.","page":2507,"meaning_status":"draft"},{"gurmukhi":"ਸੀਤ ਜ੍ਵਰ ਅਰ ਉਸਨ ਤਾਪ ਭਨੇ। ਛਈ ਰੋਗ ਅਰੁ ਸੰਨ੍ਯਪਾਤ ਗਨ। ੨੩੪।","roman":"Seet jvar ar usan taap bhane | chhaee rog aru sannyapaat gan | 234 |","meaning_en":"Cold fever and hot fever are named, ringing disease and delirium. 234.","page":2507,"meaning_status":"draft","note":"ਛਈ ਰੋਗ: 'chhai', wasting disease; as printed; uncertain."}]},{"type":"verse","number":[235],"number_text":"੨੩੫।","page":2507,"lines":[{"gurmukhi":"ਬਾਇ ਪਿਤ੍ਯ ਕਫ ਉਪਜਤ ਭਏ। ਤਾ ਤੇ ਭੇਦ ਅਮਿਤ ਹ੍ਵੈ ਗਏ।","roman":"Baai pity kaph upjat bhae | taa te bhed amit hvai gae |","meaning_en":"Wind, bile and phlegm arose, and from them countless kinds came to be.","page":2507,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤਿਨੈ ਗਨ ਪ੍ਰਗਟ ਸੁਨਾਊ। ਅਯੁਰ ਬੇਦਿਯਨ ਸਭਨ ਰਿਝਾਊ। ੨੩੫।","roman":"Naam tinai gan pragat sunaaoo | ayur bediyan sabhan rijhaaoo | 235 |","meaning_en":"I tell their names, so that I may please all physicians. 235.","page":2507,"meaning_status":"draft"}]},{"type":"verse","number":[236],"number_text":"੨੩੬।","page":2507,"lines":[{"gurmukhi":"ਆਮ ਪਾਤ ਅਰ ਸ੍ਰੋਨਤ ਪਾਤ। ਅਰਧ ਸਿਰਾ ਅਰੁ ਹ੍ਰਿਦੈ ਸੰਘਾਤ।","roman":"Aam paat ar sronat paat | aradh siraa aru hridai sanghaat |","meaning_en":"Aam pat and blood-fall, half-head pain and heart ailment,","page":2507,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰਾਨ ਬਾਇ ਆਪਾਨ ਬਾਇ ਭਨਿ। ਦੰਤ ਰੋਗ ਅਰੁ ਦਾੜ ਪੀੜ ਗਨ। ੨੩੬।","roman":"Praan baai aapaan baai bhani | dant rog aru daar peer gan | 236 |","meaning_en":"prana wind and apana wind, toothache and jaw pain. 236.","page":2507,"meaning_status":"draft"}]},{"type":"verse","number":[237],"number_text":"੨੩੭।","page":2507,"lines":[{"gurmukhi":"ਸੂਖਾ ਜਰ ਤੇਇਯਾ ਚੌਥਾਯਾ। ਅਸਟ ਦਿਵਸਯੋ ਅਰੁ ਬੀਸਾਯਾ।","roman":"Sookhaa jar teiyaa chauthaayaa | asat divasyo aru beesaayaa |","meaning_en":"Dry fever, third-day and fourth-day fever, eight-day fever and twenty-day fever,","page":2507,"meaning_status":"draft"},{"gurmukhi":"ਡੇਢ ਮਾਸਿਯਾ ਪੁਨਿ ਤਪ ਭਯੋ। ਦਾਤ ਕਾਢ ਦੈਤਨ ਪਰ ਧਯੋ। ੨੩੭।","roman":"Dedh maasiyaa puni tap bhayo | daat kaadh daitan par dhayo | 237 |","meaning_en":"a fever of a month and a half came; it ran at the demons, baring its teeth. 237.","page":2507,"meaning_status":"draft"}]},{"type":"verse","number":[238],"number_text":"੨੩੮।","page":2507,"lines":[{"gurmukhi":"ਫੀਲਪਾਵ ਪੁਨਿ ਜਾਨੂ ਰੋਗਾ। ਉਪਜਾ ਦੇਨ ਦੁਸਟ ਦਲ ਸੋਗਾ।","roman":"Pheelpaav puni jaanoo rogaa | upjaa den dusat dal sogaa |","meaning_en":"Elephant-foot and knee disease arose, giving the wicked host grief.","page":2507,"meaning_status":"draft"},{"gurmukhi":"ਖਈ ਸੁ ਬਾਦੀ ਭਈ ਮਵੇਸੀ। ਪਾਂਡ ਰੋਗ ਪੀਨਸ ਕਟਿ ਦੇਸੀ। ੨੩੮।","roman":"Khaee su baadee bhaee mavesee | paand rog peenas kati desee | 238 |","meaning_en":"Consumption, flatulence, dropsy, jaundice and fat-disease cut them down. 238.","page":2507,"meaning_status":"draft","note":"Disease names rendered as best understood; uncertain."}]},{"type":"verse","number":[239],"number_text":"੨੩੯।","page":2507,"lines":[{"gurmukhi":"ਚਿਨਗਿ ਪ੍ਰਮੇਵ ਭਗਿੰਦ੍ਰ ਦਖੂਤ੍ਰਾ। ਪਥਰੀ ਬਾਇ ਫਿਰੰਗ ਅਧਨੇਤ੍ਰਾ।","roman":"Chingi pramev bhagindr dakhootraa | pathree baai phirang adhnetraa |","meaning_en":"Chinag, prameh, fistula, dakhutra, stone, wind, venereal disease and half-blindness,","page":2507,"meaning_status":"draft"},{"gurmukhi":"ਗਲਤ ਕੁਸਟ ਉਪਜਾ ਦੁਸਟਨ ਤਨ। ਸੇਤ ਕੁਸਟ ਕੇਤਿਨ ਕੇ ਭਯੋ ਭਨ। ੨੩੯।","roman":"Galat kusat upjaa dustan tan | set kusat ketin ke bhayo bhan | 239 |","meaning_en":"rotting leprosy arose in the wicked; white leprosy came to some. 239.","page":2507,"meaning_status":"draft","note":"Disease names as best understood; uncertain."}]},{"type":"verse","number":[240],"number_text":"੨੪੦।","page":2507,"lines":[{"gurmukhi":"ਕੇਤੇ ਸਤ੍ਰੁ ਸੂਲ ਹ੍ਵੈ ਮਰੇ। ਕੇਤੇ ਆਂਤ ਰੋਗ ਤੇ ਟਰੇ।","roman":"Kete satru sool hvai mare | kete aant rog te tare |","meaning_en":"Many enemies died of colic; many were laid low by disease of the bowels.","page":2507,"meaning_status":"draft"},{"gurmukhi":"ਸੰਗ੍ਰਹਨੀ ਸੰਗ੍ਰਹ ਦੁਸਟ ਕਿਯ। ਜੀਯਨ ਕੋ ਪੁਨਿ ਨਾਮ ਨ ਤਿਨ ਲਿਯ। ੨੪੦।","roman":"Sangrahnee sangrah dusat kiy | jeeyan ko puni naam na tin liy | 240 |","meaning_en":"Sangrahani seized the wicked; they no longer took the name of life. 240.","page":2507,"meaning_status":"draft"}]},{"type":"verse","number":[241],"number_text":"੨੪੧।","page":2507,"lines":[{"gurmukhi":"ਕੇਤੇ ਉਪਜ ਸੀਤਲਾ ਮਰੇ। ਕੇਤੇ ਅਗਿਨਿ ਬਾਵ ਤੇ ਜਰੇ।","roman":"Kete upaj seetlaa mare | kete agini baav te jare |","meaning_en":"Many died when smallpox arose; many burned in a fire-like fever.","page":2507,"meaning_status":"draft"},{"gurmukhi":"ਭਰਮ ਚਿਤ ਕੇਤੇ ਹ੍ਵੈ ਮਰੇ। ਉਦਰ ਰੋਗ ਕੇਤੇ ਅਰਿ ਟਰੇ। ੨੪੧।","roman":"Bharam chit kete hvai mare | udar rog kete ari tare | 241 |","meaning_en":"Many died of confusion of mind; many enemies were brought down by disease of the belly. 241.","page":2507,"meaning_status":"draft"}]},{"type":"verse","number":[242],"number_text":"੨੪੨।","page":2507,"lines":[{"gurmukhi":"ਜਬ ਅਸਿਧੁਜ ਅਸ ਰੋਗ ਪ੍ਰਕਾਸੇ। ਅਧਿਕ ਸਤ੍ਰੁ ਤਾਪਤ ਹ੍ਵੈ ਤ੍ਰਾਸੇ।","roman":"Jab asidhuj as rog prakaase | adhik satru taapat hvai traase |","meaning_en":"When Asidhuj brought out such diseases, many enemies, tormented, were terrified.","page":2507,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਕੇ ਤਨ ਗਨ ਦਈ ਦਿਖਾਈ। ਤਿਨੌ ਜੀਯਤ ਕੀ ਆਸ ਚੁਕਾਈ। ੨੪੨।","roman":"Jaa ke tan gan daee dikhaaee | tinau jeeyat kee aas chukaaee | 242 |","meaning_en":"Those on whose bodies they appeared gave up hope of life. 242.","page":2507,"meaning_status":"draft"}]},{"type":"verse","number":[243],"number_text":"੨੪੩।","page":2507,"lines":[{"gurmukhi":"ਕੇਤਿਕ ਦੁਸਟ ਤਾਪ ਤਨ ਤਪੈ। ਕੇਤਿਕ ਉਦਰ ਰੋਗ ਹ੍ਵੈ ਖਪੈ।","roman":"Ketik dusat taap tan tapai | ketik udar rog hvai khapai |","meaning_en":"Some wicked ones burned with fever in the body; some perished of disease of the belly.","page":2507,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤਕਨ ਆਨਿ ਕਾਪਨੀ ਚਢੀ। ਕੇਤਿਕ ਬਾਇ ਪਿਤ ਤਨ ਬਢੀ। ੨੪੩।","roman":"Kitkan aani kaapnee chadhee | ketik baai pit tan badhee | 243 |","meaning_en":"Shivering came upon some; wind and bile increased in some bodies. 243.","page":2507,"meaning_status":"draft"}]},{"type":"verse","number":[244],"number_text":"੨੪੪।","page":2507,"lines":[{"gurmukhi":"ਉਦਰ ਬਿਕਾਰ ਕਿਤੇ ਮਰਿ ਗਏ। ਤਾਪਤਿ ਕਿਤਕ ਤਾਪ ਤਨ ਭਏ।","roman":"Udar bikaar kite mari gae | taapti kitak taap tan bhae |","meaning_en":"Some died of disorders of the stomach; some became feverish in the body.","page":2507,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤਕਨ ਸੰਨ੍ਯਪਾਤ ਹ੍ਵੈ ਗਯੋ। ਕੇਤਿਨ ਬਾਇ ਪਿਤ ਕਫ ਭਯੋ। ੨੪੪।","roman":"Kitkan sannyapaat hvai gayo | ketin baai pit kaph bhayo | 244 |","meaning_en":"Some had delirium; some had wind, bile and phlegm. 244.","page":2507,"meaning_status":"draft"}]},{"type":"verse","number":[245],"number_text":"੨੪੫।","page":2507,"lines":[{"gurmukhi":"ਕੇਤਿਕ ਮਰੇ ਮੂੰਡ ਕੀ ਪੀਰਾ। ਕਿਤਕ ਬਾਇ ਤੇ ਭਏ ਅਧੀਰਾ।","roman":"Ketik mare moond kee peeraa | kitak baai te bhae adheeraa |","meaning_en":"Some died of pain in the head; some grew restless with wind.","page":2507,"meaning_status":"draft"},{"gurmukhi":"ਕੇਤਿਕ ਛਈ ਰੋਗ ਛੈ ਕਿਯੋ। ਕੇਤਨ ਨਾਸ ਬਾਇ ਤੇ ਥਿਯੋ। ੨੪੫।","roman":"Ketik chhaee rog chhai kiyo | ketan naas baai te thiyo | 245 |","meaning_en":"Some were wasted by disease; some were destroyed by wind. 245.","page":2507,"meaning_status":"draft"}]},{"type":"verse","number":[246],"number_text":"੨੪੬।","page":2509,"lines":[{"gurmukhi":"ਦਾੜ ਪੀੜ ਕੇਤੇ ਮਰਿ ਗਏ। ਬਾਇ ਭਏ ਬਵਰੇ ਕਈ ਭਏ।","roman":"Daar peer kete mari gae | baai bhae bavre kaee bhae |","meaning_en":"Many died of toothache; some became crazed with wind.","page":2509,"meaning_status":"draft"},{"gurmukhi":"ਜਿਨ ਕੌ ਆਨਿ ਰੋਗ ਤਨ ਗ੍ਰਾਸਾ। ਤਾ ਕਾ ਪ੍ਰਾਨ ਦੇਹ ਤਜਿ ਨਾਸਾ। ੨੪੬।","roman":"Jin kau aani rog tan graasaa | taa kaa praan deh taji naasaa | 246 |","meaning_en":"Whomever disease came upon and seized in the body, his life left the body and was lost. 246.","page":2509,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2509,"meaning_status":"draft"},{"type":"verse","number":[247],"number_text":"੨੪੭।","page":2509,"lines":[{"gurmukhi":"ਕਹਾ ਲਗੇ ਮੈ ਬਰਨ ਸੁਨਾਊ। ਗ੍ਰੰਥ ਬਢਨ ਤੇ ਅਤਿ ਡਰਪਾਊ।","roman":"Kahaa lage mai baran sunaaoo | granth badhan te ati darpaaoo |","meaning_en":"How far shall I describe it? I fear the book will grow too large.","page":2509,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਬਿਧਿ ਭਯੋ ਦਾਨਵਨ ਨਾਸਾ। ਖੜਗਕੇਤੁ ਅਸੁ ਕਿਯਾ ਤਮਾਸਾ। ੨੪੭।","roman":"Ih bidhi bhayo daanvan naasaa | kharagketu asu kiyaa tamaasaa | 247 |","meaning_en":"Thus the destruction of the demons took place; Kharagketu made such a spectacle. 247.","page":2509,"meaning_status":"draft","note":"ਖੜਗਕੇਤੁ: Kharagketu, 'sword-bannered', another name of the same Lord as Asidhuj."}]},{"type":"verse","number":[248],"number_text":"੨੪੮।","page":2509,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਤਨ ਦਾਨਵ ਜਬ ਮਾਰੇ। ਪੁਨਿ ਅਸਿਧੁਜ ਅਸ ਮੰਤ੍ਰ ਬਿਚਾਰੇ।","roman":"Ih bidhi tan daanav jab maare | puni asidhuj as mantr bichaare |","meaning_en":"When he had killed the demons' bodies in this way, Asidhuj then thought as follows:","page":2509,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਇਨ ਕੋ ਹ੍ਵੈ ਹੈ ਰਨ ਆਸਾ। ਮੁਝੈ ਦਿਖੈ ਹੈ ਕਵਨ ਤਮਾਸਾ। ੨੪੮।","roman":"Jo in ko hvai hai ran aasaa | mujhai dikhai hai kavan tamaasaa | 248 |","meaning_en":"\"If they have any hope of the battle, what spectacle will I show them?\" 248.","page":2509,"meaning_status":"draft"}]},{"type":"verse","number":[249],"number_text":"੨੪੯।","page":2509,"lines":[{"gurmukhi":"ਤਿਨ ਕਹ ਦੀਨ ਐਸ ਬਰਦਾਨਾ। ਤੁਮਤੇ ਹੋਹਿ ਅਵਖਧੀ ਨਾਨਾ।","roman":"Tin kah deen ais bardaanaa | tumte hohi avakhdhee naanaa |","meaning_en":"He gave them this boon: \"From you will come many medicines.","page":2509,"meaning_status":"draft"},{"gurmukhi":"ਜਿਹ ਕੇ ਤਨ ਕੌ ਰੋਗ ਸੰਤਾਵੈ। ਤਾਹਿ ਅਵਖਧੀ ਬੇਗ ਜਿਯਾਵੈ। ੨੪੯।","roman":"Jih ke tan kau rog santaavai | taahi avakhdhee beg jiyaavai | 249 |","meaning_en":"Whose body disease afflicts, the medicine will quickly restore him to life.\" 249.","page":2509,"meaning_status":"draft"}]},{"type":"verse","number":[250],"number_text":"੨੫੦।","page":2509,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਦਯੋ ਜਬੈ ਬਰਦਾਨਾ। ਮਿਰਤਕ ਹੁਤੇ ਅਸੁਰ ਜੇ ਨਾਨਾ।","roman":"Ih bidhi dayo jabai bardaanaa | mirtak hute asur je naanaa |","meaning_en":"When he had given this boon, the many demons who were dead,","page":2509,"meaning_status":"draft"},{"gurmukhi":"ਤਿਨ ਤੇ ਅਧਿਕ ਅਵਖਧੀ ਨਿਕਸੀ। ਅਪਨੇ ਸਕਲ ਗੁਨਨ ਕਹ ਬਿਗਸੀ। ੨੫੦।","roman":"Tin te adhik avakhdhee niksee | apne sakal gunan kah bigsee | 250 |","meaning_en":"from them medicines came forth in numbers, delighting in all their own virtues. 250.","page":2509,"meaning_status":"draft"}]},{"type":"verse","number":[251],"number_text":"੨੫੧।","page":2509,"lines":[{"gurmukhi":"ਜਾ ਕੇ ਦੇਹ ਪਿਤ੍ਯ ਦੁਖ ਦੇਈ। ਸੋ ਭਖਿ ਜਰੀ ਬਾਤ ਕੀ ਲੇਈ।","roman":"Jaa ke deh pity dukh de'ee | so bhakhi jaree baat kee le'ee |","meaning_en":"Whose body bile pains, he eats the herb and takes it for wind.","page":2509,"meaning_status":"draft","note":"Printed 'ਸੋ ਭਖਿ ਜਰੀ ਬਾਤ ਕੀ ਲੇਈ': read as 'eats the herb that takes away wind'; uncertain."},{"gurmukhi":"ਜਿਹ ਦਾਨਵ ਕੌ ਬਾਇ ਸੰਤਾਵੈ। ਸੋ ਲੈ ਜਰੀ ਪਿਤ੍ਯ ਕੀ ਖਾਵੈ। ੨੫੧।","roman":"Jih daanav kau baai santaavai | so lai jaree pity kee khaavai | 251 |","meaning_en":"The demon whom wind afflicts takes the herb and eats it for bile. 251.","page":2509,"meaning_status":"draft"}]},{"type":"verse","number":[252],"number_text":"੨੫੨।","page":2509,"lines":[{"gurmukhi":"ਜਾ ਕੀ ਦੇਹਿਹ ਕਫ ਦੁਖ ਲ੍ਯਾਵੈ। ਸੋ ਲੈ ਕਫਨਾਸਨੀ ਚਬਾਵੈ।","roman":"Jaa kee dehih kaph dukh lyaavai | so lai kaphnaasnee chabaavai |","meaning_en":"Whose body phlegm pains, he takes and chews the phlegm-destroyer.","page":2509,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਬਿਧਿ ਅਸੁਰ ਭਏ ਬਿਨੁ ਰੋਗਾ। ਮਾਡਤ ਭਏ ਜੁਧ ਤਜਿ ਸੋਗਾ। ੨੫੨।","roman":"Ih bidhi asur bhae binu rogaa | maadat bhae judh taji sogaa | 252 |","meaning_en":"In this way the demons became free of disease and engaged again in battle, leaving grief. 252.","page":2509,"meaning_status":"draft"}]},{"type":"verse","number":[253],"number_text":"੨੫੩।","page":2509,"lines":[{"gurmukhi":"ਅਗਨਿ ਅਸਤ੍ਰ ਛਾਡਾ ਤਬ ਦਾਨਵ। ਜਾ ਤੇ ਭਏ ਭਸਮ ਬਹੁ ਮਾਨਵ।","roman":"Agni asatr chhaadaa tab daanav | jaa te bhae bhasam bahu maanav |","meaning_en":"Then the demon loosed the fire weapon, by which many men were turned to ash.","page":2509,"meaning_status":"draft"},{"gurmukhi":"ਬਾਰੁਣਾਸਤ੍ਰ ਤਬ ਕਾਲ ਚਲਾਯੋ। ਸਕਲ ਅਗਨਿ ਕੋ ਤੇਜ ਮਿਟਾਯੋ। ੨੫੩।","roman":"Baarunaasatr tab kaal chalaayo | sakal agni ko tej mitaayo | 253 |","meaning_en":"Then Kal loosed the Varun weapon and put out all the heat of the fire. 253.","page":2509,"meaning_status":"draft"}]},{"type":"verse","number":[254],"number_text":"੨੫੪।","page":2509,"lines":[{"gurmukhi":"ਰਾਛਸ ਪਵਨ ਅਸਤ੍ਰ ਸੰਧਾਨਾ। ਜਾ ਤੇ ਉਡਤ ਭਏ ਗਨ ਨਾਨਾ।","roman":"Raachhas pavan asatr sandhaanaa | jaa te udat bhae gan naanaa |","meaning_en":"The demon took aim with the wind weapon, by which many hosts were blown away.","page":2509,"meaning_status":"draft"},{"gurmukhi":"ਭੂਧਰਾਸਤ੍ਰ ਤਬ ਕਾਲ ਪ੍ਰਹਾਰਾ। ਸਭ ਸਿਵਕਨ ਕੋ ਪ੍ਰਾਨ ਉਬਾਰਾ। ੨੫੪।","roman":"Bhoodhraasatr tab kaal prahaaraa | sabh sivkan ko praan ubaaraa | 254 |","meaning_en":"Then Kal struck with the mountain weapon, and saved the lives of all his servants. 254.","page":2509,"meaning_status":"draft"}]},{"type":"verse","number":[255],"number_text":"੨੫੫।","page":2509,"lines":[{"gurmukhi":"ਮੇਘ ਅਸਤ੍ਰ ਛੋਰਾ ਪੁਨਿ ਦਾਨਵ। ਭੀਜ ਗਏ ਜਿਹ ਤੇ ਸਭ ਮਾਨਵ।","roman":"Megh asatr chhoraa puni daanav | bheej gae jih te sabh maanav |","meaning_en":"The demon then loosed the cloud weapon, by which all the men were drenched.","page":2509,"meaning_status":"draft"},{"gurmukhi":"ਬਾਇ ਅਸਤ੍ਰ ਲੈ ਕਾਲ ਚਲਾਯੋ। ਸਭ ਮੇਘਨ ਤਤਕਾਲ ਉਡਾਯੋ। ੨੫੫।","roman":"Baai asatr lai kaal chalaayo | sabh meghan tatkaal udaayo | 255 |","meaning_en":"Kal took and loosed the wind weapon and blew away all the clouds at once. 255.","page":2509,"meaning_status":"draft"}]},{"type":"verse","number":[256],"number_text":"੨੫੬।","page":2509,"lines":[{"gurmukhi":"ਰਾਛਸਾਸਤ੍ਰ ਰਾਛਸਹਿ ਚਲਾਯੋ। ਬਹੁ ਅਸੁਰਨ ਤਾ ਤੇ ਉਪਜਾਯੋ।","roman":"Raachhsaasatr raachhashi chalaayo | bahu asuran taa te upjaayo |","meaning_en":"He loosed the demon weapon against the demon and produced many demons from it.","page":2509,"meaning_status":"draft"},{"gurmukhi":"ਦੇਵਤਾਸਤ੍ਰ ਛੋਰਾ ਤਬ ਕਾਲਾ। ਅਸੁਰ ਸੈਨ ਕੂਟਾ ਦਰਹਾਲਾ। ੨੫੬।","roman":"Devtaasatr chhoraa tab kaalaa | asur sain kootaa darhaalaa | 256 |","meaning_en":"Then Kal loosed the weapon of the gods, and the demon army was beaten at once. 256.","page":2509,"meaning_status":"draft"}]},{"type":"verse","number":[257],"number_text":"੨੫੭।","page":2509,"lines":[{"gurmukhi":"ਜਛ ਅਤਸ੍ਰ ਤਬ ਅਸੁਰ ਚਲਾਯੋ। ਗੰਧ੍ਰਬਾਸਤ੍ਰ ਲੈ ਕਾਲ ਬਗਾਯੋ।","roman":"Jachh atasr tab asur chalaayo | gandhrabaasatr lai kaal bagaayo |","meaning_en":"The demon then loosed the yaksha weapon; Kal sent out the gandharva weapon.","page":2509,"meaning_status":"draft"},{"gurmukhi":"ਤੇ ਦੋਊ ਆਪੁ ਬੀਰ ਲਰਿ ਮਰੇ। ਟੁਕ ਟੁਕ ਹ੍ਵੈ ਭੂ ਪਰ ਪੁਨਿ ਝਰੇ। ੨੫੭।","roman":"Te do'oo aapu beer lari mare | tuk tuk hvai bhoo par puni jhare | 257 |","meaning_en":"Those two themselves fought each other and died, falling in pieces on the earth. 257.","page":2509,"meaning_status":"draft"}]},{"type":"verse","number":[258],"number_text":"੨੫੮।","page":2511,"lines":[{"gurmukhi":"ਚਾਰਣਾਸਤ੍ਰ ਜਬ ਅਸੁਰ ਸੰਧਾਨਾ। ਚਾਰਣ ਉਪਜ ਠਾਢ ਭੈ ਨਾਨਾ।","roman":"Chaarnaasatr jab asur sandhaanaa | chaaran upaj thaadh bhai naanaa |","meaning_en":"When the demon aimed the charan weapon, charans arose and stood in many fears.","page":2511,"meaning_status":"draft","note":"Obscure; uncertain."},{"gurmukhi":"ਸਿਧ ਅਸਤ੍ਰ ਅਸਿ ਧੁਜ ਤਬ ਛੋਰਾ। ਤਾ ਤੇ ਮੁਖ ਸਤ੍ਰਨ ਕੋ ਤੋਰਾ। ੨੫੮।","roman":"Sidh asatr asi dhuj tab chhoraa | taa te mukh satran ko toraa | 258 |","meaning_en":"Then Asidhuj loosed the siddha weapon, and from it broke the mouths of the enemies. 258.","page":2511,"meaning_status":"draft"}]},{"type":"verse","number":[259],"number_text":"੨੫੯।","page":2511,"lines":[{"gurmukhi":"ਉਰਗ ਅਸਤ੍ਰ ਲੈ ਅਸੁਰ ਪ੍ਰਹਾਰਾ। ਤਾ ਤੇ ਉਪਜੇ ਸਰਪ ਅਪਾਰਾ।","roman":"Urag asatr lai asur prahaaraa | taa te upje sarap apaaraa |","meaning_en":"The demon struck with the serpent weapon, and from it countless snakes arose.","page":2511,"meaning_status":"draft"},{"gurmukhi":"ਖਗਪਤਿ ਅਸਤ੍ਰ ਤਜਾ ਤਬ ਕਾਲਾ। ਭਛਿ ਗਏ ਨਾਗਨ ਦਰਹਾਲਾ। ੨੫੯।","roman":"Khagapti asatr tajaa tab kaalaa | bhachhi gae naagan darhaalaa | 259 |","meaning_en":"Then Kal loosed the weapon of the king of birds, and at once the snakes were eaten. 259.","page":2511,"meaning_status":"draft"}]},{"type":"verse","number":[260],"number_text":"੨੬੦।","page":2511,"lines":[{"gurmukhi":"ਬਿਤੂ ਅਸਤ੍ਰ ਦਾਨਵਹਿ ਚਲਾਯੋ। ਬਹੁ ਬਿਛੂਯਨ ਤਾ ਤੇ ਉਪਜਾਯੋ।","roman":"Bitoo asatr daanavhi chalaayo | bahu bichhooyan taa te upjaayo |","meaning_en":"The demon loosed the scorpion weapon, and from it many scorpions arose.","page":2511,"meaning_status":"draft"},{"gurmukhi":"ਲਸਿਟਕਾ ਸਤ੍ਰ ਅਸਿਧੁਜ ਤਬ ਛੋਰਾ। ਸਭ ਹੀ ਡਾਂਕ ਅਠੂਹਨ ਤੋਰਾ। ੨੬੦।","roman":"Lasitkaa satr asidhuj tab chhoraa | sabh hee daank athoohan toraa | 260 |","meaning_en":"Then Asidhuj loosed the lashing weapon, and broke all the stings of the scorpions. 260.","page":2511,"meaning_status":"draft","note":"ਲਸਿਟਕਾ: read as a lashing/whip weapon; uncertain."}]},{"type":"verse","number":[261],"number_text":"੨੬੧।","page":2511,"lines":[{"gurmukhi":"ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਅਸ ਅਸੁਰ ਚਲਾਏ। ਖੜਗ ਕੇਤੁ ਪਰ ਕਛੁ ਨ ਬਸਾਏ।","roman":"Sasatr asatr as asur chalaae | kharag ketu par kachhu na basaae |","meaning_en":"The demons loosed such missiles and weapons, but nothing worked on Kharagketu.","page":2511,"meaning_status":"draft"},{"gurmukhi":"ਅਸਤ੍ਰਨ ਸਾਥ ਅਸਤ੍ਰੁ ਬਹੁ ਛਏ। ਜਾ ਕੌ ਲਗੇ ਲੀਨ ਤੇ ਭਏ। ੨੬੧।","roman":"Astran saath astru bahu chhae | jaa kau lage leen te bhae | 261 |","meaning_en":"Many weapons mingled with weapons; whom they struck, they became merged. 261.","page":2511,"meaning_status":"draft"}]},{"type":"verse","number":[262],"number_text":"੨੬੨।","page":2511,"lines":[{"gurmukhi":"ਲੀਨ ਹ੍ਵੈ ਗਏ ਅਸਤ੍ਰ ਨਿਹਾਰੇ। ਹਾਇ ਹਾਇ ਕਰਿ ਅਸੁਰ ਪੁਕਾਰੇ।","roman":"Leen hvai gae asatr nihaare | haai haai kari asur pukaare |","meaning_en":"Seeing the weapons merged, the demons cried \"Alas, alas\".","page":2511,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਮੂਢ ਫਿਰਿ ਕੋਪ ਬਢਾਈ। ਪੁਨਿ ਅਸਿਧੁਜ ਤਨ ਕਰੀ ਲਰਾਈ। ੨੬੨।","roman":"Mahaa moodh phiri kop badhaaee | puni asidhuj tan karee laraaee | 262 |","meaning_en":"The great fools again increased their anger, and again fought with Asidhuj. 262.","page":2511,"meaning_status":"draft"}]},{"type":"verse","number":[263],"number_text":"੨੬੩।","page":2511,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਭਯੋ ਘੋਰ ਸੰਗ੍ਰਾਮਾ। ਨਿਰਖਤ ਦੇਵ ਦਾਨਵੀ ਬਾਮਾ।","roman":"Ih bidhi bhayo ghor sangraamaa | nirkhat dev daanvee baamaa |","meaning_en":"Thus a terrible battle took place, with gods and demon-women watching.","page":2511,"meaning_status":"draft"},{"gurmukhi":"ਧੰਨ੍ਯ ਧੰਨ੍ਯ ਅਸਿਧੁਜ ਕੌ ਕਹੈ। ਦਾਨਵ ਹੇਰਿ ਮੋਨ ਹ੍ਵੈ ਰਹੈ। ੨੬੩।","roman":"Dhanny dhanny asidhuj kau kahai | daanav heri mon hvai rahai | 263 |","meaning_en":"They said \"Blessed, blessed\" to Asidhuj; the demons looked on and fell silent. 263.","page":2511,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਛੰਦ","roman":"Bhujang chhand","meaning_en":"Bhujang metre.","page":2511,"meaning_status":"draft"},{"type":"verse","number":[264],"number_text":"੨੬੪।","page":2511,"lines":[{"gurmukhi":"ਮਹਾ ਰੋਸ ਕੈ ਕੈ ਹਠੀ ਫੇਰਿ ਗਾਜੇ। ਚਹੂੰ ਓਰ ਤੇ ਘੋਰ ਬਾਦਿਤ੍ਰ ਬਾਜੇ।","roman":"Mahaa ros kai kai hathee pheri gaaje | chahoon or te ghor baaditr baaje |","meaning_en":"In great rage the obstinate ones roared again; terrible instruments sounded on all four sides.","page":2511,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰਣੋ ਸੰਖ ਭੇਰੀ ਬਜੇ ਢੋਲ ਐਸੇ। ਪ੍ਰਲੈ ਕਾਲ ਕੇ ਕਾਲ ਕੀ ਰਾਤ੍ਰਿ ਜੈਸੇ। ੨੬੪।","roman":"Prano sankh bheree baje dhol aise | pralai kaal ke kaal kee raatri jaise | 264 |","meaning_en":"Conches, drums and kettledrums sounded as if in the night of the end of time. 264.","page":2511,"meaning_status":"draft","note":"ਪ੍ਰਣੋ: printed so; read as 'pano' or 'war-sounds'; uncertain."}]},{"type":"verse","number":[265],"number_text":"੨੬੫।","page":2511,"lines":[{"gurmukhi":"ਬਜੇ ਸੰਖ ਔ ਦਾਨਵੀ ਭੇਰ ਐਸੀ। ਕਹੈ ਆਸੁਰੀ ਬ੍ਰਿਤ ਕੀ ਕ੍ਰਿਤ ਜੈਸੀ।","roman":"Baje sankh au daanvee bher aisee | kahai aasuree brit kee krit jaisee |","meaning_en":"Conches sounded and the demon drums, as the demonic tongue tells the deed of its nature.","page":2511,"meaning_status":"draft","note":"Obscure; uncertain."},{"gurmukhi":"ਕਹੂੰ ਬੀਰ ਬਾਜੰਤ ਬਾਕੇ ਬਜਾਵੈ। ਮਨੋ ਚਿਤ ਕੋ ਕੋਪ ਭਾਖੇ ਸੁਨਾਵੈ। ੨੬੫।","roman":"Kahoon beer baajant baake bajaavai | mano chit ko kop bhaakhe sunaavai | 265 |","meaning_en":"In places warriors played fine war-music, as if telling the anger of the heart in words. 265.","page":2511,"meaning_status":"draft"}]},{"type":"verse","number":[266],"number_text":"੨੬੬।","page":2511,"lines":[{"gurmukhi":"ਕਿਤੇ ਬੀਰ ਬਜ੍ਰਾਨ ਕੇ ਸਾਥ ਪੇਲੇ। ਭਰੇ ਬਸਤ੍ਰ ਲੋਹੂ ਮਨੋ ਫਾਗ ਖੇਲੇ।","roman":"Kite beer bajraan ke saath pele | bhare basatr lohoo mano phaag khele |","meaning_en":"Some warriors pressed on with thunderbolts; their garments full of blood, as if playing Holi.","page":2511,"meaning_status":"draft"},{"gurmukhi":"ਮੂਏ ਖਾਇ ਕੈ ਦੁਸਟ ਕੇਤੇ ਮਰੂਰੇ। ਸੋਏ ਜਾਨ ਮਾਲੰਗ ਖਾਏ ਧਤੂਰੇ। ੨੬੬।","roman":"Mooe khaai kai dusat kete maroore | soe jaan maalang khaae dhatoore | 266 |","meaning_en":"Many wicked ones lay dead, having eaten drugs, as if malangs asleep who had eaten thorn-apple. 266.","page":2511,"meaning_status":"draft"}]},{"type":"verse","number":[267],"number_text":"੨੬੭।","page":2511,"lines":[{"gurmukhi":"ਕਿਤੇ ਟੂਕ ਟੂਕੇ ਬਲੀ ਖੇਤ ਹੋਏ। ਮਨੋ ਖਾਇ ਕੈ ਭੰਗ ਮਾਲੰਗ ਸੋਏ।","roman":"Kite took tooke balee khet hoe | mano khaai kai bhang maalang soe |","meaning_en":"Some strong ones lay on the field in pieces, as if malangs asleep after eating bhang.","page":2511,"meaning_status":"draft"},{"gurmukhi":"ਬਿਰਾਜੈ ਕਟੇ ਅੰਗ ਬਸਤ੍ਰੋ ਲਪੇਟੇ। ਜੁਮੇ ਕੇ ਮਨੋ ਰੋਜ ਮੈ ਗੌਂਸ ਲੇਟੇ। ੨੬੭।","roman":"Biraajai kate ang bastro lapete | jume ke mano roj mai gauns lete | 267 |","meaning_en":"Wrapped in cloth, with limbs cut off, they lay like the faithful lying on the day of Friday. 267.","page":2511,"meaning_status":"draft","note":"ਜੁਮੇ ਕੇ ... ਰੋਜ ਮੈ ਗੌਂਸ ਲੇਟੇ: 'like Ghauses lying on the day of Jumah (Friday)'; Persian; uncertain."}]},{"type":"verse","number":[268],"number_text":"੨੬੮।","page":2511,"lines":[{"gurmukhi":"ਕਹੂੰ ਡਾਕਨੀ ਝਾਕਨੀ ਹਾਕ ਮਾਰੈ। ਉਠੈ ਨਾਦ ਭਾਰੇ ਛੂਟੈ ਚੀਤਕਾਰੈ।","roman":"Kahoon daaknee jhaaknee haak maarai | uthai naad bhaare chhootai cheetkaarai |","meaning_en":"In places dakinis and jhakinis shouted; great cries arose and screams burst out.","page":2511,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਘੂੰਮਿ ਭੂੰਮੈ ਪਰੇ ਖੇਤ ਬਾਜੀ। ਨਿਵਾਜੇ ਝੁਕੈ ਹੈ ਮਨੌ ਕਾਬਿ ਕਾਜੀ। ੨੬੮।","roman":"Kahoon ghoonmi bhoonmai pare khet baajee | nivaaje jhukai hai manau kaabi kaajee | 268 |","meaning_en":"In places horses lay on the field turning round, like qazis bowing at prayer. 268.","page":2511,"meaning_status":"draft","note":"ਕਾਬਿ ਕਾਜੀ: qazis; ਨਿਵਾਜੇ: 'namaz' (prayer); uncertain."}]},{"type":"verse","number":[269],"number_text":"੨੬੯।","page":2513,"lines":[{"gurmukhi":"ਹਠੀ ਬਧਿ ਗੋਪਾ ਗੁਲਿਤ੍ਰਾਣ ਬਾਕੇ। ਚਲੇ ਕੋਪ ਕੈ ਕੈ ਹਠੀਲੇ ਨਿਸਾਕੇ।","roman":"Hathee badhi gopaa gulitraan baake | chale kop kai kai hatheele nisaake |","meaning_en":"Obstinate, with armoured hands and fine slingers, the obstinate ones went in rage, fearless.","page":2513,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਚਰਮ ਬਰਮੈ ਗਿਰੇ ਮਰਮ ਛੇਦੇ। ਕਹੂੰ ਮਾਸ ਕੇ ਗਿਧ ਲੈ ਗੇ ਲਬੇਦੇ। ੨੬੯।","roman":"Kahoon charam barmai gire maram chhede | kahoon maas ke gidh lai ge labede | 269 |","meaning_en":"In places shields and armour fell, pierced in the vitals; in places vultures carried off the flesh. 269.","page":2513,"meaning_status":"draft","note":"ਲਬੇਦੇ: printed so; uncertain."}]},{"type":"verse","number":[270],"number_text":"੨੭੦।","page":2513,"lines":[{"gurmukhi":"ਕਹੂੰ ਬੀਰ ਬਾਜੀ ਬਜੰਤ੍ਰੀ ਝਰੇ ਹੈ। ਕਹੂੰ ਖੰਡ ਖੰਡ ਹ੍ਵੈ ਸਿਪਾਹੀ ਮਰੇ ਹੈ।","roman":"Kahoon beer baajee bajantree jhare hai | kahoon khand khand hvai sipaahee mare hai |","meaning_en":"In places warriors and horses lay fallen with their gear; in places soldiers lay dead, cut into pieces.","page":2513,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਮਤ ਦੰਤੀ ਪਰੇ ਹੈ ਪ੍ਰਹਾਰੇ। ਗਿਰੇ ਭੂਮਿ ਪਬੈ ਮਨੋ ਬਦ੍ਰ ਮਾਰੇ। ੨੭੦।","roman":"Kahoon mat dantee pare hai prahaare | gire bhoomi pabai mano badr maare | 270 |","meaning_en":"In places mad elephants lay struck; fallen on the earth like mountains killed by Indra. 270.","page":2513,"meaning_status":"draft","note":"ਬਦ੍ਰ ਮਾਰੇ: 'killed by Indra's bolt (badra)'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":2513,"meaning_status":"draft"},{"type":"verse","number":[271],"number_text":"੨੭੧।","page":2513,"lines":[{"gurmukhi":"ਕਾਢਿ ਕ੍ਰਿਪਾਨ ਜਬੈ ਗਰਜਿਯੋ ਲਖਿ ਦੇਵ ਅਦੇਵ ਸਭੇ ਡਰ ਪਾਨੇ।","roman":"Kaadhi kripaan jabai garjiyo lakhi dev adev sabhe dar paane |","meaning_en":"When he roared, drawing his sword, gods and demons all were afraid.","page":2513,"meaning_status":"draft"},{"gurmukhi":"ਆਨਿ ਪ੍ਰਲੈ ਦਿਨ ਸੋ ਪ੍ਰਗਟ੍ਯੋ ਸਿਤ ਸਾਇਕ ਲੈ ਅਸਿਕੇਤੁ ਰਿਸਾਨੇ।","roman":"Aani pralai din so pragtyo sit saaik lai asiketu risaane |","meaning_en":"He appeared like the day of the end of the world; Asiketu raged with a bright arrow in his hand.","page":2513,"meaning_status":"draft"},{"gurmukhi":"ਫੂਕ ਭਏ ਮੁਖ ਸੂਖਿ ਗਈ ਥੁਕਿ ਜੋਰਿ ਹਥਿਯਾਰ ਕਰੋਰਿ ਪਰਾਨੇ।","roman":"Phook bhae mukh sookhi gaee thuki jori hathiyaar karori paraane |","meaning_en":"Mouths dried up and blew out; spitting, they joined hands, and crores of lives ran off.","page":2513,"meaning_status":"draft"},{"gurmukhi":"ਮਾਨਹੁ ਸਾਵਨ ਕੇ ਬਦਰਾ ਸੁਨਿ ਮਾਰੁਤਿ ਕੀ ਘਹਰੈ ਭਹਰਾਨੇ। ੨੭੧।","roman":"Maanhu saavan ke badraa suni maaruti kee ghahrai bhahraane | 271 |","meaning_en":"As if hearing the roar of the clouds of the month of Savan and of the wind, they trembled. 271.","page":2513,"meaning_status":"draft"}]},{"type":"verse","number":[272],"number_text":"੨੭੨।","page":2513,"lines":[{"gurmukhi":"ਡਾਕਿ ਅਚੈ ਕਹੂੰ ਸ੍ਰੋਨ ਡਕਾਡਕ ਪ੍ਰੇਤ ਪਿਸਾਚ ਕਹੂੰ ਕਿਲਕਾਰੈ।","roman":"Daaki achai kahoon sron dakaadak pret pisaach kahoon kilkaarai |","meaning_en":"In places they cried \"dak\" and \"sron dakadak\"; ghosts and goblins shrieked in places.","page":2513,"meaning_status":"draft"},{"gurmukhi":"ਬਾਜਤ ਹੈ ਕਹੂੰ ਡੌਰੂ ਡਮਾਡਮ ਭੈਰਵ ਭੂਤ ਕਹੂੰ ਭਭਕਾਰੈ।","roman":"Baajat hai kahoon dauroo damaadam bhairav bhoot kahoon bhabhkaarai |","meaning_en":"In places damrus sounded \"damadam\"; Bhairavs and ghosts boomed in places.","page":2513,"meaning_status":"draft"},{"gurmukhi":"ਜੰਗ ਮ੍ਰਿਦੰਗ ਉਪੰਗ ਬਜੈ ਕਹੂੰ ਭੀਖਨ ਸੀ ਰਨ ਭੇਰਿ ਭਕਾਰੈ।","roman":"Jang mridang upang bajai kahoon bheekhan see ran bheri bhakaarai |","meaning_en":"Jang, mridang and upang sounded in places; the fearful war-drums boomed.","page":2513,"meaning_status":"draft"},{"gurmukhi":"ਆਨਿ ਅਰੈ ਕਹੂੰ ਬੀਰ ਚਟਾਪਟ ਕੋਪਿ ਕਟਾਕਟ ਘਾਇ ਪ੍ਰਹਾਰੈ। ੨੭੨।","roman":"Aani arai kahoon beer chataapat kopi kataakat ghaai prahaarai | 272 |","meaning_en":"In places warriors came and stood their ground, and in rage struck blows, \"katakat\". 272.","page":2513,"meaning_status":"draft","note":"Sound-words (ਡਕਾਡਕ, ਡਮਾਡਮ, ਚਟਾਪਟ, ਕਟਾਕਟ) are given as sounds."}]},{"type":"verse","number":[273],"number_text":"੨੭੩।","page":2513,"lines":[{"gurmukhi":"ਐਸੀ ਬਿਲੋਕਿ ਕੈ ਮਾਰਿ ਮਚੀ ਭਟ ਕੋਪ ਭਰੇ ਅਰਿ ਓਰ ਚਹੈ।","roman":"Aisee biloki kai maari machee bhat kop bhare ari or chahai |","meaning_en":"Seeing such a scene, the slaughter broke out; warriors, full of rage, looked toward the enemy.","page":2513,"meaning_status":"draft"},{"gurmukhi":"ਬਰਛੇ ਅਰੁ ਬਾਨ ਕਮਾਨ ਕ੍ਰਿਪਾਨ ਗਦਾ ਬਰਛੀ ਤਿਰਸੂਲ ਗਹੈ।","roman":"Barchhe aru baan kamaan kripaan gadaa barchhee tirsool gahai |","meaning_en":"They held lances, arrows, bows, swords, maces, spears and tridents.","page":2513,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਪੈ ਅਰਰਾਇ ਕੈ ਘਾਇ ਕਰੈ ਨ ਟਰੈ ਬਹੁ ਤੀਰ ਸਰੀਰ ਸਹੈ।","roman":"Ari pai arraai kai ghaai karai na tarai bahu teer sareer sahai |","meaning_en":"Advancing on the enemy, they struck and did not budge, bearing many arrows in the body.","page":2513,"meaning_status":"draft"},{"gurmukhi":"ਪੁਰਜੇ ਪੁਰਜੇ ਤਨ ਤੇ ਰਨ ਮੈ ਦੁਖ ਤੇ ਤਨ ਮੈ ਮੁਖ ਤੇ ਨ ਕਹੈ। ੨੭੩।","roman":"Purje purje tan te ran mai dukh te tan mai mukh te na kahai | 273 |","meaning_en":"Though cut in pieces in the battle they, in pain, did not speak from their mouths. 273.","page":2513,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2513,"meaning_status":"draft"},{"type":"verse","number":[274],"number_text":"੨੭੪।","page":2513,"lines":[{"gurmukhi":"ਪੀਸ ਪੀਸ ਕਰਿ ਦਾਤ ਦੁਬਹਿਯਾ ਧਾਵਹੀ।","roman":"Pees pees kari daat dubhiyaa dhaavhee |","meaning_en":"Grinding their teeth, the dubahiyas ran;","page":2513,"meaning_status":"draft"},{"gurmukhi":"ਬਜ੍ਰ ਬਾਨ ਬਿਛੂਅਨ ਕੇ ਬਿਸਿਖ ਲਗਾਵਹੀ।","roman":"Bajr baan bichhooan ke bisikh lagaavhee |","meaning_en":"they struck thunderbolts, arrows and scorpion-darts.","page":2513,"meaning_status":"draft"},{"gurmukhi":"ਟੂਕ ਟੂਕ ਹੈ ਮਰਤ ਨ ਪਗੁ ਪਾਛੇ ਟਰੈ।","roman":"Took took hai marat na pagu paachhe tarai |","meaning_en":"Cut in pieces they died, but did not move a foot back;","page":2513,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਚਟਪਟ ਆਨਿ ਬਰੰਗਨਿ ਤਿਨ ਪੁਰਖਨ ਬਰੈ। ੨੭੪।","roman":"Ho chatpat aani barangni tin purkhan barai | 274 |","meaning_en":"at once the celestial women came and wed those men. 274.","page":2513,"meaning_status":"draft","note":"ਦੁਬਹਿਯਾ: obscure; uncertain."}]},{"type":"verse","number":[275],"number_text":"੨੭੫।","page":2513,"lines":[{"gurmukhi":"ਚਾਬਿ ਚਾਬਿ ਕਰਿ ਓਠ ਦੁਬਹਿਯਾ ਰਿਸਿ ਭਰੇ।","roman":"Chaabi chaabi kari oth dubhiyaa risi bhare |","meaning_en":"Biting their lips, the dubahiyas were filled with rage;","page":2513,"meaning_status":"draft"},{"gurmukhi":"ਟੂਕ ਟੂਕ ਹ੍ਵੈ ਗਿਰੇ ਨ ਪਗੁ ਪਾਛੇ ਪਰੇ।","roman":"Took took hvai gire na pagu paachhe pare |","meaning_en":"they fell in pieces but did not fall back a step.","page":2513,"meaning_status":"draft"},{"gurmukhi":"ਜੂਝਿ ਜੂਝਿ ਰਨ ਗਿਰਤ ਸੁਭਟ ਸਮੁਹਾਇ ਕੈ।","roman":"Joojhi joojhi ran girat subhat samuhaai kai |","meaning_en":"Fighting and fighting, warriors fell in the battle facing the enemy,","page":2513,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਬਸੇ ਸ੍ਵਰਗ ਮੋ ਜਾਇ ਪਰਮ ਸੁਖ ਪਾਇ ਕੈ। ੨੭੫।","roman":"Ho base svarag mo jaai param sukh paai kai | 275 |","meaning_en":"and went and lived in heaven, finding the highest joy. 275.","page":2513,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":2513,"meaning_status":"draft"},{"type":"verse","number":[276],"number_text":"੨੭੬।","page":2513,"lines":[{"gurmukhi":"ਕੋਪ ਘਨਾ ਕਰਿ ਕੈ ਅਸੁਰਾਰਦਨ ਕਾਢਿ ਕ੍ਰਿਪਾਨਨ ਕੌ ਰਨ ਧਾਏ।","roman":"Kop ghanaa kari kai asuraardan kaadhi kripaanan kau ran dhaae |","meaning_en":"In great rage the destroyers of demons drew their swords and ran into the battle.","page":2513,"meaning_status":"draft"},{"gurmukhi":"ਹਾਕਿ ਹਥਿਯਾਰਨ ਲੈ ਉਮਡੇ ਰਨ ਕੌ ਤਜਿ ਕੈ ਪਗੁ ਦ੍ਵੈ ਨ ਪਰਾਏ।","roman":"Haaki hathiyaaran lai umde ran kau taji kai pagu dvai na paraae |","meaning_en":"They surged up with weapons, shouting, and did not turn back even two steps.","page":2513,"meaning_status":"draft"},{"gurmukhi":"ਮਾਰ ਹੀ ਮਾਰਿ ਪੁਕਾਰਿ ਹਠੀ ਘਨ ਜ੍ਯੋ ਗਰਜੇ ਨ ਕਛੂ ਡਰ ਪਾਏ।","roman":"Maar hee maari pukaari hathee ghan jyo garje na kachhoo dar paae |","meaning_en":"Crying \"kill, kill\", the obstinate ones roared like clouds, without any fear.","page":2515,"meaning_status":"draft"},{"gurmukhi":"ਮਾਨਹੁ ਸਾਵਨ ਕੀ ਰਿਤੁ ਮੈ ਘਨ ਬੂੰਦਨ ਜ੍ਯੋ ਸਰ ਤ੍ਯੋ ਬਰਖਾਏ। ੨੭੬।","roman":"Maanhu saavan kee ritu mai ghan boondan jyo sar tyo barkhaae | 276 |","meaning_en":"As in the rainy month of Savan the clouds rain drops, so they rained arrows. 276.","page":2515,"meaning_status":"draft"}]},{"type":"verse","number":[277],"number_text":"੨੭੭।","page":2515,"lines":[{"gurmukhi":"ਧੂਲ ਜਟਾਯੁ ਤੇ ਅਦਿਕ ਸੂਰ ਸਭੈ ਉਮਡੇ ਕਰ ਆਯੁਧ ਲੈ ਕੈ।","roman":"Dhool jataayu te adik soor sabhai umde kar aayudh lai kai |","meaning_en":"Dhul, Jatayu and the other heroes surged up, with weapons in hand;","page":2515,"meaning_status":"draft"},{"gurmukhi":"ਕੋਪ ਕ੍ਰਿਪਾਨ ਲਏ ਕਰ ਬਾਨ ਮਹਾ ਹਠ ਠਾਨਿ ਬਡੀ ਰਿਸਿ ਕੈ ਕੈ।","roman":"Kop kripaan lae kar baan mahaa hath thaani badee risi kai kai |","meaning_en":"with swords in rage and arrows in hand, they dug in with great obstinacy, enraged.","page":2515,"meaning_status":"draft","note":"Names ਧੂਲ ਜਟਾਯੁ: printed so; uncertain whether 'Dhul and Jatayu' or 'Dhulat Jatayu'."},{"gurmukhi":"ਚੌਪਿ ਚੜੇ ਚਹੂੰ ਓਰਨ ਤੇ ਬਰਿਯਾਰ ਬਡੇ ਦੋਊ ਨੈਨ ਤਚੈ ਕੈ।","roman":"Chaupi chare chahoon oran te bariyaar bade do'oo nain tachai kai |","meaning_en":"Mounted with keenness from all four sides, the great warriors with both eyes sharp,","page":2515,"meaning_status":"draft","note":"ਬਰਿਯਾਰ: 'strong'; ਤਚੈ: 'sharpened'; uncertain."},{"gurmukhi":"ਆਨਿ ਅਰੇ ਖੜਗਾਧੁਜ ਸੌ ਨ ਚਲੇ ਪਗੁ ਦ੍ਵੈ ਬਿਮੁਖਾਹਵ ਹ੍ਵੈ ਕੈ। ੨੭੭।","roman":"Aani are khargaadhuj sau na chale pagu dvai bimukhaahav hvai kai | 277 |","meaning_en":"came and stood against Kharagdhuj, and did not move two steps, turning their backs. 277.","page":2515,"meaning_status":"draft","note":"ਖੜਗਾਧੁਜ: Kharagdhuj, 'sword-banner'; ਬਿਮੁਖਾਹਵ: read 'turning away'; uncertain."}]},{"type":"verse","number":[278],"number_text":"੨੭੮।","page":2515,"lines":[{"gurmukhi":"ਭਾਰੀ ਪ੍ਰਤਾਪ ਭਰੇ ਮਨ ਮੈ ਭਟ ਧਾਇ ਪਰੇ ਬਿਬਿਧਾਯੁਧ ਲੀਨੇ।","roman":"Bhaaree prataap bhare man mai bhat dhaai pare bibidhaayudh leene |","meaning_en":"Filled with great glory in their minds, the warriors fell on him with many kinds of weapons.","page":2515,"meaning_status":"draft"},{"gurmukhi":"ਕੌਚ ਕ੍ਰਿਪਾਨ ਕਸੇ ਸਭ ਸਾਜਨ ਓਠਨ ਚਾਬਿ ਬਡੀ ਰਿਸਿ ਕੀਨੇ।","roman":"Kauch kripaan kase sabh saajan othan chaabi badee risi keene |","meaning_en":"Fastening armour and swords, all ready, they bit their lips in great rage.","page":2515,"meaning_status":"draft"},{"gurmukhi":"ਆਛੇ ਕੁਲਾਨ ਬਿਖੈ ਉਪਜੇ ਸਭ ਕੌਨਹੂੰ ਬਾਤ ਬਿਖੈ ਨਹਿ ਹੀਨੇ।","roman":"Aachhe kulaan bikhai upje sabh kaunhoon baat bikhai nahi heene |","meaning_en":"All were born in good families and were wanting in nothing.","page":2515,"meaning_status":"draft"},{"gurmukhi":"ਜੂਝਿ ਗਿਰੇ ਖੜਗਾਧੁਜ ਸੌ ਲਰਿ ਸ੍ਰੋਨਿਤ ਸੋ ਸਿਗਰੇ ਅੰਗ ਭੀਨੇ। ੨੭੮।","roman":"Joojhi gire khargaadhuj sau lari sronit so sigre ang bheene | 278 |","meaning_en":"They fell fighting Kharagdhuj, with all their limbs soaked in blood. 278.","page":2515,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2515,"meaning_status":"draft"},{"type":"verse","number":[279],"number_text":"੨੭੯।","page":2515,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਕੋਪ ਕਾਲ ਜਬ ਭਰਾ। ਦੁਸਟਨ ਕੋ ਛਿਨ ਮੈ ਬਧੁ ਕਰਾ।","roman":"Ih bidhi kop kaal jab bharaa | dustan ko chhin mai badhu karaa |","meaning_en":"When Kal was filled with such anger, he killed the wicked in an instant.","page":2515,"meaning_status":"draft"},{"gurmukhi":"ਆਪੁ ਹਾਥ ਦੈ ਸਾਧ ਉਬਾਰੇ। ਸਤ੍ਰੁ ਅਨੇਕ ਛਿਨਕ ਮੋ ਟਾਰੇ। ੨੭੯।","roman":"Aapu haath dai saadh ubaare | satru anek chhinak mo taare | 279 |","meaning_en":"Giving his own hand he rescued the saints, and in an instant set aside many enemies. 279.","page":2515,"meaning_status":"draft"}]},{"type":"verse","number":[280],"number_text":"੨੮੦।","page":2515,"lines":[{"gurmukhi":"ਅਸਿਧੁਜ ਜੂ ਕੋਪਾ ਜਬ ਹੀ ਰਨ। ਮਾਰਤ ਭਯੋ ਸਤ੍ਰੁਗਨ ਚੁਨਿ ਚੁਨਿ।","roman":"Asidhuj joo kopaa jab hee ran | maarat bhayo satrugan chuni chuni |","meaning_en":"When Asidhuj grew angry in the battle, he killed hosts of enemies, picking them out one by one.","page":2515,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਸਿਵਕਨ ਕਹ ਲਿਓ ਉਬਾਰਾ। ਦੁਸਟ ਗਠਨ ਕੋ ਕਰਾ ਪ੍ਰਹਾਰਾ। ੨੮੦।","roman":"Sabh sivkan kah lio ubaaraa | dusat gathan ko karaa prahaaraa | 280 |","meaning_en":"He rescued all his servants and struck at the band of the wicked. 280.","page":2515,"meaning_status":"draft"}]},{"type":"verse","number":[281],"number_text":"੨੮੧।","page":2515,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਹਨੇ ਦੁਸਟ ਜਬ ਕਾਲਾ। ਗਿਰਿ ਗਿਰਿ ਪਰੇ ਧਰਨਿ ਬਿਕਰਾਲਾ।","roman":"Ih bidhi hane dusat jab kaalaa | giri giri pare dharni bikraalaa |","meaning_en":"When Kal had killed the wicked in this way, they fell, terrible, on the earth.","page":2515,"meaning_status":"draft"},{"gurmukhi":"ਨਿਜ ਹਾਥਨ ਦੈ ਸੰਤ ਉਬਾਰੇ। ਸਤ੍ਰੁ ਅਨੇਕ ਤਨਿਕ ਮਹਿ ਮਾਰੇ। ੨੮੧।","roman":"Nij haathan dai sant ubaare | satru anek tanik mahi maare | 281 |","meaning_en":"Giving his own hands he rescued the saints, and in a moment killed many enemies. 281.","page":2515,"meaning_status":"draft"}]},{"type":"verse","number":[282],"number_text":"੨੮੨।","page":2515,"lines":[{"gurmukhi":"ਦਾਨਵ ਅਮਿਤ ਕੋਪ ਕਰਿ ਢੂਕੇ। ਮਾਰਹਿ ਮਾਰਿ ਦਸੌ ਦਿਸਿ ਕੂਕੇ।","roman":"Daanav amit kop kari dhooke | maarhi maari dasau disi kooke |","meaning_en":"Countless demons came on in great rage, crying \"kill, kill\" in all ten directions.","page":2515,"meaning_status":"draft"},{"gurmukhi":"ਬਹੁਰਿ ਕਾਲ ਕੁਪਿ ਖੜਗ ਸੰਭਾਰਾ। ਸਤ੍ਰੁ ਸੈਨ ਪਲ ਬੀਚ ਪ੍ਰਹਾਰਾ। ੨੮੨।","roman":"Bahuri kaal kupi kharag sanbhaaraa | satru sain pal beech prahaaraa | 282 |","meaning_en":"Then Kal in rage took up his sword and struck the enemy army in a moment. 282.","page":2515,"meaning_status":"draft"}]},{"type":"verse","number":[283],"number_text":"੨੮੩।","page":2515,"lines":[{"gurmukhi":"ਬਹੁਰਿ ਕੋਪ ਕਰਿ ਦੁਸਟ ਅਪਾਰਾ। ਮਹਾ ਕਾਲ ਕੌ ਚਹਤ ਸੰਘਾਰਾ।","roman":"Bahuri kop kari dusat apaaraa | mahaa kaal kau chahat sanghaaraa |","meaning_en":"Again in rage countless wicked ones wished to kill Mahakal.","page":2515,"meaning_status":"draft"},{"gurmukhi":"ਜਿਮਿ ਗਗਨਹਿ ਕੋਈ ਬਾਨ ਚਲਾਵੈ। ਤਾਹਿ ਨ ਲਗੇ ਤਿਸੀ ਪਰ ਆਵੈ। ੨੮੩।","roman":"Jimi gaganhi koee baan chalaavai | taahi na lage tisee par aavai | 283 |","meaning_en":"As when someone shoots an arrow at the sky, it does not strike the sky but falls on him. 283.","page":2515,"meaning_status":"draft"}]},{"type":"verse","number":[284],"number_text":"੨੮੪।","page":2515,"lines":[{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਬਾਦਿਤ੍ਰ ਬਜਾਇ। ਦਾਨਵ ਨਿਕਟ ਪਹੂਚੇ ਆਇ।","roman":"Bhaati bhaati baaditr bajaai | daanav nikat pahooche aai |","meaning_en":"Playing instruments in many ways, the demons came near.","page":2515,"flags":[{"code":"ੁ+ੂ","reason":"overlapping ੁ and ੂ drawn as one ੂ"}],"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਕਾਲ ਤਬ ਬਿਰਦ ਸੰਭਾਰੋ। ਸੰਤ ਉਬਾਰਿ ਦੋਖਿਯਨ ਮਾਰੋ। ੨੮੪।","roman":"Mahaa kaal tab birad sanbhaaro | sant ubaari dokhiyan maaro | 284 |","meaning_en":"Then Mahakal remembered his own nature: he rescued the saints and killed the wrongdoers. 284.","page":2515,"meaning_status":"draft"}]},{"type":"verse","number":[285],"number_text":"੨੮੫।","page":2515,"lines":[{"gurmukhi":"ਖੰਡ ਖੰਡ ਕਰਿ ਦਾਨਵ ਮਾਰੇ। ਤਿਲ ਤਿਲ ਪ੍ਰਾਇ ਸਕਲ ਕਰਿ ਡਾਰੇ।","roman":"Khand khand kari daanav maare | til til praai sakal kari daare |","meaning_en":"He killed demons, cutting them in pieces, and made them all into bits, bit by bit.","page":2515,"meaning_status":"draft"},{"gurmukhi":"ਪਾਵਕਾਸਤ੍ਰ ਕਲਿ ਬਹੁਰਿ ਚਲਾਯੋ। ਸੈਨ ਅਸੁਰ ਕੋ ਸਗਲ ਗਿਰਾਯੋ। ੨੮੫।","roman":"Paavkaasatr kali bahuri chalaayo | sain asur ko sagal giraayo | 285 |","meaning_en":"Then Kal loosed the fire weapon and brought down the whole army of the demons. 285.","page":2515,"meaning_status":"draft"}]},{"type":"verse","number":[286],"number_text":"੨੮੬।","page":2517,"lines":[{"gurmukhi":"ਬਰੁਣਾਸਤ੍ਰ ਦਾਨਵ ਤਬ ਛੋਰਾ। ਜਾ ਤੇ ਪਾਵਕਾਸਤ੍ਰ ਕਹ ਮੋਰਾ।","roman":"Barunaasatr daanav tab chhoraa | jaa te paavkaasatr kah moraa |","meaning_en":"Then the demon loosed the Varun weapon, which turned back the fire weapon.","page":2517,"meaning_status":"draft"},{"gurmukhi":"ਬਾਸ੍ਵਾਸਤ੍ਰ ਤਬ ਕਾਲ ਚਲਾਯੋ। ਇੰਦ੍ਰ ਪ੍ਰਤ੍ਰਛ ਹ੍ਵੈ ਜੁਧ ਮਚਾਯੋ। ੨੮੬।","roman":"Baasvaasatr tab kaal chalaayo | indr pratrachh hvai judh machaayo | 286 |","meaning_en":"Then Kal loosed the weapon of Indra; Indra himself appeared and joined battle. 286.","page":2517,"meaning_status":"draft","note":"ਬਾਸ੍ਵਾਸਤ੍ਰ: the weapon of Vasava (Indra); read so; uncertain."}]},{"type":"verse","number":[287],"number_text":"੨੮੭।","page":2517,"lines":[{"gurmukhi":"ਦਾਨਵ ਨਿਰਖਿ ਠਾਢ ਰਨ ਬਾਸਵ। ਪੀਵਤ ਭਯੋ ਕੂਪ ਦ੍ਵੈ ਆਸਵ।","roman":"Daanav nirkhi thaadh ran baasav | peevat bhayo koop dvai aasav |","meaning_en":"Seeing Indra stand in the battle, the demon drank two jars of wine.","page":2517,"meaning_status":"draft"},{"gurmukhi":"ਕਰਿ ਕੈ ਕੋਪ ਅਤੁਲ ਅਸ ਗਰਜਾ। ਭੂੰਮਿ ਅਕਾਸ ਸਬਦ ਸੁਨਿ ਲਰਜਾ। ੨੮੭।","roman":"Kari kai kop atul as garjaa | bhoonmi akaas sabad suni larjaa | 287 |","meaning_en":"In rage he roared so incomparably that earth and sky trembled at the sound. 287.","page":2517,"meaning_status":"draft"}]},{"type":"verse","number":[288],"number_text":"੨੮੮।","page":2517,"lines":[{"gurmukhi":"ਅਮਿਤ ਬਾਸਵਹਿ ਬਾਨ ਪ੍ਰਹਾਰੇ। ਬਰਮ ਚਰਮ ਸਭ ਭੇਦਿ ਪਧਾਰੇ।","roman":"Amit baasavhi baan prahaare | baram charam sabh bhedi padhaare |","meaning_en":"He shot countless arrows at Indra; they pierced all armour and shields.","page":2517,"meaning_status":"draft"},{"gurmukhi":"ਜਨੁਕ ਨਾਗ ਬਾਂਬੀ ਧਸਿ ਗਏ। ਭੂਤਲ ਭੇਦਿ ਪਤਾਰ ਸਿਧਏ। ੨੮੮।","roman":"Januk naag baanbee dhasi gae | bhootal bhedi pataar sidhae | 288 |","meaning_en":"They were like snakes entering an anthill, and went through the earth into the underworld. 288.","page":2517,"meaning_status":"draft"}]},{"type":"verse","number":[289],"number_text":"੨੮੯।","page":2517,"lines":[{"gurmukhi":"ਅਮਿਤ ਰੋਸ ਬਾਸਵ ਤਬ ਕਿਯਾ। ਧਨੁਖ ਬਾਨ ਕਰ ਭੀਤਰ ਲਿਯਾ।","roman":"Amit ros baasav tab kiyaa | dhanukh baan kar bheetar liyaa |","meaning_en":"Then Indra grew very angry and took the bow and arrow in his hand.","page":2517,"meaning_status":"draft"},{"gurmukhi":"ਅਮਿਤ ਕੋਪ ਕਰਿ ਬਿਸਿਖ ਪ੍ਰਹਾਰੇ। ਫੋਰਿ ਦਾਨਵਨ ਪਾਰ ਪਧਾਰੇ। ੨੮੯।","roman":"Amit kop kari bisikh prahaare | phori daanvan paar padhaare | 289 |","meaning_en":"In great rage he shot arrows, which split through the demons and went across. 289.","page":2517,"meaning_status":"draft"}]},{"type":"verse","number":[290],"number_text":"੨੯੦।","page":2517,"lines":[{"gurmukhi":"ਦਾਨਵ ਅਧਿਕ ਰੋਸ ਕਰਿ ਧਾਏ। ਦੇਵ ਪੂਜ ਰਨ ਮਾਝ ਭਜਾਏ।","roman":"Daanav adhik ros kari dhaae | dev pooj ran maajh bhajaae |","meaning_en":"The demons ran in great rage, and made the worshipped gods flee from the battle.","page":2517,"meaning_status":"draft"},{"gurmukhi":"ਭਜਤ ਦੇਵ ਨਿਰਖੇ ਕਲਿ ਜਬ ਹੀ। ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਛੋਰੇ ਰਨ ਤਬ ਹੀ। ੨੯੦।","roman":"Bhajat dev nirkhe kali jab hee | sasatr asatr chhore ran tab hee | 290 |","meaning_en":"When Kal saw the gods fleeing, he then loosed weapons and missiles in the battle. 290.","page":2517,"meaning_status":"draft"}]},{"type":"verse","number":[291],"number_text":"੨੯੧।","page":2517,"lines":[{"gurmukhi":"ਬਾਨਨ ਕੀ ਬਰਖਾ ਕਲਿ ਕਰੀ। ਲਾਗਤ ਸੈਨ ਦਾਨਵੀ ਜਰੀ।","roman":"Baanan kee barkhaa kali karee | laagat sain daanvee jaree |","meaning_en":"Kal made a rain of arrows; the demon army was burned as they struck.","page":2517,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੁ ਅਨੇਕ ਨਿਧਨ ਕਹ ਗਏ। ਬਹੁਰਿ ਉਪਜਿ ਬਹੁ ਠਾਢੇ ਭਏ। ੨੯੧।","roman":"Satru anek nidhan kah gae | bahuri upji bahu thaadhe bhae | 291 |","meaning_en":"Many enemies went to death, and then many more arose and stood. 291.","page":2517,"meaning_status":"draft"}]},{"type":"verse","number":[292],"number_text":"੨੯੨।","page":2517,"lines":[{"gurmukhi":"ਬਹੁਰਿ ਕਾਲ ਕੁਪਿ ਬਾਨ ਪ੍ਰਹਾਰੇ। ਬੇਧਿ ਦਾਨਵਨ ਪਾਰ ਪਧਾਰੇ।","roman":"Bahuri kaal kupi baan prahaare | bedhi daanvan paar padhaare |","meaning_en":"Then Kal in rage shot arrows, which pierced the demons and passed through.","page":2517,"meaning_status":"draft"},{"gurmukhi":"ਦਾਨਵ ਤਬੈ ਅਧਿਕ ਕਰਿ ਕ੍ਰੂਧਾ। ਮੰਡਾ ਮਹਾ ਕਾਲ ਤਨ ਜੁਧਾ। ੨੯੨।","roman":"Daanav tabai adhik kari kroodhaa | mandaa mahaa kaal tan judhaa | 292 |","meaning_en":"Then the demons in great rage joined battle with Mahakal. 292.","page":2517,"meaning_status":"draft"}]},{"type":"verse","number":[293],"number_text":"੨੯੩।","page":2517,"lines":[{"gurmukhi":"ਮਹਾ ਕਾਲ ਤਬ ਬਾਨ ਪ੍ਰਹਾਰੇ। ਦਾਨਵ ਏਕ ਏਕ ਕਰਿ ਮਾਰੇ।","roman":"Mahaa kaal tab baan prahaare | daanav ek ek kari maare |","meaning_en":"Then Mahakal shot arrows and killed demons one by one.","page":2517,"meaning_status":"draft"},{"gurmukhi":"ਤਿਨ ਤੇ ਬਹੁ ਉਪਜਿਤ ਰਨ ਭਏ। ਮਹਾ ਕਾਲ ਕੇ ਸਾਮੁਹਿ ਸਿਧਏ। ੨੯੩।","roman":"Tin te bahu upjit ran bhae | mahaa kaal ke saamuhi sidhae | 293 |","meaning_en":"From them many more came to be in the battle and went before Mahakal. 293.","page":2517,"meaning_status":"draft"}]},{"type":"verse","number":[294],"number_text":"੨੯੪।","page":2517,"lines":[{"gurmukhi":"ਜੇਤਿਕ ਧਏ ਤਿਤਕ ਕਲਿ ਮਾਰੇ। ਰਥੀ ਗਜੀ ਤਿਲ ਤਿਲ ਕਰਿ ਡਾਰੇ।","roman":"Jetik dhae titak kali maare | rathee gajee til til kari daare |","meaning_en":"As many as ran, Kal killed that many; he cut charioteers and elephant-riders bit by bit.","page":2517,"meaning_status":"draft"},{"gurmukhi":"ਤਿਨਤੇ ਉਪਜਿ ਠਾਢ ਭੇ ਘਨੇ। ਰਥੀ ਗਜੀ ਬਾਜੀ ਸੁਭ ਬਨੇ। ੨੯੪।","roman":"Tinte upji thaadh bhe ghane | rathee gajee baajee subh bane | 294 |","meaning_en":"From them many arose and stood, fine charioteers, elephant-riders and horsemen. 294.","page":2517,"meaning_status":"draft"}]},{"type":"verse","number":[295],"number_text":"੨੯੫।","page":2517,"lines":[{"gurmukhi":"ਬਹੁਰਿ ਕਾਲ ਕਰਿ ਕੋਪ ਪ੍ਰਹਾਰੇ। ਦੈਤ ਅਨਿਕ ਮ੍ਰਿਤੁ ਲੋਕ ਪਧਾਰੇ।","roman":"Bahuri kaal kari kop prahaare | dait anik mritu lok padhaare |","meaning_en":"Then Kal in rage struck again, and many demons went to the world of death.","page":2517,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਕਾਲ ਬਹੁਰੌ ਧਨੁ ਧਰਾ। ਸੌ ਸੌ ਬਾਨ ਏਕ ਇਕ ਹਰਾ। ੨੯੫।","roman":"Mahaa kaal bahurau dhanu dharaa | sau sau baan ek ik haraa | 295 |","meaning_en":"Mahakal again took his bow; with each arrow he took a hundred. 295.","page":2517,"meaning_status":"draft"}]},{"type":"verse","number":[296],"number_text":"੨੯੬।","page":2517,"lines":[{"gurmukhi":"ਸੌ ਸੌ ਏਕ ਏਕ ਸਰ ਮਾਰਾ। ਸੌ ਸੌ ਗਿਰੀ ਸ੍ਰੋਨ ਕੀ ਧਾਰਾ।","roman":"Sau sau ek ek sar maaraa | sau sau giree sron kee dhaaraa |","meaning_en":"With each shot he struck a hundred; a hundred streams of blood fell.","page":2517,"meaning_status":"draft"},{"gurmukhi":"ਸਤ ਸਤ ਅਸੁਰ ਉਪਜਿ ਭੇ ਠਾਢੇ। ਅਸੀ ਗਜੀ ਕੌਚੀ ਬਲ ਗਾਢੇ। ੨੯੬।","roman":"Sat sat asur upji bhe thaadhe | asee gajee kauchee bal gaadhe | 296 |","meaning_en":"Seven by seven demons arose and stood, strong in elephants, in armour and in strength. 296.","page":2517,"meaning_status":"draft","note":"ਅਸੀ ਗਜੀ ਕੌਚੀ: obscure; uncertain."}]},{"type":"verse","number":[297],"number_text":"੨੯੭।","page":2517,"lines":[{"gurmukhi":"ਰੂਪ ਹਜਾਰ ਹਜਾਰ ਧਾਰਿ ਕਲਿ। ਗਰਜਤ ਭਯੋ ਅਤੁਲ ਕਰਿ ਕੈ ਬਲ।","roman":"Roop hajaar hajaar dhaari kali | garjat bhayo atul kari kai bal |","meaning_en":"Kal took a thousand and a thousand forms, and roared with incomparable strength.","page":2517,"meaning_status":"draft"},{"gurmukhi":"ਕਹ ਕਹ ਹਸਾ ਕਾਲ ਬਿਕਰਾਲਾ। ਕਾਢੇ ਦਾਤ ਤਜਤ ਮੁਖ ਜ੍ਵਾਲਾ। ੨੯੭।","roman":"Kah kah hasaa kaal bikraalaa | kaadhe daat tajat mukh jvaalaa | 297 |","meaning_en":"Terrible Kal laughed \"kah kah\"; baring his teeth he threw flames from his mouth. 297.","page":2517,"meaning_status":"draft"}]},{"type":"verse","number":[298],"number_text":"੨੯੮।","page":2519,"lines":[{"gurmukhi":"ਏਕ ਏਕ ਰਨ ਬਾਨ ਚਲਾਯੋ। ਸਹਸ ਸਹਸ ਦਾਨਵ ਕਹ ਘਾਯੋ।","roman":"Ek ek ran baan chalaayo | sahas sahas daanav kah ghaayo |","meaning_en":"In the battle he loosed one arrow at a time, and killed a thousand demons each.","page":2519,"meaning_status":"draft"},{"gurmukhi":"ਕੇਤਿਕ ਸੁਭਟ ਦਾੜ ਗਹਿ ਚਾਬੇ। ਕੇਤਿਕ ਸੁਭਟ ਪਾਵ ਤਰ ਦਾਬੇ। ੨੯੮।","roman":"Ketik subhat daar gahi chaabe | ketik subhat paav tar daabe | 298 |","meaning_en":"Some warriors he seized by the jaw and chewed; some he pressed under his foot. 298.","page":2519,"meaning_status":"draft"}]},{"type":"verse","number":[299],"number_text":"੨੯੯।","page":2519,"lines":[{"gurmukhi":"ਕੇਤਕ ਪਕਰਿ ਭਛ ਕਰਿ ਲਯੋ। ਤਿਨ ਤੇ ਏਕ ਨ ਉਪਜਤ ਭਯੋ।","roman":"Ketak pakri bhachh kari layo | tin te ek na upjat bhayo |","meaning_en":"Some he seized and ate; from them not one arose.","page":2519,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤਕਨ ਦ੍ਰਿਸਟਾਕਰਖਨ ਕੀਯੋ। ਸਭਹਿਨ ਕੋ ਸ੍ਰੋਨਿਤ ਹਰਿ ਲੀਯੋ। ੨੯੯।","roman":"Kitkan dristaakarkhan keeyo | sabhhin ko sronit hari leeyo | 299 |","meaning_en":"Some he drew by his gaze, and took the blood of them all. 299.","page":2519,"meaning_status":"draft","note":"ਦ੍ਰਿਸਟਾਕਰਖਨ: 'attraction by sight'; uncertain."}]},{"type":"verse","number":[300],"number_text":"੩੦੦।","page":2519,"lines":[{"gurmukhi":"ਸ੍ਰੋਨ ਰਹਿਤ ਦਾਨਵ ਜਬ ਭਯੋ। ਦੈਤ ਉਪਰਾਜਨ ਤੇ ਰਹਿ ਗਯੋ।","roman":"Sron rahit daanav jab bhayo | dait upraajan te rahi gayo |","meaning_en":"When the demons were without blood, they were unable to produce more demons.","page":2519,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਰਮਿਤ ਅਧਿਕ ਹ੍ਵੈ ਛਾਡਤ ਸ੍ਵਾਸਾ। ਤਾ ਤੇ ਕਰਤ ਦੈਤ ਪਰਗਾਸਾ। ੩੦੦।","roman":"Sramit adhik hvai chhaadat svaasaa | taa te karat dait pargaasaa | 300 |","meaning_en":"Greatly wearied, they breathed out breaths, and from them demons appeared again. 300.","page":2519,"meaning_status":"draft"}]},{"type":"verse","number":[301],"number_text":"੩੦੧।","page":2519,"lines":[{"gurmukhi":"ਪਵਨਾਕਰਖ ਕਰਾ ਤਬ ਕਾਲਾ। ਘਟੇ ਬਢਨ ਤੇ ਅਰਿ ਬਿਕਰਾਲਾ।","roman":"Pavnaakrakh karaa tab kaalaa | ghate badhan te ari bikraalaa |","meaning_en":"Then Kal drew out the breath; by the growth of the enemy's terrible strength was lessened.","page":2519,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਬਿਧਿ ਜਬ ਆਕਰਖਨ ਕੀਯਾ। ਸਭ ਬਲ ਹਰਿ ਅਸੁਰਨ ਕਾ ਲੀਯਾ। ੩੦੧।","roman":"Ih bidhi jab aakarkhan keeyaa | sabh bal hari asuran kaa leeyaa | 301 |","meaning_en":"When he made this drawing in, he took away all the strength of the demons. 301.","page":2519,"meaning_status":"draft"}]},{"type":"verse","number":[302],"number_text":"੩੦੨।","page":2519,"lines":[{"gurmukhi":"ਮਾਰਿ ਮਾਰਿ ਜੋ ਅਸੁਰ ਪੁਕਾਰਤ। ਤਿਹ ਤੇ ਅਮਿਤ ਦੈਤ ਤਨ ਧਾਰਤ।","roman":"Maari maari jo asur pukaarat | tih te amit dait tan dhaarat |","meaning_en":"The demons who cried \"kill, kill\", from them countless demons took form.","page":2519,"meaning_status":"draft"},{"gurmukhi":"ਬਾਚਾਕਰਖ ਕਾਲ ਤਬ ਕਯੋ। ਬੋਲਨ ਤੇ ਦਾਨਵ ਰਹਿ ਗਯੋ। ੩੦੨।","roman":"Baachaakrakh kaal tab kayo | bolan te daanav rahi gayo | 302 |","meaning_en":"Then Kal drew away their speech, and the demons were left without speaking. 302.","page":2519,"meaning_status":"draft"}]},{"type":"verse","number":[303],"number_text":"੩੦੩।","page":2519,"lines":[{"gurmukhi":"ਦਾਨਵ ਜਬ ਬੋਲਹਿ ਰਹਿ ਗਯੋ। ਚਿੰਤਾ ਕਰਤ ਚਿਤ ਮੋ ਭਯੋ।","roman":"Daanav jab bolhi rahi gayo | chintaa karat chit mo bhayo |","meaning_en":"When the demons were left without speech, they became anxious in their minds.","page":2519,"meaning_status":"draft"},{"gurmukhi":"ਤਾਹੀ ਤੇ ਦਾਨਵ ਬਹੁ ਭਏ। ਸਨਮੁਖ ਮਹਾ ਕਾਲ ਕੇ ਧਏ। ੩੦੩।","roman":"Taahee te daanav bahu bhae | sanmukh mahaa kaal ke dhae | 303 |","meaning_en":"From that many demons came, and ran against Mahakal. 303.","page":2519,"meaning_status":"draft"}]},{"type":"verse","number":[304],"number_text":"੩੦੪।","page":2519,"lines":[{"gurmukhi":"ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਕਰਿ ਕੋਪ ਪ੍ਰਹਾਰੇ। ਮਹਾਬੀਰ ਬਰਿਯਾਰ ਡਰਾਰੇ।","roman":"Sasatr asatr kari kop prahaare | mahaabeer bariyaar daraare |","meaning_en":"In rage they struck with missiles and weapons; great strong heroes struck terror.","page":2519,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਕਾਲ ਤਬ ਗੁਰਜ ਸੰਭਾਰੀ। ਬਹੁਤਨ ਕੀ ਮੇਧਾ ਕਢਿ ਡਾਰੀ। ੩੦੪।","roman":"Mahaa kaal tab guraj sanbhaaree | bahutan kee medhaa kadhi daaree | 304 |","meaning_en":"Then Mahakal took up his mace and knocked out the marrow of many. 304.","page":2519,"meaning_status":"draft"}]},{"type":"verse","number":[305],"number_text":"੩੦੫।","page":2519,"lines":[{"gurmukhi":"ਤਿਨ ਕੀ ਭੂਅ ਮੇਜਾ ਜੋ ਪਰੀ। ਤਾ ਤੇ ਸੈਨ ਦੇਹ ਬਹੁ ਧਰੀ।","roman":"Tin kee bhooa mejaa jo paree | taa te sain deh bahu dharee |","meaning_en":"The marrow that fell on the earth, from it an army took many bodies.","page":2519,"meaning_status":"draft"},{"gurmukhi":"ਮਾਰਿ ਮਾਰਿ ਕਰਿ ਕੋਪ ਅਪਾਰਾ। ਜਾਗਤ ਭਏ ਅਸੁਰ ਬਿਕਰਾਰਾ। ੩੦੫।","roman":"Maari maari kari kop apaaraa | jaagat bhae asur bikraaraa | 305 |","meaning_en":"In boundless rage, crying \"kill, kill\", fearful demons awoke. 305.","page":2519,"meaning_status":"draft"}]},{"type":"verse","number":[306],"number_text":"੩੦੬।","page":2519,"lines":[{"gurmukhi":"ਤਿਨ ਕੇ ਫੋਰਿ ਮੂੰਡਿ ਕਲਿ ਡਰੇ। ਤਾ ਤੇ ਮੇਧਾ ਜੋ ਭੂਅ ਪਰੇ।","roman":"Tin ke phori moondi kali dare | taa te medhaa jo bhooa pare |","meaning_en":"Kal split their heads and threw them down; the marrow that fell on the earth,","page":2519,"meaning_status":"draft"},{"gurmukhi":"ਮਾਰਿ ਮਾਰਿ ਕਹਿ ਅਸੁਰ ਜਗੇ ਰਨ। ਸੂਰਬੀਰ ਬਰਿਯਾਰ ਮਹਾਮਨ। ੩੦੬।","roman":"Maari maari kahi asur jage ran | soorbeer bariyaar mahaaman | 306 |","meaning_en":"from it demons awoke in the battle crying \"kill, kill\", brave, strong, great-minded warriors. 306.","page":2519,"meaning_status":"draft"}]},{"type":"verse","number":[307],"number_text":"੩੦੭।","page":2519,"lines":[{"gurmukhi":"ਪੁਨਿ ਕਰਿ ਕਾਲ ਗਦਾ ਰਿਸਿ ਧਰੀ। ਸਤ੍ਰੁ ਖੋਪਰੀ ਤਿਲ ਤਿਲ ਕਰੀ।","roman":"Puni kari kaal gadaa risi dharee | satru khopree til til karee |","meaning_en":"Then Kal took his mace in anger and made the enemies' skulls into bits.","page":2519,"meaning_status":"draft"},{"gurmukhi":"ਜੇਤੇ ਟੂਕ ਖੋਪ੍ਰਿਯਨ ਪਰੇ। ਤੇਤਿਕ ਰੂਪ ਦਾਨਵਨ ਧਰੇ। ੩੦੭।","roman":"Jete took khopriyan pare | tetik roop daanvan dhare | 307 |","meaning_en":"As many pieces as fell on the skulls, that many demon forms they took. 307.","page":2519,"meaning_status":"draft"}]},{"type":"verse","number":[308],"number_text":"੩੦੮।","page":2519,"lines":[{"gurmukhi":"ਕੇਤਿਕ ਗਦਾ ਪਾਨ ਗਹਿ ਧਾਏ। ਕੇਤਿਕ ਖੜਗ ਹਾਥ ਲੈ ਆਏ।","roman":"Ketik gadaa paan gahi dhaae | ketik kharag haath lai aae |","meaning_en":"Some ran taking maces in hand; some came with swords in hand.","page":2519,"meaning_status":"draft"},{"gurmukhi":"ਮਾਰਿ ਮਾਰਿ ਕੈ ਕੋਪਹਿ ਸਰਜੇ। ਮਾਨਹੁ ਮਹਾਕਾਲ ਘਨ ਗਰਜੇ। ੩੦੮।","roman":"Maari maari kai kophi sarje | maanhu mahaakaal ghan garje | 308 |","meaning_en":"Crying \"kill, kill\" they raged, as if the clouds of Mahakal roared. 308.","page":2519,"meaning_status":"draft"}]},{"type":"verse","number":[309],"number_text":"੩੦੯।","page":2519,"lines":[{"gurmukhi":"ਆਨਿ ਕਾਲ ਕਹ ਕਰਤ ਪ੍ਰਹਾਰਾ। ਇਕ ਇਕ ਸੂਰ ਸਹਸ ਹਥਿਯਾਰਾ।","roman":"Aani kaal kah karat prahaaraa | ik ik soor sahas hathiyaaraa |","meaning_en":"They came and struck Kal; each hero had a thousand weapons.","page":2519,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਕਾਲ ਕਹ ਲਗਤ ਨ ਭਏ। ਤਾ ਮਹਿ ਸਭੈ ਲੀਨ ਹ੍ਵੈ ਗਏ। ੩੦੯।","roman":"Mahaa kaal kah lagat na bhae | taa mahi sabhai leen hvai gae | 309 |","meaning_en":"They did not strike Mahakal; all merged into him. 309.","page":2519,"meaning_status":"draft"}]},{"type":"verse","number":[310],"number_text":"੩੧੦।","page":2519,"lines":[{"gurmukhi":"ਸਸਤ੍ਰ ਲੀਨ ਲਖਿ ਅਸੁਰ ਰਿਸਾਨੇ। ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਲੈ ਕੋਪਿ ਸਿਧਾਨੇ।","roman":"Sasatr leen lakhi asur risaane | sasatr asatr lai kopi sidhaane |","meaning_en":"Seeing the weapons absorbed, the demons were enraged; taking missiles and weapons they went in anger.","page":2519,"meaning_status":"draft"},{"gurmukhi":"ਅਮਿਤ ਕੋਪ ਕਰਿ ਸਸਤ੍ਰ ਪ੍ਰਹਾਰਤ। ਮਾਰਿ ਮਾਰਿ ਦਿਸਿ ਦਸੌ ਪੁਕਾਰਤ। ੩੧੦।","roman":"Amit kop kari sasatr prahaarat | maari maari disi dasau pukaarat | 310 |","meaning_en":"In boundless rage they struck with weapons and cried \"kill, kill\" in all ten directions. 310.","page":2519,"meaning_status":"draft"}]},{"type":"verse","number":[311],"number_text":"੩੧੧।","page":2521,"lines":[{"gurmukhi":"ਮਾਰਿ ਮਾਰਿ ਕੀ ਸੁਨਿ ਧੁਨਿ ਕਾਨਾ। ਕੋਪਾ ਕਾਲ ਸਸਤ੍ਰ ਗਹਿ ਨਾਨਾ।","roman":"Maari maari kee suni dhuni kaanaa | kopaa kaal sasatr gahi naanaa |","meaning_en":"Hearing the sound \"kill, kill\" in his ears, Kal grew angry and took many weapons.","page":2521,"meaning_status":"draft"},{"gurmukhi":"ਹਾਕਿ ਹਾਕਿ ਹਥਿਯਾਰ ਪ੍ਰਹਾਰੇ। ਦਸਟ ਅਨਿਕ ਪਲ ਬੀਚ ਸੰਘਾਰੇ। ੩੧੧।","roman":"Haaki haaki hathiyaar prahaare | dasat anik pal beech sanghaare | 311 |","meaning_en":"Shouting, he struck with weapons, and in a moment killed many wicked ones. 311.","page":2521,"meaning_status":"draft"}]},{"type":"verse","number":[312],"number_text":"੩੧੨।","page":2521,"lines":[{"gurmukhi":"ਤਿਨ ਤੇ ਮੇਦ ਮਾਸ ਜੋ ਪਰੋ। ਤਾ ਤੇ ਬਹੁ ਅਸੁਰਨ ਤਨ ਧਰੋ।","roman":"Tin te med maas jo paro | taa te bahu asuran tan dharo |","meaning_en":"The marrow and flesh that fell from them, from it many demons took bodies.","page":2521,"meaning_status":"draft"},{"gurmukhi":"ਮਾਰਿ ਮਾਰਿ ਕਹਿ ਸਮੁਹਿ ਸਿਧਾਏ। ਬਾਧੇ ਚੁੰਗ ਚੌਪਿ ਤਨ ਆਏ। ੩੧੨।","roman":"Maari maari kahi samuhi sidhaae | baadhe chung chaupi tan aae | 312 |","meaning_en":"Crying \"kill, kill\" they came before him, with hair-knots tied, pressing on. 312.","page":2521,"meaning_status":"draft"}]},{"type":"verse","number":[313],"number_text":"੩੧੩।","page":2521,"lines":[{"gurmukhi":"ਇਕ ਇਕ ਟੂਕ ਸਹਸ ਕਰਿ ਡਾਰੇ। ਤਿਨ ਤੇ ਭਏ ਅਸੁਰ ਰਨ ਭਾਰੇ।","roman":"Ik ik took sahas kari daare | tin te bhae asur ran bhaare |","meaning_en":"He cut each one into a thousand pieces; from them heavy demons arose in the battle.","page":2521,"meaning_status":"draft"},{"gurmukhi":"ਤਿਨ ਕੇ ਟੂਕ ਟੂਕ ਕਰਿ ਲਛਨ। ਗੀਧ ਪਿਸਾਚ ਗਏ ਕਰਿ ਭਛਨ। ੩੧੩।","roman":"Tin ke took took kari lachhan | geedh pisaach gae kari bhachhan | 313 |","meaning_en":"Making their bodies into pieces by the hundred thousand, vultures and ghouls went to eat. 313.","page":2521,"meaning_status":"draft"}]},{"type":"verse","number":[314],"number_text":"੩੧੪।","page":2521,"lines":[{"gurmukhi":"ਤੇ ਭੀ ਅਮਿਤ ਰੂਪ ਕਰਿ ਧਾਏ। ਜੇ ਤਿਲ ਤਿਲ ਕਰਿ ਸੁਭਟ ਗਿਰਾਏ।","roman":"Te bhee amit roop kari dhaae | je til til kari subhat giraae |","meaning_en":"Those also took countless forms and ran, those whom he had felled bit by bit.","page":2521,"meaning_status":"draft"},{"gurmukhi":"ਤਿਨ ਕੀ ਕਰੀ ਨਾਸ ਸਭ ਸੈਨਾ। ਮਹਾ ਕਾਲ ਕਰ ਰੰਚਕ ਭੈ ਨਾ। ੩੧੪।","roman":"Tin kee karee naas sabh sainaa | mahaa kaal kar ranchak bhai naa | 314 |","meaning_en":"He destroyed all their army; Mahakal had not even a little fear. 314.","page":2521,"meaning_status":"draft"}]},{"type":"verse","number":[315],"number_text":"੩੧੫।","page":2521,"lines":[{"gurmukhi":"ਮਾਰਿ ਮਾਰਿ ਜੋਧਾ ਕਹੂੰ ਗਾਜਹਿ। ਜੰਬੁਕ ਗੀਧ ਮਾਸ ਲੈ ਭਾਜਹਿ।","roman":"Maari maari jodhaa kahoon gaajhi | janbuk geedh maas lai bhaajhi |","meaning_en":"In places warriors roared \"kill, kill\"; jackals and vultures ran off with flesh.","page":2521,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰੇਤ ਪਿਸਾਚ ਕਹੂੰ ਕਿਲਕਾਰਹਿ। ਡਾਕਨਿ ਝਾਕਿ ਕਿਲਕਟੀ ਮਾਰਹਿ। ੩੧੫।","roman":"Pret pisaach kahoon kilkaarhi | daakni jhaaki kilaktee maarhi | 315 |","meaning_en":"Ghosts and goblins shrieked in places; dakinis peered and screamed. 315.","page":2521,"meaning_status":"draft"}]},{"type":"verse","number":[316],"number_text":"੩੧੬।","page":2521,"lines":[{"gurmukhi":"ਕੋਕਿਲ ਕਾਕ ਜਹਾ ਕਿਲਕਾਰਹਿ। ਸ੍ਰੋਨਤ ਕੇ ਕੇਸਰ ਘਸਿ ਡਾਰਹਿ।","roman":"Kokil kaak jahaa kilkaarhi | sronat ke kesar ghasi daarhi |","meaning_en":"Where the cuckoo and crow screeched, they rubbed saffron of blood.","page":2521,"meaning_status":"draft","note":"Obscure; uncertain."},{"gurmukhi":"ਜਾਨੁਕ ਢੋਲ ਬਡੇ ਡਫ ਸੋਹੈ। ਦੇਵ ਦੈਤ ਦਾਨਵ ਮਨ ਮੋਹੈ। ੩੧੬।","roman":"Jaanuk dhol bade daph sohai | dev dait daanav man mohai | 316 |","meaning_en":"Big drums shone like tambourines, charming the minds of gods, demons and monsters. 316.","page":2521,"meaning_status":"draft"}]},{"type":"verse","number":[317],"number_text":"੩੧੭।","page":2521,"lines":[{"gurmukhi":"ਬਾਨ ਜਾਨ ਕੁੰਕਮਾ ਪ੍ਰਹਾਰੇ। ਮੂਠਿ ਗੁਲਾਲਨ ਬਰਛਾ ਭਾਰੇ।","roman":"Baan jaan kunkmaa prahaare | moothi gulaalan barchhaa bhaare |","meaning_en":"They struck arrows like saffron and handfuls of gulal, with heavy lances.","page":2521,"meaning_status":"draft","note":"ਕੁੰਕਮਾ ਅਰ ਗੁਲਾਲ: saffron and red powder, used at Holi; uncertain."},{"gurmukhi":"ਢਾਲ ਮਨੋ ਡਫਮਾਲਾ ਬਨੀ। ਪਿਚਕਾਰਿਯੈ ਤੁਫੰਗੈ ਘਨੀ। ੩੧੭।","roman":"Dhaal mano daphmaalaa banee | pichkaariyai tuphangai ghanee | 317 |","meaning_en":"Shields were like a row of tambourines; squirts and guns in numbers. 317.","page":2521,"meaning_status":"draft","note":"ਪਿਚਕਾਰਿਯੈ: syringes/squirts used at Holi."}]},{"type":"verse","number":[318],"number_text":"੩੧੮।","page":2521,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਭਯੋ ਘੋਰ ਸੰਗ੍ਰਾਮਾ। ਕਾਪਾ ਇੰਦ੍ਰ ਚੰਦ੍ਰ ਕੋ ਧਾਮਾ।","roman":"Ih bidhi bhayo ghor sangraamaa | kaapaa indr chandr ko dhaamaa |","meaning_en":"Thus a dreadful battle took place; the abodes of Indra and the moon trembled.","page":2521,"meaning_status":"draft"},{"gurmukhi":"ਪਸੁ ਪੰਛੀ ਅਤਿ ਹੀ ਅਕੁਲਾਏ। ਛੋਡਿ ਧਾਮ ਕਾਨਨਹਿ ਸਿਧਾਏ। ੩੧੮।","roman":"Pasu panchhee ati hee akulaae | chhodi dhaam kaananhi sidhaae | 318 |","meaning_en":"Animals and birds were greatly troubled; leaving their homes they went to the forest. 318.","page":2521,"meaning_status":"draft"}]},{"type":"verse","number":[319],"number_text":"੩੧੯।","page":2521,"lines":[{"gurmukhi":"ਬਾਜੀ ਕਹੂੰ ਘਾਇਲ ਭਭਕਾਵਤ। ਉਠਿ ਉਠਿ ਸੁਭਟ ਸਮੁਹ ਕਹ ਧਾਵਤ।","roman":"Baajee kahoon ghaail bhabhkaavat | uthi uthi subhat samuh kah dhaavat |","meaning_en":"In places wounded horses neighed; warriors rose and ran forward.","page":2521,"meaning_status":"draft"},{"gurmukhi":"ਕਹਕਹਾਟ ਕਹੂੰ ਕਾਲ ਸੁਨਾਵੈ। ਭੀਖਨ ਸੁਨੇ ਨਾਮ ਭੈ ਆਵੈ। ੩੧੯।","roman":"Kahakhaat kahoon kaal sunaavai | bheekhan sune naam bhai aavai | 319 |","meaning_en":"In places Kal gave out laughter; hearing the dreadful name, fear came. 319.","page":2521,"meaning_status":"draft"}]},{"type":"verse","number":[320],"number_text":"੩੨੦।","page":2521,"lines":[{"gurmukhi":"ਸੂਰਨ ਕੇ ਲੋਮਾ ਭੇ ਖਰੇ। ਕਾਤਰ ਨਿਰਖਿ ਧਾਮ ਰਨ ਬਰੇ।","roman":"Sooran ke lomaa bhe khare | kaatar nirkhi dhaam ran bare |","meaning_en":"The hair of the heroes stood on end; cowards seeing the field went to their homes.","page":2521,"meaning_status":"draft"},{"gurmukhi":"ਸੋਫੀ ਸੂਮ ਭਏ ਬਹੁ ਬ੍ਯਾਕੁਲ। ਦਸੋ ਦਿਸਨ ਭਜਿ ਚਲੇ ਡਰਾਕੁਲ। ੩੨੦।","roman":"Sophee soom bhae bahu byaakul | daso disan bhaji chale daraakul | 320 |","meaning_en":"The abstemious became miserly and very anxious; they fled in the ten directions, terrified. 320.","page":2521,"meaning_status":"draft","note":"ਸੋਫੀ: 'sufi'; read as 'abstemious'; uncertain."}]},{"type":"verse","number":[321],"number_text":"੩੨੧।","page":2521,"lines":[{"gurmukhi":"ਕੇਤਿਕ ਸੁਭਟ ਪਾਵ ਤੇ ਰੋਪੈ। ਲੈ ਲੈ ਖੜਗ ਨਗਨ ਕਰਿ ਧੋਪੈ।","roman":"Ketik subhat paav te ropai | lai lai kharag nagan kari dhopai |","meaning_en":"Some warriors planted their feet; taking swords they struck with naked blades.","page":2521,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਕਾਲ ਕੁਪਿ ਸਸਤ੍ਰ ਪ੍ਰਹਾਰੈ। ਸਾਧ ਉਬਾਰਿ ਦੁਸਟ ਸਭ ਮਾਰੇ। ੩੨੧।","roman":"Mahaa kaal kupi sasatr prahaarai | saadh ubaari dusat sabh maare | 321 |","meaning_en":"Mahakal in rage struck with weapons; he rescued the saints and killed all the wicked. 321.","page":2521,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਛੰਦ","roman":"Bhujang chhand","meaning_en":"Bhujang metre.","page":2521,"meaning_status":"draft"},{"type":"verse","number":[322],"number_text":"੩੨੨।","page":2521,"lines":[{"gurmukhi":"ਮਚੇ ਆਨਿ ਮੈਦਾਨ ਮੈ ਬੀਰ ਭਾਰੇ। ਦਿਖੈ ਕੌਨ ਜੀਤੈ ਦਿਖੈ ਕੌਨ ਹਾਰੇ।","roman":"Mache aani maidaan mai beer bhaare | dikhai kaun jeetai dikhai kaun haare |","meaning_en":"Great warriors engaged on the field; who will see who wins and who loses?","page":2521,"meaning_status":"draft"},{"gurmukhi":"ਲਏ ਸੂਲ ਔ ਸੇਲ ਕਾਤੀ ਕਟਾਰੀ। ਚਹੂੰ ਓਰ ਗਾਜੇ ਹਠੀ ਬੀਰ ਭਾਰੀ। ੩੨੨।","roman":"Lae sool au sel kaatee kataaree | chahoon or gaaje hathee beer bhaaree | 322 |","meaning_en":"They took spears, lances, knives and daggers; the obstinate great warriors roared on all four sides. 322.","page":2521,"meaning_status":"draft"}]},{"type":"verse","number":[323],"number_text":"੩੨੩।","page":2523,"lines":[{"gurmukhi":"ਬਜੇ ਘੋਰ ਸੰਗ੍ਰਾਮ ਮੋ ਘੋਰ ਬਾਜੇ। ਚਹੂੰ ਓਰ ਬਾਕੇ ਰਥੀ ਬੀਰ ਗਾਜੇ।","roman":"Baje ghor sangraam mo ghor baaje | chahoon or baake rathee beer gaaje |","meaning_en":"Terrible instruments sounded in the terrible battle; fine charioteers roared on all four sides.","page":2523,"meaning_status":"draft"},{"gurmukhi":"ਲਏ ਸੂਲ ਔ ਸੇਲ ਕਾਤੀ ਕਟਾਰੇ। ਮਚੇ ਕੋਪ ਕੈ ਕੈ ਹਠੀਲੇ ਰਜ੍ਯਾਰੇ। ੩੨੩।","roman":"Lae sool au sel kaatee kataare | mache kop kai kai hatheele rajyaare | 323 |","meaning_en":"Taking spears, lances, knives and daggers, the stubborn, resolute ones set to in rage. 323.","page":2523,"meaning_status":"draft"}]},{"type":"verse","number":[324],"number_text":"੩੨੪।","page":2523,"lines":[{"gurmukhi":"ਕਹੂੰ ਧੂਲਧਾਨੀ ਛੁਟੈ ਫੀਲ ਨਾਲੈ। ਕਹੂੰ ਬਾਜ ਨਾਲੈ ਮਹਾ ਘੋਰ ਜ੍ਵਾਲੈ।","roman":"Kahoon dhooldhaanee chhutai pheel naalai | kahoon baaj naalai mahaa ghor jvaalai |","meaning_en":"In places the dust-holders loosed from elephants' guns; in places horse-guns with fearful flames.","page":2523,"meaning_status":"draft","note":"ਧੂਲਧਾਨੀ: obscure; ਫੀਲ ਨਾਲੈ: elephant-mounted guns; ਬਾਜ ਨਾਲੈ: guns on horses; uncertain."},{"gurmukhi":"ਕਹੂੰ ਸੰਖ ਭੇਰੀ ਪ੍ਰਣੋ ਢੋਲ ਬਾਜੈ। ਕਹੂੰ ਸੂਰ ਠੋਕੈ ਭੁਜਾ ਭੂਪ ਗਾਜੈ। ੩੨੪।","roman":"Kahoon sankh bheree prano dhol baajai | kahoon soor thokai bhujaa bhoop gaajai | 324 |","meaning_en":"In places conches, drums, pano and drum sounded; in places heroes slapped their arms and kings roared. 324.","page":2523,"meaning_status":"draft"}]},{"type":"verse","number":[325],"number_text":"੩੨੫।","page":2523,"lines":[{"gurmukhi":"ਕਹੂੰ ਘੋਰ ਬਾਦਿਤ੍ਰ ਬਾਜੈ ਨਗਾਰੇ। ਕਹੂੰ ਬੀਰ ਬਾਜੀ ਗਿਰੇ ਖੇਤ ਮਾਰੇ।","roman":"Kahoon ghor baaditr baajai nagaare | kahoon beer baajee gire khet maare |","meaning_en":"In places dreadful instruments, kettledrums sounded; in places warriors and horses fell, killed on the field.","page":2523,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਖੇਤ ਨਾਚੈ ਪਠੇ ਪਖਰਾਰੇ। ਕਹੂੰ ਸੂਰ ਸੰਗ੍ਰਾਮ ਸੋਹੈ ਡਰਾਰੇ। ੩੨੫।","roman":"Kahoon khet naachai pathe pakhraare | kahoon soor sangraam sohai daraare | 325 |","meaning_en":"In places armoured horses danced on the field; in places heroes shone in the battle, terrifying. 325.","page":2523,"meaning_status":"draft"}]},{"type":"verse","number":[326],"number_text":"੩੨੬।","page":2523,"lines":[{"gurmukhi":"ਕਹੂ ਬਾਜ ਮਾਰੇ ਕਹੂੰ ਝੂਮ ਹਾਥੀ। ਕਹੂੰ ਫੈਟ ਭਾਥੀ ਜੁਝੇ ਬਾਧਿ ਸਾਥੀ।","roman":"Kahoo baaj maare kahoon jhoom haathee | kahoon phait bhaathee jujhe baadhi saathee |","meaning_en":"In places horses were killed, in places elephants swayed; in places sash-fastened companions fought together.","page":2523,"meaning_status":"draft","note":"ਫੈਟ ਭਾਥੀ: obscure (sashes and quivers?); uncertain."},{"gurmukhi":"ਕਹੂੰ ਗਰਜਿ ਠੋਕੈ ਭੁਜਾ ਭੂਪ ਭਾਰੇ। ਬਮੈ ਸ੍ਰੋਨ ਕੇਤੇ ਗਿਰੇ ਖੇਤ ਮਾਰੇ। ੩੨੬।","roman":"Kahoon garji thokai bhujaa bhoop bhaare | bamai sron kete gire khet maare | 326 |","meaning_en":"In places great kings roared and slapped their arms; many bleeding fell, killed on the field. 326.","page":2523,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2523,"meaning_status":"draft"},{"type":"verse","number":[327],"number_text":"੩੨੭।","page":2523,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਅਸੁਰ ਜਬੈ ਚੁਨਿ ਮਾਰੇ। ਅਮਿਤ ਰੋਸ ਕਰਿ ਔਰ ਸਿਧਾਰੇ।","roman":"Ih bidhi asur jabai chuni maare | amit ros kari aur sidhaare |","meaning_en":"When the demons had been picked off in this way, others came on with boundless rage.","page":2523,"meaning_status":"draft"},{"gurmukhi":"ਬਾਧੇ ਫੈਟ ਬਿਰਾਜੈ ਭਾਥੀ। ਆਗੇ ਚਲੇ ਅਮਿਤ ਧਰਿ ਹਾਥੀ। ੩੨੭।","roman":"Baadhe phait biraajai bhaathee | aage chale amit dhari haathee | 327 |","meaning_en":"Sashes tied, quivers shining, countless elephants moved forward. 327.","page":2523,"meaning_status":"draft"}]},{"type":"verse","number":[328],"number_text":"੩੨੮।","page":2523,"lines":[{"gurmukhi":"ਸਾਥ ਲਏ ਅਨਗਨ ਪਖਰਾਰੇ। ਉਮਡਿ ਚਲੇ ਦੈ ਢੋਲ ਨਗਾਰੇ।","roman":"Saath lae angan pakhraare | umdi chale dai dhol nagaare |","meaning_en":"They took countless armoured horses with them; they surged up beating drums and kettledrums.","page":2523,"meaning_status":"draft"},{"gurmukhi":"ਸੰਖ ਝਾਂਝ ਅਰੁ ਢੋਲ ਬਜਾਇ। ਚਮਕਿ ਚਲੇ ਚੌਗੁਨ ਕਰਿ ਚਾਇ। ੩੨੮।","roman":"Sankh jhaanjh aru dhol bajaai | chamki chale chaugun kari chaai | 328 |","meaning_en":"Playing conches, cymbals and drums, they went flashing with fourfold zeal. 328.","page":2523,"meaning_status":"draft"}]},{"type":"verse","number":[329],"number_text":"੩੨੯।","page":2523,"lines":[{"gurmukhi":"ਡਵਰੂ ਕਹੂੰ ਗੁੜਗੁੜੀ ਬਾਜੈ। ਠੋਕਿ ਭੁਜਾ ਰਨ ਮੋ ਭਟ ਗਾਜੈ।","roman":"Davroo kahoon gurguree baajai | thoki bhujaa ran mo bhat gaajai |","meaning_en":"In places damrus and gudgudis sounded; slapping arms, warriors roared in the battle.","page":2523,"meaning_status":"draft"},{"gurmukhi":"ਮੁਰਜ ਉਪੰਗ ਮੁਰਲਿਯੈ ਘਨੀ। ਭੇਰ ਝਾਂਜ ਬਾਜੈ ਰੁਨਝੁਨੀ। ੩੨੯।","roman":"Muraj upang murliyai ghanee | bher jhaanj baajai runjhunee | 329 |","meaning_en":"Murajs, upangs and many flutes; drums and cymbals sounded \"runjhun\". 329.","page":2523,"meaning_status":"draft"}]},{"type":"verse","number":[330],"number_text":"੩੩੦।","page":2523,"lines":[{"gurmukhi":"ਕਹੀ ਤੂੰਬਰੇ ਬਜੈ ਅਪਾਰਾ। ਬੇਨ ਬਾਸੁਰੀ ਕਹੂੰ ਹਜਾਰਾ।","roman":"Kahee toonbre bajai apaaraa | ben baasuree kahoon hajaaraa |","meaning_en":"In places countless tumburs sounded; in places thousands of flutes and pipes.","page":2523,"meaning_status":"draft"},{"gurmukhi":"ਸੁਤਰੀ ਫੀਲ ਨਗਾਰੇ ਘਨੇ। ਅਮਿਤ ਕਾਨ੍ਹਰੇ ਜਾਤ ਨ ਗਨੇ। ੩੩੦।","roman":"Sutree pheel nagaare ghane | amit kaanhare jaat na gane | 330 |","meaning_en":"Sutris, elephant-drums and many kettledrums; countless kanhars, beyond counting. 330.","page":2523,"meaning_status":"draft","note":"Instrument names as printed."}]},{"type":"verse","number":[331],"number_text":"੩੩੧।","page":2523,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਭਯੋ ਜਬੈ ਸੰਗ੍ਰਾਮਾ। ਨਿਕਸੀ ਦਿਨ ਦੂਲਹ ਹ੍ਵੈ ਬਾਮਾ।","roman":"Ih bidhi bhayo jabai sangraamaa | niksee din doolah hvai baamaa |","meaning_en":"When the battle took place in this way, a woman came out, the bride of the day.","page":2523,"meaning_status":"draft","note":"ਦਿਨ ਦੂਲਹ ਹ੍ਵੈ ਬਾਮਾ: 'the woman, bride of the day'; uncertain."},{"gurmukhi":"ਸਿੰਘ ਬਾਹਨੀ ਧੁਜਾ ਬਿਰਾਜੈ। ਜਾਹਿ ਬਿਲੋਕ ਦੈਤ ਦਲ ਭਾਜੈ। ੩੩੧।","roman":"Singh baahnee dhujaa biraajai | jaahi bilok dait dal bhaajai | 331 |","meaning_en":"Her banner of the lion-rider shone, seeing which the demon army fled. 331.","page":2523,"meaning_status":"draft"}]},{"type":"verse","number":[332],"number_text":"੩੩੨।","page":2523,"lines":[{"gurmukhi":"ਆਵਤ ਹੀ ਬਹੁ ਅਸੁਰ ਸੰਘਾਰੇ। ਤਿਲ ਤਿਲ ਪ੍ਰਾਇ ਰਥੀ ਕਰਿ ਡਾਰੇ।","roman":"Aavat hee bahu asur sanghaare | til til praai rathee kari daare |","meaning_en":"On arriving she killed many demons; she cut charioteers bit by bit.","page":2523,"meaning_status":"draft"},{"gurmukhi":"ਕਾਟਿ ਦਈ ਕੇਤਿਨ ਕੀ ਧੁਜਾ। ਜੰਘਾ ਪਾਵ ਸੀਸ ਅਰੁ ਭੁਜਾ। ੩੩੨।","roman":"Kaati daee ketin kee dhujaa | janghaa paav sees aru bhujaa | 332 |","meaning_en":"She cut down the banners of many, with thighs, feet, heads and arms. 332.","page":2523,"meaning_status":"draft"}]},{"type":"verse","number":[333],"number_text":"੩੩੩।","page":2523,"lines":[{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਤਨ ਸੁਭਟ ਪ੍ਰਹਾਰੇ। ਟੂਕ ਟੂਕ ਕਰਿ ਪ੍ਰਿਥੀ ਪਛਾਰੇ।","roman":"Bhaati bhaati tan subhat prahaare | took took kari prithee pachhaare |","meaning_en":"She struck warriors in many ways; she cut them into pieces and threw them on the earth.","page":2523,"meaning_status":"draft"},{"gurmukhi":"ਕੇਸਨ ਤੇ ਗਹਿ ਕਿਤਨ ਪਛਾਰਾ। ਸਤ੍ਰੁ ਸੈਨ ਤਿਲ ਤਿਲ ਕਰਿ ਡਾਰਾ। ੩੩੩।","roman":"Kesan te gahi kitan pachhaaraa | satru sain til til kari daaraa | 333 |","meaning_en":"Some she seized by the hair and threw down; she cut up the enemy army, bit by bit. 333.","page":2523,"meaning_status":"draft"}]},{"type":"verse","number":[334],"number_text":"੩੩੪।","page":2525,"lines":[{"gurmukhi":"ਝਮਕਤ ਕਹੀ ਅਸਿਨ ਕੀ ਧਾਰਾ। ਭਭਕਤ ਰੁੰਡ ਮੁੰਡ ਬਿਕਰਾਰਾ।","roman":"Jhamkat kahee asin kee dhaaraa | bhabhkat rund mund bikraaraa |","meaning_en":"In places the edges of swords flashed; trunks and heads gurgled terribly.","page":2525,"meaning_status":"draft"},{"gurmukhi":"ਕੇਤਿਕ ਗਰਜਿ ਸਸਤ੍ਰ ਕਟਿ ਸਜਹੀ। ਅਸਤ੍ਰ ਛੋਰਿ ਕੇਤੇ ਭਟ ਭਜਹੀ। ੩੩੪।","roman":"Ketik garji sasatr kati sajhee | asatr chhori kete bhat bhajhee | 334 |","meaning_en":"Some roared and fixed weapons at the waist; some warriors left their weapons and fled. 334.","page":2525,"meaning_status":"draft"}]},{"type":"verse","number":[335],"number_text":"੩੩੫।","page":2525,"lines":[{"gurmukhi":"ਮਾਰੇ ਪਰੇ ਪ੍ਰਿਥੀ ਪਰ ਕੇਤੇ। ਮਹਾ ਬੀਰ ਬਿਕਰਾਰ ਬਿਚੇਤੇ।","roman":"Maare pare prithee par kete | mahaa beer bikraar bichete |","meaning_en":"Many lay killed on the earth, great terrible warriors unconscious.","page":2525,"meaning_status":"draft"},{"gurmukhi":"ਝਿਮਿ ਝਿਮਿ ਗਿਰੈ ਸ੍ਰੋਨ ਜਿਮਿ ਝਰਨਾ। ਭਯੋ ਘੋਰ ਰਨ ਜਾਤ ਨ ਬਰਨਾ। ੩੩੫।","roman":"Jhimi jhimi girai sron jimi jharnaa | bhayo ghor ran jaat na barnaa | 335 |","meaning_en":"Blood fell \"jhim jhim\" like a stream; a dreadful battle arose that cannot be told. 335.","page":2525,"meaning_status":"draft"}]},{"type":"verse","number":[336],"number_text":"੩੩੬।","page":2525,"lines":[{"gurmukhi":"ਅਚਿ ਅਚਿ ਰੁਧਰ ਡਾਕਨੀ ਡਹਕੈ। ਭਖਿ ਭਖਿ ਮਾਸ ਕਾਕ ਕਹੂੰ ਕਹਕੈ।","roman":"Achi achi rudhar daaknee dahkai | bhakhi bhakhi maas kaak kahoon kahkai |","meaning_en":"Dakinis drank blood again and again, and shrieked; crows cawed in places, eating flesh.","page":2525,"meaning_status":"draft"},{"gurmukhi":"ਦਾਰੁਨ ਹੋਤ ਭਯੋ ਤਹ ਜੁਧਾ। ਹਮਰੇ ਬੀਚ ਨ ਆਵਤ ਬੁਧਾ। ੩੩੬।","roman":"Daarun hot bhayo tah judhaa | hamre beech na aavat budhaa | 336 |","meaning_en":"A dreadful fight took place there; wisdom did not come between us. 336.","page":2525,"meaning_status":"draft","note":"ਹਮਰੇ ਬੀਚ ਨ ਆਵਤ ਬੁਧਾ: 'wisdom does not come between us'; uncertain."}]},{"type":"verse","number":[337],"number_text":"੩੩੭।","page":2525,"lines":[{"gurmukhi":"ਮਾਰੇ ਪਰੇ ਦੈਤ ਕਹੀ ਭਾਰੇ। ਗਿਰੇ ਕਾਢਿ ਕਰਿ ਦਾਤ ਡਰਾਰੇ।","roman":"Maare pare dait kahee bhaare | gire kaadhi kari daat daraare |","meaning_en":"Many demons lay killed; fallen, they bared their teeth, terrifying.","page":2525,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਰੋਨਤ ਬਮਤ ਬਦਨ ਤੇ ਏਕਾ। ਬੀਰ ਖੇਤ ਬਲਵਾਨ ਅਨੇਕਾ। ੩੩੭।","roman":"Sronat bamat badan te ekaa | beer khet balvaan anekaa | 337 |","meaning_en":"Many strong warriors on the field vomited blood from their mouths. 337.","page":2525,"meaning_status":"draft"}]},{"type":"verse","number":[338],"number_text":"੩੩੮।","page":2525,"lines":[{"gurmukhi":"ਬਡੇ ਬਡੇ ਜਿਨ ਕੇ ਸਿਰ ਸੀਗਾ। ਚੋਂਚੈ ਬਡੀ ਭਾਤਿ ਜਿਨ ਢੀਗਾ।","roman":"Bade bade jin ke sir seegaa | chonchai badee bhaati jin dheegaa |","meaning_en":"Those with great horns on their heads, those with large beaks, near them,","page":2525,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਰੋਨਤ ਸੇ ਸਰ ਨੈਨ ਅਪਾਰਾ। ਨਿਰਖ ਜਿਨੈ ਉਪਜਤ ਭ੍ਰਮ ਭਾਰਾ। ੩੩੮।","roman":"Sronat se sar nain apaaraa | nirakh jinai upjat bhram bhaaraa | 338 |","meaning_en":"their eyes limitless like pools of blood, seeing which great delusion arises. 338.","page":2525,"meaning_status":"draft","note":"Obscure; uncertain."}]},{"type":"verse","number":[339],"number_text":"੩੩੯।","page":2525,"lines":[{"gurmukhi":"ਮਹਾ ਬੀਰ ਤ੍ਰੈ ਲੋਕ ਅਤੁਲ ਬਲ। ਅਰਿ ਅਨੇਕ ਜੀਤੇ ਜਿਨ ਜਲ ਥਲ।","roman":"Mahaa beer trai lok atul bal | ari anek jeete jin jal thal |","meaning_en":"Great heroes of unequalled strength in the three worlds, who had conquered many enemies on water and land,","page":2525,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਬੀਰ ਬਲਵਾਨ ਡਰਾਰੇ। ਚੁਨਿ ਚੁਨਿ ਬਾਲ ਬਰਛਿਯਨ ਮਾਰੇ। ੩੩੯।","roman":"Mahaa beer balvaan daraare | chuni chuni baal barchhiyan maare | 339 |","meaning_en":"great strong warriors, terrible, she chose them one by one and killed them with spears. 339.","page":2525,"meaning_status":"draft"}]},{"type":"verse","number":[340],"number_text":"੩੪੦।","page":2525,"lines":[{"gurmukhi":"ਕੇਤਿਕ ਸੁਭਟ ਅਬਿਕਟੇ ਮਾਰੇ। ਕੇਤਿਕ ਕਰਨ ਕੇਹਰੀ ਫਾਰੇ।","roman":"Ketik subhat abikte maare | ketik karan kehree phaare |","meaning_en":"Some warriors she killed unharmed; some she tore apart like a lioness.","page":2525,"meaning_status":"draft"},{"gurmukhi":"ਕੇਤਿਕ ਮਹਾ ਕਾਲ ਅਰਿ ਕੂਟੇ। ਬਾਦਲ ਸੇ ਸਭ ਹੀ ਦਲ ਫੂਟੇ। ੩੪੦।","roman":"Ketik mahaa kaal ari koote | baadal se sabh hee dal phoote | 340 |","meaning_en":"Some were pounded by Mahakal's foe; all the army burst like clouds. 340.","page":2525,"meaning_status":"draft","note":"ਮਹਾ ਕਾਲ ਅਰਿ: printed 'Mahakal's enemy'; uncertain."}]},{"type":"verse","number":[341],"number_text":"੩੪੧।","page":2525,"lines":[{"gurmukhi":"ਕੇਤੇ ਬੀਰ ਬਰਛਿਯਨ ਮਾਰੇ। ਟੂਕ ਟੂਕ ਕੇਤਿਕ ਕਰਿ ਡਾਰੇ।","roman":"Kete beer barchhiyan maare | took took ketik kari daare |","meaning_en":"Many heroes she killed with spears; many she cut to pieces.","page":2525,"meaning_status":"draft"},{"gurmukhi":"ਕੇਤੇ ਹਨੇ ਖੜਗ ਕੀ ਧਾਰਾ। ਲੋਹ ਕਟੀਲੇ ਸੂਰ ਅਪਾਰਾ। ੩੪੧।","roman":"Kete hane kharag kee dhaaraa | loh kateele soor apaaraa | 341 |","meaning_en":"Many were killed by the edge of the sword, sharp iron-wielding warriors without number. 341.","page":2525,"meaning_status":"draft"}]},{"type":"verse","number":[342],"number_text":"੩੪੨।","page":2525,"lines":[{"gurmukhi":"ਕੇਤਿਕ ਸੂਲ ਸੈਹਥੀ ਹਨੇ। ਸੁੰਦਰ ਸੁਘਰ ਸਿਪਾਹੀ ਬਨੇ।","roman":"Ketik sool saihthee hane | sundar sughar sipaahee bane |","meaning_en":"Some were killed by spears and javelins, fine and skilled soldiers.","page":2525,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਬਿਧਿ ਪਰੇ ਸੁ ਬੀਰ ਪ੍ਰਹਾਰੇ। ਭੂਮਿ ਚਾਲ ਮਨੋ ਗਿਰੇ ਮੁਨਾਰੇ। ੩੪੨।","roman":"Ih bidhi pare su beer prahaare | bhoomi chaal mano gire munaare | 342 |","meaning_en":"Thus the struck heroes fell; the earth shook, and minarets seemed to fall. 342.","page":2525,"meaning_status":"draft"}]},{"type":"verse","number":[343],"number_text":"੩੪੩।","page":2525,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਗਿਰੇ ਬੀਰ ਰਨ ਭਾਰੇ। ਜਨੁ ਨਗ ਇੰਦ੍ਰ ਬਜ੍ਰ ਭੇ ਮਾਰੇ।","roman":"Ih bidhi gire beer ran bhaare | janu nag indr bajr bhe maare |","meaning_en":"Thus great warriors fell in the battle, as if mountains were killed by Indra's thunderbolt.","page":2525,"meaning_status":"draft"},{"gurmukhi":"ਟੂਕ ਟੂਕ ਜੂਝੇ ਹ੍ਵੈ ਘਨੇ। ਜਾਨੁਕ ਗੌਸ ਕੁਤਬ ਸੇ ਬਨੇ। ੩੪੩।","roman":"Took took joojhe hvai ghane | jaanuk gaus kutab se bane | 343 |","meaning_en":"Cut in pieces, many fell, as if they had become Ghaus and Qutb. 343.","page":2525,"flags":[{"code":"0x50","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft"}]},{"type":"verse","number":[344],"number_text":"੩੪੪।","page":2525,"lines":[{"gurmukhi":"ਸ੍ਰੋਨ ਪੁਲਿਤ ਹ੍ਵੈ ਕਿਤੇ ਪਰਾਏ। ਚਾਚਰਿ ਖੇਲਿ ਮਨੋ ਘਰ ਆਏ।","roman":"Sron pulit hvai kite paraae | chaachri kheli mano ghar aae |","meaning_en":"Some fled, drenched in blood, as if they came home after playing Holi.","page":2525,"meaning_status":"draft","note":"ਚਾਚਰਿ: spring songs; uncertain."},{"gurmukhi":"ਭਾਜਤ ਭਏ ਬਿਮਨ ਹ੍ਵੈ ਐਸੇ। ਦਰਬ ਹਰਾਇ ਜੁਆਰੀ ਜੈਸੇ। ੩੪੪।","roman":"Bhaajat bhae biman hvai aise | darab haraai juaaree jaise | 344 |","meaning_en":"They fled downcast, like a gambler who has lost his wealth. 344.","page":2525,"meaning_status":"draft"}]},{"type":"verse","number":[345],"number_text":"੩੪੫।","page":2525,"lines":[{"gurmukhi":"ਜੋ ਜੂਝੇ ਸਨਮੁਖ ਅਸ ਧਾਰਾ। ਤਿਨ ਕਾ ਪਲ ਮੋ ਭਯੋ ਉਧਾਰਾ।","roman":"Jo joojhe sanmukh as dhaaraa | tin kaa pal mo bhayo udhaaraa |","meaning_en":"Those who fell facing the stream of weapons, they were delivered in an instant.","page":2525,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਜਗ ਤੇ ਬਿਲਖਤ ਨਹਿ ਭਏ। ਚੜਿ ਬਿਵਾਨ ਸੁਰਲੋਕ ਸਿਧਏ। ੩੪੫।","roman":"Ih jag te bilkhat nahi bhae | chari bivaan surlok sidhae | 345 |","meaning_en":"They did not linger in this world; mounting celestial cars they went to the world of the gods. 345.","page":2525,"meaning_status":"draft"}]},{"type":"verse","number":[346],"number_text":"੩੪੬।","page":2527,"lines":[{"gurmukhi":"ਸੋਫੀ ਜੇਤੇ ਭਜਤ ਪ੍ਰਹਾਰੇ। ਤੇ ਲੈ ਬਡੇ ਨਰਕ ਮੋ ਡਾਰੇ।","roman":"Sophee jete bhajat prahaare | te lai bade narak mo daare |","meaning_en":"The abstemious who fled when struck, those they took and cast into great hell.","page":2527,"meaning_status":"draft"},{"gurmukhi":"ਸਾਮੁਹਿ ਹ੍ਵੈ ਜਿਨਿ ਦੀਨੇ ਪ੍ਰਾਨਾ। ਤਿਨ ਨਰ ਬੀਰ ਬਰੰਗਨਿ ਨਾਨਾ। ੩੪੬।","roman":"Saamuhi hvai jini deene praanaa | tin nar beer barangni naanaa | 346 |","meaning_en":"Those men and heroes who gave their lives facing the foe, many celestial women. 346.","page":2527,"meaning_status":"draft","note":"Last line printed ਤਿਨ ਨਰ ਬੀਰ ਬਰੰਗਨਿ ਨਾਨਾ; read as 'many celestial women wed them'."}]},{"type":"verse","number":[347],"number_text":"੩੪੭।","page":2527,"lines":[{"gurmukhi":"ਕੇਤਿਕ ਬਿਧੇ ਬਜ੍ਰ ਅਰੁ ਬਾਨਾ। ਗਿਰਿ ਗਿਰਿ ਪਰੇ ਧਰਨ ਪਰ ਨਾਨਾ।","roman":"Ketik bidhe bajr aru baanaa | giri giri pare dharan par naanaa |","meaning_en":"Some were pierced by thunderbolts and arrows; they fell and fell on the earth, many.","page":2527,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਰਥੀ ਬਾਨਨ ਕੌ ਬਾਧੇ। ਗਿਰਿ ਗਿਰਿ ਪਰੇ ਰਹੇ ਪੁਨਿ ਸਾਧੇ। ੩੪੭।","roman":"Mahaa rathee baanan kau baadhe | giri giri pare rahe puni saadhe | 347 |","meaning_en":"Great charioteers, bound by arrows, fell and fell, yet steadied again. 347.","page":2527,"meaning_status":"draft"}]},{"type":"verse","number":[348],"number_text":"੩੪੮।","page":2527,"lines":[{"gurmukhi":"ਸੂਰ ਬਡੇ ਰਨ ਮਚੇ ਬਿਕਟ ਅਤਿ। ਧਾਇ ਧਾਇ ਕਰ ਪਰੇ ਬਿਕਟ ਮਤਿ।","roman":"Soor bade ran mache bikat ati | dhaai dhaai kar pare bikat mati |","meaning_en":"Great heroes fought terribly in the battle; running they came, in dreadful mind.","page":2527,"meaning_status":"draft"},{"gurmukhi":"ਮਾਰਿ ਮਾਰਿ ਕਰਿ ਸਕਲ ਪੁਕਾਰਾ। ਦੁੰਦਭਿ ਢੋਲ ਦਮਾਮੋ ਭਾਰਾ। ੩੪੮।","roman":"Maari maari kari sakal pukaaraa | dundbhi dhol damaamo bhaaraa | 348 |","meaning_en":"All cried \"kill, kill\"; kettledrums, drums and great drums. 348.","page":2527,"meaning_status":"draft"}]},{"type":"verse","number":[349],"number_text":"੩੪੯।","page":2527,"lines":[{"gurmukhi":"ਹਾਕਿ ਹਾਕਿ ਹਥਿਯਾਰ ਪ੍ਰਹਾਰੇ। ਬੀਨਿ ਬੀਨਿ ਬਾਨਨ ਤਨ ਮਾਰੇ।","roman":"Haaki haaki hathiyaar prahaare | beeni beeni baanan tan maare |","meaning_en":"Shouting they struck with weapons; picking them one by one she killed them with arrows.","page":2527,"meaning_status":"draft"},{"gurmukhi":"ਝੁਕਿ ਝੁਕਿ ਹਨੇ ਸੈਹਥੀ ਘਾਇਨ। ਜੂਝੈ ਅਧਿਕ ਦੁਬਹਿਯਾ ਚਾਇਨ। ੩੪੯।","roman":"Jhuki jhuki hane saihthee ghaain | joojhai adhik dubhiyaa chaain | 349 |","meaning_en":"Bending again and again she struck with spears the wounds; the dubahiyas fought with great eagerness. 349.","page":2527,"meaning_status":"draft"}]},{"type":"verse","number":[350],"number_text":"੩੫੦।","page":2527,"lines":[{"gurmukhi":"ਕਹੀ ਪਰੇ ਹਾਥਿਨ ਕੇ ਸੁੰਡਾ। ਬਾਜੀ ਰਥੀ ਗਜਨ ਕੇ ਮੁੰਡਾ।","roman":"Kahee pare haathin ke sundaa | baajee rathee gajan ke mundaa |","meaning_en":"In places lay the trunks of elephants, and the heads of horses, charioteers and elephants.","page":2527,"meaning_status":"draft"},{"gurmukhi":"ਝੁੰਡ ਪਰੇ ਕਹੀ ਜੂਝਿ ਜੁਝਾਰੇ। ਤੀਰ ਤੁਫੰਡ ਤੁਪਨ ਕੇ ਮਾਰੇ। ੩੫੦।","roman":"Jhund pare kahee joojhi jujhaare | teer tuphand tupan ke maare | 350 |","meaning_en":"Fighters lay in heaps, killed by arrows, guns and cannon. 350.","page":2527,"meaning_status":"draft"}]},{"type":"verse","number":[351],"number_text":"੩੫੧।","page":2527,"lines":[{"gurmukhi":"ਬਹੁ ਜੂਝੇ ਇਹ ਭਾਤਿ ਸਿਪਾਹੀ। ਭਾਤਿ ਭਾਤਿ ਧੁਜਨੀ ਰਿਪੁ ਗਾਹੀ।","roman":"Bahu joojhe ih bhaati sipaahee | bhaati bhaati dhujnee ripu gaahee |","meaning_en":"Many soldiers fell in this way; she plunged through the enemy hosts in many ways.","page":2527,"meaning_status":"draft"},{"gurmukhi":"ਉਤ ਕੀਯ ਸਿੰਘ ਬਾਹਨੀ ਕੋਪੈ। ਇਤਿ ਅਸਿਧੁਜ ਲੈ ਧਾਯੋ ਧੋਪੈ। ੩੫੧।","roman":"Ut keey singh baahnee kopai | iti asidhuj lai dhaayo dhopai | 351 |","meaning_en":"On that side the lion-rider raged; on this side Asidhuj ran and attacked. 351.","page":2527,"meaning_status":"draft","note":"ਸਿੰਘ ਬਾਹਨੀ: lion-rider, the goddess; ਧੋਪੈ: 'attacked'; uncertain."}]},{"type":"verse","number":[352],"number_text":"੩੫੨।","page":2527,"lines":[{"gurmukhi":"ਕਹੂੰ ਲਸੈ ਰਨ ਖੜਗ ਕਟਾਰੀ। ਜਾਨੁਕ ਮਛ ਬੰਧੇ ਮਧਿ ਜਾਰੀ।","roman":"Kahoon lasai ran kharag kataaree | jaanuk machh bandhe madhi jaaree |","meaning_en":"In places swords and daggers shone in the battle, like fish caught in a net.","page":2527,"meaning_status":"draft"},{"gurmukhi":"ਸਿੰਘ ਬਾਹਨੀ ਸਤ੍ਰੁ ਬਿਹੰਡੇ। ਤਿਲ ਤਿਲ ਪ੍ਰਾਇ ਅਸੁਰ ਕਰਿ ਖੰਡੇ। ੩੫੨।","roman":"Singh baahnee satru bihande | til til praai asur kari khande | 352 |","meaning_en":"The lion-rider destroyed the enemies and cut the demons into bits, bit by bit. 352.","page":2527,"meaning_status":"draft"}]},{"type":"verse","number":[353],"number_text":"੩੫੩।","page":2527,"lines":[{"gurmukhi":"ਕਹੂੰ ਪਾਖਰੈ ਕਟੀ ਬਿਰਾਜੈ। ਬਖਤਰ ਕਹੂੰ ਗਿਰੇ ਨਰ ਰਾਜੈ।","roman":"Kahoon paakhrai katee biraajai | bakhtar kahoon gire nar raajai |","meaning_en":"In places armoured horses lay cut; in places armour lay and men shone.","page":2527,"meaning_status":"draft","note":"Obscure; uncertain."},{"gurmukhi":"ਕਹੂੰ ਚਲਤ ਸ੍ਰੋਨਤ ਕੀ ਧਾਰਾ। ਛੁਟਤ ਬਾਗ ਮੋ ਜਨਕੁ ਫੁਹਾਰਾ। ੩੫੩।","roman":"Kahoon chalat sronat kee dhaaraa | chhutat baag mo janku phuhaaraa | 353 |","meaning_en":"In places a stream of blood flowed, like a fountain loosed in a garden. 353.","page":2527,"meaning_status":"draft"}]},{"type":"verse","number":[354],"number_text":"੩੫੪।","page":2527,"lines":[{"gurmukhi":"ਕਹੂੰ ਡਾਕਨੀ ਸ੍ਰੋਨਤ ਪੀਯੈ। ਝਾਕਨਿ ਕਹੂੰ ਮਾਸ ਭਖਿ ਜੀਯੈ।","roman":"Kahoon daaknee sronat peeyai | jhaakni kahoon maas bhakhi jeeyai |","meaning_en":"In places dakinis drank blood; jhakinis lived on eating flesh.","page":2527,"meaning_status":"draft"},{"gurmukhi":"ਕਾਕਨਿ ਕਹੂੰ ਫਿਰੈ ਕਹਕਾਤੀ। ਪ੍ਰੇਤ ਪਿਸਾਚਨ ਡੋਲਤ ਮਾਤੀ। ੩੫੪।","roman":"Kaakni kahoon phirai kahkaatee | pret pisaachan dolat maatee | 354 |","meaning_en":"In places crows went about cawing; ghosts and goblins wandered, intoxicated. 354.","page":2527,"meaning_status":"draft"}]},{"type":"verse","number":[355],"number_text":"੩੫੫।","page":2527,"lines":[{"gurmukhi":"ਹਸਤ ਫਿਰਤ ਪ੍ਰੇਤਨ ਕੀ ਦਾਰਾ। ਡਾਕਨਿ ਕਹੂੰ ਬਜਾਵਤ ਤਾਰਾ।","roman":"Hasat phirat pretan kee daaraa | daakni kahoon bajaavat taaraa |","meaning_en":"The wives of ghosts went about laughing; in places dakinis clapped their hands.","page":2527,"meaning_status":"draft"},{"gurmukhi":"ਜੋਗਿਨ ਫਿਰੈ ਕਹੂੰ ਮੁਸਕਾਤੀ। ਭੂਤਨ ਕੀ ਇਸਤ੍ਰੀ ਮਦ ਮਾਤੀ। ੩੫੫।","roman":"Jogin phirai kahoon muskaatee | bhootan kee istree mad maatee | 355 |","meaning_en":"Yoginis went about smiling in places; the wives of ghosts were drunk. 355.","page":2527,"meaning_status":"draft"}]},{"type":"verse","number":[356],"number_text":"੩੫੬।","page":2527,"lines":[{"gurmukhi":"ਫਿਰਤ ਡਕਾਰ ਕਹੂੰ ਰਨ ਡਾਕਨਿ। ਮਾਸ ਅਹਾਰ ਕਰਤ ਕਹੂੰ ਝਾਕਨਿ।","roman":"Phirat dakaar kahoon ran daakni | maas ahaar karat kahoon jhaakni |","meaning_en":"In places dakinis went about belching in the battle; jhakinis were feeding on flesh in places.","page":2527,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰੇਤ ਪਿਸਾਚ ਹਸੇ ਕਿਲਕਾਰੈ। ਕਹੂੰ ਮਸਾਨ ਕਿਲਕਟੀ ਮਾਰੈ। ੩੫੬।","roman":"Pret pisaach hase kilkaarai | kahoon masaan kilaktee maarai | 356 |","meaning_en":"Ghosts and goblins laughed and shrieked; in places jackals howled. 356.","page":2527,"meaning_status":"draft"}]},{"type":"verse","number":[357],"number_text":"੩੫੭।","page":2527,"lines":[{"gurmukhi":"ਕਢੈ ਦੈਤ ਰਨ ਦਾਤ ਬਿਹਾਰਤ। ਭੂਤ ਪ੍ਰੇਤ ਤਾਲੀ ਕਹ ਮਾਰਤ।","roman":"Kadhai dait ran daat bihaarat | bhoot pret taalee kah maarat |","meaning_en":"The demons bared their teeth in the battle; ghosts and spirits clapped hands.","page":2527,"meaning_status":"draft"},{"gurmukhi":"ਉਲਕਾ ਪਾਤ ਹੋਤ ਆਕਾਸਾ। ਅਸੁਰ ਸੈਨ ਇਹ ਬਿਧਿ ਭਯੋ ਨਾਸਾ। ੩੫੭।","roman":"Ulkaa paat hot aakaasaa | asur sain ih bidhi bhayo naasaa | 357 |","meaning_en":"Meteors fell in the sky; in this way the demon army was destroyed. 357.","page":2527,"meaning_status":"draft"}]},{"type":"verse","number":[358],"number_text":"੩੫੮।","page":2529,"lines":[{"gurmukhi":"ਬਹਤ ਅਮਿਤ ਰਨ ਪਵਨ ਪ੍ਰਚੰਡਾ। ਦਿਖਿਯਤ ਪਰੇ ਸੁਭਟ ਖੰਡ ਖੰਡਾ।","roman":"Bahat amit ran pavan prachandaa | dikhiyat pare subhat khand khandaa |","meaning_en":"A fierce wind blew countlessly in the battle; warriors were seen lying in pieces.","page":2529,"meaning_status":"draft"},{"gurmukhi":"ਕਾਕਨਿ ਕੁਹਕਿ ਮਾਨਵਤਿ ਤਾਤੀ। ਫਾਗੁਨ ਜਾਨੁ ਕੋਕਿਲਾ ਮਾਤੀ। ੩੫੮।","roman":"Kaakni kuhki maanavti taatee | phaagun jaanu kokilaa maatee | 358 |","meaning_en":"Crows cawed, as in Phagun the cuckoos grow drunk. 358.","page":2529,"meaning_status":"draft","note":"ਕਾਕਨਿ ਕੁਹਕਿ ਮਾਨਵਤਿ ਤਾਤੀ: obscure; uncertain."}]},{"type":"verse","number":[359],"number_text":"੩੫੯।","page":2529,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਸ੍ਰੋਨ ਕੁੰਡਿ ਭਰਿ ਗਯੋ। ਦੂਸਰ ਮਾਨਸਰੋਵਰ ਭਯੋ।","roman":"Ih bidhi sron kundi bhari gayo | doosar maanasrovar bhayo |","meaning_en":"In this way the pool of blood was filled, and became another Manasarovar.","page":2529,"meaning_status":"draft"},{"gurmukhi":"ਸੇਤ ਛਤ੍ਰੁ ਤਹ ਹੰਸ ਬਿਰਾਜੈ। ਅਨਤ ਸਾਜ ਜਲਜਿਯ ਸੇ ਰਾਜੈ। ੩੫੯।","roman":"Set chhatru tah hans biraajai | anat saaj jaljiy se raajai | 359 |","meaning_en":"White umbrellas shone there like swans; countless trappings gleamed like water-creatures. 359.","page":2529,"meaning_status":"draft"}]},{"type":"verse","number":[360],"number_text":"੩੬੦।","page":2529,"lines":[{"gurmukhi":"ਟੂਕ ਟੂਕ ਦੰਤੀ ਕਹੂੰ ਭਏ। ਤਿਲ ਤਿਲ ਪ੍ਰਾਇ ਸੁਭਟ ਹ੍ਵੈ ਗਏ।","roman":"Took took dantee kahoon bhae | til til praai subhat hvai gae |","meaning_en":"In places elephants were in pieces; warriors were cut, bit by bit.","page":2529,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਰੋਨਤ ਧਾਰਿ ਬਹੀ ਇਕ ਬਾਰਾ। ਭਈ ਧੂਰਿ ਰਨ ਕੀ ਸਭ ਗਾਰਾ। ੩੬੦।","roman":"Sronat dhaari bahee ik baaraa | bhaee dhoori ran kee sabh gaaraa | 360 |","meaning_en":"A stream of blood flowed at one time; the dust of the battle all turned to mud. 360.","page":2529,"meaning_status":"draft"}]},{"type":"verse","number":[361],"number_text":"੩੬੧।","page":2529,"lines":[{"gurmukhi":"ਨੇਜਬਾਜ ਬਹੁ ਬੀਰ ਸੰਘਾਰੇ। ਪ੍ਰੋਏ ਬਰਾ ਸੀਖ ਭਟਿਯਾਰੇ।","roman":"Nejbaaj bahu beer sanghaare | proe baraa seekh bhatiyaare |","meaning_en":"Many heroes were killed by lancers; the spearmen strung them on skewers.","page":2529,"meaning_status":"draft","note":"ਨੇਜਬਾਜ: lancers; ਭਟਿਯਾਰੇ: cooks (taken); uncertain."},{"gurmukhi":"ਟੂਕ ਟੂਕ ਭਟ ਰਨ ਹ੍ਵੈ ਰਹੇ। ਜਿਨ ਕੇ ਘਾਵ ਸਰੋਹਿਨ ਬਹੇ। ੩੬੧।","roman":"Took took bhat ran hvai rahe | jin ke ghaav sarohin bahe | 361 |","meaning_en":"The warriors lay in the battle in pieces, from whose wounds blood flowed like Sirohi blades. 361.","page":2529,"meaning_status":"draft","note":"ਸਰੋਹਿਨ: obscure; uncertain."}]},{"type":"verse","number":[362],"number_text":"੩੬੨।","page":2529,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਅਮਿਤ ਕੋਪ ਕਰਿ ਕਾਲਾ। ਕਾਢਤ ਭਯੋ ਦਾਤ ਬਿਕਰਾਲਾ।","roman":"Ih bidhi amit kop kari kaalaa | kaadhat bhayo daat bikraalaa |","meaning_en":"In this way Kal, in boundless rage, bared terrible teeth.","page":2529,"meaning_status":"draft"},{"gurmukhi":"ਛਿਪ੍ਰ ਹਨੇ ਛਿਨ ਮਾਝ ਛਤ੍ਰਾਲੇ। ਸੂਰਬੀਰ ਬਲਵਾਨ ਮੁਛਾਲੇ। ੩੬੨।","roman":"Chhipr hane chhin maajh chhatraale | soorbeer balvaan muchhaale | 362 |","meaning_en":"In an instant she quickly killed the umbrella-bearing, strong, moustached warriors. 362.","page":2529,"meaning_status":"draft","note":"Obscure ਛਤ੍ਰਾਲੇ; uncertain."}]},{"type":"verse","number":[363],"number_text":"੩੬੩।","page":2529,"lines":[{"gurmukhi":"ਦੁਹੂੰ ਅਧਿਕ ਰਨ ਕਿਯੋ ਅਪਾਰਾ। ਦਾਨਵ ਮਰਤ ਭਯੋ ਨਹਿ ਮਾਰਾ।","roman":"Duhoon adhik ran kiyo apaaraa | daanav marat bhayo nahi maaraa |","meaning_en":"Both made great battle without limit; the demons died but were not killed.","page":2529,"meaning_status":"draft"},{"gurmukhi":"ਤਬ ਅਸਿਧੁਜ ਅਸ ਮੰਤ੍ਰ ਬਿਚਾਰੋ। ਜਿਹ ਬਿਧਿ ਤੇ ਦਾਨਵਹਿ ਸੰਘਾਰੋ। ੩੬੩।","roman":"Tab asidhuj as mantr bichaaro | jih bidhi te daanavhi sanghaaro | 363 |","meaning_en":"Then Asidhuj thought of a plan, by which he might destroy the demons. 363.","page":2529,"meaning_status":"draft"}]},{"type":"verse","number":[364],"number_text":"੩੬੪।","page":2529,"lines":[{"gurmukhi":"ਸਰਬਾਕਰਖਨ ਕਿਯ ਅਸਿਧੁਜ ਜਬ। ਉਪਜਤ ਤੇ ਰਹਿ ਗਏ ਅਸੁਰ ਤਬ।","roman":"Sarbaakarkhan kiy asidhuj jab | upjat te rahi gae asur tab |","meaning_en":"When Asidhuj drew in everything, the demons no longer arose.","page":2529,"meaning_status":"draft"},{"gurmukhi":"ਆਗ੍ਯਾ ਬਹੁਰਿ ਕਾਲਿ ਕਹ ਦਈ। ਸਤ੍ਰੁ ਸੈਨ ਭਛਨ ਕਰਿ ਗਈ। ੩੬੪।","roman":"Aagyaa bahuri kaali kah daee | satru sain bhachhan kari gaee | 364 |","meaning_en":"Then he gave the command to Kali, and she went and devoured the enemy army. 364.","page":2529,"meaning_status":"draft"}]},{"type":"verse","number":[365],"number_text":"੩੬੫।","page":2529,"lines":[{"gurmukhi":"ਏਕੈ ਅਸੁਰ ਤਬੈ ਰਹਿ ਗਯੋ। ਤ੍ਰਾਸਿਤ ਅਧਿਕ ਚਿਤ ਮਹਿ ਭਯੋ।","roman":"Ekai asur tabai rahi gayo | traasit adhik chit mahi bhayo |","meaning_en":"Then only one demon remained, greatly terrified in his mind.","page":2529,"meaning_status":"draft"},{"gurmukhi":"ਹਾਇ ਹਾਇ ਕਸ ਕਰੌ ਉਪਾਵਾ। ਅਸ ਕੋਈ ਚਲਤ ਨੇ ਮੇਰਾ ਦਾਵਾ। ੩੬੫।","roman":"Haai haai kas karau upaavaa | as koee chalat ne meraa daavaa | 365 |","meaning_en":"\"Alas, alas, what means shall I use? No such claim of mine goes on.\" 365.","page":2529,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2529,"meaning_status":"draft"},{"type":"verse","number":[366],"number_text":"੩੬੬।","page":2529,"lines":[{"gurmukhi":"ਮਹਾ ਕਾਲ ਕੀ ਸਰਨਿ ਜੇ ਪਰੇ ਸੁ ਲਏ ਬਚਾਇ।","roman":"Mahaa kaal kee sarni je pare su lae bachaai |","meaning_en":"Those who fall in the shelter of Mahakal, he saves.","page":2529,"meaning_status":"draft"},{"gurmukhi":"ਔਰ ਨ ਉਪਜਾ ਦੂਸਰ ਜਗ ਭਛਿਯੋ ਸਭੈ ਬਨਾਇ। ੩੬੬।","roman":"Aur na upjaa doosar jag bhachhiyo sabhai banaai | 366 |","meaning_en":"No other arose; the second one devoured the whole world made. 366.","page":2529,"meaning_status":"draft","note":"Obscure; uncertain."}]},{"type":"verse","number":[367],"number_text":"੩੬੭।","page":2529,"lines":[{"gurmukhi":"ਜੋ ਪੂਜਾ ਅਸਿਕੇਤੁ ਕੀ ਨਿਤ ਪ੍ਰਤਿ ਕਰੈ ਬਨਾਇ।","roman":"Jo poojaa asiketu kee nit prati karai banaai |","meaning_en":"Whoever offers worship to Asiketu daily, properly,","page":2529,"meaning_status":"draft"},{"gurmukhi":"ਤਿਨ ਪਰ ਅਪਨੋ ਹਾਥ ਦੈ ਅਸਿਧੁਜ ਲੇਤ ਬਚਾਇ। ੩੬੭।","roman":"Tin par apno haath dai asidhuj let bachaai | 367 |","meaning_en":"over them Asidhuj puts his own hand and saves them. 367.","page":2529,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2529,"meaning_status":"draft"},{"type":"verse","number":[368],"number_text":"੩੬੮।","page":2529,"lines":[{"gurmukhi":"ਦੁਸਟ ਦੈਤ ਕਛੁ ਬਾਤ ਨ ਜਾਨੀ। ਮਹਾ ਕਾਲ ਤਨ ਪੁਨਿ ਰਿਸਿ ਠਾਨੀ।","roman":"Dusat dait kachhu baat na jaanee | mahaa kaal tan puni risi thaanee |","meaning_en":"The wicked demon understood nothing; again he took up anger against Mahakal.","page":2529,"meaning_status":"draft"},{"gurmukhi":"ਬਲ ਅਪਬਲ ਅਪਨੋ ਨ ਬਿਚਾਰਾ। ਗਰਬ ਠਾਨਿ ਜਿਯ ਬਹੁਰਿ ਹੰਕਾਰਾ। ੩੬੮।","roman":"Bal apbal apno na bichaaraa | garab thaani jiy bahuri hankaaraa | 368 |","meaning_en":"He did not reckon his own strength or weakness; he took on pride and ego in his heart. 368.","page":2529,"meaning_status":"draft"}]},{"type":"verse","number":[369],"number_text":"੩੬੯।","page":2529,"lines":[{"gurmukhi":"ਰੇ ਰੇ ਕਾਲ ਫੂਲਿ ਜਿਨਿ ਜਾਹੂ। ਬਹੁਰਿ ਆਨਿ ਸੰਗ੍ਰਾਮ ਮਚਾਹੂ।","roman":"Re re kaal phooli jini jaahoo | bahuri aani sangraam machaahoo |","meaning_en":"\"O O Kal, do not go swollen with pride; come again and set up the battle.","page":2529,"meaning_status":"draft"},{"gurmukhi":"ਏਕ ਨਿਦਾਨ ਕਰੋ ਰਨ ਮਾਹੀ। ਕੈ ਅਸਿਧੁਜਿ ਕੈ ਦਾਨਵ ਨਾਹੀ। ੩੬੯।","roman":"Ek nidaan karo ran maahee | kai asidhuji kai daanav naahee | 369 |","meaning_en":"Let us make an end in the battle: either Asidhuj or the demon is no more.\" 369.","page":2529,"meaning_status":"draft"}]},{"type":"verse","number":[370],"number_text":"੩੭੦।","page":2531,"lines":[{"gurmukhi":"ਏਕ ਪਾਵ ਤਜਿ ਜੁਧ ਨ ਭਾਜਾ। ਮਹਾਰਾਜ ਦੈਤਨ ਕਾ ਰਾਜਾ।","roman":"Ek paav taji judh na bhaajaa | mahaaraaj daitan kaa raajaa |","meaning_en":"Without leaving a single foot, he did not flee the battle, the great king of demons.","page":2531,"meaning_status":"draft"},{"gurmukhi":"ਆਂਤੌ ਗੀਧ ਗਗਨ ਲੈ ਗਏ। ਬਾਹਤ ਬਿਸਿਖ ਤਊ ਹਠ ਭਏ। ੩੭੦।","roman":"Aantau geedh gagan lai gae | baahat bisikh taoo hath bhae | 370 |","meaning_en":"Vultures took his entrails into the sky; yet struck by arrows he stayed obstinate. 370.","page":2531,"meaning_status":"draft"}]},{"type":"verse","number":[371],"number_text":"੩੭੧।","page":2531,"lines":[{"gurmukhi":"ਅਸੁਰ ਅਮਿਤ ਰਨ ਬਾਨ ਚਲਾਏ। ਨਿਰਖਿ ਖੜਗਧੁਜ ਕਾਟਿ ਗਿਰਾਏ।","roman":"Asur amit ran baan chalaae | nirkhi kharagdhuj kaati giraae |","meaning_en":"The demon shot countless arrows in the battle; seeing them Khargadhuj cut them down.","page":2531,"meaning_status":"draft"},{"gurmukhi":"ਬੀਸ ਸਹਸ੍ਰ ਅਸੁਰ ਪਰ ਬਾਨਾ। ਸ੍ਰੀ ਅਸਿਧੁਜ ਛਾਡੇ ਬਿਧਿ ਨਾਨਾ। ੩੭੧।","roman":"Bees sahasr asur par baanaa | sree asidhuj chhaade bidhi naanaa | 371 |","meaning_en":"Sri Asidhuj shot arrows at the demon, twenty thousand, in many ways. 371.","page":2531,"meaning_status":"draft"}]},{"type":"verse","number":[372],"number_text":"੩੭੨।","page":2531,"lines":[{"gurmukhi":"ਮਹਾ ਕਾਲ ਪੁਨਿ ਜਿਯ ਮੈ ਕੋਪਾ। ਧਨੁਖ ਟੰਕੋਰ ਬਹੁਰਿ ਰਨ ਰੋਪਾ।","roman":"Mahaa kaal puni jiy mai kopaa | dhanukh tankor bahuri ran ropaa |","meaning_en":"Mahakal grew angry in his heart again; he twanged his bow and again took the field.","page":2531,"meaning_status":"draft"},{"gurmukhi":"ਏਕ ਬਾਨ ਤੇ ਧੁਜਹਿ ਗਿਰਾਯੋ। ਦੁਤਿਯ ਸਤ੍ਰੁ ਕੋ ਸੀਸ ਉਡਾਯੋ। ੩੭੨।","roman":"Ek baan te dhujhi giraayo | dutiy satru ko sees udaayo | 372 |","meaning_en":"With one arrow he brought down the banner; with a second he struck off the enemy's head. 372.","page":2531,"meaning_status":"draft"}]},{"type":"verse","number":[373],"number_text":"੩੭੩।","page":2531,"lines":[{"gurmukhi":"ਦੁਹੂੰ ਬਿਸਿਖ ਕਰਿ ਦ੍ਵੈ ਰਥ ਚਕ੍ਰ। ਕਾਟਿ ਦਏ ਛਿਨ ਇਕ ਮੈ ਬਕ੍ਰ।","roman":"Duhoon bisikh kari dvai rath chakr | kaati dae chhin ik mai bakr |","meaning_en":"With two arrows he cut the two wheels of the chariot, bent in an instant.","page":2531,"meaning_status":"draft"},{"gurmukhi":"ਚਾਰਹਿ ਬਾਨ ਚਾਰ ਹੂੰ ਬਾਜਾ। ਮਾਰ ਦਏ ਸਭ ਜਗ ਕੇ ਰਾਜਾ। ੩੭੩।","roman":"Chaarhi baan chaar hoon baajaa | maar dae sabh jag ke raajaa | 373 |","meaning_en":"With four arrows he killed the four horses, the lord of all the world. 373.","page":2531,"meaning_status":"draft"}]},{"type":"verse","number":[374],"number_text":"੩੭੪।","page":2531,"lines":[{"gurmukhi":"ਬਹੁਰਿ ਅਸੁਰ ਕਾ ਕਾਟਸਿ ਮਾਥਾ। ਸ੍ਰੀ ਅਸਿਕੇਤਿ ਜਗਤ ਕੇ ਨਾਥਾ।","roman":"Bahuri asur kaa kaatsi maathaa | sree asiketi jagat ke naathaa |","meaning_en":"Then he cut off the head of the demon, Sri Asiketu, lord of the world.","page":2531,"meaning_status":"draft"},{"gurmukhi":"ਦੁਤਿਯ ਬਾਨ ਸੌ ਦੋਊ ਅਰਿ ਕਰ। ਕਾਟਿ ਦਯੋ ਅਸਿਧੁਜ ਨਰ ਨਾਹਰ। ੩੭੪।","roman":"Dutiy baan sau do'oo ari kar | kaati dayo asidhuj nar naahar | 374 |","meaning_en":"With a second arrow Asidhuj cut off both of the enemy's arms, the lion among men. 374.","page":2531,"meaning_status":"draft","note":"ਸਾਰ: 'lion among men' (ਨਰ ਨਾਹਰ); uncertain."}]},{"type":"verse","number":[375],"number_text":"੩੭੫।","page":2531,"lines":[{"gurmukhi":"ਪੁਨਿ ਰਾਛਸ ਕਾ ਕਾਟਾ ਸੀਸਾ। ਸ੍ਰੀ ਅਸਿਕੇਤੁ ਜਗਤ ਕੇ ਈਸਾ।","roman":"Puni raachhas kaa kaataa seesaa | sree asiketu jagat ke eesaa |","meaning_en":"Then he cut off the head of the demon, Sri Asiketu, Lord of the world.","page":2531,"meaning_status":"draft"},{"gurmukhi":"ਪੁਹਪਨ ਬ੍ਰਿਸਟਿ ਗਗਨ ਤੇ ਭਈ। ਸਭਹਿਨ ਆਨਿ ਬਧਾਈ ਦਈ। ੩੭੫।","roman":"Puhpan bristi gagan te bhaee | sabhhin aani badhaaee daee | 375 |","meaning_en":"A rain of flowers fell from the sky; all came and offered congratulations. 375.","page":2531,"meaning_status":"draft"}]},{"type":"verse","number":[376],"number_text":"੩੭੬।","page":2531,"lines":[{"gurmukhi":"ਧੰਨ੍ਯ ਧੰਨ੍ਯ ਲੋਗਨ ਕੇ ਰਾਜਾ। ਦੁਸਟਨ ਦਾਹ ਗਰੀਬ ਨਿਵਾਜਾ।","roman":"Dhanny dhanny logan ke raajaa | dustan daah gareeb nivaajaa |","meaning_en":"\"Blessed, blessed, king of the people, destroyer of the wicked, cherisher of the poor,","page":2531,"meaning_status":"draft"},{"gurmukhi":"ਅਖਲ ਭਵਨ ਕੇ ਸਿਰਜਨਹਾਰੇ। ਦਾਸ ਜਾਨਿ ਮੁਹਿ ਲੇਹੁ ਉਬਾਰੇ। ੩੭੬।","roman":"Akhal bhavan ke sirjanhaare | daas jaani muhi lehu ubaare | 376 |","meaning_en":"creator of all the worlds, count me as your servant and rescue me.\" 376.","page":2531,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਕਬ੍ਯੋ ਬਾਚ ਬੇਨਤੀ","gurmukhi":"ਕਬ੍ਯੋ ਬਾਚ ਬੇਨਤੀ","roman":"Kabyo baach bentee","meaning_en":"The poet speaks: a supplication.","page":2531,"meaning_status":"draft","note":"This heading begins the passage recited as Chaupai Sahib (Benti Chaupai). Traditions differ on where it ends: many recite verses 377-401, some continue to 405. In daily recitation it is followed by a savaiya and dohra from Ram Avtar ('ਪਾਂਇ ਗਹੇ ਜਬ ਤੇ ਤੁਮਰੇ', 'ਸਗਲ ਦੁਆਰ ਕਉ ਛਾਡਿ ਕੈ'), which are not in this PDF."},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai metre.","page":2531,"meaning_status":"draft"},{"type":"verse","number":[377],"number_text":"੩੭੭।","page":2531,"lines":[{"gurmukhi":"ਹਮਰੀ ਕਰੋ ਹਾਥ ਦੈ ਰਛਾ। ਪੂਰਨ ਹੋਇ ਚਿਤ ਕੀ ਇਛਾ।","roman":"Hamree karo haath dai rachhaa | pooran hoi chit kee ichhaa |","meaning_en":"Protect me with Your own hand; may the wish of my heart be fulfilled.","page":2531,"meaning_status":"draft","note":"ਹਾਥ ਦੈ: 'giving Your hand', i.e. personally, directly."},{"gurmukhi":"ਤਵ ਚਰਨਨ ਮਨ ਰਹੈ ਹਮਾਰਾ। ਅਪਨਾ ਜਾਨ ਕਰੋ ਪ੍ਰਤਿਪਾਰਾ। ੩੭੭।","roman":"Tav charnan man rahai hamaaraa | apnaa jaan karo pratipaaraa | 377 |","meaning_en":"May my mind remain at Your feet; consider me Your own and sustain me.","page":2531,"meaning_status":"draft"}]},{"type":"verse","number":[378],"number_text":"੩੭੮।","page":2531,"lines":[{"gurmukhi":"ਹਮਰੇ ਦੁਸਟ ਸਭੈ ਤੁਮ ਘਾਵਹੁ। ਆਪੁ ਹਾਥ ਦੈ ਮੋਹਿ ਬਚਾਵਹੁ।","roman":"Hamre dusat sabhai tum ghaavhu | aapu haath dai mohi bachaavhu |","meaning_en":"Destroy all my enemies; save me with Your own hand.","page":2531,"meaning_status":"draft","note":"ਦੁਸਟ: the wicked, enemies; also read as the inner enemies (vices)."},{"gurmukhi":"ਸੁਖੀ ਬਸੈ ਮੋਰੋ ਪਰਿਵਾਰਾ। ਸੇਵਕ ਸਿਖ੍ਯ ਸਭੈ ਕਰਤਾਰਾ। ੩੭੮।","roman":"Sukhee basai moro parivaaraa | sevak sikhy sabhai kartaaraa | 378 |","meaning_en":"May my family live in peace, O Creator, and all my servants and Sikhs.","page":2531,"meaning_status":"draft"}]},{"type":"verse","number":[379],"number_text":"੩੭੯।","page":2531,"lines":[{"gurmukhi":"ਮੋ ਰਛਾ ਨਿਜੁ ਕਰ ਦੈ ਕਰਿਯੈ। ਸਭ ਬੈਰਿਨ ਕੌ ਆਜ ਸੰਘਰਿਯੈ।","roman":"Mo rachhaa niju kar dai kariyai | sabh bairin kau aaj sanghriyai |","meaning_en":"Protect me with Your own hand; destroy all my enemies today.","page":2531,"meaning_status":"draft"},{"gurmukhi":"ਪੂਰਨ ਹੋਇ ਹਮਾਰੀ ਆਸਾ। ਤੋਰਿ ਭਜਨ ਕੀ ਰਹੈ ਪਿਯਾਸਾ। ੩੭੯।","roman":"Pooran hoi hamaaree aasaa | tori bhajan kee rahai piyaasaa | 379 |","meaning_en":"May my hope be fulfilled; may my thirst for Your remembrance remain.","page":2531,"meaning_status":"draft"}]},{"type":"verse","number":[380],"number_text":"੩੮੦।","page":2531,"lines":[{"gurmukhi":"ਤੁਮਹਿ ਛਾਡਿ ਕੋਈ ਅਵਰ ਨ ਧ੍ਯਾਊ। ਜੋ ਬਰ ਚਾਹੌ ਸੁ ਤੁਮ ਤੇ ਪਾਊ।","roman":"Tumhi chhaadi koee avar na dhyaaoo | jo bar chaahau su tum te paaoo |","meaning_en":"Forsaking You, I will meditate on no other; whatever boon I desire, I will receive from You.","page":2531,"meaning_status":"draft","note":"ਬਰ: boon, blessing."},{"gurmukhi":"ਸੇਵਕ ਸਿਖ੍ਯ ਹਮਾਰੇ ਤਾਰਿਯਹਿ। ਚੁਨ ਚੁਨ ਸਤ੍ਰੁ ਹਮਾਰੇ ਮਾਰਿਯਹਿ। ੩੮੦।","roman":"Sevak sikhy hamaare taariyhi | chun chun satru hamaare maariyhi | 380 |","meaning_en":"Carry my servants and Sikhs across (the world-ocean); pick out and destroy my enemies one by one.","page":2531,"meaning_status":"draft"}]},{"type":"verse","number":[381],"number_text":"੩੮੧।","page":2531,"lines":[{"gurmukhi":"ਆਪੁ ਹਾਥ ਦੈ ਮੁਝੈ ਉਬਰਿਯੈ। ਮਰਨ ਕਾਲ ਕਾ ਤ੍ਰਾਸ ਨਿਵਰਿਯੈ।","roman":"Aapu haath dai mujhai ubriyai | maran kaal kaa traas nivriyai |","meaning_en":"Lift me up with Your own hand; remove the fear of the time of death.","page":2531,"meaning_status":"draft"},{"gurmukhi":"ਹੂਜੋ ਸਦਾ ਹਮਾਰੇ ਪਛਾ। ਸ੍ਰੀ ਅਸਿਧੁਜ ਜੂ ਕਰਿਯਹੁ ਰਛਾ। ੩੮੧।","roman":"Hoojo sadaa hamaare pachhaa | sree asidhuj joo kariyhu rachhaa | 381 |","meaning_en":"Be always on my side; O revered Asidhuj (Bearer of the sword-banner), protect me.","page":2531,"meaning_status":"draft","note":"ਅਸਿਧੁਜ: 'whose banner is the sword', a name of God (the Timeless)."}]},{"type":"verse","number":[382],"number_text":"੩੮੨।","page":2531,"lines":[{"gurmukhi":"ਰਾਖਿ ਲੇਹੁ ਮੁਹਿ ਰਾਖਨਹਾਰੇ। ਸਾਹਿਬ ਸੰਤ ਸਹਾਇ ਪਿਯਾਰੇ।","roman":"Raakhi lehu muhi raakhanhaare | saahib sant sahaai piyaare |","meaning_en":"Save me, O Saviour; O Master, Helper of the saints, Beloved.","page":2531,"meaning_status":"draft"},{"gurmukhi":"ਦੀਨਬੰਧੁ ਦੁਸਟਨ ਕੇ ਹੰਤਾ। ਤੁਮ ਹੋ ਪੁਰੀ ਚਤੁਰਦਸ ਕੰਤਾ। ੩੮੨।","roman":"Deenbandhu dustan ke hantaa | tum ho puree chaturdas kantaa | 382 |","meaning_en":"Friend of the humble, Destroyer of the wicked, You are the Master of the fourteen worlds.","page":2531,"meaning_status":"draft","note":"ਪੁਰੀ ਚਤੁਰਦਸ: the fourteen worlds (of Indian cosmology). ਕੰਤਾ: lord, husband."}]},{"type":"verse","number":[383],"number_text":"੩੮੩।","page":2533,"lines":[{"gurmukhi":"ਕਾਲ ਪਾਇ ਬ੍ਰਹਮਾ ਬਪੁ ਧਰਾ। ਕਾਲ ਪਾਇ ਸਿਵ ਜੂ ਅਵਤਰਾ।","roman":"Kaal paai brahmaa bapu dharaa | kaal paai siv joo avatraa |","meaning_en":"In time Brahma took a body; in time Shiva became incarnate.","page":2533,"meaning_status":"draft","note":"ਕਾਲ ਪਾਇ: read as 'in due time' or 'by (the will of) Kaal, the Timeless Lord'. Both readings are traditional."},{"gurmukhi":"ਕਾਲ ਪਾਇ ਕਰਿ ਬਿਸਨ ਪ੍ਰਕਾਸਾ। ਸਕਲ ਕਾਲ ਕਾ ਕੀਯਾ ਤਮਾਸਾ। ੩੮੩।","roman":"Kaal paai kari bisan prakaasaa | sakal kaal kaa keeyaa tamaasaa | 383 |","meaning_en":"In time Vishnu became manifest; all of this is the play of Kaal (the Timeless).","page":2533,"meaning_status":"draft","note":"ਸਕਲ ਕਾਲ ਕਾ ਕੀਯਾ ਤਮਾਸਾ: 'all is the spectacle made by Kaal'."}]},{"type":"verse","number":[384],"number_text":"੩੮੪।","page":2533,"lines":[{"gurmukhi":"ਜਵਨ ਕਾਲ ਜੋਗੀ ਸਿਵ ਕੀਯੋ। ਬੇਦ ਰਾਜ ਬ੍ਰਹਮਾ ਜੂ ਥੀਯੋ।","roman":"Javan kaal jogee siv keeyo | bed raaj brahmaa joo theeyo |","meaning_en":"The Kaal (Timeless Lord) who made Shiva a yogi, and by whom Brahma became the master of the Vedas;","page":2533,"meaning_status":"draft","note":"ਬੇਦ ਰਾਜ: master (king) of the Vedas."},{"gurmukhi":"ਜਵਨ ਕਾਲ ਸਭ ਲੋਕ ਸਵਾਰਾ। ਨਮਸਕਾਰ ਹੈ ਤਾਹਿ ਹਮਾਰਾ। ੩੮੪।","roman":"Javan kaal sabh lok savaaraa | namaskaar hai taahi hamaaraa | 384 |","meaning_en":"the Kaal who fashioned all the worlds: to Him is my salutation.","page":2533,"meaning_status":"draft"}]},{"type":"verse","number":[385],"number_text":"੩੮੫।","page":2533,"lines":[{"gurmukhi":"ਜਵਨ ਕਾਲ ਸਭ ਜਗਤ ਬਨਾਯੋ। ਦੇਵ ਦੈਤ ਜਛਨ ਉਪਜਾਯੋ।","roman":"Javan kaal sabh jagat banaayo | dev dait jachhan upjaayo |","meaning_en":"The Kaal who made the whole world and created gods, demons and yakshas;","page":2533,"meaning_status":"draft","note":"ਜਛ: yakshas, a class of semi-divine beings."},{"gurmukhi":"ਆਦਿ ਅੰਤਿ ਏਕੈ ਅਵਤਾਰਾ। ਸੋਈ ਗੁਰੂ ਸਮਝਿਯਹੁ ਹਮਾਰਾ। ੩੮੫।","roman":"Aadi anti ekai avtaaraa | soee guroo samjhiyhu hamaaraa | 385 |","meaning_en":"from the beginning to the end He alone is the incarnation (manifestation); know Him alone as my Guru.","page":2533,"meaning_status":"draft","note":"ਏਕੈ ਅਵਤਾਰਾ: read as 'the one manifest Being'; it does not refer to a human incarnation."}]},{"type":"verse","number":[386],"number_text":"੩੮੬।","page":2533,"lines":[{"gurmukhi":"ਨਮਸਕਾਰ ਤਿਸ ਹੀ ਕੋ ਹਮਾਰੀ। ਸਕਲ ਪ੍ਰਜਾ ਜਿਨ ਆਪ ਸਵਾਰੀ।","roman":"Namaskaar tis hee ko hamaaree | sakal prajaa jin aap savaaree |","meaning_en":"My salutation is to Him alone, who Himself fashioned all His creatures;","page":2533,"meaning_status":"draft"},{"gurmukhi":"ਸਿਵਕਨ ਕੋ ਸਿਵਗੁਨ ਸੁਖ ਦੀਯੋ। ਸਤ੍ਰੁਨ ਕੋ ਪਲ ਮੋ ਬਧ ਕੀਯੋ। ੩੮੬।","roman":"Sivkan ko sivgun sukh deeyo | satrun ko pal mo badh keeyo | 386 |","meaning_en":"who gave His servants divine virtues and peace, and destroyed the enemies in a moment.","page":2533,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft","note":"ਸਿਵਕਨ ਕੋ ਸਿਵਗੁਨ: read as 'to His servants (He gave) godly virtues'; some read ਸਿਵਕਨ as 'devotees of Shiva'."}]},{"type":"verse","number":[387],"number_text":"੩੮੭।","page":2533,"lines":[{"gurmukhi":"ਘਟ ਘਟ ਕੇ ਅੰਤਰ ਕੀ ਜਾਨਤ। ਭਲੇ ਬੁਰੇ ਕੀ ਪੀਰ ਪਛਾਨਤ।","roman":"Ghat ghat ke antar kee jaanat | bhale bure kee peer pachhaanat |","meaning_en":"He knows what is within every heart; He knows the pain of the good and the bad.","page":2533,"meaning_status":"draft"},{"gurmukhi":"ਚੀਟੀ ਤੇ ਕੁੰਚਰ ਅਸਥੂਲਾ। ਸਭ ਪਰ ਕ੍ਰਿਪਾ ਦ੍ਰਿਸਟਿ ਕਰਿ ਫੂਲਾ। ੩੮੭।","roman":"Cheetee te kunchar asthoolaa | sabh par kripaa dristi kari phoolaa | 387 |","meaning_en":"From the ant to the huge elephant, He casts His glance of grace on all and is pleased.","page":2533,"meaning_status":"draft","note":"ਕੁੰਚਰ ਅਸਥੂਲਾ: the massive elephant. ਫੂਲਾ: delighted, pleased."}]},{"type":"verse","number":[388],"number_text":"੩੮੮।","page":2533,"lines":[{"gurmukhi":"ਸੰਤਨ ਦੁਖ ਪਾਏ ਤੇ ਦੁਖੀ। ਸੁਖ ਪਾਏ ਸਾਧਨ ਕੇ ਸੁਖੀ।","roman":"Santan dukh paae te dukhee | sukh paae saadhan ke sukhee |","meaning_en":"He is pained when His saints are pained, and happy when His holy ones are happy.","page":2533,"meaning_status":"draft"},{"gurmukhi":"ਏਕ ਏਕ ਕੀ ਪੀਰ ਪਛਾਨੈ। ਘਟ ਘਟ ਕੇ ਪਟ ਪਟ ਕੀ ਜਾਨੈ। ੩੮੮।","roman":"Ek ek kee peer pachhaanai | ghat ghat ke pat pat kee jaanai | 388 |","meaning_en":"He knows the pain of each and every one; He knows the innermost secrets of every heart.","page":2533,"meaning_status":"draft","note":"ਪਟ ਪਟ: the layers / veils, i.e. the innermost secrets."}]},{"type":"verse","number":[389],"number_text":"੩੮੯।","page":2533,"lines":[{"gurmukhi":"ਜਬ ਉਦਕਰਖ ਕਰਾ ਕਰਤਾਰਾ। ਪ੍ਰਜਾ ਧਰਤ ਤਬ ਦੇਹ ਅਪਾਰਾ।","roman":"Jab udakrakh karaa kartaaraa | prajaa dharat tab deh apaaraa |","meaning_en":"When the Creator expanded Himself, His creation took on countless bodies.","page":2533,"meaning_status":"draft","note":"ਉਦਕਰਖ: expansion, spreading out (creation)."},{"gurmukhi":"ਜਬ ਆਕਰਖ ਕਰਤ ਹੋ ਕਬਹੂੰ। ਤੁਮ ਮੈ ਮਿਲਤ ਦੇਹ ਧਰ ਸਭਹੂੰ। ੩੮੯।","roman":"Jab aakrakh karat ho kabhoon | tum mai milat deh dhar sabhhoon | 389 |","meaning_en":"When at any time You draw it back in, all beings with bodies merge into You.","page":2533,"meaning_status":"draft","note":"ਆਕਰਖ: drawing in, contraction (dissolution)."}]},{"type":"verse","number":[390],"number_text":"੩੯੦।","page":2533,"lines":[{"gurmukhi":"ਜੇਤੇ ਬਦਨ ਸ੍ਰਿਸਟਿ ਸਭ ਧਾਰੈ। ਆਪੁ ਆਪੁਨੀ ਬੂਝਿ ਉਚਾਰੈ।","roman":"Jete badan sristi sabh dhaarai | aapu aapunee boojhi uchaarai |","meaning_en":"All the faces (beings) that the creation bears describe You according to their own understanding.","page":2533,"meaning_status":"draft","note":"ਬਦਨ: faces / mouths, i.e. beings."},{"gurmukhi":"ਤੁਮ ਸਭ ਹੀ ਤੇ ਰਹਤ ਨਿਰਾਲਮ। ਜਾਨਤ ਬੇਦ ਭੇਦ ਅਰੁ ਆਲਮ। ੩੯੦।","roman":"Tum sabh hee te rahat niraalam | jaanat bed bhed aru aalam | 390 |","meaning_en":"You remain detached from all; the Vedas and the learned know this secret.","page":2533,"meaning_status":"draft","note":"ਆਲਮ: read as 'the learned' (Arabic ʿālim) or 'the world' (ʿālam). Both readings exist."}]},{"type":"verse","number":[391],"number_text":"੩੯੧।","page":2533,"lines":[{"gurmukhi":"ਨਿਰੰਕਾਰ ਨ੍ਰਿਬਿਕਾਰ ਨ੍ਰਿਲੰਭ। ਆਦਿ ਅਨੀਲ ਅਨਾਦਿ ਅਸੰਭ।","roman":"Nirankaar nribikaar nrilanbh | aadi aneel anaadi asanbh |","meaning_en":"Formless, free of all defect, needing no support, primal, stainless, without beginning, unborn.","page":2533,"meaning_status":"draft","note":"ਅਨੀਲ: stainless / colourless."},{"gurmukhi":"ਤਾ ਕਾ ਮੂੜ ਉਚਾਰਤ ਭੇਦਾ। ਜਾ ਕੋ ਭੇਵ ਨ ਪਾਵਤ ਬੇਦਾ। ੩੯੧।","roman":"Taa kaa moor uchaarat bhedaa | jaa ko bhev na paavat bedaa | 391 |","meaning_en":"The fool claims to tell the secret of the One whose secret not even the Vedas can find.","page":2533,"meaning_status":"draft"}]},{"type":"verse","number":[392],"number_text":"੩੯੨।","page":2533,"lines":[{"gurmukhi":"ਤਾ ਕੌ ਕਰਿ ਪਾਹਨ ਅਨੁਮਾਨਤ। ਮਹਾ ਮੂੜ ਕਛੁ ਭੇਦ ਨ ਜਾਨਤ।","roman":"Taa kau kari paahan anumaanat | mahaa moor kachhu bhed na jaanat |","meaning_en":"He imagines Him to be a stone; the great fool knows nothing of His secret.","page":2533,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾਦੇਵ ਕੌ ਕਹਤ ਸਦਾ ਸਿਵ। ਨਿਰੰਕਾਰ ਕਾ ਚੀਨਤ ਨਹਿ ਭਿਵ। ੩੯੨।","roman":"Mahaadev kau kahat sadaa siv | nirankaar kaa cheenat nahi bhiv | 392 |","meaning_en":"He calls Mahadev (Shiva) the Eternal Lord (Sada Shiv), and does not recognise the secret of the Formless.","page":2533,"meaning_status":"draft","note":"ਸਦਾ ਸਿਵ: 'the eternal Shiva', a title of the Supreme. ਭਿਵ: secret (ਭੇਵ)."}]},{"type":"verse","number":[393],"number_text":"੩੯੩।","page":2533,"lines":[{"gurmukhi":"ਆਪੁ ਆਪੁਨੀ ਬੁਧਿ ਹੈ ਜੇਤੀ। ਬਰਨਤ ਭਿੰਨ ਭਿੰਨ ਤੁਹਿ ਤੇਤੀ।","roman":"Aapu aapunee budhi hai jetee | barnat bhinn bhinn tuhi tetee |","meaning_en":"Each according to their own understanding describes You in different ways.","page":2533,"meaning_status":"draft"},{"gurmukhi":"ਤੁਮਰਾ ਲਖਾ ਨ ਜਾਇ ਪਸਾਰਾ। ਕਿਹ ਬਿਧਿ ਸਜਾ ਪ੍ਰਥਮ ਸੰਸਾਰਾ। ੩੯੩।","roman":"Tumraa lakhaa na jaai pasaaraa | kih bidhi sajaa pratham sansaaraa | 393 |","meaning_en":"Your expanse cannot be known, nor how You first fashioned the world.","page":2533,"meaning_status":"draft"}]},{"type":"verse","number":[394],"number_text":"੩੯੪।","page":2533,"lines":[{"gurmukhi":"ਏਕੈ ਰੂਪ ਅਨੂਪ ਸਰੂਪਾ। ਰੰਕ ਭਯੋ ਰਾਵ ਕਹੀ ਭੂਪਾ।","roman":"Ekai roop anoop saroopaa | rank bhayo raav kahee bhoopaa |","meaning_en":"You have one form, of incomparable beauty; You became a pauper, a chief, and also a king.","page":2533,"meaning_status":"draft","note":"ਰਾਵ: chieftain, ruler."},{"gurmukhi":"ਅੰਡਜ ਜੇਰਜ ਸੇਤਜ ਕੀਨੀ। ਉਤਭੁਜ ਖਾਨਿ ਬਹੁਰਿ ਰਚਿ ਦੀਨੀ। ੩੯੪।","roman":"Andaj jeraj setaj keenee | utbhuj khaani bahuri rachi deenee | 394 |","meaning_en":"You made beings born from eggs, from wombs and from sweat, and then created the source of those that sprout from the earth.","page":2533,"meaning_status":"draft","note":"The four sources (ਖਾਣੀਆਂ) of life: ਅੰਡਜ (egg), ਜੇਰਜ (womb), ਸੇਤਜ (sweat / moisture), ਉਤਭੁਜ (sprouting from the earth)."}]},{"type":"verse","number":[395],"number_text":"੩੯੫।","page":2535,"lines":[{"gurmukhi":"ਕਹੁੰ ਫੂਲਿ ਰਾਜਾ ਹ੍ਵੈ ਬੈਠਾ। ਕਹੂੰ ਸਿਮਟਿ ਭਯੋ ਸੰਕਰ ਇਕੈਠਾ।","roman":"Kahun phooli raajaa hvai baithaa | kahoon simti bhayo sankar ikaithaa |","meaning_en":"Somewhere You sit expanded as a king; somewhere You have drawn Yourself together as Shankar (Shiva), the ascetic.","page":2535,"meaning_status":"draft","note":"ਫੂਲਿ: expanded, in splendour; ਸਿਮਟਿ: contracted, withdrawn (in yogic austerity)."},{"gurmukhi":"ਸਗਰੀ ਸ੍ਰਿਸਟਿ ਦਿਖਾਇ ਅਚੰਭਵ। ਆਦਿ ਜੁਗਾਦਿ ਸਰੂਪ ਸੁਯੰਭਵ। ੩੯੫।","roman":"Sagree sristi dikhaai achanbhav | aadi jugaadi saroop suyanbhav | 395 |","meaning_en":"You have shown wonders throughout the creation; You are primal, from the beginning of the ages, of self-existent form.","page":2535,"meaning_status":"draft","note":"ਸੁਯੰਭਵ: self-existent."}]},{"type":"verse","number":[396],"number_text":"੩੯੬।","page":2535,"lines":[{"gurmukhi":"ਅਬ ਰਛਾ ਮੇਰੀ ਤੁਮ ਕਰੋ। ਸਿਖ੍ਯ ਉਬਾਰਿ ਅਸਿਖ੍ਯ ਸੰਘਰੋ।","roman":"Ab rachhaa meree tum karo | sikhy ubaari asikhy sanghro |","meaning_en":"Now You protect me; save the Sikhs and destroy the non-Sikhs (those who oppose).","page":2535,"meaning_status":"draft","note":"ਅਸਿਖ੍ਯ: read as 'those who oppose / the unrighteous'; the word is understood in different ways."},{"gurmukhi":"ਦੁਸਟ ਜਿਤੇ ਉਠਵਤ ਉਤਪਾਤਾ। ਸਕਲ ਮਲੇਛ ਕਰੋ ਰਣ ਘਾਤਾ। ੩੯੬।","roman":"Dusat jite uthvat utpaataa | sakal malechh karo ran ghaataa | 396 |","meaning_en":"All the wicked who raise mischief, and all the malechhas, destroy in battle.","page":2535,"meaning_status":"draft","note":"ਮਲੇਛ: the impure / wicked, those who oppress; often read as those of evil conduct rather than any community."}]},{"type":"verse","number":[397],"number_text":"੩੯੭।","page":2535,"lines":[{"gurmukhi":"ਜੇ ਅਸਿਧੁਜ ਤਵ ਸਰਨੀ ਪਰੇ। ਤਿਨ ਕੇ ਦੁਸਟ ਦੁਖਿਤ ਹ੍ਵੈ ਮਰੇ।","roman":"Je asidhuj tav sarnee pare | tin ke dusat dukhit hvai mare |","meaning_en":"O Asidhuj, those who seek Your refuge: their enemies die in misery.","page":2535,"meaning_status":"draft"},{"gurmukhi":"ਪੁਰਖ ਜਵਨ ਪਗੁ ਕਰੇ ਤਿਹਾਰੇ। ਤਿਨ ਕੇ ਤੁਮ ਸੰਕਟ ਸਭ ਟਾਰੇ। ੩੯੭।","roman":"Purakh javan pagu kare tihaare | tin ke tum sankat sabh taare | 397 |","meaning_en":"Those people who fall at Your feet: You remove all their troubles.","page":2535,"meaning_status":"draft","note":"ਪਗੁ ਕਰੇ ਤਿਹਾਰੇ: read as 'who hold to Your feet'."}]},{"type":"verse","number":[398],"number_text":"੩੯੮।","page":2535,"lines":[{"gurmukhi":"ਜੋ ਕਲਿ ਕੌ ਇਕ ਬਾਰ ਧਿਐਹੈ। ਤਾ ਕੇ ਕਾਲ ਨਿਕਟਿ ਨਹਿ ਐਹੈ।","roman":"Jo kali kau ik baar dhiaihai | taa ke kaal nikti nahi aihai |","meaning_en":"Whoever meditates even once on Kaal (the Timeless), death will not come near him.","page":2535,"meaning_status":"draft","note":"ਕਲਿ: here read as ਕਾਲ, the Timeless Lord; some read 'in the Kali age, whoever meditates once'."},{"gurmukhi":"ਰਛਾ ਹੋਇ ਤਾਹਿ ਸਭ ਕਾਲਾ। ਦੁਸਟ ਅਰਿਸਟ ਟਰੇ ਤਤਕਾਲਾ। ੩੯੮।","roman":"Rachhaa hoi taahi sabh kaalaa | dusat arisat tare tatkaalaa | 398 |","meaning_en":"He is protected at all times; the wicked and misfortunes go away at once.","page":2535,"meaning_status":"draft","note":"ਅਰਿਸਟ: misfortune, calamity."}]},{"type":"verse","number":[399],"number_text":"੩੯੯।","page":2535,"lines":[{"gurmukhi":"ਕ੍ਰਿਪਾ ਦ੍ਰਿਸਟਿ ਤਨ ਜਾਹਿ ਨਿਹਰਿਹੋ। ਤਾ ਕੇ ਤਾਪ ਤਨਕ ਮਹਿ ਹਰਿ ਹੋ।","roman":"Kripaa dristi tan jaahi nihriho | taa ke taap tanak mahi hari ho |","meaning_en":"The one on whom You cast Your glance of grace, You remove his afflictions in an instant.","page":2535,"meaning_status":"draft"},{"gurmukhi":"ਰਿਧਿ ਸਿਧਿ ਘਰ ਮੋ ਸਭ ਹੋਈ। ਦੁਸਟ ਛਾਹ ਛ੍ਵੈ ਸਕੈ ਨ ਕੋਈ। ੩੯੯।","roman":"Ridhi sidhi ghar mo sabh hoee | dusat chhaah chhvai sakai na koee | 399 |","meaning_en":"Prosperity and spiritual powers are all in his home; no shadow of the wicked can touch him.","page":2535,"meaning_status":"draft"}]},{"type":"verse","number":[400],"number_text":"੪੦੦।","page":2535,"lines":[{"gurmukhi":"ਏਕ ਬਾਰ ਜਿਨ ਤੁਮੈ ਸੰਭਾਰਾ। ਕਾਲ ਫਾਸ ਤੇ ਤਾਹਿ ਉਬਾਰਾ।","roman":"Ek baar jin tumai sanbhaaraa | kaal phaas te taahi ubaaraa |","meaning_en":"Whoever remembered You even once, You saved him from the noose of death.","page":2535,"meaning_status":"draft"},{"gurmukhi":"ਜਿਨ ਨਰ ਨਾਮ ਤਿਹਾਰੋ ਕਹਾ। ਦਾਰਿਦ ਦੁਸਟ ਦੋਖ ਤੇ ਰਹਾ। ੪੦੦।","roman":"Jin nar naam tihaaro kahaa | daarid dusat dokh te rahaa | 400 |","meaning_en":"The person who uttered Your name was kept safe from poverty, the wicked and faults.","page":2535,"meaning_status":"draft"}]},{"type":"verse","number":[401],"number_text":"੪੦੧।","page":2535,"lines":[{"gurmukhi":"ਖੜਗਕੇਤੁ ਮੈ ਸਰਨਿ ਤਿਹਾਰੀ। ਆਪੁ ਹਾਥ ਦੈ ਲੇਹੁ ਉਬਾਰੀ।","roman":"Kharagketu mai sarni tihaaree | aapu haath dai lehu ubaaree |","meaning_en":"O Kharagketu (Bearer of the sword-banner), I am in Your refuge; save me with Your own hand.","page":2535,"meaning_status":"draft","note":"ਖੜਗਕੇਤੁ: 'whose banner is the sword', a name of God."},{"gurmukhi":"ਸਰਬ ਠੌਰ ਮੋ ਹੋਹੁ ਸਹਾਈ। ਦੁਸਟ ਦੋਖ ਤੇ ਲੇਹੁ ਬਚਾਈ। ੪੦੧।","roman":"Sarab thaur mo hohu sahaaee | dusat dokh te lehu bachaaee | 401 |","meaning_en":"Be my helper in every place; save me from the wicked and from faults.","page":2535,"meaning_status":"draft"}]},{"type":"verse","number":[402],"number_text":"੪੦੨।","page":2535,"lines":[{"gurmukhi":"ਕ੍ਰਿਪਾ ਕਰੀ ਹਮ ਪਰ ਜਗਮਾਤਾ। ਗ੍ਰੰਥ ਕਰਾ ਪੂਰਨ ਸੁਭਰਾਤਾ।","roman":"Kripaa karee ham par jagmaataa | granth karaa pooran subhraataa |","meaning_en":"The Mother of the world showed mercy to me, and I completed this book in auspicious (time).","page":2535,"meaning_status":"draft","note":"ਜਗਮਾਤਾ: the Mother of the world, read as the divine power. ਸੁਭਰਾਤਾ: read as 'on an auspicious night' or 'with good intent'; uncertain."},{"gurmukhi":"ਕਿਲਬਿਖ ਸਕਲ ਦੇਖ ਕੋ ਹਰਤਾ। ਦੁਸਟ ਦੋਖਿਯਨ ਕੋ ਛੈ ਕਰਤਾ। ੪੦੨।","roman":"Kilbikh sakal dekh ko hartaa | dusat dokhiyan ko chhai kartaa | 402 |","meaning_en":"(She is) the remover of all sins and faults, and the destroyer of the wicked and the evil.","page":2535,"meaning_status":"draft","note":"This edition prints ਦੇਖ (kept as printed); the usual reading is ਦੋਖ (faults)."}]},{"type":"verse","number":[403],"number_text":"੪੦੩।","page":2535,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਅਸਿਧੁਜ ਜਬ ਭਏ ਦਯਾਲਾ। ਪੂਰਨ ਕਰਾ ਗ੍ਰੰਥ ਤਤਕਾਲਾ।","roman":"Sree asidhuj jab bhae dayaalaa | pooran karaa granth tatkaalaa |","meaning_en":"When the revered Asidhuj became merciful, I completed this book at once.","page":2535,"meaning_status":"draft"},{"gurmukhi":"ਮਨ ਬਾਛਤ ਫਲ ਪਾਵੈ ਸੋਈ। ਦੂਖ ਨ ਤਿਸੈ ਬਿਆਪਤ ਕੋਈ। ੪੦੩।","roman":"Man baachhat phal paavai soee | dookh na tisai biaapat koee | 403 |","meaning_en":"Whoever (reads it) obtains the fruit his mind desires; no sorrow afflicts him.","page":2535,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril metre.","page":2535,"meaning_status":"draft"},{"type":"verse","number":[404],"number_text":"੪੦੪।","page":2535,"lines":[{"gurmukhi":"ਸੁਨੈ ਗੁੰਗ ਜੋ ਯਾਹਿ ਸੁ ਰਸਨਾ ਪਾਵਈ।","roman":"Sunai gung jo yaahi su rasnaa paavaee |","meaning_en":"If a mute person hears this, he gains a tongue (speech);","page":2535,"meaning_status":"draft"},{"gurmukhi":"ਸੁਨੈ ਮੂੜ ਚਿਤ ਲਾਇ ਚਤੁਰਤਾ ਆਵਈ।","roman":"Sunai moor chit laai chaturtaa aavaee |","meaning_en":"if a foolish person listens with attention, wisdom comes to him;","page":2535,"meaning_status":"draft"},{"gurmukhi":"ਦੂਖ ਦਰਦ ਭੌ ਨਿਕਟ ਨ ਤਿਨ ਨਰ ਕੇ ਰਹੈ।","roman":"Dookh darad bhau nikat na tin nar ke rahai |","meaning_en":"pain, suffering and fear do not stay near that person","page":2535,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜੋ ਯਾ ਕੀ ਏਕ ਬਾਰ ਚੌਪਈ ਕੋ ਕਹੈ। ੪੦੪।","roman":"Ho jo yaa kee ek baar chaupaee ko kahai | 404 |","meaning_en":"who recites this chaupai even once.","page":2535,"meaning_status":"draft","note":"ਹੋ: an exclamation that begins the last line of an arril."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai metre.","page":2535,"meaning_status":"draft"},{"type":"verse","number":[405],"number_text":"੪੦੫।","page":2535,"lines":[{"gurmukhi":"ਸੰਬਤ ਸਤ੍ਰਹ ਸਹਸ ਭਣਿਜੈ। ਅਰਧ ਸਹਸ ਫੁਨਿ ਤੀਨਿ ਕਹਿਜੈ।","roman":"Sanbat satrah sahas bhanijai | aradh sahas phuni teeni kahijai |","meaning_en":"Count it the year seventeen hundred, and add half a hundred and three more (Bikrami 1753);","page":2535,"meaning_status":"draft","note":"ਸੰਬਤ ਸਤ੍ਰਹ ਸਹਸ ... ਅਰਧ ਸਹਸ ਫੁਨਿ ਤੀਨਿ: read as Samvat 1753 (1696 CE); ਸਹਸ here is read as 'hundred' by most commentators."},{"gurmukhi":"ਭਾਦ੍ਰਵ ਸੁਦੀ ਅਸਟਮੀ ਰਵਿ ਵਾਰਾ। ਤੀਰ ਸਤੁਦ੍ਰਵ ਗ੍ਰੰਥ ਸੁਧਾਰਾ। ੪੦੫।","roman":"Bhaadrav sudee asatmee ravi vaaraa | teer satudrav granth sudhaaraa | 405 |","meaning_en":"on Sunday, the eighth day of the bright half of Bhadon, on the bank of the Sutlej, the book was completed.","page":2535,"meaning_status":"draft","note":"ਤੀਰ ਸਤੁਦ੍ਰਵ: on the bank of the Satluj (Sutlej) river."}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਚਰਿਤ੍ਰ ਪਖ੍ਯਾਨੇ ਤ੍ਰਿਯਾ ਚਰਿਤ੍ਰੇ ਮੰਤ੍ਰੀ ਭੂਪ ਸੰਬਾਦੇ ਚਾਰ ਸੌ ਚਾਰ ਚਰਿਤ੍ਰ ਸਮਾਪਤਮ","roman":"Iti sree charitr pakhyaane triyaa charitre mantree bhoop sanbaade chaar sau chaar charitr samaaptam","meaning_en":"Thus ends the four hundred and fourth charitra of the Charitropakhyan, in the dialogue between the minister and the king,","page":2535,"meaning_status":"draft","note":"ਤ੍ਰਿਯਾ ਚਰਿਤ੍ਰ: the stories of the wiles (of men and women); ਮੰਤ੍ਰੀ ਭੂਪ ਸੰਬਾਦ: told as a dialogue between a minister and a king."},{"gurmukhi":"ਸਤੁ ਸੁਭਮ ਸਤੁ। ੪੦੪। ੭੫੩੯। ਸਮਾਪਤਮ।","roman":"Satu subham satu | 404 | 7539 | samaaptam |","meaning_en":"True, auspicious, true. 404. 7539. Complete.","page":2535,"meaning_status":"draft","note":"ਸਤੁ ਸੁਭਮ ਸਤੁ: a traditional closing formula, 'it is true and auspicious'."}],"page":2535}});
